Object.assign(window.TEM8_DICTIONARY, {"diminutive":{"media":{"uk":"media/uk/diminutive__gb_1.mp3","us":"media/us/diminutive__us_1.mp3"},"oxford":{"phon":"dɪˈmɪnjətɪv","pos":"adjective","senses":[{"en":"very small","cn":"极小的；特小的；微小的","ex":{"en":"She was a diminutive figure beside her husband.","cn":"她同丈夫比起来身材十分娇小。"}},{"en":"a word or an ending of a word that shows that somebody/something is small, for example piglet (= a young pig), kitchenette (= a small kitchen)","cn":"指小词，指小词缀（如 piglet 小猪，kitchenette 小厨房）","pos":"noun"},{"en":"a short informal form of a word, especially a name","cn":"（单词，尤指名字的）非正式缩略形式","ex":{"en":"‘Nick’ is a common diminutive of ‘Nicholas’.","cn":"Nick 是 Nicholas 的常用简称。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"很小的;微小的","en":"A diminutive person or object is very small.","ex":{"en":"She noticed a diminutive figure standing at the entrance.","cn":"她注意到入口处站着一个小小的身影。"}},{"pos":"N-COUNT 可数名词","cn":"昵称;爱称","en":"A diminutive is an informal form of a name. For example, 'Jim' and 'Jimmy' are diminutives of 'James'."},{"pos":"N-COUNT 可数名词","cn":"指小词缀(表示亲昵或某东西很小的后缀，如 -ie 和 -ette)","en":"A diminutive is a suffix which is added to a word to show affection or to indicate that something is small. For example, '-ie' and '-ette' are diminutives, for example in 'doggie' and 'statuette'."}]},"examples":[{"en":"‘Nick’ is a common diminutive of ‘Nicholas’. * Nick","cn":"是 Nicholas 的常用简称。"},{"en":"She was a diminutive figure beside her husband.","cn":"她同丈夫比起来就像个小人。"}]},"discreet":{"media":{"uk":"media/uk/discreet__gb_1.mp3","us":"media/us/discreet__us_1.mp3"},"oxford":{"phon":"dɪˈskriːt","pos":"adjective","senses":[{"en":"careful in what you say or do, in order to keep something secret or to avoid causing difficulty for somebody or making them feel embarrassed","cn":"（言行）谨慎的，慎重的；考虑周到的","ex":{"en":"He was always very discreet about his love affairs.","cn":"他对两性关系一贯谨小慎微。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(言行)谨慎的，考虑周到的","en":"If you are discreet, you are polite and careful in what you do or say, because you want to avoid embarrassing or offending someone.","ex":{"en":"They were gossipy and not always discreet","cn":"他们很爱传闲话，而且常常口无遮拦。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"言语谨慎的","en":"If you are discreet about something you are doing, you do not tell other people about it, in order to avoid being embarrassed or to gain an advantage.","ex":{"en":"We were very discreet about the romance","cn":"我们对这段恋情很谨慎。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不显眼的;朴素的;少的;小的","en":"If you describe something as discreet, you approve of it because it is small in size or degree, or not easily noticed.","ex":{"en":"She wore discreet jewellery.","cn":"她戴着素净的首饰。"}}]},"examples":[{"en":"She coughed discreetly to announce her presence.","cn":"她审慎地咳了一声以让人注意自己在场。"},{"en":"You ought to make a few discreet enquiries before you sign anything.","cn":"你应该审慎地询问清楚再签字。"}]},"distracted":{"media":{"uk":"media/uk/distracted__gb_1.mp3","us":"media/us/distracted__us_1.mp3"},"oxford":{"phon":"dɪˈstræktɪd","pos":"adjective","senses":[{"en":"unable to pay attention to somebody/something because you are worried or thinking about something else","cn":"注意力分散的；思想不集中的","ex":{"en":"Luke looked momentarily distracted.","cn":"卢克似乎有片刻心不在焉。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"注意力分散的;思想不集中的;心烦意乱的","en":"If you are distracted, you are not concentrating on something because you are worried or are thinking about something else.","ex":{"en":"She had seemed curiously distracted","cn":"她看上去好像心烦意乱,真奇怪。"}}]},"base":"distract"},"diary":{"media":{"uk":"media/uk/diary__gb_1.mp3","us":"media/us/diary__us_1.mp3"},"oxford":{"phon":"ˈdaɪəri","pos":"noun","senses":[{"en":"a book in which you can write down the experiences you have each day, your private thoughts, etc.","cn":"日记；日记簿","ex":{"en":"Do you keep a diary (= write one regularly)?","cn":"你经常记日记吗？"}},{"en":"a book or an app with spaces for each day of the year in which you can record things you have to do in the future","cn":"日程本；记事簿","lab":"British English","ex":{"en":"I used to keep a desk diary for business appointments.","cn":"我曾经为商务约会写办公桌日记。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"日记;日记本;记事簿","en":"A diary is a book which has a separate space for each day of the year. You use a diary to write down things you plan to do, or to record what happens in your life day by day."}]},"examples":[{"en":"I'll make a note of our next meeting in my diary.","cn":"我将把下次会议的事记在我的记事簿上。"},{"en":"Do you keep a diary (= write one regularly)?","cn":"你有写日记吗？"}]},"disadvantaged":{"media":{"uk":"media/uk/disadvantaged__gb_1.mp3","us":"media/us/disadvantaged__us_1.mp3"},"oxford":{"phon":"ˌdɪsədˈvɑːntɪdʒd","pos":"adjective","senses":[{"en":"not having the things, such as education, or enough money, that people need in order to succeed in life","cn":"弱势的；社会地位低下的","ex":{"en":"disadvantaged groups/children","cn":"生活条件差的群体／孩子"}},{"en":"people who are disadvantaged","cn":"下层社会","g":"[plural]"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"社会地位低下的;生活条件差的;贫困的","en":"People who are disadvantaged or live in disadvantaged areas live in bad conditions and tend not to get a good education or have a reasonable standard of living.","ex":{"en":"...the educational problems of disadvantaged children","cn":"贫困儿童的教育问题"}}]},"examples":[{"en":"disadvantaged groups/children","cn":"生活条件差的群体/孩子"},{"en":"a severely disadvantaged area","cn":"极贫困地区"}],"base":"disadvantage"},"dissonance":{"oxford":{"phon":"ˈdɪsənəns","pos":"noun","senses":[{"en":"a combination of musical notes that do not sound pleasant together","cn":"不协和和弦","g":"[countable, uncountable]","lab":"music"},{"en":"lack of agreement","cn":"不和谐；不协调；不一致","g":"[uncountable]","lab":"formal"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"不和谐;不协调","en":"Dissonance is a lack of agreement or harmony between things."}]},"media":{"uk":"media/uk/dissonance__gb_1.mp3","us":"media/us/dissonance__us_1.mp3"},"examples":[{"en":"dissonant voices/notes","cn":"刺耳的声音；不协和音"}]},"diminish":{"media":{"uk":"media/uk/diminish__gb_1.mp3","us":"media/us/diminish__us_1.mp3"},"oxford":{"phon":"dɪˈmɪnɪʃ","pos":"verb","senses":[{"en":"to become smaller, weaker, etc.; to make something become smaller, weaker, etc.","cn":"减少；（使）减弱，缩减；降低","g":"[intransitive, transitive]","ex":{"en":"The world's resources are rapidly diminishing.","cn":"世界资源正在迅速减少。"}},{"en":"to make somebody/something seem less important than they really are","cn":"贬低；贬损；轻视","g":"[transitive]","ex":{"en":"I don't wish to diminish the importance of their contribution.","cn":"我并不想贬低他们所作贡献的重要性。"}}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"（使）减小;（使）减弱;（使）降低","en":"When something diminishes, or when something diminishes it, it becomes reduced in size, importance, or intensity.","ex":{"en":"The threat of nuclear war has diminished","cn":"核战争的威胁已经减小了。"}},{"pos":"VERB 动词","cn":"贬低;轻视","en":"If you diminish someone or something, you talk about them or treat them in a way that makes them appear less important than they really are.","ex":{"en":"He never put her down or diminished her","cn":"他从未奚落或贬低过她。"}}]},"examples":[{"en":"His influence has diminished with time.","cn":"随着时间的推移，他的影响已不如从前了。"},{"en":"Our efforts were producing diminishing returns (= we achieved less although we spent more time or money).","cn":"我们不断付出努力，但收效却越来越小。"}]},"disadvantage":{"oxford":{"phon":"ˌdɪsədˈvɑːntɪdʒ","pos":"verb","senses":[{"en":"to cause problems and tend to stop somebody/something from succeeding or making progress","cn":"不利因素；障碍；不便之处","ex":{"en":"Some pension plans may disadvantage women.","cn":"有些养老金计划可能对妇女不利。"}},{"en":"something that causes problems and tends to stop somebody/something from succeeding or making progress","cn":"不利因素；障碍；不便之处","ex":{"en":"a serious/severe/significant disadvantage","cn":"一个严重不利的条件"},"pos":"noun"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"不利条件;劣势;不便之处","en":"A disadvantage is a factor which makes someone or something less useful, acceptable, or successful than other people or things.","ex":{"en":"His two main rivals suffer the disadvantage of having been long-term political exiles","cn":"他的两个主要竞争对手因长期政治流亡而处于不利的地位。"}},{"pos":"PHRASE 短语","cn":"处于不利的境地","en":"If you are at a disadvantage, you have a problem or difficulty that many other people do not have, which makes it harder for you to be successful.","ex":{"en":"The children from poor families were at a distinct disadvantage","cn":"来自贫困家庭的孩子们处于明显的不利地位。"}},{"pos":"PHRASE 短语","cn":"对…不利","en":"If something is to your disadvantage or works to your disadvantage, it creates difficulties for you.","ex":{"en":"A snap election would be to their disadvantage","cn":"提前选举将对他们不利。"}}]},"media":{"uk":"media/uk/disadvantage__gb_1.mp3","us":"media/us/disadvantage__us_1.mp3"},"examples":[{"en":"Many children in the class suffered severe social and economic disadvantage.","cn":"班上许多孩子都来自社会地位低下并且经济困难的家庭。"},{"en":"One major disadvantage of the area is the lack of public transport.","cn":"这个地区的一大不便之处就是缺少公共交通工具。"}]},"disillusioned":{"media":{"uk":"media/uk/disillusioned__gb_1.mp3","us":"media/us/disillusioned__us_1.mp3"},"oxford":{"phon":"ˌdɪsɪˈluːʒnd","pos":"adjective","senses":[{"en":"disappointed because the person you admired or the idea you believed to be good and true now seems without value","cn":"大失所望的；不再抱幻想的；幻想破灭的","ex":{"en":"I soon became disillusioned with the job.","cn":"我不久便对这个工作不再抱幻想了。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"失望的;醒悟的;幻想破灭的","en":"If you are disillusioned with something, you are disappointed, because it is not as good as you had expected or thought.","ex":{"en":"I've become very disillusioned with politics","cn":"我对政治完全不再抱幻想了。"}}]},"examples":[{"en":"I soon became disillusioned with the job.","cn":"我不久便对这个工作不再抱幻想了。"},{"en":"As she grew older, Laura became increasingly disillusioned with politics.","cn":"随着年龄的增长﹐劳拉对政治越来越不抱幻想了。"}]},"disapprove":{"oxford":{"phon":"ˌdɪsəˈpruːv","pos":"verb","senses":[{"en":"to think that somebody/something is not good or suitable; to not approve of somebody/something","cn":"不赞成；不同意；反对","g":"[intransitive, transitive]","lab":"North American English","ex":{"en":"She wants to be an actress, but her parents disapprove.","cn":"她想当演员，可是她父母不同意。"}},{"en":"to officially refuse to agree to a plan, request, etc.","cn":"否决；否定；反对","g":"[transitive]","ex":{"en":"Parents should get the option to approve or disapprove a child's online purchase.","cn":"家长应该可以选择批准或拒绝孩子的在线购买。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"不赞成;反对;不喜欢","en":"If you disapprove of something or someone, you feel or show that you do not like them or do not approve of them.","ex":{"en":"Most people disapprove of such violent tactics","cn":"多数人反对这种暴力的手段。"}}]},"media":{"uk":"media/uk/disapprove__gb_1.mp3","us":"media/us/disapprove__us_1.mp3"},"examples":[{"en":"( NAmE ) A solid majority disapproves the way the president is handling the controversy.","cn":"大多数人都反对总统处理争论的方式。"},{"en":"She wants to be an actress, but her parents disapprove.","cn":"她想当演员，可是她父母不同意。"}]},"distant":{"media":{"uk":"media/uk/distant__gb_1.mp3","us":"media/us/distant__us_1.mp3"},"oxford":{"phon":"ˈdɪstənt","pos":"adjective","senses":[{"en":"far away in space or time","cn":"遥远地；在远处；久远地","lab":"formal","ex":{"en":"the distant sound of music","cn":"远处的音乐声"}},{"en":"not like something else","cn":"不相似的；不同的","ex":{"en":"Their life seemed utterly distant from his own.","cn":"他们的生活与他自己的生活似乎完全不同。"}},{"en":"related to you but not closely","cn":"远亲的；远房的","g":"[only before noun]","ex":{"en":"a distant cousin/aunt/relative","cn":"远房堂兄弟／姑母／亲戚"}},{"en":"not friendly; not wanting a close relationship with somebody","cn":"不友好的；冷淡的；疏远的","ex":{"en":"Pat sounded very cold and distant on the phone.","cn":"从电话里听起来帕特非常冷淡和疏远。"}},{"en":"not paying attention to something but thinking about something completely different","cn":"心不在焉的；恍惚的；出神的","ex":{"en":"There was a distant look in her eyes; her mind was obviously on something else.","cn":"她眼神恍惚，显然心里在想着别的什么事儿。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"遥远的;远距离的","en":"Distant means very far away.","ex":{"en":"The mountains rolled away to a distant horizon.","cn":"群山向远处的地平线绵延而去。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(时间或事件)久远的","en":"You use distant to describe a time or event that is very far away in the future or in the past.","ex":{"en":"There is little doubt, however, that things will improve in the not too distant future","cn":"不过事情在不久的将来会有所改善，这几乎毋庸置疑。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"远房的;远亲的","en":"A distant relative is one who you are not closely related to.","ex":{"en":"He's a distant relative of the mayor","cn":"他是市长的一个远亲。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"冷淡的;疏远的;不友好的","en":"If you describe someone as distant, you mean that you find them cold and unfriendly.","ex":{"en":"He found her cold, ice-like and distant","cn":"他觉得她冷若冰霜，拒人于千里之外。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"恍惚的;心不在焉的;注意力不集中的","en":"If you describe someone as distant, you mean that they are not concentrating on what they are doing because they are thinking about other things.","ex":{"en":"There was a distant look in her eyes from time to time, her thoughts elsewhere.","cn":"她眼中时时流露出心不在焉的神情，思绪已飘至别处。"}}]},"examples":[{"en":"There was a distant look in her eyes; her mind was obviously on something else.","cn":"她眼神恍惚，显然心里在想着别的什么事儿。"},{"en":"The time we spent together is now a distant memory.","cn":"我们一起度过的时光现已成为久远的记忆。"}]},"disputes":{"lemma":"dispute"},"disbelief":{"media":{"uk":"media/uk/disbelief__gb_1.mp3","us":"media/us/disbelief__us_1.mp3"},"oxford":{"phon":"ˌdɪsbɪˈliːf","pos":"noun","senses":[{"en":"the feeling of not being able to believe something","cn":"不信；怀疑","ex":{"en":"He stared at me in disbelief.","cn":"他满腹疑惑地盯着我。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"不相信;怀疑","en":"Disbelief is not believing that something is true or real.","ex":{"en":"She looked at him in disbelief.","cn":"她全然不信地看着他。"}}]},"examples":[{"en":"To enjoy the movie you have to suspend your disbelief (= pretend to believe sth, even if it seems very unlikely).","cn":"要欣赏这部电影就得暂且相信那甚至不可能发生的事。"},{"en":"He stared at me in disbelief.","cn":"他满腹疑惑地盯着我。"}]},"disappointment":{"media":{"uk":"media/uk/disappointment__gb_1.mp3","us":"media/us/disappointment__us_1.mp3"},"oxford":{"phon":"ˌdɪsəˈpɔɪntmənt","pos":"noun","senses":[{"en":"the feeling of being sad because something has not happened or been as good, successful, etc. as you expected or hoped","cn":"失望；沮丧；扫兴","g":"[uncountable]","ex":{"en":"Book early for the show to avoid disappointment.","cn":"欲看演出，从速订票，以免向隅。"}},{"en":"a person or thing that is disappointing","cn":"使人失望的人（或事物）；令人扫兴的人（或事物）","g":"[countable]","ex":{"en":"a bitter/major disappointment","cn":"令人极度失望／大失所望的事"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"失望;沮丧;扫兴","en":"Disappointment is the state of feeling disappointed.","ex":{"en":"Despite winning the title, their last campaign ended in great disappointment","cn":"尽管赢得了冠军，但他们最后一役却令人大失所望。"}},{"pos":"N-COUNT 可数名词","cn":"令人失望的人（或事物）","en":"Something or someone that is a disappointment is not as good as you had hoped.","ex":{"en":"For many, their long-awaited homecoming was a bitter disappointment.","cn":"对许多人来说，他们期盼已久的还乡之行却令他们大失所望。"}}]},"examples":[{"en":"He found it difficult to hide his disappointment when she didn't arrive.","cn":"她没有来，他感到很难掩饰自己内心的沮丧。"},{"en":"To our great disappointment, it rained every day of the trip.","cn":"这次旅行天天下雨，让我们大失所望。"}]},"disorder":{"media":{"uk":"media/uk/disorder__gb_1.mp3","us":"media/us/disorder__us_1.mp3"},"oxford":{"phon":"dɪsˈɔːdə(r)","pos":"noun","senses":[{"en":"a condition or illness that causes problems with the way part of the body or brain works","cn":"失调；紊乱；疾病","g":"[countable, uncountable]","lab":"medical","ex":{"en":"a blood/bowel disorder","cn":"血液病；闹肚子"}},{"en":"an untidy state; a lack of order or organization","cn":"杂乱；混乱；凌乱","g":"[uncountable]","lab":"formal","ex":{"en":"The room was in a state of disorder.","cn":"房间凌乱不堪。"}},{"en":"violent behaviour of large groups of people","cn":"骚乱；动乱","g":"[uncountable]","lab":"formal","ex":{"en":"an outbreak of rioting and public disorder","cn":"暴乱和公众骚乱的爆发"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"(身心机能的)失调，不适，紊乱，疾病","en":"A disorder is a problem or illness which affects someone's mind or body.","ex":{"en":"...a rare nerve disorder that can cause paralysis of the arms.","cn":"一种可致手臂瘫痪的罕见的神经疾病"}},{"pos":"N-UNCOUNT 不可数名词","cn":"杂乱;混乱;凌乱","en":"Disorder is a state of being untidy, badly prepared, or badly organized.","ex":{"en":"The emergency room was in disorder","cn":"急诊室里一片混乱。"}},{"pos":"N-VAR 可变名词","cn":"骚乱;动乱","en":"Disorder is violence or rioting in public.","ex":{"en":"He called on the authorities to stop public disorder","cn":"他呼吁当局制止公众骚乱。"}}]},"examples":[{"en":"His financial affairs were in complete disorder.","cn":"他的钱财完全是一笔糊涂账。"},{"en":"He was suffering from some form of psychiatric disorder.","cn":"他患有某种类型的精神错乱。"}]},"divisions":{"lemma":"division"},"distraction":{"oxford":{"phon":"dɪˈstrækʃn","pos":"noun","senses":[{"en":"a thing that takes your attention away from what you are doing or thinking about","cn":"分散注意力的事物；使人分心的事物","g":"[countable, uncountable]","ex":{"en":"I find it hard to work at home because there are too many distractions.","cn":"我发觉在家里工作很难，因为使人分心的事太多。"}},{"en":"an activity that entertains you","cn":"娱乐；消遣","g":"[countable]"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"分散注意力的事;使人分心的事","en":"A distraction is something that turns your attention away from something you want to concentrate on.","ex":{"en":"I feel this is getting to be a distraction from what I really want to do","cn":"我觉得这开始让我无法集中精神做我真正想做的事情了。"}},{"pos":"N-COUNT 可数名词","cn":"娱乐;消遣","en":"A distraction is an activity which is intended to entertain and amuse you.","ex":{"en":"...every conceivable distraction from show jumping to bouncy castles","cn":"每一个能想象得到的娱乐项目,从跳跃障碍赛到塑料充气城堡"}},{"pos":"PHRASE 短语","cn":"让人心烦意乱;让人恼火","en":"If you say that something or someone drives you to distraction, you are emphasizing that they annoy you a great deal.","ex":{"en":"A very clingy child can drive a parent to distraction.","cn":"一个非常黏人的孩子会让父母不胜其烦。"}}]},"media":{"uk":"media/uk/distraction__gb_1.mp3","us":"media/us/distraction__us_1.mp3"},"examples":[{"en":"I find it hard to work at home because there are too many distractions.","cn":"我发觉在家里工作很难，因为使人分心的事太多。"},{"en":"The children are driving me to distraction today.","cn":"今天孩子们闹得我心烦意乱。"}]},"disconnect":{"oxford":{"phon":"ˌdɪskəˈnekt","pos":"verb","senses":[{"en":"to remove a piece of equipment from a supply of gas, water or electricity","cn":"切断（燃气、水或电的供应）","g":"[transitive]","ex":{"en":"First, disconnect the boiler from the water mains.","cn":"先将锅炉与供水总管断开。"}},{"en":"to officially stop the supply of phone lines, water, electricity or gas to a building","cn":"切断（电话服务）；停止供应（水、电或燃气）","g":"[transitive]","ex":{"en":"You may be disconnected if you do not pay the bill.","cn":"若不付账单就可能停止供应。"}},{"en":"to separate something from something","cn":"使分离；使脱离","g":"[transitive, often passive]","ex":{"en":"The ski had become disconnected from the boot.","cn":"滑雪板与靴子脱离了。"}},{"en":"to break the contact between two people who are talking on the phone","cn":"使（电话线路）中断","g":"[transitive]","ex":{"en":"We were suddenly disconnected.","cn":"我们的电话突然断了。"}},{"en":"to end a connection to the internet","cn":"（与互联网）断开","g":"[transitive, often passive, intransitive]","ex":{"en":"I keep getting disconnected when I'm online.","cn":"我联网时不断掉线。"}},{"en":"to remove somebody's connection to a piece of equipment, especially a life support machine","cn":"断开，切断（某人与设备的连接，尤指生命支持设备）","g":"[transitive]","ex":{"en":"It was the family's decision to disconnect her from the life support machine.","cn":"是家人决定给她断开生命支持设备的。"}},{"en":"a difference or lack of connection","cn":"差异；分歧；缺乏联系","ex":{"en":"There is a fundamental disconnect between union leaders and members.","cn":"工会领袖和会员之间存在着根本性的脱节。"},"pos":"noun"},{"en":"a lack of connection with a network, a supply of electricity, the internet, etc.","cn":"（与网络或电源等）断开连接，没有连接","ex":{"en":"There might be a power failure or sudden network disconnect.","cn":"可能是断电或突然断网。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"切断;断开","en":"To disconnect a piece of equipment means to separate it from its source of power or to break a connection that it needs in order to work.","ex":{"en":"The device automatically disconnects the ignition when the engine is switched off","cn":"当引擎关掉时，这个装置会自动切断点火开关。"}},{"pos":"VERB 动词","cn":"(通常指因欠费而)切断(煤气、水、电或者电话)","en":"If you are disconnected by a gas, electricity, water, or telephone company, they turn off the connection to your house, usually because you have not paid the bill.","ex":{"en":"You will be given three months to pay before you are disconnected.","cn":"在被切断供应之前你有三个月的时间来付款。"}},{"pos":"VERB 动词","cn":"使分离;使分开","en":"If you disconnect something from something else, you separate the two things.","ex":{"en":"He disconnected the IV bottle from the overhead hook.","cn":"他把静脉滴注瓶从头顶的钩子上拿下来。"}}]},"media":{"uk":"media/uk/disconnect__gb_1.mp3","us":"media/us/disconnect__us_1.mp3"},"examples":[{"en":"My computer crashes every time I disconnect from the Internet.","cn":"我每次下网，计算机都会突然死机。"},{"en":"You may be disconnected if you do not pay the bill.","cn":"若不付账单就可能停止供应。"}]},"divine":{"media":{"uk":"media/uk/divine__gb_1.mp3","us":"media/us/divine__us_1.mp3"},"oxford":{"phon":"dɪˈvaɪn","pos":"adjective","senses":[{"en":"coming from or connected with God or a god","cn":"天赐的；上帝的；神的","g":"[usually before noun]","ex":{"en":"divine law/love/will","cn":"天道；上帝的慈爱；天意"}},{"en":"wonderful; beautiful","cn":"绝妙的；非凡的；极美的","lab":"old-fashioned","ex":{"en":"That mango tasted divine!","cn":"那个芒果味道好极了！"}},{"en":"to find out something by guessing","cn":"猜到；领悟","g":"[transitive]","lab":"formal","ex":{"en":"She could divine what he was thinking just by looking at him.","cn":"她一看就知道他在想什么。"},"pos":"verb"},{"en":"to search for underground water using a stick in the shape of a Y, called a divining rod","cn":"（用丫形杖）探测（地下水）","g":"[transitive, intransitive]","pos":"verb"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"天赐的;神的;神圣的","en":"You use divine to describe something that is provided by or relates to a god or goddess.","ex":{"en":"He suggested that the civil war had been a divine punishment.","cn":"他暗示说内战是上天的惩罚。"}},{"pos":"N-COUNT 可数名词","cn":"专门研究神学的牧师","en":"A divine is a priest who specializes in the study of God and religion."},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"绝妙的;非凡的;极棒的","en":"People use divine to express their pleasure or enjoyment of something.","ex":{"en":"'Isn't it divine?' she said. 'I wish I had the right sort of brooch to lend you for it.'","cn":"“它是不是美极了？”她说道，“真希望我有合适的胸针可以借给你来搭配它。”"}},{"pos":"VERB 动词","cn":"猜测;揣度","en":"If you divine something, you discover or learn it by guessing.","ex":{"en":"...the child's ability to divine the needs of its parents and respond to them","cn":"孩子猜测父母的需要并作出回应的能力"}},{"pos":"VERB 动词","cn":"(用探测棒)探测（地下水或矿藏）","en":"If you divine, you try to find underground supplies of water or minerals, using a special rod or pair of rods.","ex":{"en":"The only reason I was divining for water was because of the drought.","cn":"我之所以探寻水源是因为发生了旱灾。"}}]},"examples":[{"en":"She could divine what he was thinking just by looking at him.","cn":"她一看就知道他在想什么。"},{"en":"divine intervention (= help from God to change a situation)","cn":"上帝之佑"}]},"dipped":{"lemma":"dip"},"disturbed":{"media":{"uk":"media/uk/disturbed__gb_1.mp3","us":"media/us/disturbed__us_1.mp3"},"oxford":{"phon":"dɪˈstɜːbd","pos":"adjective","senses":[{"en":"mentally ill, especially because of very unhappy or unpleasant experiences","cn":"有精神病的；心理不正常的；精神紊乱的","ex":{"en":"a special school for emotionally disturbed children","cn":"为精神异常儿童开办的特殊学校"}},{"en":"unhappy and full of bad or horrible experiences","cn":"不幸的；多灾多难的；坎坷的","ex":{"en":"The killer had a disturbed family background.","cn":"那名杀手出身于一个坎坷不幸的家庭。"}},{"en":"very anxious and unhappy about something","cn":"心神不安的；心烦意乱的；烦恼的","ex":{"en":"I was deeply disturbed and depressed by the news.","cn":"这消息使我深感不安和沮丧。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有精神病的;心理不正常的;精神紊乱的","en":"A disturbed person is very upset emotionally, and often needs special care or treatment.","ex":{"en":"...working with severely emotionally disturbed children","cn":"致力于帮助情绪严重失常的孩子"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"心神不安的;心烦意乱的;烦恼的","en":"You can say that someone is disturbed when they are very worried or anxious.","ex":{"en":"Doctors were disturbed that less than 30 percent of the patients were women","cn":"医生们焦虑不安，因为患者中有不到30%为女性。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不幸的;多灾多难的;动荡不安的","en":"If you describe a situation or period of time as disturbed, you mean that it is unhappy and full of problems.","ex":{"en":"...these disturbed times.","cn":"这些动荡不安的岁月"}}]},"examples":[{"en":"The killer had a disturbed family background.","cn":"那名杀手出身于一个坎坷不幸的家庭。"},{"en":"a special school for emotionally disturbed children","cn":"为精神异常儿童开办的特殊学校"}],"base":"disturb"},"dickens":{"media":{"uk":"media/uk/dickens__gb_1.mp3","us":"media/us/dickens__us_1.mp3"},"oxford":{"phon":"ˈdɪkɪnz","pos":"noun","senses":[{"en":"used in questions instead of ‘devil’ to show that you are annoyed or surprised","cn":"（用于问句代替 devil，表示烦恼或吃惊）究竟，到底","ex":{"en":"Where the dickens did he go?","cn":"他究竟上哪儿去了？"}},{"en":"used when you are saying how attractive, etc. somebody is","cn":"（某人）…极了，太…了，多么…啊","lab":"North American English","ex":{"en":"cute as the dickens","cn":"可爱极了"}}]},"examples":[{"en":"Where the dickens did he go?","cn":"他究竟上哪儿去了？"},{"en":"cute as the dickens","cn":"可爱极了"}]},"diversify":{"media":{"uk":"media/uk/diversify__gb_1.mp3","us":"media/us/diversify__us_1.mp3"},"oxford":{"phon":"daɪˈvɜːsɪfaɪ","pos":"verb","senses":[{"en":"to develop a wider range of products, interests, skills, etc. in order to be more successful or reduce risk","cn":"增加…的品种；从事多种经营；扩大业务范围","g":"[intransitive, transitive]","ex":{"en":"Farmers are being encouraged to diversify into new crops.","cn":"目前正鼓励农民兼种新的农作物。"}},{"en":"to change or to make something change so that there is greater variety","cn":"（使）多样化，变化，不同","g":"[intransitive, transitive]","ex":{"en":"Patterns of family life are diversifying.","cn":"家庭生活模式正在变得多样化。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"增加…的品种;从事多种经营;（使）多样化","en":"When an organization or person diversifies into other things, or diversifies their range of something, they increase the variety of things that they do or make.","ex":{"en":"The company's troubles started only when it diversified into new products","cn":"当公司增加新产品时，麻烦才开始的。"}}]},"examples":[{"en":"The culture has been diversified with the arrival of immigrants.","cn":"随着外来移民的到来，这里的文化变得多元化了。"},{"en":"Farmers are being encouraged to diversify into new crops.","cn":"目前正鼓励农民兼种新的农作物。"}]},"dime":{"media":{"uk":"media/uk/dime__gb_1.mp3","us":"media/us/dime__us_1.mp3"},"oxford":{"phon":"daɪm","pos":"noun","senses":[{"en":"a coin of the US and Canada worth ten cents","cn":"（美国、加拿大的）十分硬币，十分钱"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(美国货币中的)10分硬币","en":"A dime is an American coin worth ten cents."}]},"examples":[{"en":"PhDs are a dime a dozen nowadays.","cn":"如今博士学位不稀罕了。"}]},"diversity":{"media":{"uk":"media/uk/diversity__gb_1.mp3","us":"media/us/diversity__us_1.mp3"},"oxford":{"phon":"daɪˈvɜːsəti","pos":"noun","senses":[{"en":"a range of many people or things that are very different from each other","cn":"差异（性）；不同（点）","g":"[uncountable, countable, usually singular]","ex":{"en":"the biological diversity of the rainforests","cn":"热带雨林的生物多样性"}},{"en":"the quality or fact of including a range of many people or things","cn":"多样性；多样化","g":"[uncountable]","ex":{"en":"There is a need for greater diversity and choice in education.","cn":"教育方面需要更加多元化和更大的选择性。"}},{"en":"the practice or quality of including or involving people from a range of different social and ethnic backgrounds and of different genders, religions, etc.","cn":"包容或涉及来自不同社会和种族背景以及不同性别、宗教等的人们的做法或质量。","g":"[uncountable]","lab":"British English","ex":{"en":"People are being encouraged to celebrate the diversity of their communities.","cn":"人们被鼓动着颂扬他们社区的多样性。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"多样性;多样化;多元性","en":"The diversity of something is the fact that it contains many very different elements.","ex":{"en":"...the cultural diversity of British society.","cn":"英国社会文化的多元性"}},{"pos":"N-SING 单数名词","cn":"不同;差异","en":"A diversity of things is a range of things which are very different from each other.","ex":{"en":"His object is to gather as great a diversity of material as possible.","cn":"他的目标就是尽可能多地搜集各种材料。"}}]},"examples":[{"en":"There is a need for greater diversity and choice in education.","cn":"教育方面需要更加多元化和更大的选择性。"},{"en":"the biological diversity of the rainforests","cn":"热带雨林的生物多样性"}]},"disagreements":{"lemma":"disagreement"},"distinction":{"media":{"uk":"media/uk/distinction__gb_1.mp3","us":"media/us/distinction__us_1.mp3"},"oxford":{"phon":"dɪˈstɪŋkʃn","pos":"noun","senses":[{"en":"a clear difference or contrast especially between people or things that are similar or related","cn":"差别；区别；对比","g":"[countable]","ex":{"en":"distinctions between traditional and modern societies","cn":"传统社会和现代社会的差别"}},{"en":"the act of separating people or things into different groups","cn":"区分；分清；辨别","g":"[uncountable]","ex":{"en":"The new law makes no distinction between adults and children (= treats them equally).","cn":"这项新法规对成人和孩子同样适用。"}},{"en":"the quality of being something that is special","cn":"特质；特点；不同凡响","g":"[singular]","ex":{"en":"She had the distinction of being the first woman to fly the Atlantic.","cn":"她不同凡响，是第一个飞越大西洋的女子。"}},{"en":"the quality of being excellent or important","cn":"优秀；杰出；卓越","g":"[uncountable]","ex":{"en":"a writer of distinction","cn":"优秀作家"}},{"en":"a special mark or award that is given to somebody, especially a student, for excellent work","cn":"（尤指给学生的）优等评分，荣誉，奖赏","g":"[countable, uncountable]","ex":{"en":"Naomi got a distinction in maths.","cn":"娜奥米的数学得了优等。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"分别;差别;不同","en":"A distinction between similar things is a difference.","ex":{"en":"There are obvious distinctions between the two wine-making areas","cn":"两个酿酒地区之间有着显著的差别。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"卓越;杰出;优秀","en":"Distinction is the quality of being very good or better than other things of the same type.","ex":{"en":"Lewis emerges as a composer of distinction and sensitivity.","cn":"刘易斯作为一位悟性很高的优秀作曲家崭露头角。"}},{"pos":"N-COUNT 可数名词","cn":"特殊奖励;荣誉;光荣","en":"A distinction is a special award or honour that is given to someone because of their very high level of achievement.","ex":{"en":"The order was created in 1902 as a special distinction for eminent men and women","cn":"该勋位设立于1902年，作为一项殊荣授予杰出的男性和女性。"}},{"pos":"N-SING 单数名词","cn":"特质;特点","en":"If you say that someone or something has the distinction of being something, you are drawing attention to the fact that they have the special quality of being that thing. Distinction is normally used to refer to good qualities, but can sometimes also be used to refer to bad qualities.","ex":{"en":"He has the distinction of being regarded as the Federal Republic's greatest living writer.","cn":"他才华横溢，被誉为联邦共和国目前尚在世的最伟大的作家。"}}]},"examples":[{"en":"Philosophers did not use to make a distinction between arts and science.","cn":"哲学家过去习惯不把艺术和科学区别开来。"},{"en":"She had the distinction of being the first woman to fly the Atlantic.","cn":"她不同凡响，是第一个飞越大西洋的女子。"}]},"distrust":{"media":{"uk":"media/uk/distrust__gb_1.mp3","us":"media/us/distrust__us_1.mp3"},"oxford":{"phon":"dɪsˈtrʌst","pos":"noun","senses":[{"en":"a feeling of not being able to trust somebody/something","cn":"不信任；怀疑","ex":{"en":"They looked at each other with distrust.","cn":"他们心怀戒备地看着对方。"}},{"en":"to feel that you cannot trust or believe somebody/something","cn":"不信任；怀疑","ex":{"en":"She distrusted his motives for wanting to see her again.","cn":"她怀疑他想再见她一面是别有用心。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"不信任;怀疑","en":"If you distrust someone or something, you think they are not honest, reliable, or safe.","ex":{"en":"I don't have any particular reason to distrust them.","cn":"我没有任何特别的理由怀疑他们。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"不信任;怀疑","en":"Distrust is the feeling of doubt that you have towards someone or something you distrust.","ex":{"en":"What he saw there left him with a profound distrust of all political authority.","cn":"他在那儿的所见让他对一切政治当局产生了一种深深的不信任感。"}}]},"examples":[{"en":"She distrusted his motives for wanting to see her again.","cn":"她怀疑他想再见她一面是别有用心。"},{"en":"They looked at each other with distrust.","cn":"他们心怀戒备地相互看着对方。"}]},"disaster":{"media":{"uk":"media/uk/disaster__gb_1.mp3","us":"media/us/disaster__us_1.mp3"},"oxford":{"phon":"dɪˈzɑːstə(r)","pos":"noun","senses":[{"en":"an unexpected event, such as a very bad accident, a flood or a fire, that kills a lot of people or causes a lot of damage","cn":"灾难；灾祸；灾害","g":"[countable]","ex":{"en":"the world's worst humanitarian disaster","cn":"世界上最严重的人道主义灾难"}},{"en":"a very bad situation that causes problems","cn":"不幸；祸患","g":"[countable, uncountable]","ex":{"en":"Losing your job doesn't have to be such a disaster.","cn":"丢了工作不一定就是大难临头。"}},{"en":"a complete failure","cn":"彻底失败的人（或事）","g":"[countable]","lab":"informal","ex":{"en":"As a teacher, he's a disaster.","cn":"他当老师压根儿就不称职。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(尤指伤亡惨重的)灾难，灾祸(如地震、坠机等)","en":"A disaster is a very bad accident such as an earthquake or a plane crash, especially one in which a lot of people are killed.","ex":{"en":"It was the second air disaster in the region in less than two months","cn":"这已经是该地区不到两个月内的第二次空难了。"}},{"pos":"N-COUNT 可数名词","cn":"非常糟糕的事;彻底的失败;不幸","en":"If you refer to something as a disaster, you are emphasizing that you think it is extremely bad or unacceptable.","ex":{"en":"The whole production was just a disaster!","cn":"整个产品简直就是一个败笔！"}},{"pos":"N-UNCOUNT 不可数名词","cn":"灾祸;祸患","en":"Disaster is something which has very bad consequences for you.","ex":{"en":"The government brought itself to the brink of fiscal disaster","cn":"政府把自己推向了财政危机的边缘。"}},{"pos":"PHRASE 短语","cn":"没有什么好结果；后患无穷","en":"If you say that something is a recipe for disaster, you mean that it is very likely to have unpleasant consequences."}]},"examples":[{"en":"Letting her organize the party is a recipe for disaster (= something that is likely to go badly wrong).","cn":"让她来组织这次聚会非坏事不可。"},{"en":"Losing your job doesn't have to be such a disaster.","cn":"丢了工作不一定就是大难临头。"}]},"diamond":{"oxford":{"phon":"ˈdaɪmənd","pos":"noun","senses":[{"en":"a clear precious stone of pure carbon, the hardest substance known. Diamonds are used in jewellery and also in industry, especially for cutting glass.","cn":"金刚石；钻石","g":"[uncountable, countable]","ex":{"en":"a diamond ring/necklace","cn":"钻石戒指／项链"}},{"en":"a shape with four straight sides of equal length and with angles that are not right angles","cn":"菱形","g":"[countable]","ex":{"en":"a sweater with a diamond pattern","cn":"有菱形图案的套头衫"}},{"en":"one of the four suits (= sets) in a pack of cards. The cards are marked with red diamond shapes.","cn":"（扑克牌的）方块","g":"[plural, uncountable]","ex":{"en":"the ten of diamonds","cn":"方块十"}},{"en":"one card from the suit called diamonds","cn":"（扑克牌的）方块","g":"[countable]","ex":{"en":"You must play a diamond if you have one.","cn":"如果你有方块就必须出。"}},{"en":"the space inside the lines that connect the four bases; also used to mean the whole baseball field","cn":"内场；棒球场","g":"[countable]"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"金刚石;钻石","en":"A diamond is a hard, bright, precious stone which is clear and colourless. Diamonds are used in jewellery and for cutting very hard substances.","ex":{"en":"...a pair of diamond earrings.","cn":"一对钻石耳环"}},{"pos":"N-PLURAL 复数名词","cn":"钻石首饰;钻石饰物","en":"Diamonds are jewellery such as necklaces and rings which have diamonds set into them.","ex":{"en":"Nicole loves wearing her diamonds, even with jeans and a white T-shirt.","cn":"妮科尔很喜欢戴她的钻石首饰，即使穿的是牛仔裤和白色T恤衫。"}},{"pos":"N-COUNT 可数名词","cn":"◇. 菱形","en":"A diamond is a shape with four straight sides of equal length where the opposite angles are the same, but none of the angles is equal to 90˚:","ex":{"en":"He formed his hands into the shape of a diamond.","cn":"他双手合成菱形。"}},{"pos":"N-UNCOUNT-COLL 不可数集合名词","cn":"(纸牌中四种花色之一的)方块","en":"Diamonds is one of the four suits of cards in a pack of playing cards. Each card in the suit is marked with one or more red symbols in the shape of a diamond.","ex":{"en":"He drew the seven of diamonds.","cn":"他摸了一张方块 7。"}},{"pos":"N-COUNT 可数名词","cn":"(棒球场的)内场","en":"In baseball, the diamond is the diamond-shaped area of the playing field between the four bases."}]},"media":{"uk":"media/uk/diamond__gb_1.mp3","us":"media/us/diamond__us_1.mp3"},"examples":[{"en":"The lights shone like diamonds.","cn":"灯光像钻石一样闪闪发亮。"},{"en":"You must play a diamond if you have one.","cn":"如果你有方块就必须出。"}]},"dignity":{"media":{"uk":"media/uk/dignity__gb_1.mp3","us":"media/us/dignity__us_1.mp3"},"oxford":{"phon":"ˈdɪɡnəti","pos":"noun","senses":[{"en":"a calm and serious manner that deserves respect","cn":"庄重；庄严；尊严","g":"[uncountable, singular]","ex":{"en":"She accepted the criticism with quiet dignity.","cn":"她大度地接受了批评。"}},{"en":"the fact of being given honour and respect by people","cn":"尊贵；高贵；高尚","g":"[uncountable]","ex":{"en":"the dignity of work","cn":"工作的光荣"}},{"en":"a sense of your own importance and value","cn":"自豪；自尊；自重","g":"[uncountable]","ex":{"en":"It's difficult to preserve your dignity when you have no job and no home.","cn":"一个无家无业的人难以保持自己的尊严。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"庄严;庄重;端庄","en":"If someone behaves or moves with dignity, they are calm, controlled, and admirable.","ex":{"en":"...her extraordinary dignity and composure.","cn":"她那种端庄沉着的非凡气质"}},{"pos":"N-UNCOUNT 不可数名词","cn":"尊贵;高贵;高尚","en":"If you talk about the dignity of people or their lives or activities, you mean that they are valuable and worthy of respect.","ex":{"en":"...the sense of human dignity.","cn":"人的高尚感"}},{"pos":"N-UNCOUNT 不可数名词","cn":"尊严;自尊","en":"Your dignity is the sense that you have of your own importance and value, and other people's respect for you.","ex":{"en":"If you were wrong, admit it. You won't lose dignity, but will gain respect","cn":"如果你错了，那就承认。你不会因此而失去尊严，反而会赢得尊重。"}}]},"examples":[{"en":"It's difficult to preserve your dignity when you have no job and no home.","cn":"一个无家无业的人难以保持自己的尊严。"},{"en":"The terminally ill should be allowed to die with dignity.","cn":"应该允许垂危病人死得有尊严。"}]},"disagreement":{"oxford":{"phon":"ˌdɪsəˈɡriːmənt","pos":"noun","senses":[{"en":"a situation where people have different opinions about something and often argue","cn":"意见不一；分歧；争论","g":"[uncountable, countable]","ex":{"en":"Disagreement arose about exactly how to plan the show.","cn":"在如何拟订具体演出计划的问题上出现了分歧。"}},{"en":"a difference between two things that should be the same","cn":"不符；不一致","g":"[uncountable, countable]","ex":{"en":"The comparison shows considerable disagreement between theory and practice.","cn":"这一对比表明理论和实践之间有相当大的出入。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"异议;反对意见","en":"Disagreement means objecting to something such as a proposal.","ex":{"en":"Britain and France have expressed some disagreement with the proposal.","cn":"英国和法国对这项提案已经发表了一些反对意见。"}},{"pos":"N-VAR 可变名词","cn":"争执;意见不合","en":"When there is disagreement about something, people disagree or argue about what should be done.","ex":{"en":"The United States Congress and the President are still locked in disagreement over proposals to reduce the massive budget deficit","cn":"美国国会和总统就削减巨额预算赤字的提案仍持不同意见，双方僵持不下。"}}]},"media":{"uk":"media/uk/disagreement__gb_1.mp3","us":"media/us/disagreement__us_1.mp3"},"examples":[{"en":"Disagreement arose about exactly how to plan the show.","cn":"在如何拟订具体演出计划的问题上出现了分歧。"},{"en":"The comparison shows considerable disagreement between theory and practice.","cn":"这一对比表明理论和实践之间有相当大的差距。"}]},"displacement":{"oxford":{"phon":"dɪsˈpleɪsmənt","pos":"noun","senses":[{"en":"the act of forcing somebody/something away from their home or position","cn":"迫使流亡；迫使迁移；移位","lab":"formal","ex":{"en":"the largest displacement of civilian population since World War Two","cn":"自第二次世界大战以来最大规模的平民迁移"}},{"en":"the amount of a liquid moved out of place by something floating or put in it, especially a ship floating in water","cn":"排水量","g":"[countable]","lab":"physics","ex":{"en":"a ship with a displacement of 10 000 tonnes","cn":"排水量为 1 万吨的船"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"取代;代替","en":"Displacement is the removal of something from its usual place or position by something which then occupies that place or position.","ex":{"en":"...the displacement of all my energy into caring for the baby.","cn":"我所有精力都放在了照顾宝宝上"}},{"pos":"N-UNCOUNT 不可数名词","cn":"迫使迁徙;迫使背井离乡","en":"Displacement is the forcing of people away from the area or country where they live.","ex":{"en":"...the gradual displacement of the American Indian.","cn":"美洲印第安人被迫逐渐迁徙"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(船的)排量,排水量","en":"Displacement is the weight or volume of a liquid that is displaced by an object under the surface or floating on it, for example the weight of water displaced by a ship."}]},"media":{"uk":"media/uk/displacement__gb_1.mp3","us":"media/us/displacement__us_1.mp3"},"examples":[{"en":"the largest displacement of civilian population since World War Two","cn":"自第二次世界大战以来最大规模的平民迁移"},{"en":"a ship with a displacement of 10 000 tonnes","cn":"排水量为 1 万吨的船"}]},"discriminatory":{"media":{"uk":"media/uk/discriminatory__gb_1.mp3","us":"media/us/discriminatory__us_1.mp3"},"oxford":{"phon":"dɪˈskrɪmɪnətəri","pos":"adjective","senses":[{"en":"unfair; treating somebody or one group of people worse than others","cn":"区别对待的；不公正的；歧视的","ex":{"en":"discriminatory practices/rules/measures","cn":"不公正的做法／规定／措施"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（法规、做法）不公平的，歧视的","en":"Discriminatory laws or practices are unfair because they treat one group of people worse than other groups.","ex":{"en":"These reforms will abolish racially discriminatory laws.","cn":"这些改革措施将彻底废除带有种族歧视的法律。"}}]},"examples":[{"en":"discriminatory practices/rules/measures","cn":"不公正的做法/规定/措施"},{"en":"sexually/racially discriminatory laws","cn":"性别/种族歧视性法律"}]},"directly":{"media":{"uk":"media/uk/directly__gb_1.mp3","us":"media/us/directly__us_1.mp3"},"oxford":{"phon":"dəˈrektli","pos":"adverb","senses":[{"en":"without stopping or changing direction","cn":"直接；径直","ex":{"en":"The path leads directly to the river.","cn":"这条小路直接通向那条河。"}},{"en":"with nobody or nothing in between","cn":"直接的；无中间人（或物）的","ex":{"en":"She speaks directly to camera.","cn":"她直接对着镜头说话。"}},{"en":"exactly in a particular position","cn":"正；正好地；恰好","ex":{"en":"directly opposite/below/ahead","cn":"正对面；正下方；正前方"}},{"en":"immediately","cn":"立即；立刻；马上","ex":{"en":"She left directly after the show.","cn":"演出一结束，她马上就走了。"}},{"en":"soon","cn":"过一会儿；很快","lab":"British English, old-fashioned，，","ex":{"en":"Tell them I'll be there directly.","cn":"告诉他们我一会儿就到。"}},{"en":"as soon as","cn":"一…就…","ex":{"en":"I went home directly I had finished work.","cn":"我一干完活就回家了。"},"pos":"conjunction"}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"直接地;正好地","en":"If something is directly above, below, or in front of something, it is in exactly that position.","ex":{"en":"The second rainbow will be bigger than the first, and directly above it","cn":"第二道彩虹将比第一道还要大，而且正好位于其上。"}},{"pos":"ADV 副词","cn":"径直地;紧跟地","en":"If you do one action directly after another, you do the second action as soon as the first one is finished.","ex":{"en":"Directly after the meeting, a senior cabinet minister spoke to the BBC","cn":"会议刚刚结束，一名高级内阁部长就在英国广播公司的电台上发表了讲话。"}},{"pos":"ADV 副词","cn":"立刻;马上","en":"If something happens directly, it happens without any delay.","ex":{"en":"He will be there directly.","cn":"他马上就到那儿。"}}]},"examples":[{"en":"He drove her directly to her hotel.","cn":"他驾车直接把她送到了她下榻的旅馆。"},{"en":"We have not been directly affected by the cuts.","cn":"我们并未直接受到裁减的影响。"}]},"diarrhoea":{"oxford":{"phon":"ˌdaɪəˈrɪə","pos":"noun","senses":[{"en":"an illness in which waste matter is emptied from the bowels much more frequently than normal, and in liquid form","cn":"腹泻","ex":{"en":"Symptoms include diarrhoea and vomiting.","cn":"症状有腹泻和呕吐。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"腹泻","en":"If someone has diarrhoea, a lot of liquid faeces comes out of their body because they are ill."}]},"media":{"uk":"media/uk/diarrhoea__gb_1.mp3","us":"media/us/diarrhoea__us_1.mp3"},"examples":[{"en":"Symptoms include diarrhoea and vomiting.","cn":"症状有腹泻和呕吐。"}]},"dissidence":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who publicly criticizes the government in a country where this is punished","cn":""}]},"media":{"uk":"media/uk/dissidence__gb_1.mp3","us":"media/us/dissidence__us_1.mp3"},"oxford":{"phon":"ˈdɪsɪdəns","pos":"noun","senses":[{"en":"the act of strongly disagreeing with and criticizing your government, especially in a country where this kind of action is dangerous","cn":"持不同政见者"}]}},"discouraging":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if something shakes or damages someone's confidence , it makes them feel unsure of their abilities and less confident","cn":""},{"en":"making people feel that they cannot be successful at something they are trying to do, so that they become unwilling to continue with it","cn":""}]},"examples":[{"en":"The results were discouraging.","cn":"结果让人泄气。","src":"ld"}],"media":{"uk":"media/uk/discouraging__gb_1.mp3","us":"media/us/discouraging__us_1.mp3"},"oxford":{"phon":"dɪsˈkʌrɪdʒɪŋ","pos":"adjective","senses":[{"en":"making you feel less confident or enthusiastic about doing something","cn":"令人沮丧的","ex":{"en":"a discouraging experience/response/result","cn":"令人灰心的经历／答复／结果"}}]},"base":"discourage"},"different":{"media":{"uk":"media/uk/different__gb_1.mp3","us":"media/us/different__us_1.mp3"},"oxford":{"phon":"ˈdɪfrənt","pos":"adjective","senses":[{"en":"not the same as somebody/something; not like somebody/something else","cn":"不同的；有区别的；有差异的","lab":"especially British English","ex":{"en":"American English is significantly different from British English.","cn":"美式英语与英式英语有很大差异。"}},{"en":"separate and individual","cn":"分别的；各别的；各种的","g":"[only before noun]","ex":{"en":"Each chapter deals with a different type of business.","cn":"每一章讲述一种不同的业务。"}},{"en":"unusual; not like other people or things","cn":"不平常；与众不同；别致","g":"[not usually before noun]","lab":"informal","ex":{"en":"‘Did you enjoy the play?’ ‘Well, it was certainly different!’","cn":"“你喜欢这出戏吗？”“哦，的确不同凡响！”"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有差别的;不同的","en":"If two people or things are different, they are not like each other in one or more ways.","ex":{"en":"London was different from most European capitals","cn":"伦敦同大多数欧洲国家的首都都有所不同。"}},{"pos":"ADJ 形容词","cn":"分别的;个别的;各种的","en":"You use different to indicate that you are talking about two or more separate and distinct things of the same kind.","ex":{"en":"Different countries specialised in different products","cn":"不同国家专门生产不同的产品。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不同寻常的;与众不同的","en":"You can describe something as different when it is unusual and not like others of the same kind.","ex":{"en":"This recipe is certainly interesting and different.","cn":"这种烹饪法的确很有意思而且与众不同。"}}]},"examples":[{"en":"‘Did you enjoy the play?’ ‘Well, it was certainly different!’ “","cn":"你喜欢这出戏吗？” “哦，的确不同凡响！”"},{"en":"People often give very different accounts of the same event.","cn":"人们常常对同一件事有非常不同的叙述。"}]},"disgusts":{"lemma":"disgust","media":{"uk":"media/uk/disgust__gb_1.mp3","us":"media/us/disgust__us_1.mp3"}},"differently":{"oxford":{"phon":"ˈdɪfrəntli","pos":"adverb","senses":[{"en":"in a different way from somebody/something","cn":"不同地；有区别地；有差异地","ex":{"en":"Boys and girls may behave differently.","cn":"男孩儿和女孩儿的表现可能不同。"}}]},"media":{"uk":"media/uk/differently__gb_1.mp3","us":"media/us/differently__us_1.mp3"},"examples":[{"en":"Boys and girls may behave differently.","cn":"男孩儿和女孩儿的表现可能不同。"},{"en":"The male bird has a differently shaped head.","cn":"雄鸟的头形有点特别。"}]},"divorced":{"media":{"uk":"media/uk/divorced__gb_1.mp3","us":"media/us/divorced__us_1.mp3"},"oxford":{"phon":"dɪˈvɔːst","pos":"adjective","senses":[{"en":"no longer married because your marriage has been legally ended","cn":"离婚的；离异的","lab":"especially North American English","ex":{"en":"My parents are divorced.","cn":"我的父母离婚了。"}},{"en":"appearing not to be affected by something; separate from something","cn":"表现得不受影响的；脱离…的","lab":"formal","ex":{"en":"He seems completely divorced from reality.","cn":"他似乎完全脱离了现实。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"离婚的;离异的","en":"Someone who is divorced from their former husband or wife has separated from them and is no longer legally married to them.","ex":{"en":"Princess Margaret is divorced from Lord Snowdon","cn":"玛格丽特公主与斯诺登勋爵离婚了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"脱离…的;与…完全不一样的","en":"If you say that one thing is divorced from another, you mean that the two things are very different and separate from each other.","ex":{"en":"...speculative theories divorced from political reality.","cn":"与政治事实相脱离的投机理论"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不受…影响的;置身世外的","en":"If you say that someone is divorced from a situation, you mean that they act as if they are not affected by it in any way.","ex":{"en":"This just shows how divorced from reality she's become.","cn":"这恰恰说明了她变得多么不切实际。"}}]},"examples":[{"en":"Many divorced men remarry and have second families.","cn":"许多离婚的男子再婚组成了新的家庭。"},{"en":"He seems completely divorced from reality.","cn":"他似乎完全脱离了现实。"}],"base":"divorce"},"discussions":{"lemma":"discussion","media":{"uk":"media/uk/discussion__gb_1.mp3","us":"media/us/discussion__us_1.mp3"}},"discontent":{"media":{"uk":"media/uk/discontent__gb_1.mp3","us":"media/us/discontent__us_1.mp3"},"oxford":{"phon":"ˌdɪskənˈtent","pos":"noun","senses":[{"en":"a feeling of being unhappy because you are not satisfied with a particular situation; something that makes you have this feeling","cn":"不满；不满足；不满足的缘由","lab":"formal","ex":{"en":"There is widespread discontent among the staff at the proposed changes to pay and conditions.","cn":"员工对改变工资和工作环境的建议普遍不满。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"不满;不满意","en":"Discontent is the feeling that you have when you are not satisfied with your situation.","ex":{"en":"There are reports of widespread discontent in the capital.","cn":"有报道称首都弥漫着不满的情绪。"}}]},"examples":[{"en":"There is widespread discontent among the staff at the proposed changes to pay and conditions.","cn":"员工对改变工资和环境的建议普遍不满。"},{"en":"Discontent with the current government is strong.","cn":"对现任政府的不满情绪很强烈。"}]},"dividing":{"lemma":"divide"},"diesel":{"oxford":{"phon":"ˈdiːzl","pos":"noun","senses":[{"en":"a type of heavy oil used as a fuel instead of petrol","cn":"柴油","g":"[uncountable]","ex":{"en":"a diesel engine (= one that burns diesel)","cn":"柴油机"}},{"en":"a vehicle that uses diesel fuel","cn":"柴油车；内燃机车","g":"[countable]","ex":{"en":"Our new car is a diesel.","cn":"我们的新车是柴油车。"}}]},"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"柴油","en":"Diesel or diesel oil is the heavy oil used in a diesel engine."},{"pos":"N-COUNT 可数名词","cn":"柴油车;内燃机车","en":"A diesel is a vehicle which has a diesel engine."}]},"media":{"uk":"media/uk/diesel__gb_1.mp3","us":"media/us/diesel__us_1.mp3"},"examples":[{"en":"Our new car is a diesel.","cn":"我们的新车是柴油车。"},{"en":"a diesel engine (= one that burns diesel )","cn":"柴油发动机"}]},"display":{"media":{"uk":"media/uk/display__gb_1.mp3","us":"media/us/display__us_1.mp3"},"oxford":{"phon":"dɪˈspleɪ","pos":"verb","senses":[{"en":"to put something in a place where people can see it easily; to show something to people","cn":"陈列；展出；展示","g":"[transitive]","ex":{"en":"The exhibition gives local artists an opportunity to display their work.","cn":"这次展览为当地艺术家提供了展示自己作品的机会。"}},{"en":"to show a quality, feeling, skill or type of behaviour; to show signs of something","cn":"显示，显露，表现（特性、情感、技能、行为等）","g":"[transitive]","ex":{"en":"I have rarely seen her display any sign of emotion.","cn":"我难得见到她将喜怒形于色。"}},{"en":"to show information","cn":"显示","g":"[transitive]","ex":{"en":"Giant screens displayed images of cheering crowds.","cn":"大屏幕上显示的是欢呼人群的画面。"}},{"en":"to show a special pattern of behaviour that is intended to attract a female bird or animal","cn":"（为求偶）炫耀","g":"[intransitive]","lab":"specialist"},{"en":"an arrangement of things in a public place to inform or entertain people or advertise something for sale","cn":"陈列；展览","g":"[countable]","ex":{"en":"a beautiful floral display","cn":"美丽的花卉展览"},"pos":"noun"},{"en":"an act of performing a skill or of showing something happening, in order to entertain","cn":"展示；表演","g":"[countable]","ex":{"en":"They put on a spectacular firework display.","cn":"他们举行了场面壮观的烟花燃放。"},"pos":"noun"},{"en":"an occasion when you show a particular quality, feeling or ability by the way that you behave","cn":"（特性、情感或能力的）显示，表现，表露","g":"[countable]","ex":{"en":"a display of affection/emotion/skill","cn":"爱／情感的流露；才能的展示"},"pos":"noun"},{"en":"the words, pictures, etc. shown on a computer screen; the process of showing words, pictures, etc. on a computer screen","cn":"（计算机屏幕上的）显示，显像","g":"[countable, uncountable]","ex":{"en":"a high resolution colour display","cn":"高分辨率彩色显示"},"pos":"noun"},{"en":"an electronic device for presenting words, pictures, etc.","cn":"显示器","g":"[countable]","ex":{"en":"The colour display now costs £400.","cn":"彩色显示器现在的价格是 400 英镑。"},"pos":"noun"},{"en":"a special pattern of behaviour by male birds and animals of some species that is intended to attract a female bird or animal","cn":"（为求偶）炫耀","g":"[countable]","lab":"specialist","ex":{"en":"Males perform courtship displays to attract mates.","cn":"雄性进行求偶炫耀以吸引配偶。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"展示;展览;陈列","en":"If you display something that you want people to see, you put it in a particular place, so that people can see it easily.","ex":{"en":"Among the protesters and war veterans proudly displaying their medals was Aubrey Rose","cn":"在抗议者和骄傲地展示勋章的退伍老兵中，就有奥布里·罗斯。"}},{"pos":"VERB 动词","cn":"展现;展示","en":"If you display something, you show it to people.","ex":{"en":"She displayed her wound to the twelve gentlemen of the jury","cn":"她给陪审团的 12 位男士看了她的伤口。"}},{"pos":"VERB 动词","cn":"显示，显露，表现(特性或情感)","en":"If you display a characteristic, quality, or emotion, you behave in a way which shows that you have it.","ex":{"en":"It was unlike Gordon to display his feelings","cn":"戈登不太可能表露他的情感。"}},{"pos":"VERB 动词","cn":"(计算机)显示","en":"When a computer displays information, it shows it on a screen.","ex":{"en":"They started out by looking at the computer screens which display the images","cn":"他们开始在显示那些图像的电脑屏幕上寻找。"}},{"pos":"N-COUNT 可数名词","cn":"展示;展览;陈列","en":"A display is an arrangement of things that have been put in a particular place, so that people can see them easily.","ex":{"en":"...a display of your work","cn":"你的成果展示"}},{"pos":"N-COUNT 可数名词","cn":"表演","en":"A display is a public performance or other event which is intended to entertain people.","ex":{"en":"...the firework display.","cn":"烟火表演"}},{"pos":"N-COUNT 可数名词","cn":"(计算机屏幕上的)显示，显像;显示器","en":"The display on a computer screen is the information that is shown there. The screen itself can also be referred to as the display .","ex":{"en":"A hard copy of the screen display can also be obtained from a printer.","cn":"屏幕上显示的内容也可以通过打印机打印一份。"}}]},"examples":[{"en":"The exhibition gives local artists an opportunity to display their work.","cn":"这次展览为当地艺术家提供了展示自己作品的机会。"},{"en":"She displayed her bruises for all to see.","cn":"她将自己身上青一块紫一块的伤痕露出来给大家看。"}]},"dialect":{"oxford":{"phon":"ˈdaɪəlekt","pos":"noun","senses":[{"en":"the form of a language that is spoken in one area with grammar, words and pronunciation that may be different from other forms of the same language","cn":"地方话；土话；方言","ex":{"en":"the Yorkshire dialect","cn":"约克郡方言"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"方言;地方话;土话","en":"A dialect is a form of a language that is spoken in a particular area.","ex":{"en":"In the fifties, many Italians spoke only local dialect","cn":"在 20 世纪 50 年代，许多意大利人只会说当地方言。"}}]},"media":{"uk":"media/uk/dialect__gb_1.mp3","us":"media/us/dialect__us_1.mp3"},"examples":[{"en":"the Yorkshire dialect","cn":"约克郡方言"}]},"disciplines":{"lemma":"discipline","media":{"uk":"media/uk/discipline__gb_1.mp3","us":"media/us/discipline__us_1.mp3"}},"disaffected":{"media":{"uk":"media/uk/disaffected__gb_1.mp3","us":"media/us/disaffected__us_1.mp3"},"oxford":{"phon":"ˌdɪsəˈfektɪd","pos":"adjective","senses":[{"en":"no longer satisfied with your situation, organization, belief, etc. and therefore no longer supporting it","cn":"心怀不满的","ex":{"en":"Some disaffected members left to form a new party.","cn":"部分不满的成员已脱党另立新党。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(对曾经支持过的组织或政治信仰)不再支持的，不满的，不忠的","en":"Disaffected people no longer fully support something such as an organization or political ideal which they previously supported.","ex":{"en":"He attracts disaffected voters","cn":"他吸引了心怀不满的选民们。"}}]},"examples":[{"en":"Some disaffected members left to form a new party.","cn":"部分不满的成员已脱党另立新党。"},{"en":"There are signs of growing disaffection amongst voters.","cn":"选民中出现日渐不满的迹象。"}]},"direction":{"media":{"uk":"media/uk/direction__gb_1.mp3","us":"media/us/direction__us_1.mp3"},"oxford":{"phon":"dəˈrekʃn","pos":"noun","senses":[{"en":"the general position a person or thing moves or points towards","cn":"方向；方位","g":"[countable, uncountable]","sc":"where to","ex":{"en":"They headed in the direction of the village.","cn":"他们朝村子的方向走去。"}},{"en":"instructions about how to do something, where to go, etc.","cn":"用法说明；操作指南；旅行指南","g":"[countable, usually plural]","sc":"instructions","ex":{"en":"Let's stop and ask for directions.","cn":"咱们停下来问问路吧。"}},{"en":"the general way in which a person or thing develops","cn":"趋势；动向","g":"[countable, uncountable]","sc":"development","ex":{"en":"The exhibition provides evidence of several new directions in her work.","cn":"这个展览表明她的创作有几个新动向。"}},{"en":"the general position a person or thing comes or develops from","cn":"方面","g":"[countable]","sc":"where from","ex":{"en":"Support came from an unexpected direction.","cn":"一个出人意料的来源提供了帮助。"}},{"en":"a purpose; an aim","cn":"目的；目标","g":"[uncountable]","sc":"purpose","ex":{"en":"We are looking for somebody with a clear sense of direction.","cn":"我们想找一个有明确目标的人。"}},{"en":"the art of managing or guiding somebody/something","cn":"管理；指导","g":"[uncountable]","sc":"control","ex":{"en":"She was entrusted with the direction of the project.","cn":"她受委托负责这项计划。"}},{"en":"the instructions given by somebody directing a film or play","cn":"（电影或戏剧导演的）指点，指导","g":"[uncountable]","sc":"film/movie","ex":{"en":"There is some clever direction and the film is very well shot.","cn":"由于导演指导有方，影片拍得非常成功。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"方向;方位","en":"A direction is the general line that someone or something is moving or pointing in.","ex":{"en":"St Andrews was ten miles in the opposite direction","cn":"圣安德鲁斯在相反方向上 10 英里处。"}},{"pos":"N-VAR 可变名词","cn":"（发展）方向，趋势，倾向","en":"A direction is the general way in which something develops or progresses.","ex":{"en":"They threatened to walk out if the party did not change direction","cn":"他们威胁说，如果该党不改变方针，他们就将集体退席。"}},{"pos":"N-PLURAL 复数名词","cn":"指示;说明;指路","en":"Directions are instructions that tell you what to do, how to do something, or how to get somewhere.","ex":{"en":"I should know by now not to throw away the directions until we've finished cooking","cn":"现在我知道了不该在饭没做完之前就扔掉烹饪说明。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(影片、戏剧或电视节目的)导演","en":"The direction of a film, play, or television programme is the work that the director does while it is being made.","ex":{"en":"His failures underline the difference between theatre and film direction.","cn":"他的失败说明了导演戏剧和电影是不同的。"}}]},"examples":[{"en":"All work was produced by the students under the direction of John Williams.","cn":"所有作品都是在约翰 · 威廉斯的指导下由学生创作完成的。"},{"en":"It's only a small improvement, but at least it's a step in the right direction.","cn":"虽然这只是小小的改进，但至少是朝正确方向迈出的一步。"}]},"dismantle":{"media":{"uk":"media/uk/dismantle__gb_1.mp3","us":"media/us/dismantle__us_1.mp3"},"oxford":{"phon":"dɪsˈmæntl","pos":"verb","senses":[{"en":"to take apart a machine or structure so that it is in separate pieces","cn":"拆开，拆卸（机器或结构）","ex":{"en":"I had to dismantle the engine in order to repair it.","cn":"我得把发动机拆开来修理。"}},{"en":"to end an organization or a system gradually in an organized way","cn":"（逐渐）废除，取消","ex":{"en":"The government was in the process of dismantling the state-owned industries.","cn":"政府正在着手逐步取消国有企业。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"拆卸;拆开;拆除","en":"If you dismantle a machine or structure, you carefully separate it into its different parts.","ex":{"en":"He asked for immediate help from the United States to dismantle the warheads.","cn":"他请求美国立即提供援助，拆除这批弹头。"}},{"pos":"VERB 动词","cn":"（逐渐）废除，撤销，破坏","en":"To dismantle an organization or system means to cause it to stop functioning by gradually reducing its power or purpose.","ex":{"en":"...opposition to the president's policy of dismantling apartheid","cn":"反对总统废除种族隔离的政策"}}]},"examples":[{"en":"The government was in the process of dismantling the state-owned industries.","cn":"政府正在着手逐步废除国有企业。"},{"en":"I had to dismantle the engine in order to repair it.","cn":"我得把发动机拆开来修理。"}]},"dizzy":{"media":{"uk":"media/uk/dizzy__gb_1.mp3","us":"media/us/dizzy__us_1.mp3"},"oxford":{"phon":"ˈdɪzi","pos":"adjective","senses":[{"en":"feeling as if everything is turning around you and that you are not able to balance","cn":"头晕目眩的；眩晕的","ex":{"en":"Climbing so high made me feel dizzy.","cn":"爬那么高使我感到头晕目眩。"}},{"en":"making you feel dizzy; making you feel that a situation is changing very fast","cn":"使人眩晕的；使人头昏眼花的；使人感到变化太快的","ex":{"en":"the dizzy descent from the summit","cn":"从山顶陡然而下，令人目眩"}},{"en":"silly or stupid","cn":"愚蠢的；笨的","lab":"especially North American English, informal，，","ex":{"en":"a dizzy blonde","cn":"金发傻妞"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"头晕目眩的;眩晕的","en":"If you feel dizzy, you feel that you are losing your balance and are about to fall.","ex":{"en":"Her head still hurt, and she felt slightly dizzy and disoriented","cn":"她的头还痛，并且觉得有些晕头转向。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(指女子)粗心的，没记性的，大大咧咧的","en":"You can use dizzy to describe a woman who is careless and forgets things, but is easy to like.","ex":{"en":"She is famed for playing dizzy blondes.","cn":"她以扮演金发傻妞而闻名。"}},{"pos":"VERB 动词","cn":"使眩晕;使困惑;使晕头转向","en":"If something dizzies you, it causes you to feel unsteady or confused.","ex":{"en":"The sudden height dizzied her and she clung tightly.","cn":"突然上升的高度让她晕头转向，她抓得紧紧的。"}},{"pos":"PHRASE 短语","cn":"重要的职位;显赫的地位","en":"If you say that someone has reached the dizzy heights of something, you are emphasizing that they have reached a very high level by achieving it.","ex":{"en":"I escalated to the dizzy heights of director's secretary.","cn":"我升到了总经理秘书这一显赫高位。"}}]},"examples":[{"en":"the dizzy descent from the summit","cn":"从山顶陡然而下令人目眩的山坡"},{"en":"Climbing so high made me feel dizzy.","cn":"爬那么高使我感到头晕目眩。"}]},"distinguished":{"media":{"uk":"media/uk/distinguished__gb_1.mp3","us":"media/us/distinguished__us_1.mp3"},"oxford":{"phon":"dɪˈstɪŋɡwɪʃt","pos":"adjective","senses":[{"en":"very successful and admired by other people","cn":"卓越的；杰出的；著名的","ex":{"en":"He has had a long and distinguished career in medicine.","cn":"他从医时间长，成就卓越。"}},{"en":"having an appearance that makes somebody look important or that makes people admire or respect them","cn":"显得重要的；高贵的；有尊严的","ex":{"en":"I think grey hair makes you look very distinguished.","cn":"我认为灰白的头发使你看上去特别可敬。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"卓越的;杰出的;著名的","en":"If you describe a person or their work as distinguished, you mean that they have been very successful in their career and have a good reputation.","ex":{"en":"...a distinguished academic family.","cn":"杰出的学者之家"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"高贵的;尊贵的;高尚的","en":"If you describe someone as distinguished, you mean that they look very noble and respectable.","ex":{"en":"He looked very distinguished.","cn":"他看上去非常高贵。"}}]},"examples":[{"en":"I think grey hair makes you look very distinguished.","cn":"我认为灰白的头发使你看上去很有尊严。"},{"en":"a distinguished career in medicine","cn":"在医学领域的辉煌生涯"}],"base":"distinguish"},"dispute":{"oxford":{"phon":"dɪˈspjuːt","pos":"noun","senses":[{"en":"an argument between two people, groups or countries; discussion about a subject on which people disagree","cn":"争论；辩论；争端；纠纷","ex":{"en":"industrial/pay disputes","cn":"劳资／工资纠纷"}},{"en":"to question whether something is true or legally or officially acceptable","cn":"质疑（某事是否属实、合法或应该接受）","g":"[transitive]","ex":{"en":"These figures have been disputed.","cn":"有人对这些数字提出了质疑。"},"pos":"verb"},{"en":"to argue or disagree strongly with somebody about something, especially about who owns something","cn":"争论；辩论；争执","g":"[transitive, intransitive]","ex":{"en":"I tried to dispute the bill with the waiter.","cn":"我试图与服务员争论账单。"},"pos":"verb"},{"en":"to fight to get control of something or to win something","cn":"争夺；竞争","g":"[transitive]","ex":{"en":"On the last lap three runners were disputing the lead.","cn":"在最后一圈，三名赛跑者在争夺领先地位。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"争吵;吵闹","en":"A dispute is an argument or disagreement between people or groups.","ex":{"en":"They have won previous pay disputes with the government","cn":"在先前和政府的工资纠纷中他们赢了。"}},{"pos":"VERB 动词","cn":"质疑(事实、声明或理论)；对…表示异议","en":"If you dispute a fact, statement, or theory, you say that it is incorrect or untrue.","ex":{"en":"He disputed the allegations","cn":"他对指控表示怀疑。"}},{"pos":"V-RECIP 相互动词","cn":"争夺","en":"When people dispute something, they fight for control or ownership of it. You can also say that one group of people dispute something with another group.","ex":{"en":"Russia and Ukraine have been disputing the ownership of the fleet","cn":"俄罗斯和乌克兰一直在争夺舰队的所有权。"}},{"pos":"PHR-RECIP 相互短语","cn":"有争端;有分歧;有纠纷","en":"If two or more people or groups are in dispute, they are arguing or disagreeing about something.","ex":{"en":"The two countries are in dispute over the boundaries of their coastal waters","cn":"两国在近海水域分界线上尚存分歧。"}},{"pos":"PHRASE 短语","cn":"在争论中;处于争议中","en":"If something is in dispute, people are questioning it or arguing about it.","ex":{"en":"All those matters are in dispute and it is not for me to decide them.","cn":"所有这些事项都尚无定论，也不是我可以决定的。"}}]},"media":{"uk":"media/uk/dispute__gb_1.mp3","us":"media/us/dispute__us_1.mp3"},"examples":[{"en":"It is disputed whether the law applies in this case.","cn":"有人对这项法律是否适用于这个案例提出质疑。"},{"en":"On the last lap three runners were disputing the lead.","cn":"在最后一圈，三名赛跑者在争夺领先地位。"}]},"diameter":{"media":{"img":["media/pic/circles_comp.jpg","media/thumb/circles1.jpg"],"uk":"media/uk/diameter__gb_1.mp3","us":"media/us/diameter__us_1.mp3"},"oxford":{"phon":"daɪˈæmɪtə(r)","pos":"noun","senses":[{"en":"a straight line going from one side of a circle or any other round object to the other side, passing through the centre","cn":"直径；对径","ex":{"en":"The diameter of the tree trunk was more than a metre.","cn":"树干的直径有一米多。"}},{"en":"a measurement of the power of an instrument to magnify something","cn":"放大率；放大倍数","lab":"specialist","ex":{"en":"a lens magnifying 300 diameters (= making something look 300 times larger than it really is)","cn":"放大 300 倍的透镜"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"直径;对径","en":"The diameter of a round object is the length of a straight line that can be drawn across it, passing through the middle of it.","ex":{"en":"...a tube less than a fifth of the diameter of a human hair.","cn":"直径不足人的头发直径1/5的电子管"}}]},"examples":[{"en":"The dome is 42.3 metres in diameter.","cn":"这个穹顶直径为 42.3 米。"},{"en":"a lens magnifying 300 diameters (= making sth look 300 times larger than it really is)","cn":"放大 300 倍的透镜"}]},"district":{"media":{"uk":"media/uk/district__gb_1.mp3","us":"media/us/district__us_1.mp3"},"oxford":{"phon":"ˈdɪstrɪkt","pos":"noun","senses":[{"en":"an area of a country or town, especially one that has particular features","cn":"地区；区域","ex":{"en":"the City of London’s financial district","cn":"伦敦市中心的金融区"}},{"en":"one of the areas that a country, town or state is divided into for purposes of organization, with official boundaries (= borders)","cn":"区；管区；行政区","ex":{"en":"a tax/postal district","cn":"税务区；邮政区"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"地区;区域","en":"A district is a particular area of a town or country.","ex":{"en":"I drove around the business district.","cn":"我开车在商业区转了转。"}},{"pos":"N-COUNT 可数名词","cn":"行政区;辖区;管区","en":"A district is an area of a town or country which has been given official boundaries for the purpose of administration.","ex":{"en":"...the home of the governor of the district.","cn":"该区行政长官的家"}}]},"examples":[{"en":"the City of London's financial district","cn":"伦敦市的金融区"},{"en":"a tax/postal district","cn":"税务区；邮政区"}]},"dialogue":{"media":{"uk":"media/uk/dialogue__gb_1.mp3","us":"media/us/dialogue__us_2.mp3"},"oxford":{"phon":"ˈdaɪəlɒɡ","pos":"noun","senses":[{"en":"a conversation in a book, play or film or in language teaching materials","cn":"对话；会话","ex":{"en":"Learners are asked to listen to three short dialogues.","cn":"要求学习者听三段短对话。"}},{"en":"a formal discussion between two groups or countries, especially when they are trying to solve a problem, end a disagreement, etc.","cn":"（尤指集体或国家间为解决问题、结束争端等进行的）对话","ex":{"en":"The president told waiting reporters there had been a constructive dialogue.","cn":"总统告诉等候的记者，刚才进行了一次富有建设性的对话。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"对话;谈话;讨论;交换意见","en":"Dialogue is communication or discussion between people or groups of people such as governments or political parties.","ex":{"en":"People of all social standings should be given equal opportunities for dialogue","cn":"社会各阶层的人们都应该拥有平等的对话机会。"}},{"pos":"N-VAR 可变名词","cn":"(书、电影或戏剧中的)对话，对白","en":"A dialogue is a conversation between two people in a book, film, or play.","ex":{"en":"The dialogue is amusing but the plot is weak","cn":"对白逗趣但是情节薄弱。"}}]},"examples":[{"en":"The President told waiting reporters there had been a constructive dialogue.","cn":"总统告诉等候的记者，刚才进行了一次富有建设性的对话。"},{"en":"The novel has long descriptions and not much dialogue.","cn":"这部小说描述多对话少。"}]},"distinct":{"media":{"uk":"media/uk/distinct__gb_1.mp3","us":"media/us/distinct__us_1.mp3"},"oxford":{"phon":"dɪˈstɪŋkt","pos":"adjective","senses":[{"en":"easily or clearly heard, seen, felt, etc.","cn":"清晰的；清楚的；明白的；明显的","ex":{"en":"There was a distinct smell of gas.","cn":"有一股明显的煤气味。"}},{"en":"clearly different or of a different kind","cn":"截然不同的；有区别的；不同种类的","ex":{"en":"The results of the survey fell into two distinct groups.","cn":"调查结果分为截然不同的两组。"}},{"en":"used to emphasize that you think an idea or situation definitely exists and is important","cn":"确定无疑的；确实的；确切的","g":"[only before noun]","ex":{"en":"Being tall gave Tony a distinct advantage.","cn":"托尼个子高是个明显的优势。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有区别的;不同的;个别的","en":"If something is distinct from something else of the same type, it is different or separate from it.","ex":{"en":"Engineering and technology are disciplines distinct from one another and from science","cn":"工程学和工艺学互不相同，也有别于自然学科。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"清楚的;清晰的;明显的","en":"If something is distinct, you can hear, see, or taste it clearly.","ex":{"en":"...to impart a distinct flavor with a minimum of cooking fat.","cn":"用最少量的食用油来调出一种独特的口味"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"确定无疑的;确切的;清楚的","en":"If an idea, thought, or intention is distinct, it is clear and definite.","ex":{"en":"Now that Tony was no longer present, there was a distinct change in her attitude","cn":"由于托尼不在场了，她的态度有了明显的转变。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"显著的;明显的","en":"You can use distinct to emphasize that something is great enough in amount or degree to be noticeable or important.","ex":{"en":"Being 6ft 3in tall has some distinct disadvantages!","cn":"身高6英尺3英寸有些明显的不便之处！"}},{"pos":"PREP-PHRASE 短语介词","cn":"截然不同于;完全不同于;有区别于","en":"If you say that you are talking about one thing as distinct from another, you are indicating exactly which thing you mean.","ex":{"en":"There's a lot of evidence that oily fish, as distinct from fatty meat, has a beneficial effect.","cn":"有许多证据表明油性鱼，与高脂肪肉不同，对人体有益。"}}]},"examples":[{"en":"Jamaican reggae music is quite distinct from North American jazz or blues.","cn":"牙买加的雷盖音乐完全不同于北美的爵士乐或布鲁斯音乐。"},{"en":"His voice was quiet but every word was distinct.","cn":"他说话声音不大，但字字清晰。"}]},"dictionaries":{"lemma":"dictionary"},"disembark":{"media":{"uk":"media/uk/disembark__gb_1.mp3","us":"media/us/disembark__us_1.mp3"},"oxford":{"phon":"ˌdɪsɪmˈbɑːk","pos":"verb","senses":[{"en":"to leave a vehicle, especially a ship or an aircraft, at the end of a journey; to let or make people leave a vehicle","cn":"（使）下（车、船、飞机等）","ex":{"en":"We will be disembarking at midday.","cn":"我们将在中午下船。"}}]}},"die":{"media":{"uk":"media/uk/die__gb_1.mp3","us":"media/us/die__us_1.mp3"},"oxford":{"phon":"daɪ","pos":"verb","senses":[{"en":"to stop living","cn":"死；死亡；凋谢","g":"[intransitive, transitive]","lab":"informal","ex":{"en":"My father died suddenly at the age of 48.","cn":"我父亲在 48 岁时突然离世。"}},{"en":"to stop existing; to disappear","cn":"消失；消亡；灭亡","g":"[intransitive]","ex":{"en":"The old customs are dying.","cn":"旧的习俗正在消亡。"}},{"en":"to stop working","cn":"关闭；关上；停止运转","g":"[intransitive]","ex":{"en":"My phone died and I had no way to contact you.","cn":"我的手机关机了，没有办法联系你。"}},{"en":"a block of metal with a special shape, or with a pattern cut into it, that is used for shaping other pieces of metal such as coins, or for making patterns on paper or leather","cn":"模具；冲模；压模","pos":"noun"},{"en":"a small cube of wood, plastic, etc., with a different number of spots on each of its sides, used in games of chance","cn":"骰子；色子","lab":"especially North American English","pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"死;死亡;（植物）枯死，凋谢","en":"When people, animals, and plants die, they stop living. →see usage note at:","ex":{"en":"A year later my dog died","cn":"一年后我的狗死了。"}},{"pos":"VERB 动词","cn":"临死;垂死;奄奄一息","en":"If a person, animal, or plant is dying, they are so ill or so badly injured that they will not live very much longer.","ex":{"en":"The elm trees are all dying","cn":"那些榆树全都奄奄一息了。"}},{"pos":"VERB 动词","cn":"以…的方式死亡","en":"If someone dies a violent, unnatural, or painful death, they die in a violent, unnatural, or painful way.","ex":{"en":"He watched helplessly as his mother died an agonizing death","cn":"他无助地看着母亲痛苦地死去。"}},{"pos":"VERB 动词","cn":"(机器或设备)完全停止运行","en":"If a machine or device dies, it stops completely, especially after a period of working more and more slowly or inefficiently.","ex":{"en":"Then suddenly, the engine coughed, spluttered and died.","cn":"然后，发动机突然咔咔地响着，发出一阵噼啪声，接着就彻底熄火了。"}},{"pos":"VERB 动词","cn":"(火或光)熄灭","en":"If a fire or light dies, it stops burning or shining.","ex":{"en":"Her cigarette glowed brightly, then died.","cn":"她的香烟燃起一阵亮光，然后就熄灭了。"}},{"pos":"VERB 动词","cn":"(感情或表情)完全消失","en":"If an emotion or facial expression dies, it disappears completely, usually after a period of gradually becoming weaker and less noticeable.","ex":{"en":"My love for you will never die","cn":"我对你的爱永不止息。"}},{"pos":"VERB 动词","cn":"(渴、饿、闷或好奇)得要命;…得要死","en":"You can say that you are dying of thirst, hunger, boredom, or curiosity to emphasize that you are very thirsty, hungry, bored, or curious.","ex":{"en":"Order me a pot of tea, I'm dying of thirst.","cn":"给我来一壶茶，我快要渴死了。"}},{"pos":"VERB 动词","cn":"很想要;非常渴望","en":"You can say that you are dying for something or are dying to do something to emphasize that you very much want to have it or do it.","ex":{"en":"I'm dying for a breath of fresh air","cn":"我非常渴望能呼吸到新鲜空气。"}},{"pos":"VERB 动词","cn":"(用于强调震惊、不安、窘迫或好笑等)我差点要死/（如果发生某事）我会死的","en":"You can use die in expressions such as 'I almost died' or 'I'd die if anything happened' where you are emphasizing your feelings about a situation, for example to say that it is very shocking, upsetting, embarrassing, or amusing.","ex":{"en":"I nearly died when I learned where I was ending up","cn":"得知自己到了哪里时，我简直要晕过去了。"}},{"pos":"N-COUNT 可数名词","cn":"模具;冲模;压模","en":"A die is a specially shaped or patterned block of metal which is used to press or cut other metal into a particular shape."},{"pos":"PHRASE 短语","cn":"事已定局;木已成舟","en":"You can say that the die is cast to draw attention to the importance of an event or decision which is going to affect your future and which cannot be changed or avoided.","ex":{"en":"It was too late and too urgent to turn back. The die was cast.","cn":"现在为时已晚，来不及回头。事情已成定局了。"}},{"pos":"PHRASE 短语","cn":"(习惯或观念)难以改掉，很难摆脱","en":"If you say that habits or attitudes die hard, you mean that they take a very long time to disappear or change, so that it may not be possible to get rid of them completely.","ex":{"en":"Old habits die hard","cn":"积习难改。"}},{"pos":"","cn":"","en":"相关词组：die away die back die down die out"}]},"examples":[{"en":"This species has nearly died out because its habitat is being destroyed.","cn":"因栖息地正受到破坏，这一物种已濒于灭绝。"},{"en":"The play got terrible reviews and quickly died a death.","cn":"这出戏被批得一无是处，很快就收场了。"}]},"disrupt":{"media":{"uk":"media/uk/disrupt__gb_1.mp3","us":"media/us/disrupt__us_1.mp3"},"oxford":{"phon":"dɪsˈrʌpt","pos":"verb","senses":[{"en":"to make it difficult for something to continue in the normal way","cn":"扰乱；使中断；打乱","ex":{"en":"Demonstrators succeeded in disrupting the meeting.","cn":"示威者成功地扰乱了会议。"}},{"en":"to cause significant change in an industry or market by means of innovation (= new ideas or methods)","cn":"改变行业传统运作方式，颠覆","lab":"business","ex":{"en":"Our radical new printing technology is disrupting traditional manufacturing.","cn":"我们革新性的印刷技术正在颠覆传统制造业。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"使中断;扰乱","en":"If someone or something disrupts an event, system, or process, they cause difficulties that prevent it from continuing or operating in a normal way.","ex":{"en":"Anti-war protesters disrupted the debate.","cn":"反战示威者们打断了辩论。"}}]},"examples":[{"en":"We aim to help you move house with minimum disruption to yourself.","cn":"我们的宗旨是帮您搬家的时候，尽量减少给您带来的不便。"},{"en":"Bus services will be disrupted tomorrow because of the bridge closure.","cn":"明日公共汽车服务将因大桥停止通行而受影响。"}]},"digs":{"media":{"uk":"media/uk/digs__gb_1.mp3","us":"media/us/digs__us_1.mp3"},"oxford":{"phon":"dɪɡz","pos":"noun","senses":[{"en":"a room or rooms that you rent to live in","cn":"租住的住所；住处","ex":{"en":"I shared digs with him for two years.","cn":"我和他共用了两年的挖掘地。"}}]},"base":"dig"},"diamonds":{"lemma":"diamond"},"divided":{"media":{"uk":"media/uk/divided__gb_1.mp3","us":"media/us/divided__us_1.mp3"},"oxford":{"phon":"dɪˈvaɪdɪd","pos":"adjective","senses":[{"en":"split by arguments or different opinions","cn":"分裂的；有分歧的","ex":{"en":"The government is divided on this issue.","cn":"政府在这个问题上意见不统一。"}}]},"examples":[{"en":"The government is divided on this issue.","cn":"政府在这个问题上意见不统一。"},{"en":"The regime is profoundly divided against itself.","cn":"这一政体内部彻底分裂了。"}],"base":"divide"},"disease":{"media":{"uk":"media/uk/disease__gb_1.mp3","us":"media/us/disease__us_1.mp3"},"oxford":{"phon":"dɪˈziːz","pos":"noun","senses":[{"en":"an illness affecting humans, animals or plants, often caused by infection","cn":"病；疾病","g":"[uncountable, countable]","lab":"British English","ex":{"en":"heart/lung/liver disease","cn":"心脏病；肺病；肝病"}},{"en":"something that is very wrong with people’s attitudes, way of life or with society","cn":"弊端；恶疾；痼疾","g":"[countable]","lab":"formal","ex":{"en":"Greed is a disease of modern society.","cn":"贪婪是现代社会的恶疾。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"疾病;(动植物的)病害","en":"A disease is an illness which affects people, animals, or plants, for example one which is caused by bacteria or infection.","ex":{"en":"...the rapid spread of disease in the area.","cn":"疾病在这一区域的迅速蔓延"}},{"pos":"N-COUNT 可数名词","cn":"（尤指社会某一群体的）弊病，积习，恶习","en":"You can refer to a bad attitude or habit, usually one that a group of people have, as a disease.","ex":{"en":"...the wretched disease of racism eating away at the core of our society.","cn":"侵蚀着我们社会核心的种族主义恶疾"}}]},"examples":[{"en":"He suffers from a rare blood disease.","cn":"他患有一种罕见的血液病。"},{"en":"health measures to prevent the spread of disease","cn":"预防疾病传播的保健措施"}]},"digital":{"media":{"uk":"media/uk/digital__gb_1.mp3","us":"media/us/digital__us_1.mp3"},"oxford":{"phon":"ˈdɪdʒɪtl","pos":"adjective","senses":[{"en":"using a system of receiving and sending information as a series of the numbers one and zero, showing that an electronic signal is there or is not there","cn":"数字信息系统的；数码的；数字式的","ex":{"en":"a digital camera","cn":"数码相机"}},{"en":"connected with the use of computer technology, especially the internet","cn":"数字的；计算机（网络）的","ex":{"en":"communication in the digital age","cn":"数字时代的交流"}},{"en":"showing information by using figures, rather than with hands that point to numbers","cn":"数字显示的","ex":{"en":"a digital clock/watch","cn":"数字钟；数字表"}},{"en":"digital technology","cn":"数字技术","ex":{"en":"The world of digital is forever changing.","cn":"数字技术领域是不断变化的。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"数字的;数码的","en":"Digital systems record or transmit information in the form of thousands of very small signals.","ex":{"en":"The new digital technology would allow a rapid expansion in the number of TV channels.","cn":"新的数字技术将会使电视频道的数量迅速增加。"}},{"pos":"ADJ 形容词","cn":"(钟表等)数字(显示)的","en":"Digital devices such as watches or clocks give information by displaying numbers rather than by having a pointer which moves round a dial.","ex":{"en":"...a digital display.","cn":"数字显示"}}]},"examples":[{"en":"With digital you can choose the camera angle you want.","cn":"有了数字电视你就可以选择你想要的摄像角度。"},{"en":"digital terrestrial and digital satellite broadcasting","cn":"数字陆上广播和数字卫星广播"}]},"dirt":{"media":{"uk":"media/uk/dirt__gb_1.mp3","us":"media/us/dirt__us_1.mp3"},"oxford":{"phon":"dɜːt","pos":"noun","senses":[{"en":"any substance that makes something dirty, for example dust, soil or mud","cn":"污物；尘土；烂泥","ex":{"en":"His clothes were covered in dirt.","cn":"他的衣服沾满了污垢。"}},{"en":"loose earth or soil","cn":"松土；泥土；散土","lab":"especially North American English","ex":{"en":"He picked up a handful of dirt and threw it at them.","cn":"他抓起一把土朝他们扔过去。"}},{"en":"unpleasant or harmful information about somebody that could be used to damage their reputation, career, etc.","cn":"丑闻；流言蜚语","lab":"informal","ex":{"en":"Do you have any dirt on the new guy?","cn":"你知道新来的那个人的丑闻吗？"}},{"en":"solid waste matter from the body","cn":"粪便；屎","lab":"informal","ex":{"en":"dog dirt","cn":"狗屎"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"灰尘;尘土;污物","en":"If there is dirt on something, there is dust, mud, or a stain on it.","ex":{"en":"I started to scrub off the dirt.","cn":"我开始擦洗上面的灰尘。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"泥土;尘土;松土","en":"You can refer to the earth on the ground as dirt, especially when it is dusty.","ex":{"en":"They all sit on the dirt in the dappled shade of a tree.","cn":"他们全都坐在斑驳树阴下的泥土地上。"}},{"pos":"ADJ 形容词","cn":"(路面、地面等)土的，泥的","en":"A dirt road or track is made from hard earth. A dirt floor is made from earth without any cement, stone, or wood laid on it.","ex":{"en":"I drove along the dirt road","cn":"我驱车沿那条土路行进。"}},{"pos":"N-SING 单数名词","cn":"丑闻;丑事;流言蜚语","en":"If you say that you have the dirt on someone, you mean that you have information that could harm their reputation or career.","ex":{"en":"Steve was keen to get all the dirt he could on her","cn":"史蒂夫一心想要搜罗关于她的一切丑闻。"}},{"pos":"PHRASE 短语","cn":"说闲话;散布流言蜚语","en":"If someone dishes the dirt on you, they say bad things about you, without worrying if they are true or not, or if they will damage your reputation.","ex":{"en":"He dishes the dirt on his buddies.","cn":"他说自己伙伴的闲话。"}},{"pos":"PHRASE 短语","cn":"视…如草芥;瞧不起;轻视","en":"If you say that someone treats you like dirt, you are angry with them because you think that they treat you unfairly and with no respect.","ex":{"en":"People think they can treat me like dirt!","cn":"人们以为可以视我为草芥！"}}]},"examples":[{"en":"Do you have any dirt on the new guy?","cn":"你知道新来的那个人的丑闻吗？"},{"en":"First remove any grease or dirt from the surface.","cn":"先把表面的油污或尘土去掉。"}]},"dirty":{"media":{"uk":"media/uk/dirty__gb_1.mp3","us":"media/us/dirty__us_1.mp3","img":["media/ldoce/img/clean_dirty.jpg"]},"oxford":{"phon":"ˈdɜːti","pos":"adjective","senses":[{"en":"not clean","cn":"不洁","sc":"not clean","ex":{"en":"dirty hands/clothes/dishes","cn":"脏手；脏衣服；脏盘子"}},{"en":"connected with sex in an offensive way","cn":"下流的；色情的；黄色的；猥亵的","g":"[usually before noun]","sc":"offensive","ex":{"en":"a dirty joke/book","cn":"下流的笑话；黄色的书"}},{"en":"unpleasant or dishonest","cn":"令人厌恶的；卑鄙的；不诚实的","g":"[usually before noun]","lab":"informal","sc":"unpleasant/dishonest","ex":{"en":"That's a dirty lie!","cn":"胡说八道！"}},{"en":"not bright","cn":"暗淡的；不明亮的","g":"[only before noun]","sc":"colours","ex":{"en":"a dirty brown carpet","cn":"暗褐色的地毯"}},{"en":"using illegal drugs","cn":"吸毒的","lab":"North American English, slang，，","sc":"drugs"},{"en":"to make something dirty","cn":"弄脏","pos":"verb"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"脏的;肮脏的;污秽的","en":"If something is dirty, it is marked or covered with stains, spots, or mud, and needs to be cleaned.","ex":{"en":"She still did not like the woman who had dirty fingernails","cn":"她还是不喜欢那个指甲脏脏的女子。"}},{"pos":"VERB 动词","cn":"弄脏;使变脏","en":"To dirty something means to cause it to become dirty.","ex":{"en":"He was afraid the dog's hairs might dirty the seats","cn":"他担心狗毛弄脏了座位。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"卑劣的;卑鄙的;不道德的","en":"If you describe an action as dirty, you disapprove of it and consider it unfair, immoral, or dishonest.","ex":{"en":"The gunman had been hired by a rival Mafia family to do the dirty deed.","cn":"一个敌对的黑手党家族雇用了那个枪手来实施这一卑劣行动。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(笑话、书籍、话语等)淫秽的，下流的，黄色的","en":"If you describe something such as a joke, a book, or someone's language as dirty, you mean that it refers to sex in a way that some people find offensive.","ex":{"en":"They told dirty jokes and sang raucous ballads","cn":"他们说着荤段子，哼着不着调的小曲儿。"}},{"pos":"ADJ 形容词","cn":"(用于批评之词前作强调)可恶的，可恨的","en":"Dirty is used before words of criticism to emphasize that you do not approve of someone or something.","ex":{"en":"You dirty liar.","cn":"你这个可恶的骗子。"}},{"pos":"PHRASE 短语","cn":"把丑事公开;使家丑外扬","en":"If you say that someone washes their dirty linen in public, you disapprove of their discussing or arguing about unpleasant or private things in front of other people. There are several other forms of this expression, for example wash your dirty laundry in public, or in American English, air your dirty laundry in public .","ex":{"en":"The spectacle of the former naval officers washing their dirty linen in public was distinctly embarrassing","cn":"前海军官员们自揭伤疤的做法显然非常令人尴尬。"}},{"pos":"PHRASE 短语","cn":"愤怒的眼神;怒目圆睁","en":"If someone gives you a dirty look, they look at you in a way which shows that they are angry with you.","ex":{"en":"Michael gave him a dirty look and walked out.","cn":"迈克尔狠狠地瞪了他一眼然后走开了。"}},{"pos":"PHRASE 短语","cn":"老色鬼;老淫棍;老不正经","en":"Dirty old man is an expression some people use to describe an older man who they think shows an unnatural interest in sex.","ex":{"en":"He was always trying it on. But now he's 71, it's causing problems. He's just a dirty old man.","cn":"他以前总想乱来。但现在他已 71 岁，有些力不从心了。不过是个老色鬼罢了。"}},{"pos":"PHRASE 短语","cn":"替…干不法勾当;替…干苦差","en":"To do someone's dirty work means to do a task for them that is dishonest or unpleasant and which they do not want to do themselves.","ex":{"en":"As a member of an elite army hit squad, the army would send us out to do their dirty work for them.","cn":"作为特工小分队的一员，部队总会派我们去做他们不愿做的事。"}},{"pos":"PHRASE 短语","cn":"(主要为性而进行的)周末幽会","en":"A dirty weekend is a weekend during which two people go away together, mainly in order to have sex."},{"pos":"PHRASE 短语","cn":"引起反感的词;令人讨厌的字眼","en":"If you say that an expression is a dirty word in a particular group of people, you mean it refers to an idea that they strongly dislike or disagree with.","ex":{"en":"Marketing became a dirty word at the company.","cn":"市场营销成了公司里一个很令人讨厌的字眼。"}}]},"examples":[{"en":"The singer got down and dirty at the club last night and made headlines again.","cn":"这个歌手昨晚在俱乐部的无耻行为使他又上了报纸的头版头条。"},{"en":"The candidate again got down and dirty with his rival.","cn":"这名候选人又开始用下作的手段对付他的竞争对手。"}]},"diagram":{"oxford":{"phon":"ˈdaɪəɡræm","pos":"verb","senses":[{"en":"to show something using a diagram","cn":"图表：使用图表显示事物","ex":{"en":"The overall structures of these enzymes are diagrammed in Fig 1.","cn":"这些酶的总体结构如图1所示。"}},{"en":"a simple drawing using lines to explain where something is, how something works, etc.","cn":"简图；图解；图表；示意图","ex":{"en":"The results are shown in diagram 2.","cn":"结果显示在表 2 上。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"图表;简图;示意图","en":"A diagram is a simple drawing which consists mainly of lines and is used, for example, to explain how a machine works.","ex":{"en":"...a circuit diagram","cn":"电路图"}},{"pos":"VERB 动词","cn":"绘制…的示意图;用图表表示（或说明）","en":"To diagram something means to draw a diagram of it or to explain it using a diagram.","ex":{"en":"The sound waves of the voice could be diagramed as in B.","cn":"这个声音的声波如图B所示。"}}]},"media":{"uk":"media/uk/diagram__gb_1.mp3","us":"media/us/diagram__us_1.mp3"},"examples":[{"en":"The results are shown in diagram 2.","cn":"结果显示在表 2 上。"},{"en":"a diagram of the wiring system","cn":"线路系统图"}]},"discipline":{"media":{"uk":"media/uk/discipline__gb_1.mp3","us":"media/us/discipline__us_1.mp3"},"oxford":{"phon":"ˈdɪsəplɪn","pos":"noun","senses":[{"en":"the practice of training people to obey rules and orders and punishing them if they do not; the controlled behaviour or situation that is the result of this training","cn":"训练；训导；纪律；风纪","g":"[uncountable]","ex":{"en":"The school has a reputation for high standards of discipline.","cn":"这所学校因纪律严格而名闻遐迩。"}},{"en":"a method of training your mind or body or of controlling your behaviour; an area of activity where this is necessary","cn":"训练方法；行为准则；符合准则的行为","g":"[countable]","ex":{"en":"Yoga is a good discipline for learning to relax.","cn":"瑜伽是一种学习放松的有效方法。"}},{"en":"the ability to control your behaviour or the way you live, work, etc.","cn":"自制力；遵守纪律","g":"[uncountable]","ex":{"en":"He'll never get anywhere working for himself—he's got no discipline.","cn":"他自己做事是不会有什么成就的——他毫无自制力。"}},{"en":"an area of knowledge; a subject that people study or are taught, especially in a university","cn":"知识领域；（尤指大学的）学科，科目","g":"[countable]","lab":"formal","ex":{"en":"The new recruits were drawn from a range of academic disciplines.","cn":"新人来自各个学科。"}},{"en":"to punish somebody for something they have done","cn":"惩罚；处罚","ex":{"en":"The officers were disciplined for using racist language.","cn":"这些军官因使用种族歧视性语言而受到惩罚。"},"pos":"verb"},{"en":"to train somebody, especially a child, to obey particular rules and control the way they behave","cn":"训练；训导；管教","ex":{"en":"a guide to the best ways of disciplining your child","cn":"管教子女最佳方法指南"},"pos":"verb"},{"en":"to control the way you behave and make yourself do things that you believe you should do","cn":"自我控制；严格要求（自己）","ex":{"en":"Dieting is a matter of disciplining yourself.","cn":"节食是自我控制的问题。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"训练;纪律;风纪","en":"Discipline is the practice of making people obey rules or standards of behaviour, and punishing them when they do not.","ex":{"en":"Order and discipline have been placed in the hands of headmasters and governing bodies.","cn":"维持秩序和纪律的工作已交接给了校长和管理机构了。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"自制力;遵守纪律","en":"Discipline is the quality of being able to behave and work in a controlled way which involves obeying particular rules or standards.","ex":{"en":"It was that image of calm and discipline that appealed to voters.","cn":"正是那个冷静、自律的形象打动了选民。"}},{"pos":"N-VAR 可变名词","cn":"训练;磨炼","en":"If you refer to an activity or situation as a discipline, you mean that, in order to be successful in it, you need to behave in a strictly controlled way and obey particular rules or standards.","ex":{"en":"...inner disciplines like transcendental meditation","cn":"内省，如冥思静坐"}},{"pos":"VERB 动词","cn":"惩罚;处罚;处分","en":"If someone is disciplined for something that they have done wrong, they are punished for it.","ex":{"en":"The workman was disciplined by his company but not dismissed","cn":"那个工人受到了公司的处罚，但并没有被解雇。"}},{"pos":"VERB 动词","cn":"训练;训导;管教","en":"If you discipline yourself to do something, you train yourself to behave and work in a strictly controlled and regular way.","ex":{"en":"Out on the course you must discipline yourself to let go of detailed theory","cn":"在高尔夫球场上，你必须训练自己做到不拘泥于细枝末节的理论。"}},{"pos":"N-COUNT 可数名词","cn":"(尤指大学里的)学科，科目","en":"A discipline is a particular area of study, especially a subject of study in a college or university.","ex":{"en":"You've got to make sure that people work together across disciplines","cn":"你必须确保让那些出身不同学科的人一起共事。"}}]},"examples":[{"en":"He'll never get anywhere working for himself — he's got no discipline.","cn":"他为自己工作是不会有什么成就的，他毫无自制力。"},{"en":"The officers were disciplined for using racist language.","cn":"这些军官因使用种族歧视性语言而受到惩罚。"}]},"division":{"oxford":{"phon":"dɪˈvɪʒn","pos":"noun","senses":[{"en":"the process or result of dividing into separate parts; the process or result of dividing something or sharing it out","cn":"分开；分隔；分配；（分出来的）部分","g":"[uncountable, singular]","sc":"into separate parts","ex":{"en":"The organism begins as a single cell and grows by cell division.","cn":"这种生物始于单细胞，并通过细胞分裂而生长。"}},{"en":"the process of dividing one number by another","cn":"除（法）","g":"[uncountable]","sc":"mathematics","ex":{"en":"the division sign (÷)","cn":"除号"}},{"en":"a disagreement or difference in opinion, way of life, etc., especially between members of a society or an organization","cn":"分歧；不和；差异","g":"[countable, uncountable]","sc":"disagreement/difference","ex":{"en":"We choose peace over hatred and division.","cn":"我们选择和平，而不是仇恨和分裂。"}},{"en":"a large and important unit or section of an organization","cn":"（机构的）部门","g":"[countable + singular or plural verb]","sc":"part of organization","ex":{"en":"the organized crime division of the Austrian police force","cn":"奥地利警察部队有组织犯罪部门"}},{"en":"part of a city, county, or country that is regarded as a separate area for administration purposes","cn":"（市、县、国家的）地区，区，行政区","g":"[countable]","sc":"part of organization","ex":{"en":"Oldham is one of the police divisions of Greater Manchester.","cn":"奥尔德姆是大曼彻斯特的一个警区。"}},{"en":"a group of teams or competitors in a sports competition who compete against each other. Divisions may be organized by ability, geography or weight, depending on the sport.","cn":"（体育比赛中的）级，分区","g":"[countable + singular or plural verb]","sc":"in sport","ex":{"en":"the premier division","cn":"超级联赛"}},{"en":"a unit of an army, consisting of several brigades or regiments","cn":"师","g":"[countable + singular or plural verb]","sc":"part of army","ex":{"en":"the Guards Armoured Division","cn":"禁卫装甲师"}},{"en":"a line that divides something","cn":"分界线","g":"[countable]","lab":"figurative","sc":"border","ex":{"en":"A hedge forms the division between their land and ours.","cn":"他们的土地与我们的土地之间以一道树篱隔开。"}},{"en":"the act of separating members of the British parliament into groups to vote for or against something","cn":"（英国议会的）分组表决","g":"[countable]","lab":"specialist","sc":"in parliament","ex":{"en":"The Bill was read without a division.","cn":"议案未经分组表决就宣读通过了。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"分开;划分;分隔","en":"The division of a large unit into two or more distinct parts is the act of separating it into these parts.","ex":{"en":"...the unification of Germany, after its division into two states at the end of World War Two.","cn":"二战结束时曾被一分为二的德国实现了统一"}},{"pos":"N-UNCOUNT 不可数名词","cn":"分配;分派","en":"The division of something among people or things is its separation into parts which are distributed among the people or things.","ex":{"en":"The current division of labor between workers and management will alter.","cn":"当前工人与管理部门的分工将会改变。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(算术中的)除法","en":"Division is the arithmetical process of dividing one number into another number.","ex":{"en":"I taught my daughter how to do division at the age of six.","cn":"女儿6岁时我就教她如何做除法了。"}},{"pos":"N-VAR 可变名词","cn":"分歧;争议;差异","en":"A division is a significant distinction or argument between two groups, which causes the two groups to be considered as very different and separate.","ex":{"en":"The division between the prosperous west and the impoverished east remains.","cn":"繁荣的西部和贫穷的东部之间的差距仍然存在。"}},{"pos":"N-COUNT 可数名词","cn":"(大机构的)部门","en":"In a large organization, a division is a group of departments whose work is done in the same place or is connected with similar tasks.","ex":{"en":"...the bank's Latin American division.","cn":"该银行的拉丁美洲分部"}},{"pos":"N-COUNT 可数名词","cn":"(军队编制中的)师","en":"A division is a group of military units which fight as a single unit.","ex":{"en":"Several armoured divisions are being moved from Germany.","cn":"正从德国调动几个装甲师。"}},{"pos":"N-COUNT 可数名词","cn":"(英国议会中的)分组表决","en":"In the British Parliament, a division is a vote where the Members of Parliament go into separate rooms in order to record their vote."},{"pos":"N-COUNT 可数名词","cn":"(足球等体育运动中联赛的)级","en":"In some sports, such as football, baseball, and basketball, a division is one of the groups of teams which make up a league. The teams in each division are considered to be approximately the same standard, and they all play against each other during the season.","ex":{"en":"Villa had just been relegated from the First Division.","cn":"维拉队刚刚从甲级联赛中降级。"}}]},"media":{"uk":"media/uk/division__gb_1.mp3","us":"media/us/division__us_1.mp3"},"examples":[{"en":"A hedge forms the division between their land and ours.","cn":"他们的土地与我们的土地之间以一道树篱隔开。"},{"en":"There are deep divisions in the party over the war.","cn":"党内对于这场战争存在着严重的分歧。"}]},"disappointing":{"media":{"uk":"media/uk/disappointing__gb_1.mp3","us":"media/us/disappointing__us_1.mp3"},"oxford":{"phon":"ˌdɪsəˈpɔɪntɪŋ","pos":"adjective","senses":[{"en":"not as good, successful, etc. as you had hoped; making you feel disappointed","cn":"令人失望的；令人沮丧的；令人扫兴的","ex":{"en":"a disappointing result/performance/defeat","cn":"令人沮丧的结果／演出／失败"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"令人失望的;令人沮丧的;令人扫兴的","en":"Something that is disappointing is not as good or as large as you hoped it would be.","ex":{"en":"The wine was excellent, but the food was disappointing","cn":"酒棒极了，但是饭菜却让人不敢恭维。"}}]},"examples":[{"en":"The outcome of the court case was disappointing for the family involved.","cn":"诉讼案的结果使得涉及本案的这家人非常失望。"},{"en":"The room was disappointingly small.","cn":"房间小得令人失望。"}]},"discover":{"media":{"uk":"media/uk/discover__gb_1.mp3","us":"media/us/discover__us_1.mp3"},"oxford":{"phon":"dɪˈskʌvə(r)","pos":"verb","senses":[{"en":"to be the first person to become aware that a particular place or thing exists","cn":"（第一个）发现","ex":{"en":"Cook is credited with discovering Hawaii.","cn":"人们把发现夏威夷的功劳归于库克。"}},{"en":"to find somebody/something that was hidden or that you did not expect to find","cn":"（出乎意料地）发现，找到，发觉","ex":{"en":"Police discovered a large stash of drugs while searching the house.","cn":"警方搜查这栋房子时发现里面藏着一大批毒品。"}},{"en":"to find out about something; to find some information about something","cn":"了解到；认识到；查明","ex":{"en":"She was determined to discover the truth about her neighbours.","cn":"她决心弄清她邻居的真相。"}},{"en":"to be the first person to realize that somebody is very good at singing, acting, etc. and help them to become successful and famous","cn":"发现（人才）","g":"[often passive]","ex":{"en":"The singer was discovered while still at school.","cn":"这个歌唱家在上学的时候就受到赏识了。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"发现(以前不知道的事实)","en":"If you discover something that you did not know about before, you become aware of it or learn of it.","ex":{"en":"She discovered that they'd escaped","cn":"她发现他们已经逃跑了。"}},{"pos":"VERB 动词","cn":"(偶然)发现;找到(一直在寻找的某人或某物)","en":"If a person or thing is discovered, someone finds them, either by accident or because they have been looking for them.","ex":{"en":"A few days later his badly beaten body was discovered on a roadside outside the city.","cn":"几天后，他的尸体在城外的路边被发现，身上有被严重殴打过的痕迹。"}},{"pos":"VERB 动词","cn":"(第一个)发现","en":"When someone discovers a new place, substance, scientific fact, or scientific technique, they are the first person to find it or become aware of it.","ex":{"en":"...the first European to discover America","cn":"第一个发现美洲大陆的欧洲人"}},{"pos":"VERB 动词","cn":"初次接触(某活动并乐在其中)","en":"If you say that someone has discovered a particular activity or subject, you mean that they have tried doing it or studying it for the first time and that they enjoyed it.","ex":{"en":"I wish I'd discovered photography when I was younger","cn":"我要是早点接触到摄影技术就好了。"}},{"pos":"VERB 动词","cn":"发现，发掘(不为人所知的演员、音乐人等艺人)","en":"When an actor, musician, or other performer who is not well-known is discovered, someone recognizes that they have talent and helps them in their career.","ex":{"en":"The Beatles were discovered in the early 1960's.","cn":"甲壳虫乐队于20世纪60年代初为世人所知。"}}]},"examples":[{"en":"Scientists around the world are working to discover a cure for AIDS.","cn":"全世界的科学家都在努力寻找治疗艾滋病的方法。"},{"en":"Police discovered a large stash of drugs while searching the house.","cn":"警方搜查这栋房子时发现里面藏着一大批毒品。"}]},"distinguishes":{"lemma":"distinguish"},"discouraged":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"to not be confident about your abilities or appearance","cn":""},{"en":"not confident about meeting or speaking to people who you do not know","cn":""}]},"examples":[{"en":"A lot of players get discouraged and quit.","cn":"许多选手失去信心﹐放弃了。","src":"ld"}],"media":{"uk":"media/uk/discouraged__gb_1.mp3","us":"media/us/discouraged__us_1.mp3"},"oxford":{"phon":"dɪsˈkʌrɪdʒd","pos":"adjective","senses":[{"en":"feeling less confident or enthusiastic about doing something","cn":"使灰心；使泄气；使丧失信心","ex":{"en":"Learners can feel very discouraged if an exercise is too difficult.","cn":"如果练习太难，学习者可能会丧失信心。"}}]},"base":"discourage"},"dietetics":{"media":{"uk":"media/uk/dietetics__gb_1.mp3","us":"media/us/dietetics__us_1.mp3"},"oxford":{"phon":"ˌdaɪəˈtetɪks","pos":"noun","senses":[{"en":"the scientific study of diet and healthy eating","cn":"饮食营养学"}]},"examples":[{"en":"dietetic advice","cn":"饮食建议"}]},"did":{"collins":{"senses":[{"pos":"","cn":"","en":"Did is the past tense of do."}]},"media":{"uk":"media/uk/did__gb_1.mp3","us":"media/us/did__us_1.mp3"},"oxford":{"phon":"ˌdiː aɪ ˈdiː","pos":"abbreviation","senses":[{"en":"dissociative identity disorder (= a mental illness in which somebody feels uncertain about who they are and feels that they have more than one separate identity, each one having its own name, voice, memories, personality, etc.)","cn":"分离性身份识别障碍;分离性人格障碍"}]},"base":"do"},"dilute":{"media":{"uk":"media/uk/dilute__gb_1.mp3","us":"media/us/dilute__us_1.mp3"},"oxford":{"phon":"daɪˈluːt","pos":"verb","senses":[{"en":"to make a liquid weaker by adding water or another liquid to it","cn":"稀释；冲淡","ex":{"en":"The paint can be diluted with water to make a lighter shade.","cn":"这颜料可用水稀释以使色度淡一些。"}},{"en":"to make something weaker or less effective","cn":"削弱；降低；使降低效果","ex":{"en":"Large classes dilute the quality of education that children receive.","cn":"大班上课会降低孩子所受教育的质量。"}},{"en":"made weaker by adding water or another substance","cn":"稀释了的；冲淡了的","ex":{"en":"Fertilize with a dilute liquid plant food.","cn":"用稀释的液体植物食物施肥。"},"pos":"adjective"},{"en":"having only a small amount of a substance dissolved in it","cn":"稀的","lab":"chemistry","ex":{"en":"a dilute solution of acetic acid","cn":"醋酸稀溶液"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"（使）稀释;（使）冲淡","en":"If a liquid is diluted or dilutes, it is added to or mixes with water or another liquid, and becomes weaker.","ex":{"en":"If you give your baby juice, dilute it well with cooled, boiled water","cn":"如果给婴儿喝果汁，要用凉开水充分稀释。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"稀释过的;冲淡的","en":"A dilute liquid is very thin and weak, usually because it has had water added to it.","ex":{"en":"...a dilute solution of bleach.","cn":"经稀释的漂白剂"}},{"pos":"VERB 动词","cn":"削弱;降低;减轻","en":"If someone or something dilutes a belief, quality, or value, they make it weaker and less effective.","ex":{"en":"There was a clear intention to dilute black voting power","cn":"明显有意图要削弱黑人的选举力量。"}}]},"examples":[{"en":"This is a serious dilution of their election promises.","cn":"这是对他们竞选时许下的诺言大打折扣。"},{"en":"Large classes dilute the quality of education that children receive.","cn":"大班上课会降低孩子所受教育的质量。"}]},"disagree":{"oxford":{"phon":"ˌdɪsəˈɡriː","pos":"verb","senses":[{"en":"if two people disagree or one person disagrees with another about something, they have a different opinion about it","cn":"不同意；持不同意见；有分歧","g":"[intransitive]","ex":{"en":"Even friends disagree sometimes.","cn":"即便是朋友有时也有分歧。"}},{"en":"if statements or reports disagree, they give different information","cn":"不符；不一致","g":"[intransitive]","ex":{"en":"The results of the two approaches disagree.","cn":"两种方法的结果不一致。"}}]},"collins":{"senses":[{"pos":"V-RECIP 相互动词","cn":"不同意;有分歧;意见不合","en":"If you disagree with someone or disagree with what they say, you do not accept that what they say is true or correct. You can also say that two people disagree .","ex":{"en":"You must continue to see them no matter how much you may disagree with them","cn":"无论你和他们之间有多大的分歧，你都得继续去看他们。"}},{"pos":"VERB 动词","cn":"不赞成;反对","en":"If you disagree with a particular action or proposal, you disapprove of it and believe that it is wrong.","ex":{"en":"I respect the president but I disagree with his decision","cn":"我尊敬总统，但我反对他的这个决定。"}},{"pos":"VERB 动词","cn":"(尤指食物)对…不适宜，使…身体不适，不合…胃口","en":"If a particular food or drink disagrees with you, it makes you feel unwell.","ex":{"en":"Orange juice seems to disagree with some babies.","cn":"橙汁似乎不适合某些婴儿饮用。"}}]},"media":{"uk":"media/uk/disagree__gb_1.mp3","us":"media/us/disagree__us_1.mp3"},"examples":[{"en":"Few would disagree that students learn best when they are interested in the topic.","cn":"学生对自己感兴趣的题目学得最好，这一点几乎所有人都不会有异议。"},{"en":"No, I disagree. I don't think it would be the right thing to do.","cn":"不，我不赞成。我认为这样做不合适。"}]},"divide":{"oxford":{"phon":"dɪˈvaɪd","pos":"verb","senses":[{"en":"to separate into parts; to make something separate into parts","cn":"（使）分开，分散，分割，分成","g":"[intransitive, transitive]","sc":"separate","ex":{"en":"The cells began to divide rapidly.","cn":"细胞开始迅速分裂。"}},{"en":"to separate something into parts and give a share to each of a number of different people, etc.","cn":"分配；分享；分担","g":"[transitive]","sc":"separate","ex":{"en":"They could not agree on how to divide the land.","cn":"他们无法就如何分割土地达成一致。"}},{"en":"to use different parts of your time, energy, etc. for different activities, etc.","cn":"把（时间、精力等）分别用于","g":"[transitive]","sc":"separate","ex":{"en":"As working parents we think carefully about how we divide our time.","cn":"作为职业父母，我们会仔细考虑如何分配时间。"}},{"en":"to separate into two or more parts that lead in different directions","cn":"分岔","g":"[intransitive]","sc":"separate","ex":{"en":"Where the path divides, keep right.","cn":"来到岔口就靠右行。"}},{"en":"to separate two people or things","cn":"使分离；使分开","g":"[transitive]","lab":"formal","sc":"separate","ex":{"en":"Can it ever be right to divide a mother from her child?","cn":"让母子分离难道还有对的时候？"}},{"en":"to be the real or imaginary line or barrier that separates two people or things","cn":"是…的分界线；分隔；把…隔开","g":"[transitive]","sc":"separate","ex":{"en":"A fence divides off the western side of the grounds.","cn":"一道篱笆把庭院的西面隔开。"}},{"en":"to find out how many times one number is contained in another","cn":"除以","g":"[transitive, intransitive]","sc":"mathematics","ex":{"en":"30 divided by 6 is 5 (= 30 ÷ 6 = 5).","cn":"30 除以 6 等于 5。"}},{"en":"to be able to be multiplied to give another number","cn":"除","g":"[intransitive, transitive]","sc":"mathematics","ex":{"en":"5 divides into 30 6 times.","cn":"5 除 30 等于 6。"}},{"en":"to make people disagree","cn":"使产生分歧；使意见不一","g":"[transitive]","sc":"disagreement","ex":{"en":"to divide the nation/country","cn":"分裂国家"}},{"en":"to disagree","cn":"持不同意见；有分歧","g":"[intransitive]","sc":"disagreement","ex":{"en":"Communities frequently divided along religious lines.","cn":"社区经常因宗教信仰而分裂。"}},{"en":"a difference between two groups of people or two things that separates them from each other","cn":"不同；差异；分歧","sc":"difference","ex":{"en":"He offered advice on bridging cultural divides.","cn":"他就如何弥合文化鸿沟发表了意见。"},"pos":"noun"},{"en":"a line of high land that separates two systems of rivers","cn":"分水岭；分水线","lab":"especially North American English","sc":"between rivers","pos":"noun"}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"（使）分开；（使）分散;（使）分裂","en":"When people or things are divided or divide into smaller groups or parts, they become separated into smaller parts.","ex":{"en":"The physical benefits of exercise can be divided into three factors","cn":"运动对身体的好处可以分为3个方面。"}},{"pos":"VERB 动词","cn":"分配;分享;分担","en":"If you divide something among people or things, you separate it into several parts or quantities which you distribute to the people or things.","ex":{"en":"Paul divides most of his spare time between the study and his bedroom","cn":"保罗在大部分空闲时间里要么呆在书房里，要么呆在卧室里。"}},{"pos":"VERB 动词","cn":"除;除以","en":"If you divide a larger number by a smaller number or divide a smaller number into a larger number, you calculate how many times the smaller number can fit exactly into the larger number.","ex":{"en":"Measure the floor area of the greenhouse and divide it by six.","cn":"量一下温室的建筑面积再将它除以 6。"}},{"pos":"VERB 动词","cn":"分隔;把…分开;是…的分界线","en":"If a border or line divides two areas or divides an area into two, it keeps the two areas separate from each other.","ex":{"en":"...remote border areas dividing Tamil and Muslim settlements.","cn":"将泰米尔聚居区和穆斯林聚居区隔开的偏远边境地区"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）产生分歧;(使)意见不一","en":"If people divide over something or if something divides them, it causes strong disagreement between them.","ex":{"en":"She has done more to divide the Conservatives than anyone else","cn":"她在分裂保守党这件事上所起的作用比任何人都大。"}},{"pos":"N-COUNT 可数名词","cn":"明显差异;(常指引起争论的)分歧","en":"A divide is a significant distinction between two groups, often one that causes conflict.","ex":{"en":"...a deliberate attempt to create a Hindu-Muslim divide in India.","cn":"故意在印度的印度教徒和穆斯林之间制造分歧的企图"}},{"pos":"N-COUNT 可数名词","cn":"（时间、过程的）分界线，分界点","en":"A divide is a moment in time or a point in a process when there is a complete change from one situation to another.","ex":{"en":"The time had come to cross the great divide between formality and truth.","cn":"是时候跨越形式与真理之间的巨大分界线了。"}},{"pos":"N-COUNT 可数名词","cn":"分水岭","en":"A divide is a line of high ground between areas that are drained by different rivers."},{"pos":"PHRASE 短语","cn":"分而治之","en":"You use divide and rule to refer to a policy which is intended to keep someone in a position of power by causing disagreements between people who might otherwise unite against them.","ex":{"en":"The government's policies of divide and rule have only contributed to the volatility of the region.","cn":"政府分而治之的政策只是加剧了该地区的不稳定性。"}},{"pos":"","cn":"","en":"相关词组：divide off divide up"}]},"media":{"uk":"media/uk/divide__gb_1.mp3","us":"media/us/divide__us_1.mp3"},"examples":[{"en":"He divides his energies between politics and business.","cn":"他把精力一部分用在政治上，一部分用在业务上。"},{"en":"A sentence can be divided up into meaningful segments.","cn":"一个句子可以划分成有意义的各个部分。"}]},"digitally":{"oxford":{"phon":"ˈdɪdʒɪtəli","pos":"adverb","senses":[{"en":"using digital technology","cn":"数字化：使用数字技术","ex":{"en":"digitally remastered audio","cn":"以数字方式重新灌制的音频"}}]},"media":{"uk":"media/uk/digitally__gb_1.mp3","us":"media/us/digitally__us_1.mp3"},"examples":[{"en":"digitally remastered tapes","cn":"以数字方式重新灌制的录音带"},{"en":"a recording on digital audiotape","cn":""}]},"distress":{"oxford":{"phon":"dɪˈstres","pos":"noun","senses":[{"en":"a feeling of great worry or unhappiness; great mental pain","cn":"忧虑；悲伤；痛苦","ex":{"en":"The newspaper article caused the actor considerable distress.","cn":"报上的文章使这位演员相当苦恼。"}},{"en":"severe problems caused by not having enough money, food, etc.","cn":"贫困；窘迫；困苦","ex":{"en":"economic/financial distress","cn":"经济拮据；财政困难"}},{"en":"a situation in which a ship, plane, etc. is in danger or difficulty and needs help","cn":"（船、飞机等）遇险","ex":{"en":"a distress signal (= a message asking for help)","cn":"求救信号"}},{"en":"a state of physical pain and effort, especially difficulty in breathing","cn":"疼痛疲劳；（尤指）呼吸困难","lab":"medical","ex":{"en":"The patient was suffering serious respiratory distress.","cn":"该患者患有严重的呼吸困难。"}},{"en":"to make somebody feel very worried or unhappy","cn":"使忧虑；使悲伤；使苦恼","ex":{"en":"It was clear that the letter had deeply distressed her.","cn":"这封信显然使她极为悲伤。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"悲伤;痛苦;忧虑","en":"Distress is a state of extreme sorrow, suffering, or pain.","ex":{"en":"Jealousy causes distress and painful emotions.","cn":"嫉妒会带来忧虑和痛苦。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"危难;危急;危险","en":"Distress is the state of being in extreme danger and needing urgent help.","ex":{"en":"He expressed concern that the ship might be in distress.","cn":"他担心船可能会遇险。"}},{"pos":"VERB 动词","cn":"使忧虑;使悲伤;使苦恼","en":"If someone or something distresses you, they cause you to be upset or worried.","ex":{"en":"The idea of Toni being in danger distresses him enormously.","cn":"想到托尼正处于危险中，他心急如焚。"}}]},"media":{"uk":"media/uk/distress__gb_1.mp3","us":"media/us/distress__us_1.mp3"},"examples":[{"en":"The newspaper article caused the actor considerable distress.","cn":"报上的文章给这位演员带来极大的痛苦。"},{"en":"It is a rule of the sea to help another boat in distress.","cn":"救助别的遇难船是海上的规则。"}]},"disturb":{"oxford":{"phon":"dɪˈstɜːb","pos":"verb","senses":[{"en":"to interrupt somebody when they are trying to work, sleep, etc.","cn":"打扰；干扰；妨碍","ex":{"en":"I'm sorry to disturb you, but can I talk to you for a moment?","cn":"对不起，打扰你一下，我能跟你谈一会儿吗？"}},{"en":"to make somebody worry","cn":"使焦虑；使不安；使烦恼","ex":{"en":"The letter shocked and disturbed me.","cn":"这封信使我感到震惊和不安。"}},{"en":"to move something or change its position","cn":"搅乱；弄乱；搞乱","ex":{"en":"Don't disturb the papers on my desk.","cn":"别把我写字台上的文件弄乱了。"}},{"en":"to make something function differently from normal","cn":"干扰；破坏","ex":{"en":"During a magnetic storm, the earth's magnetic field is disturbed.","cn":"在磁暴期间，地球磁场受到干扰。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"打扰;干扰;妨碍","en":"If you disturb someone, you interrupt what they are doing and upset them.","ex":{"en":"I hope I'm not disturbing you.","cn":"我希望没有打扰到你。"}},{"pos":"VERB 动词","cn":"使焦虑;使不安;使烦恼","en":"If something disturbs you, it makes you feel upset or worried.","ex":{"en":"I dream about him, dreams so vivid that they disturb me for days","cn":"我几次梦见了他，梦境如此逼真，我好几天都心神不宁。"}},{"pos":"VERB 动词","cn":"搅乱;弄乱;搞乱","en":"If something is disturbed, its position or shape is changed.","ex":{"en":"He'd placed his notes in the brown envelope. They hadn't been disturbed","cn":"他将笔记放到那个棕色的信封里了，并没有人动过。"}},{"pos":"VERB 动词","cn":"干扰，破坏(形势、氛围)","en":"If something disturbs a situation or atmosphere, it spoils it or causes trouble.","ex":{"en":"Neither Baker nor Levy seemed eager to disturb the cordial atmosphere by discussing more sensitive issues","cn":"贝克和利维似乎都不愿谈及更为敏感的话题而破坏了友好的氛围。"}},{"pos":"PHRASE 短语","cn":"扰乱治安","en":"If someone is accused of disturbing the peace, they are accused of behaving in a noisy and offensive way in public."}]},"media":{"uk":"media/uk/disturb__gb_1.mp3","us":"media/us/disturb__us_1.mp3"},"examples":[{"en":"Do not disturb (= a sign placed on the outside of the door of a hotel room, office, etc.)","cn":"请勿打扰（旅馆房间、办公室等门上的提示牌）"},{"en":"I'm sorry to disturb you, but can I talk to you for a moment?","cn":"对不起，打扰你一下，我能跟你谈一会儿吗？"}]},"dingy":{"media":{"uk":"media/uk/dingy__gb_1.mp3","us":"media/us/dingy__us_1.mp3"},"oxford":{"phon":"ˈdɪndʒi","pos":"adjective","senses":[{"en":"dark and dirty","cn":"又黑又脏的；昏暗的；肮脏的","ex":{"en":"a dingy room/hotel","cn":"又黑又脏的房间／旅馆"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(建筑或地方)昏暗的，破败的","en":"A dingy building or place is rather dark and depressing, and perhaps dirty.","ex":{"en":"Shaw took me to his rather dingy office.","cn":"肖带我去了他那个陈旧昏暗的办公室。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(衣服、室内陈设等)肮脏的，褪色的，暗淡的","en":"Dingy clothes, curtains, or furnishings look dirty or dull.","ex":{"en":"...wallpaper with stripes of dingy yellow.","cn":"有暗淡的黄色条纹的墙纸"}}]},"examples":[{"en":"a dingy room/hotel","cn":"又黑又脏的房间/旅馆"},{"en":"dingy curtains/clothes","cn":"脏得发黑的窗帘/衣服"}]},"diverse":{"media":{"uk":"media/uk/diverse__gb_1.mp3","us":"media/us/diverse__us_1.mp3"},"oxford":{"phon":"daɪˈvɜːs","pos":"adjective","senses":[{"en":"very different from each other and of various kinds","cn":"不同的；相异的；多种多样的；形形色色的","ex":{"en":"People from diverse cultures were invited to the event.","cn":"不同文化背景的人获邀参加这次活动。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"形形色色的;各式各样的","en":"If a group or range of things is diverse, it is made up of a wide variety of things.","ex":{"en":"...shops selling a diverse range of gifts","cn":"出售各种礼品的商店"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不同的;迥异的","en":"Diverse people or things are very different from each other.","ex":{"en":"Jones has a much more diverse and perhaps younger audience.","cn":"琼斯的观众群更为多样化而且可能更年轻。"}}]},"examples":[{"en":"My interests are very diverse.","cn":"我的兴趣非常广泛。"},{"en":"people from diverse cultures","cn":"不同文化背景的人"}]},"disciplinary":{"oxford":{"phon":"ˌdɪsəˈplɪnəri","pos":"adjective","senses":[{"en":"connected with the punishment of people who break rules","cn":"有关纪律的；执行纪律的；惩戒性的","ex":{"en":"a disciplinary hearing (= to decide if somebody has done something wrong)","cn":"纪律审讯"}},{"en":"connected with an area of knowledge, especially a subject that people study in a university","cn":"（尤指大学）学科的","lab":"formal","ex":{"en":"Students need to broaden and deepen their disciplinary knowledge.","cn":"学生需要拓宽和深化他们的学科知识。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"惩戒性的;执行纪律的","en":"Disciplinary bodies or actions are concerned with making sure that people obey rules or regulations and that they are punished if they do not.","ex":{"en":"He will now face a disciplinary hearing for having an affair","cn":"他因有外遇而要面临纪律听证会的裁决。"}}]},"media":{"uk":"media/uk/disciplinary__gb_1.mp3","us":"media/us/disciplinary__us_1.mp3"},"examples":[{"en":"The company will be taking disciplinary action against him.","cn":"公司将对他进行纪律处分。"},{"en":"a disciplinary hearing (= to decide if sb has done sth wrong)","cn":"纪律审讯"}]},"diet":{"oxford":{"phon":"ˈdaɪət","pos":"noun","senses":[{"en":"the food and drink that you eat and drink regularly","cn":"日常饮食；日常食物","g":"[countable, uncountable]","ex":{"en":"to eat a healthy, balanced diet","cn":"吃健康均衡的食物"}},{"en":"a limited variety or amount of food that you eat for medical reasons or because you want to lose weight; a time when you only eat this limited variety or amount","cn":"规定饮食（为健康或减肥等目的）；规定饮食的时期","g":"[countable, uncountable]","lab":"British English","ex":{"en":"He followed a strict low-fat diet.","cn":"他严格坚持低脂饮食。"}},{"en":"a large amount of a limited range of activities","cn":"大量单调的活动","g":"[singular]","lab":"disapproving","ex":{"en":"Children today are brought up on a diet of video games and TV on demand.","cn":"如今的孩子是在打电子游戏和看点播电视片中长大的。"}},{"en":"to eat less food or only food of a particular type in order to lose weight","cn":"节食；进行规定饮食","ex":{"en":"She's always dieting but she never seems to lose any weight.","cn":"她总是在节食，但体重好像并未减少。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"日常饮食;日常食物","en":"Your diet is the type and range of food that you regularly eat.","ex":{"en":"It's never too late to improve your diet.","cn":"什么时候改善饮食都为时不晚。"}},{"pos":"N-COUNT 可数名词","cn":"(医生指定的)特别饮食，规定饮食","en":"If a doctor puts someone on a diet, he or she makes them eat a special type or range of foods in order to improve their health.","ex":{"en":"He was put on a diet of milky food.","cn":"他按照医嘱要食用乳制品。"}},{"pos":"N-VAR 可变名词","cn":"（为减轻体重的）限制饮食，节食","en":"If you are on a diet, you eat special kinds of food or you eat less food than usual because you are trying to lose weight.","ex":{"en":"Have you been on a diet? You've lost a lot of weight","cn":"你最近在节食吗？你瘦了好多。"}},{"pos":"VERB 动词","cn":"(为减轻体重而)限制饮食，节食","en":"If you are dieting, you eat special kinds of food or you eat less food than usual because you are trying to lose weight.","ex":{"en":"I've been dieting ever since the birth of my fourth child","cn":"我生完第四个孩子后就一直在节食。"}},{"pos":"ADJ 形容词","cn":"(饮料或食物)有助于减肥的，低热量的，低卡路里的","en":"Diet drinks or foods have been specially produced so that they do not contain many calories.","ex":{"en":"...sugar-free diet drinks.","cn":"无糖低热量饮料"}},{"pos":"N-COUNT 可数名词","cn":"(尤指令人不快或劣质的东西的)大量","en":"If you are fed on a diet of something, especially something unpleasant or of poor quality, you receive or experience a very large amount of it.","ex":{"en":"The radio had fed him a diet of pop songs","cn":"他从广播里听到的都是千篇一律的流行歌曲。"}}]},"media":{"uk":"media/uk/diet__gb_1.mp3","us":"media/us/diet__us_1.mp3"},"examples":[{"en":"Children today are brought up on a diet of television cartoons and soap operas.","cn":"如今的孩子是看电视上的动画片和肥皂剧长大的。"},{"en":"the Japanese diet of rice, vegetables and fish","cn":"米饭、蔬菜和鱼这些日本人常吃的食物"}]},"didn't":{"media":{"uk":"media/uk/didn_t_1_gb_1.mp3","us":"media/us/didn_t_1_us_1.mp3"},"oxford":{"phon":"ˈdɪdnt","pos":"short form","senses":[{"en":"did not","cn":""}]},"collins":{"senses":[{"pos":"","cn":"(did not 的常用口语形式)","en":"Didn't is the usual spoken form of 'did not'."}]},"examples":[{"en":"You saw him, didn’t you?","cn":""},{"en":"I didn’t want to go.","cn":""}]},"disgust":{"media":{"uk":"media/uk/disgust__gb_1.mp3","us":"media/us/disgust__us_1.mp3"},"oxford":{"phon":"dɪsˈɡʌst","pos":"noun","senses":[{"en":"a strong feeling of dislike for somebody/something that you feel is unacceptable, or for something that looks, smells, etc. unpleasant","cn":"厌恶；憎恶；反感","ex":{"en":"The idea fills me with disgust.","cn":"这个想法实在令我恶心。"}},{"en":"if something disgusts you, it makes you feel shocked and almost sick because it is so unpleasant","cn":"使作呕；使厌恶；使反感","ex":{"en":"The level of violence in the film really disgusted me.","cn":"影片中的暴力程度实在让我反感。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"厌恶;憎恶","en":"Disgust is a feeling of very strong dislike or disapproval.","ex":{"en":"He spoke of his disgust at the incident","cn":"他谈到了他对这件事的厌恶。"}},{"pos":"VERB 动词","cn":"使厌恶;使憎恶","en":"To disgust someone means to make them feel a strong sense of dislike and disapproval.","ex":{"en":"He disgusted many with his boorish behaviour.","cn":"他的粗野行为让很多人都讨厌他。"}}]},"examples":[{"en":"She expressed her disgust at the programme by writing a letter of complaint.","cn":"她写了封投诉信，表示对这个节目的反感。"},{"en":"She wrinkled her nose in disgust at the smell.","cn":"她闻到那气味，恶心地皱起了鼻子。"}]},"disturbing":{"oxford":{"phon":"dɪˈstɜːbɪŋ","pos":"adjective","senses":[{"en":"making you feel anxious and upset or shocked","cn":"引起烦恼的；令人不安的；引起恐慌的","ex":{"en":"a disturbing piece of news","cn":"一则令人不安的消息"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"引起烦恼的;令人不安的;引起恐慌的","en":"Something that is disturbing makes you feel worried or upset.","ex":{"en":"There was something about him she found disturbing","cn":"他身上有某种东西使她不安。"}}]},"media":{"uk":"media/uk/disturbing__gb_1.mp3","us":"media/us/disturbing__us_1.mp3"},"examples":[{"en":"a disturbing piece of news","cn":"一则令人不安的消息"},{"en":"a disturbing increase in the crime rate","cn":"令人不安的犯罪率增幅"}],"base":"disturb"},"difference":{"media":{"uk":"media/uk/difference__gb_1.mp3","us":"media/us/difference__us_1.mp3"},"oxford":{"phon":"ˈdɪfrəns","pos":"noun","senses":[{"en":"the way in which two people or things are not like each other; the way in which somebody/something has changed","cn":"差别；差异；不同（之处）；变化（之处）","g":"[countable, uncountable]","ex":{"en":"Americans and Brits speak the same language, but there are big cultural differences.","cn":"美国人和英国人说同一种语言，但文化差异很大。"}},{"en":"the amount that something is greater or smaller than something else","cn":"差；差额","g":"[singular, uncountable]","ex":{"en":"We measured the difference in temperature.","cn":"我们测量了温度的变化。"}},{"en":"a disagreement between people","cn":"意见分歧；不和","g":"[countable]","ex":{"en":"We have our differences, but she's still my sister.","cn":"我们之间虽然不和，但她仍旧是我的妹妹。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"差别;差异;不同之处","en":"The difference between two things is the way in which they are unlike each other.","ex":{"en":"That is the fundamental difference between the two societies","cn":"那是这两个社会之间的根本性差异。"}},{"pos":"N-SING 单数名词","cn":"差（量）；差额","en":"A difference between two quantities is the amount by which one quantity is less than the other.","ex":{"en":"The difference is 8532.","cn":"差为 8,532。"}},{"pos":"N-COUNT 可数名词","cn":"（意见的）分歧，不和","en":"If people have their differences about something, they disagree about it.","ex":{"en":"The two communities are learning how to resolve their differences.","cn":"这两个社群正在学着如何解决彼此之间的分歧。"}},{"pos":"PHRASE 短语","cn":"有…影响;起…作用","en":"If something makes a difference or makes a lot of difference, it affects you and helps you in what you are doing. If something makes no difference, it does not have any effect on what you are doing.","ex":{"en":"Where you live can make such a difference to the way you feel","cn":"住在哪里会极大地影响你的感受。"}},{"pos":"PHRASE 短语","cn":"（在数量、价格上）折中，各让一步","en":"If you split the difference with someone, you agree on an amount or price which is halfway between two suggested amounts or prices.","ex":{"en":"Shall we split the difference and say $7,500?","cn":"我们折中一下，7,500 美元怎么样？"}},{"pos":"PHRASE 短语","cn":"非常有趣的;与众不同的","en":"If you describe a job or holiday, for example, as a job with a difference or a holiday with a difference, you mean that the job or holiday is very interesting and unusual.","ex":{"en":"For a beach resort with a difference, try Key West.","cn":"如果想去一个与众不同的海滨度假胜地，那就去基韦斯特吧。"}},{"pos":"PHRASE 短语","cn":"意见分歧;看法不同","en":"If there is a difference of opinion between two or more people or groups, they disagree about something.","ex":{"en":"Was there a difference of opinion over what to do with the Nobel Prize money?","cn":"在如何利用那笔诺贝尔奖金的问题上有不同意见吗？"}}]},"examples":[{"en":"He was studying the complex similarities and differences between humans and animals.","cn":"他在研究人和动物之间错综复杂的相似与不同之处。"},{"en":"‘Shall we go on Friday or Saturday?’ ‘It makes no difference (to me).’ “","cn":"我们星期五还是星期六去？” “（我）无所谓。”"}]},"di":{"media":{"uk":"media/uk/di__gb_1.mp3","us":"media/us/di__us_1.mp3"},"oxford":{"phon":"ˌdiː ˈaɪ","pos":"noun","senses":[{"en":"a British police officer of middle rank (the abbreviation for ‘Detective Inspector’)","cn":"探长（英国中级警官，全写为 Detective Inspector）","ex":{"en":"DI Ross","cn":"罗斯探长"}},{"en":"a first name for girls, short for Diana or Diane","cn":"黛（女子名，Diana 或 Diane 缩写）","pos":""},{"en":"twice; two; double","cn":"二；双","ex":{"en":"dicotyledon","cn":"双子叶植物"},"pos":"combining form"},{"en":"containing two atoms or groups of the type mentioned","cn":"含有两个原子的；含有两组…物质的","lab":"chemistry","ex":{"en":"carbon dioxide","cn":"二氧化碳"},"pos":"combining form"}]},"examples":[{"en":"DI Ross","cn":"罗斯探长"}]},"disproportionate":{"oxford":{"phon":"ˌdɪsprəˈpɔːʃənət","pos":"adjective","senses":[{"en":"too large or too small when compared with something else","cn":"不成比例的；不相称的；太大（或太小）的","ex":{"en":"The area contains a disproportionate number of young middle-class families.","cn":"这一区年轻的中产阶级家庭特别多。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(数量或尺寸)不成比例的，不相称的","en":"Something that is disproportionate is surprising or unreasonable in amount or size, compared with something else.","ex":{"en":"A disproportionate amount of time was devoted to one topic","cn":"纠缠在同一个话题上的时间太长了。"}}]},"media":{"uk":"media/uk/disproportionate__gb_1.mp3","us":"media/us/disproportionate__us_1.mp3"},"examples":[{"en":"The lower-paid spend a disproportionately large amount of their earnings on food.","cn":"低工资者将收入花在食物上的比例很大。"},{"en":"The area contains a disproportionate number of young middle-class families.","cn":"此地年轻的中产阶级家庭特别多。"}]},"dissatisfied":{"media":{"uk":"media/uk/dissatisfied__gb_1.mp3","us":"media/us/dissatisfied__us_1.mp3"},"oxford":{"phon":"dɪsˈsætɪsfaɪd","pos":"adjective","senses":[{"en":"not happy or satisfied with somebody/something","cn":"（对…）不满的，不高兴的，不满意的","ex":{"en":"dissatisfied customers","cn":"不满的顾客"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不满的;不高兴的","en":"If you are dissatisfied with something, you are not contented or pleased with it.","ex":{"en":"82% of voters are dissatisfied with the way their country is being governed","cn":"82% 的选民对本国的治理方式不满意。"}}]},"examples":[{"en":"If you are dissatisfied with our service, please write to the manager.","cn":"对于服务如有不满，请函告经理。"},{"en":"dissatisfied customers","cn":"不满的顾客"}]},"disapproval":{"media":{"uk":"media/uk/disapproval__gb_1.mp3","us":"media/us/disapproval__us_1.mp3"},"oxford":{"phon":"ˌdɪsəˈpruːvl","pos":"noun","senses":[{"en":"a feeling that you do not like an idea, an action or somebody’s behaviour because you think it is bad, not suitable or going to have a bad effect on somebody else","cn":"不赞成；反对","ex":{"en":"to show/express disapproval","cn":"表明／表示反对"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"不赞同;反对;不许可","en":"If you feel or show disapproval of something or someone, you feel or show that you do not approve of them.","ex":{"en":"His action had been greeted with almost universal disapproval.","cn":"他的行动几乎遭到了一致的反对。"}}]},"examples":[{"en":"She looked at my clothes with disapproval.","cn":"她不满意地看着我的衣服。"},{"en":"He shook his head in disapproval.","cn":"他摇了摇头，表示反对。"}]},"distance":{"media":{"uk":"media/uk/distance__gb_1.mp3","us":"media/us/distance__us_1.mp3"},"oxford":{"phon":"ˈdɪstəns","pos":"noun","senses":[{"en":"the amount of space between two places or things","cn":"距离；间距","g":"[countable, uncountable]","ex":{"en":"a short/long distance","cn":"短距离；长距离"}},{"en":"being far away in space or in time","cn":"（空间的）遥远；（时间的）久远，间隔","g":"[uncountable]","ex":{"en":"Distance is no problem on the internet.","cn":"在互联网上距离根本不是问题。"}},{"en":"a point that is a particular amount of space away from something else","cn":"远方；远处","g":"[singular]","ex":{"en":"You'll never get the ball in from that distance.","cn":"你绝不可能从那么远的地方把球投进去。"}},{"en":"a difference or lack of a connection between two things","cn":"（两事物之间的）差异，无关","g":"[countable, usually singular, uncountable]","lab":"British English","ex":{"en":"The distance between fashion and art remains as great as ever.","cn":"时尚与艺术之间的差别之大依然如故。"}},{"en":"a situation in which there is a lack of friendly feelings or of a close relationship between two people or groups of people","cn":"冷淡；疏远","g":"[uncountable, countable]","ex":{"en":"The coldness and distance in her voice took me by surprise.","cn":"她话语中透出的冷淡和疏远使我感到意外。"}},{"en":"to become less involved or connected with somebody/something","cn":"拉开距离；与…疏远","ex":{"en":"When he retired, he tried to distance himself from politics.","cn":"退休后，他便尽量使自己置身于政治之外。"},"pos":"verb"},{"en":"to make somebody/something less involved or connected with somebody/something","cn":"使疏远；使远离","ex":{"en":"Her mother wished to distance her from the rough village children.","cn":"她母亲希望她远离那些粗野的乡下孩子。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"距离;间距","en":"The distance between two points or places is the amount of space between them.","ex":{"en":"...the distance between the island and the nearby shore","cn":"该岛和附近陆地之间的距离"}},{"pos":"N-UNCOUNT 不可数名词","cn":"遥远;间隔","en":"When two things are very far apart, you talk about the distance between them.","ex":{"en":"The distance wouldn't be a problem.","cn":"距离不成问题。"}},{"pos":"ADJ 形容词","cn":"远程的;函授的","en":"Distance learning or distance education involves studying at home and sending your work to a college or university, rather than attending the college or university in person.","ex":{"en":"I'm doing a theology degree by distance learning.","cn":"我正通过远程教育课程攻读神学学位。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（人际关系的）疏远；（事物间的）差距","en":"When you want to emphasize that two people or things do not have a close relationship or are not the same, you can refer to the distance between them.","ex":{"en":"...the emotional distance between them","cn":"他们之间情感上的疏远"}},{"pos":"N-SING 单数名词","cn":"远处;远方","en":"If you can see something in the distance, you can see it, far away from you.","ex":{"en":"We suddenly saw her in the distance","cn":"我们突然看见她在远处。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"冷淡;不友好","en":"Distance is coolness or unfriendliness in the way that someone behaves towards you.","ex":{"en":"There were periods of sulking, of pronounced distance, of coldness.","cn":"沉闷、明显不友好和冷淡的场面多次出现。"}},{"pos":"VERB 动词","cn":"使疏远;对…冷淡;使不介入","en":"If you distance yourself from a person or thing, or if something distances you from them, you feel less friendly or positive towards them, or become less involved with them.","ex":{"en":"The author distanced himself from some of the comments in his book","cn":"作者使自己书中的某些评论不带个人色彩。"}},{"pos":"PHRASE 短语","cn":"在远处;相距遥远;久远地","en":"If you are at a distance from something, or if you see it or remember it from a distance, you are a long way away from it in space or time.","ex":{"en":"The only way I can cope with my mother is at a distance","cn":"我可以和我妈妈相处的唯一方法就是保持距离。"}},{"pos":"PHRASE 短语","cn":"保持疏远;保持距离","en":"If you keep your distance from someone or something or keep them at a distance, you do not become involved with them.","ex":{"en":"Jay had always tended to keep his girlfriends at a distance.","cn":"杰伊一贯和他的女朋友们保持距离。"}},{"pos":"PHRASE 短语","cn":"不靠近;保持距离","en":"If you keep your distance from someone or something, you do not get physically close to them.","ex":{"en":"He walked towards the doorway, careful to keep his distance.","cn":"他走向门口，小心翼翼地保持着距离。"}}]},"examples":[{"en":"Nobody thought he would last 15 rounds, but he went the full distance.","cn":"谁都以为他坚持不到 15 个回合，可是他却打完了全场。"},{"en":"She was warned to keep her distance from Charles if she didn't want to get hurt.","cn":"有人告诫她说，如果不想受到伤害，就与查尔斯离得远一点。"}]},"distractions":{"lemma":"distraction"},"discussion":{"media":{"uk":"media/uk/discussion__gb_1.mp3","us":"media/us/discussion__us_1.mp3"},"oxford":{"phon":"dɪˈskʌʃn","pos":"noun","senses":[{"en":"a conversation about somebody/something; the process of discussing somebody/something","cn":"讨论；商讨","ex":{"en":"I discovered something interesting during a family discussion.","cn":"在一次家庭讨论中我发现了一些有趣的事情。"}},{"en":"a speech or a piece of writing that discusses many different aspects of a subject","cn":"详述；论述","ex":{"en":"I have chosen to focus my discussion on a single work.","cn":"我决定集中讨论一部作品。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"讨论;商讨","en":"If there is discussion about something, people talk about it, often in order to reach a decision.","ex":{"en":"There was a lot of discussion about the wording of the report","cn":"关于此则报道的措辞议论纷纷。"}},{"pos":"N-COUNT 可数名词","cn":"论述;详述","en":"A discussion of a subject is a piece of writing or a lecture in which someone talks about it in detail.","ex":{"en":"For a discussion of biology and sexual politics, see chapter 4.","cn":"生态政治和性别政治论述请见第4章。"}},{"pos":"ADJ 形容词","cn":"探讨性的","en":"A discussion document or paper is one that contains information and usually proposals for people to discuss."}]},"examples":[{"en":"The President told waiting reporters there had been a constructive dialogue.","cn":"总统告诉等候的记者，刚才进行了一次富有建设性的对话。"},{"en":"After considerable discussion, they decided to accept our offer.","cn":"他们经过反复讨论后决定接受我们的报价。"}]},"disagreeing":{"lemma":"disagree"},"disgusted":{"oxford":{"phon":"dɪsˈɡʌstɪd","pos":"adjective","senses":[{"en":"feeling or showing disgust","cn":"厌恶的；憎恶的；反感的","ex":{"en":"I was disgusted at/by the sight.","cn":"我一看就恶心。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"厌恶的;憎恶的","en":"If you are disgusted, you feel a strong sense of dislike and disapproval at something.","ex":{"en":"I'm disgusted with the way that he was treated","cn":"他受到如此对待让我气愤。"}}]},"media":{"uk":"media/uk/disgusted__gb_1.mp3","us":"media/us/disgusted__us_1.mp3"},"examples":[{"en":"He was disgusted to see such awful living conditions.","cn":"看到如此糟糕的生活环境他觉得很气愤。"},{"en":"I was disgusted with myself for eating so much.","cn":"我吃得太多，自己也觉得无地自容。"}],"base":"disgust"},"disappear":{"media":{"uk":"media/uk/disappear__gb_1.mp3","us":"media/us/disappear__us_1.mp3"},"oxford":{"phon":"ˌdɪsəˈpɪə(r)","pos":"verb","senses":[{"en":"to become impossible to see","cn":"消失；不见","g":"[intransitive]","ex":{"en":"With that, Matt promptly disappeared.","cn":"说完，马特瞬间消失了。"}},{"en":"to stop existing","cn":"不复存在；灭绝；消亡","g":"[intransitive]","ex":{"en":"Her nervousness quickly disappeared once she was on stage.","cn":"她一上台紧张情绪便迅速消失了。"}},{"en":"to be lost or impossible to find","cn":"失踪；丢失","g":"[intransitive]","ex":{"en":"I can never find a pen in this house. They disappear as soon as I buy them.","cn":"我在家里从来找不到一支笔。每次我一买来就不翼而飞。"}},{"en":"if a person is disappeared, they are arrested or captured and kept in prison without trial or killed, usually for political reasons","cn":"使消失，使不存在（因政治原因拘捕或关押）；秘密（或非法）除掉","g":"[transitive, usually passive]","ex":{"en":"10 000 people have been disappeared and over 160 000 displaced.","cn":"10000人失踪，160000多人流离失所。"}},{"en":"to remove something secretly or illegally so that it cannot be found","cn":"不复存在；灭绝；消亡","g":"[transitive, often passive]","ex":{"en":"In the last five years, nearly 5 000 companies have been disappeared from the registry.","cn":"过去五年里，近 5000 家公司从登记处消失。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"(通常指因位置改变而)消失,不见","en":"If you say that someone or something disappears, you mean that you can no longer see them, usually because you or they have changed position.","ex":{"en":"The black car drove away from them and disappeared","cn":"那辆黑色轿车驶离了他们的视线。"}},{"pos":"VERB 动词","cn":"消失;失踪","en":"If someone or something disappears, they go away or are taken away somewhere where nobody can find them.","ex":{"en":"...a Japanese woman who disappeared thirteen years ago","cn":"一个 13 年前失踪的日本女人"}},{"pos":"VERB 动词","cn":"不复存在;灭绝;消亡","en":"If something disappears, it stops existing or happening.","ex":{"en":"The immediate security threat has disappeared.","cn":"直接的安全威胁已不复存在了。"}}]},"examples":[{"en":"I can never find a pen in this house. They disappear as soon as I buy them.","cn":"我在家里从来找不到一支笔。每次我一买来就不翼而飞。"},{"en":"Our countryside is disappearing at an alarming rate.","cn":"我们的农村地区正在以惊人的速度消亡。"}]},"dinner-dance":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（为了成功或存活的）依靠，依赖","en":"Your dependence on something or someone is your need for them in order to succeed or be able to survive.","ex":{"en":"...the city's traditional dependence on tourism","cn":"该市传统上对旅游业的依赖"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(对毒品或酒精的)依赖，瘾，癖","en":"If you talk about drug dependence or alcohol dependence, you are referring to a situation where someone is addicted to drugs or is an alcoholic.","ex":{"en":"French doctors tend to regard drug dependence as a form of deep-rooted psychological disorder.","cn":"法国医生倾向于把毒瘾看作是一种根深蒂固的心理障碍。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（受其影响或决定的）依赖（关系）","en":"You talk about the dependence of one thing on another when the first thing will be affected or determined by the second.","ex":{"en":"...the dependence of circulation on production.","cn":"流通对生产的依赖"}}]},"oxford":{"phon":"ˈdɪnə dɑːns","pos":"noun","senses":[{"en":"a social event in the evening that includes a formal meal and dancing","cn":"晚宴舞会"}]}},"difficulty":{"media":{"uk":"media/uk/difficulty__gb_1.mp3","us":"media/us/difficulty__us_1.mp3"},"oxford":{"phon":"ˈdɪfɪkəlti","pos":"noun","senses":[{"en":"a problem; a thing or situation that causes problems","cn":"困难；难题；难事；困境","g":"[countable, usually plural, uncountable]","ex":{"en":"the difficulties of English syntax","cn":"英语句法的难点"}},{"en":"the state or quality of being hard to do or to understand; the effort that something involves","cn":"艰难；困难；费劲；辛苦","g":"[uncountable]","ex":{"en":"I had considerable difficulty (in) persuading her to leave.","cn":"我费了好大的劲说服她离开。"}},{"en":"how hard something is","cn":"困难程度；难度","g":"[uncountable]","ex":{"en":"Both roles had a high degree of difficulty.","cn":"两个角色的难度都很高。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"难题;难事","en":"A difficulty is a problem.","ex":{"en":"...the difficulty of getting accurate information","cn":"获取准确信息的难题"}},{"pos":"N-UNCOUNT 不可数名词","cn":"困难;艰难","en":"If you have difficulty doing something, you are not able to do it easily.","ex":{"en":"Do you have difficulty getting up?","cn":"你能站起来吗？"}},{"pos":"PHRASE 短语","cn":"遭遇困难;身处困境","en":"If you are in difficulty or in difficulties, you are having a lot of problems.","ex":{"en":"You have to admit that you are, in fact, in difficulties","cn":"你不得不承认，你事实上是陷入了困境。"}}]},"examples":[{"en":"The changes were made with surprisingly little difficulty.","cn":"这些变化几乎没有遇到阻力，简直不可思议。"},{"en":"We've run into difficulties/difficulty with the new project.","cn":"我们在这项新工程中遇到了难题。"}]},"divergence":{"media":{"uk":"media/uk/divergence__gb_1.mp3","us":"media/us/divergence__us_1.mp3"},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"(意见、态度等的)分歧，差异","en":"A divergence is a difference between two or more things, attitudes, or opinions.","ex":{"en":"There's a substantial divergence of opinion within the party","cn":"党内存在着重大的意见分歧。"}}]},"examples":[{"en":"a wide divergence of opinion","cn":"严重的意见分歧"},{"en":"The two species diverged millions of years ago.","cn":""}],"oxford":{"phon":"daɪˈvɜːdʒəns","pos":"noun","senses":[{"en":"the process or fact of separating or becoming different","cn":"分歧：分离或变得不同的过程或事实","ex":{"en":"the divergence of these two species","cn":"这两个物种的分歧"}},{"en":"a difference in opinions, views, etc.","cn":"分歧；相异","ex":{"en":"a wide divergence of opinion","cn":"意见迥异"}},{"en":"the process of becoming different from what is expected, planned, etc.","cn":"偏离；背离；违背","ex":{"en":"a divergence from traditionally held beliefs","cn":"与传统信仰的背离"}}]}},"disheartening":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"令人灰心的;令人气馁的","en":"If something is disheartening, it makes you feel disappointed and less confident or less hopeful."}]},"media":{"uk":"media/uk/disheartening__gb_1.mp3","us":"media/us/disheartening__us_1.mp3"},"examples":[{"en":"a disheartening experience","cn":"令人沮丧的经历"}],"oxford":{"phon":"dɪsˈhɑːtnɪŋ","pos":"adjective","senses":[{"en":"making you lose hope or confidence","cn":"使沮丧；使失去信心；使灰心","ex":{"en":"a disheartening experience","cn":"令人沮丧的经历"}}]}},"disabled":{"oxford":{"phon":"dɪsˈeɪbld","pos":"adjective","senses":[{"en":"having a condition that makes it difficult for you to do some things that most other people can do","cn":"丧失能力的；有残疾的；无能力的","ex":{"en":"physically/developmentally/intellectually disabled","cn":"身体/发育/智力障碍"}},{"en":"people who are disabled","cn":"残疾人；伤残者","g":"[plural]","lab":"old-fashioned","ex":{"en":"caring for the sick, elderly and disabled","cn":"关心老弱病残"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"丧失能力的;有残疾的","en":"Someone who is disabled has an illness, injury, or condition that tends to restrict the way that they can live their life, especially by making it difficult for them to move about.","ex":{"en":"...practical problems encountered by disabled people in the workplace.","cn":"在工作场所中残疾人所遇到的实际问题"}}]},"media":{"uk":"media/uk/disabled__gb_1.mp3","us":"media/us/disabled__us_1.mp3"},"examples":[{"en":"The museum has special facilities for blind and partially sighted visitors.","cn":"博物馆有专门设备供失明和视力有缺陷的参观者使用。"},{"en":"He was born disabled.","cn":"他天生残疾。"}]},"dismissal":{"oxford":{"phon":"dɪsˈmɪsl","pos":"noun","senses":[{"en":"the act of dismissing somebody from their job; an example of this","cn":"解雇；开除；撤职","g":"[uncountable, countable]","ex":{"en":"He still hopes to win his claim against unfair dismissal.","cn":"他仍然希望赢得无理解雇的索赔。"}},{"en":"the failure to consider something as important","cn":"不予考虑；不予理会；摒弃","g":"[uncountable]","ex":{"en":"Her casual dismissal of the threats seemed irresponsible.","cn":"她对这些威胁毫不在乎而不予理会，似乎很不负责任。"}},{"en":"the act of not allowing a trial or legal case to continue, usually because there is not enough evidence","cn":"（诉讼的）驳回，不予受理","g":"[uncountable, countable]","lab":"law","ex":{"en":"the dismissal of the appeal","cn":"驳回上诉"}},{"en":"the act of sending somebody away or allowing them to leave","cn":"解散；打发走","g":"[uncountable, countable]"},{"en":"the end of the innings of a player or team","cn":"（球员或球队的）退场，出局","g":"[uncountable, countable]"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"解雇;开除;免职","en":"When an employee is dismissed from their job, you can refer to their dismissal .","ex":{"en":"...Mr Low's dismissal from his post at the head of the commission.","cn":"免去洛先生的委员会主任一职"}},{"pos":"N-UNCOUNT 不可数名词","cn":"不予考虑;不予理会","en":"Dismissal of something means deciding or saying that it is not important.","ex":{"en":"...their high-handed dismissal of public opinion.","cn":"他们对公众意见的蛮横漠视"}}]},"media":{"uk":"media/uk/dismissal__gb_1.mp3","us":"media/us/dismissal__us_1.mp3"},"examples":[{"en":"Her casual dismissal of the threats seemed irresponsible.","cn":"她对这些威胁毫不在乎而不予理会，似乎很不负责任。"},{"en":"He still hopes to win his claim against unfair dismissal.","cn":"他声称遭无理解雇，仍然希望赢得申诉。"}]},"differs":{"lemma":"differ","media":{"uk":"media/uk/differ__gb_1.mp3","us":"media/us/differ__us_1.mp3"}},"divorce":{"media":{"uk":"media/uk/divorce__gb_1.mp3","us":"media/us/divorce__us_1.mp3"},"oxford":{"phon":"dɪˈvɔːs","pos":"noun","senses":[{"en":"the legal ending of a marriage","cn":"离婚","g":"[uncountable, countable]","lab":"especially North American English","ex":{"en":"The marriage ended in divorce in 1996.","cn":"这桩婚姻在 1996 年以离婚告终。"}},{"en":"an act of separating two things; the ending of a relationship between two things","cn":"分离；脱离","g":"[countable, usually singular]","lab":"formal","ex":{"en":"the divorce between religion and science","cn":"宗教与科学的分裂"}},{"en":"to end your marriage to somebody legally","cn":"与（某人）离婚；离婚","g":"[transitive, intransitive]","ex":{"en":"They're getting divorced.","cn":"他们要离婚了。"},"pos":"verb"},{"en":"to separate a person, an idea, a subject, etc. from something; to keep two things separate","cn":"使分离；使脱离","g":"[transitive, often passive]","lab":"formal","ex":{"en":"They believed that art should be divorced from politics.","cn":"他们认为艺术应该与政治分开。"},"pos":"verb"},{"en":"a man whose marriage has been legally ended","cn":"离婚男子"}]},"collins":{"senses":[{"pos":"","cn":"离婚","en":"A divorce is the formal ending of a marriage by law.","ex":{"en":"Numerous marriages now end in divorce","cn":"现在许多婚姻都以离婚收场。"}},{"pos":"","cn":"(与…)离婚","en":"If a man and woman divorce or if one of them divorces the other, their marriage is legally ended.","ex":{"en":"My parents divorced when I was very young","cn":"我很小的时候父母就离婚了。"}},{"pos":"","cn":"分离;脱离","en":"A divorce of one thing from another, or a divorce between two things is a separation between them which is permanent or is likely to be permanent.","ex":{"en":"...this divorce of Christian culture from the roots of faith","cn":"基督教文化和信仰根基的脱离"}},{"pos":"","cn":"使分离;使分开","en":"If you say that one thing cannot be divorced from another, you mean that the two things cannot be considered as different and separate things.","ex":{"en":"Good management in the police cannot be divorced from accountability","cn":"对警察队伍的良好管理和应负的责任是分不开的。"}}]},"examples":[{"en":"The marriage ended in divorce in 1996.","cn":"这桩婚姻在 1996 年以离婚告终。"},{"en":"When he was depressed, he felt utterly divorced from reality.","cn":"他沮丧时便感到完全脱离了现实。"}]},"director":{"media":{"uk":"media/uk/director__gb_1.mp3","us":"media/us/director__us_1.mp3"},"oxford":{"phon":"dəˈrektə(r)","pos":"noun","senses":[{"en":"one of a group of senior managers who run a company","cn":"董事；理事；经理","ex":{"en":"a non-executive director","cn":"非执行董事"}},{"en":"a person in charge of a film or play who tells the actors and staff what to do","cn":"（电影、戏剧等的）导演","ex":{"en":"a famous film director","cn":"著名电影导演"}},{"en":"a person who is in charge of a particular activity or department in a company, a college, etc.","cn":"（某一活动的）负责人；（公司部门的）主任，经理；（学院的）院长","ex":{"en":"She was artistic director of the city's photography festival.","cn":"她是该市摄影节的艺术总监。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（戏剧、电影、电视等的）导演","en":"The director of a play, film, or television programme is the person who decides how it will appear on stage or screen, and who tells the actors and technical staff what to do."},{"pos":"N-COUNT 可数名词","cn":"主任;主管;署长;局长","en":"In some organizations and public authorities, the person in charge is referred to as the director .","ex":{"en":"...the director of the intensive care unit at Guy's Hospital.","cn":"盖伊医院重症护理病房的主任"}},{"pos":"N-COUNT 可数名词","cn":"(公司的)经理，董事","en":"The directors of a company are its most senior managers, who meet regularly to make important decisions about how it will be run.","ex":{"en":"He served on the board of directors of a local bank.","cn":"他是当地一家银行的董事会成员之一。"}},{"pos":"N-COUNT 可数名词","cn":"(管弦乐队或合唱团的)指挥","en":"The director of an orchestra or choir is the person who is conducting it."}]},"examples":[{"en":"He's on the board of directors.","cn":"他是董事会成员。"},{"en":"an executive/non-executive director","cn":"执行/非执行董事"}]},"dislike":{"media":{"uk":"media/uk/dislike__gb_1.mp3","us":"media/us/dislike__us_1.mp3"},"oxford":{"phon":"dɪsˈlaɪk","pos":"verb","senses":[{"en":"to not like somebody/something","cn":"不喜爱；厌恶","ex":{"en":"Why do you dislike him so much?","cn":"你为什么那么讨厌他呢？"}},{"en":"a feeling of not liking somebody/something","cn":"不喜爱；厌恶；反感","g":"[uncountable, singular]","ex":{"en":"He did not try to hide his dislike of his boss.","cn":"他没有掩饰自己对上司的反感。"},"pos":"noun"},{"en":"a thing that you do not like","cn":"不喜欢的事物；讨厌的事物","g":"[countable, usually plural]","ex":{"en":"I've told you all my likes and dislikes.","cn":"我喜欢什么，不喜欢什么，都对你说了。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"不喜欢;厌恶","en":"If you dislike someone or something, you consider them to be unpleasant and do not like them.","ex":{"en":"We don't serve liver often because so many people dislike it","cn":"我们不常做肝这道菜，因为很多人吃不惯。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"不喜欢;反感","en":"Dislike is the feeling that you do not like someone or something.","ex":{"en":"He made no attempt to conceal his dislike of me","cn":"他毫不掩饰对我的厌恶。"}},{"pos":"N-COUNT 可数名词","cn":"厌恶的事物","en":"Your dislikes are the things that you do not like.","ex":{"en":"Consider what your likes and dislikes are about your job","cn":"想想工作中哪些部分是自己喜欢的，哪些是不喜欢的。"}},{"pos":"PHRASE 短语","cn":"厌恶;嫌憎;讨厌","en":"If you take a dislike to someone or something, you decide that you do not like them.","ex":{"en":"I took a violent dislike to him","cn":"我非常烦他。"}}]},"examples":[{"en":"She took an instant dislike to the house and the neighbourhood.","cn":"她一下子就对那栋房子以及邻近地区产生了反感。"},{"en":"Much as she disliked going to funerals (= although she did not like it at all), she knew she had to be there.","cn":"尽管她很不喜欢参加葬礼，但她知道她必须去。"}]},"dictation":{"oxford":{"phon":"dɪkˈteɪʃn","pos":"noun","senses":[{"en":"the act of speaking or reading so that somebody can write down the words or they can be recorded","cn":"口述","g":"[uncountable]","ex":{"en":"Her secretary is very good at taking dictation.","cn":"她的秘书很擅长做口授记录。"}},{"en":"a test in which students write down what is being read to them, especially in language lessons","cn":"听写","g":"[countable, uncountable]","ex":{"en":"The teacher gave them a dictation.","cn":"老师让他们听写。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"口授;口述;听写","en":"Dictation is the speaking or reading aloud of words for someone else to write down.","ex":{"en":"...taking dictation from the dean of the Faculty","cn":"记录系主任口述的内容"}},{"pos":"N-UNCOUNT 不可数名词","cn":"命令;发号施令","en":"Dictation is the giving of orders in a forceful and commanding way.","ex":{"en":"The Europeans, while keen for partnership with the US, would not accept dictation.","cn":"欧洲虽然很想与美国建立伙伴关系，但不会接受其对自己发号施令。"}}]},"media":{"uk":"media/uk/dictation__gb_1.mp3","us":"media/us/dictation__us_1.mp3"},"examples":[{"en":"There were no secretaries available to take dictation (= write down what someone is saying ) .","cn":"身边没有秘书来记录口授内容。"},{"en":"I hate doing French dictations .","cn":"我讨厌做法语听写。"}]},"difficult":{"media":{"uk":"media/uk/difficult__gb_1.mp3","us":"media/us/difficult__us_1.mp3"},"oxford":{"phon":"ˈdɪfɪkəlt","pos":"adjective","senses":[{"en":"not easy; needing effort or skill to do or to understand","cn":"指困难的、费力的、难做的、难懂的","ex":{"en":"The competition judges were given a very difficult task.","cn":"比赛评委们面临着一项非常艰巨的任务。"}},{"en":"full of problems; causing a lot of trouble","cn":"问题很多的；充满艰难困苦的；麻烦的","ex":{"en":"I found myself in a difficult situation.","cn":"我发现自己处境艰难。"}},{"en":"not easy to please; not helpful","cn":"难以讨好的；难以取悦的；不愿帮助的","ex":{"en":"a difficult child/customer/boss","cn":"难哄的孩子；难对付的顾客；难讨好的老板"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"困难的;不容易的","en":"Something that is difficult is not easy to do, understand, or deal with.","ex":{"en":"Hobart found it difficult to get her first book published","cn":"霍巴特发现要出版自己的第一本书很不容易。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"难相处的;难取悦的;不随和的","en":"Someone who is difficult behaves in an unreasonable and unhelpful way.","ex":{"en":"I had a feeling you were going to be difficult about this.","cn":"我有种感觉：你会在这件事上找别扭。"}}]},"examples":[{"en":"It's difficult for them to get here much before seven.","cn":"他们很难在七点以前早早地来到这里。"},{"en":"It is difficult for young people to find jobs around here.","cn":"年轻人要在这里附近找到工作很难。"}]},"discuss":{"media":{"uk":"media/uk/discuss__gb_1.mp3","us":"media/us/discuss__us_1.mp3"},"oxford":{"phon":"dɪˈskʌs","pos":"verb","senses":[{"en":"to talk about something with somebody, especially in order to decide something","cn":"讨论；谈论；商量","ex":{"en":"Have you discussed the problem with anyone?","cn":"你与谁商量过这个问题吗？"}},{"en":"to write or talk about something in detail, showing the different ideas and opinions about it","cn":"详述；论述","ex":{"en":"This topic will be discussed at greater length in the next chapter.","cn":"这个题目将在下一章里详细论述。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"讨论;谈论;商量","en":"If people discuss something, they talk about it, often in order to reach a decision.","ex":{"en":"I will be discussing the situation with colleagues tomorrow","cn":"明天我会和同事们讨论一下情况。"}},{"pos":"VERB 动词","cn":"详细论述;阐述","en":"If you discuss something, you write or talk about it in detail.","ex":{"en":"I will discuss the role of diet in cancer prevention in Chapter 7","cn":"我会在第7章详细论述日常饮食在抗癌中的作用。"}}]},"examples":[{"en":"We briefly discussed buying a second car.","cn":"我们草草商量过再买一辆汽车的事儿。"},{"en":"We need to discuss when we should go.","cn":"我们需要商量一下什么时候动身。"}]},"dinner":{"media":{"uk":"media/uk/dinner__gb_1.mp3","us":"media/us/dinner__us_1.mp3"},"oxford":{"phon":"ˈdɪnə(r)","pos":"noun","senses":[{"en":"the main meal of the day, eaten either in the middle of the day or in the evening","cn":"（中午或晚上吃的）正餐，主餐","g":"[uncountable, countable]","lab":"North American English also","ex":{"en":"It's time for dinner.","cn":"该吃饭了。"}},{"en":"a large formal social gathering at which dinner is eaten","cn":"宴会","g":"[countable]","ex":{"en":"The club's annual dinner will be held on 3 June.","cn":"俱乐部一年一度的宴会将于 6 月 3 日举行。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"正餐;主餐;晚餐","en":"Dinner is the main meal of the day, usually served in the early part of the evening.","ex":{"en":"She invited us to her house for dinner","cn":"她请我们去她家吃晚餐。"}},{"pos":"N-VAR 可变名词","cn":"午餐;午饭","en":"Any meal you eat in the middle of the day can be referred to as dinner . →see usage note at:"},{"pos":"N-COUNT 可数名词","cn":"晚宴;宴会","en":"A dinner is a formal social event at which a meal is served. It is held in the evening.","ex":{"en":"...a series of official lunches and dinners","cn":"一系列的正式午餐和晚宴"}}]},"examples":[{"en":"The club's annual dinner will be held on 3 June.","cn":"俱乐部一年一度的宴会将于 6 月 3 日举行。"},{"en":"I'd like to take you out to dinner tonight.","cn":"今天晚上我想带你出去吃饭。"}]},"dishonest":{"oxford":{"phon":"dɪsˈɒnɪst","pos":"adjective","senses":[{"en":"not honest; intending to trick people","cn":"不诚实的；骗人的；欺骗性的","ex":{"en":"Beware of dishonest traders in the tourist areas.","cn":"在旅游区一定要谨防奸商。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不诚实的;靠不住的","en":"If you say that a person or their behaviour is dishonest, you mean that they are not truthful or honest and that you cannot trust them.","ex":{"en":"You have been dishonest with me","cn":"你对我不诚实。"}}]},"media":{"uk":"media/uk/dishonest__gb_1.mp3","us":"media/us/dishonest__us_1.mp3"},"examples":[{"en":"I don't like him, and it would be dishonest of me to pretend otherwise.","cn":"我不喜欢他，如果假装喜欢，那就是我不诚实了。"},{"en":"Beware of dishonest traders in the tourist areas.","cn":"在旅游区一定要谨防奸商。"}]},"disappointed":{"media":{"uk":"media/uk/disappointed__gb_1.mp3","us":"media/us/disappointed__us_1.mp3"},"oxford":{"phon":"ˌdɪsəˈpɔɪntɪd","pos":"adjective","senses":[{"en":"upset because something you hoped for has not happened or been as good, successful, etc. as you expected","cn":"失望的；沮丧的；失意的","ex":{"en":"The singer has promised to refund any disappointed fans.","cn":"这位歌手已承诺给所有失望的歌迷退款。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(对某事)失望的，沮丧的，失意的","en":"If you are disappointed, you are rather sad because something has not happened or because something is not as good as you had hoped.","ex":{"en":"Castle-hunters won't be disappointed with the Isle of Man","cn":"马恩岛不会让城堡探寻者失望的。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(对某人)失望的，灰心的","en":"If you are disappointed in someone, you are rather sad because they have not behaved as well as you expected them to.","ex":{"en":"You should have accepted that. I'm disappointed in you.","cn":"你本应该接受那个的，我对你很失望。"}}]},"examples":[{"en":"I'm disappointed in you — I really thought I could trust you!","cn":"你真让我失望，我原以为可以相信你的！"},{"en":"He was disappointed to see she wasn't at the party.","cn":"看到她没来参加晚会，他感到很失望。"}]},"disruptive":{"oxford":{"phon":"dɪsˈrʌptɪv","pos":"adjective","senses":[{"en":"causing problems, noise, etc. so that something cannot continue normally","cn":"引起混乱的；扰乱性的；破坏性的","ex":{"en":"She had a disruptive influence on the rest of the class.","cn":"她搅扰了班上其他学生。"}},{"en":"new and original, in a way that causes major changes to how something is done","cn":"颠覆性的；创新而引起巨变的","ex":{"en":"Printing in 3D is a disruptive technology which may transform manufacturing.","cn":"3D 打印是一项颠覆性技术，可能会改变制造业。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"破坏性的;制造混乱的","en":"To be disruptive means to prevent something from continuing or operating in a normal way.","ex":{"en":"Alcohol can produce violent, disruptive behavior","cn":"酒精会引发暴力和破坏性行为。"}}]},"media":{"uk":"media/uk/disruptive__gb_1.mp3","us":"media/us/disruptive__us_1.mp3"},"examples":[{"en":"She had a disruptive influence on the rest of the class.","cn":"她搅扰了班上其他的学生。"},{"en":"Night work can be very disruptive to home life.","cn":"夜间工作会给家庭生活带来很大的麻烦。"}]},"diving":{"media":{"uk":"media/uk/diving__gb_1.mp3","us":"media/us/diving__us_1.mp3"},"oxford":{"phon":"ˈdaɪvɪŋ","pos":"noun","senses":[{"en":"the sport or activity of diving into water with your head and arms first","cn":"跳水；跳水运动","ex":{"en":"a diving competition","cn":"跳水比赛"}},{"en":"the activity of swimming underwater using special breathing equipment","cn":"（戴呼吸装备的）潜水","ex":{"en":"I'd love to go diving in the Aegean.","cn":"我很想到爱琴海去潜水。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"潜水","en":"Diving is the activity of working or looking around underwater, using special breathing equipment.","ex":{"en":"...equipment and accessories for diving.","cn":"潜水用的装备及配件"}},{"pos":"N-UNCOUNT 不可数名词","cn":"跳水;跳水运动","en":"Diving is the sport or activity in which you jump into water head first with your arms held straight above your head, usually from a diving board.","ex":{"en":"Weight is crucial in diving because the aim is to cause the smallest splash possible.","cn":"体重在跳水运动中至关重要，因为跳水就是要做到尽可能压住水花。"}}]},"examples":[{"en":"I'd love to go diving in the Aegean.","cn":"我很想到爱琴海去潜水。"},{"en":"a diving competition","cn":"跳水比赛"}],"base":"dive"},"dial":{"media":{"uk":"media/uk/dial__gb_1.mp3","us":"media/us/dial__us_1.mp3"},"oxford":{"phon":"ˈdaɪəl","pos":"noun","senses":[{"en":"the face of a clock or watch, or a similar control on a machine, piece of equipment or vehicle that shows a measurement of time, amount, speed, temperature, etc.","cn":"表盘；刻度盘；标度盘；仪表盘","ex":{"en":"an alarm clock with a luminous dial","cn":"夜光闹钟"}},{"en":"the round control on a radio, cooker, etc. that you turn in order to change something, for example to choose a particular station or to choose a particular temperature","cn":"（收音机、炉、灶等的）调节盘，控制盘"},{"en":"the round part on some older phones, with holes for the fingers, that you move around to call a particular number","cn":"（旧式电话机的）拨号盘"},{"en":"to use a phone by pushing buttons or turning the dial to call a number","cn":"拨号","lab":"British English","ex":{"en":"He dialled the number and waited.","cn":"他拨号后便等着通话。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"钟面;表盘;（仪表等的）刻度盘，标度盘","en":"A dial is the part of a machine or instrument such as a clock or watch which shows you the time or a measurement that has been recorded.","ex":{"en":"The luminous dial on the clock showed five minutes to seven","cn":"夜光钟面显示时间为 6点 55 分。"}},{"pos":"N-COUNT 可数名词","cn":"（装置或设备的）调节器，控制器","en":"A dial is a control on a device or piece of equipment which you can move in order to adjust the setting, for example to select or change the frequency on a radio or the temperature of a heater.","ex":{"en":"He turned the dial on the radio","cn":"他转动收音机的电台旋钮。"}},{"pos":"N-COUNT 可数名词","cn":"(尤指老式电话机的)拨号盘","en":"On some telephones, especially older ones, the dial is the disc on the front that you turn with your finger to choose the number that you want to call. The disc has holes in it, and numbers or letters behind the holes.","ex":{"en":"...turning the dial on the phone.","cn":"打转盘拨号电话"}},{"pos":"VERB 动词","cn":"拨(电话号码)","en":"If you dial or if you dial a number, you turn the dial or press the buttons on a telephone in order to phone someone.","ex":{"en":"He lifted the phone and dialled her number","cn":"他拿起电话，拨打了她的号码。"}}]},"examples":[{"en":"Check the tyre pressure on the dial.","cn":"检查一下仪表盘显示的车胎压力。"},{"en":"Dial 0033 for France.","cn":"打电话到法国拨 0033。"}]},"discourse":{"media":{"uk":"media/uk/discourse__gb_1.mp3","us":"media/us/discourse__us_1.mp3"},"oxford":{"phon":"ˈdɪskɔːs","pos":"noun","senses":[{"en":"a long and serious treatment or discussion of a subject in speech or writing","cn":"论文；演讲","g":"[countable, uncountable]","lab":"formal","ex":{"en":"a discourse on issues of gender and sexuality","cn":"关于性别和性行为的论文"}},{"en":"the use of language in speech and writing in order to produce meaning; language that is studied, usually in order to see how the different parts of a text are connected","cn":"语篇；话语","g":"[uncountable]","lab":"linguistics","ex":{"en":"spoken/written discourse","cn":"口头／书面语篇"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(尤指对某严肃话题口头或书面的)演讲，论述，著述","en":"Discourse is spoken or written communication between people, especially serious discussion of a particular subject.","ex":{"en":"...a tradition of political discourse.","cn":"政治演讲的传统"}},{"pos":"N-UNCOUNT 不可数名词","cn":"话语;语篇","en":"In linguistics, discourse is natural spoken or written language in context, especially when complete texts are being considered.","ex":{"en":"The Centre has a strong record of research in discourse analysis.","cn":"该中心在语篇分析研究方面成果丰硕。"}},{"pos":"N-COUNT 可数名词","cn":"演讲;论述","en":"A discourse is a serious talk or piece of writing which is intended to teach or explain something.","ex":{"en":"Gates responds with a lengthy discourse on deployment strategy.","cn":"盖茨以一篇有关部署策略的鸿篇大论予以回应。"}},{"pos":"VERB 动词","cn":"高谈阔论;论述","en":"If someone discourses on something, they talk for a long time about it in a confident way.","ex":{"en":"He discoursed for several hours on French and English prose.","cn":"他花了几个小时讲述法国和英国的散文。"}}]},"examples":[{"en":"He was hoping for some lively political discourse at the meeting.","cn":"他希望在会上听到些生动的政治演讲。"},{"en":"a discourse on issues of gender and sexuality","cn":"关于性别和性行为的论文"}]},"distressed":{"oxford":{"phon":"dɪˈstrest","pos":"adjective","senses":[{"en":"very upset and anxious","cn":"烦恼的；忧虑的；苦恼的","ex":{"en":"He was too distressed and confused to answer their questions.","cn":"他非常苦恼而困惑，无法回答他们的问题。"}},{"en":"suffering pain; in a poor physical condition","cn":"痛苦的；身体虚弱的","ex":{"en":"When the baby was born, it was blue and distressed.","cn":"这婴儿出生时全身发青，非常虚弱。"}},{"en":"made to look older and more worn than it really is","cn":"刻意磨损以显老旧的；做旧的","ex":{"en":"a distressed leather jacket","cn":"做旧的皮夹克"}},{"en":"having problems caused by lack of money","cn":"贫困的；窘迫的；受经济困扰的","lab":"formal or business","ex":{"en":"They buy up financially distressed companies.","cn":"他们收购陷入财务危机的公司。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"烦恼的;忧虑的;苦恼的","en":"If someone is distressed, they are upset or worried.","ex":{"en":"I feel very alone and distressed about my problem.","cn":"对自己的问题我觉得很无助、很苦恼。"}},{"pos":"ADJ 形容词","cn":"仿旧的;做旧的","en":"A distressed object such as a piece of furniture or an item of clothing has been deliberately made to look old.","ex":{"en":"...distressed jeans.","cn":"仿旧牛仔裤"}}]},"media":{"uk":"media/uk/distressed__gb_1.mp3","us":"media/us/distressed__us_1.mp3"},"examples":[{"en":"He was too distressed and confused to answer their questions.","cn":"他非常苦恼而困惑，无法回答他们的问题。"},{"en":"When the baby was born, it was blue and distressed.","cn":"这婴儿出生时全身发青，非常虚弱。"}],"base":"distress"},"differ":{"media":{"uk":"media/uk/differ__gb_1.mp3","us":"media/us/differ__us_1.mp3"},"oxford":{"phon":"ˈdɪfə(r)","pos":"verb","senses":[{"en":"to be different from somebody/something","cn":"相异；有区别；不同于","g":"[intransitive]","ex":{"en":"They hold differing views.","cn":"他们持有不同的观点。"}},{"en":"to disagree with somebody","cn":"意见相左；持不同看法；不同意","g":"[intransitive]","ex":{"en":"I have to differ with you on that.","cn":"在那一点上我不能同意你的看法。"}}]},"collins":{"senses":[{"pos":"V-RECIP 相互动词","cn":"相异;有区别;不同","en":"If two or more things differ, they are unlike each other in some way.","ex":{"en":"The story he told police differed from the one he told his mother","cn":"他在警方和母亲那里说辞不一。"}},{"pos":"V-RECIP 相互动词","cn":"有分歧;持不同看法","en":"If people differ about something, they do not agree with each other about it.","ex":{"en":"The two leaders had differed on the issue of sanctions","cn":"两位领导人在制裁问题上存在意见分歧。"}},{"pos":"","cn":"","en":"to agree to differ→see: ; ‘I beg to differ’→see: ;"}]},"examples":[{"en":"Medical opinion differs as to how to treat the disease.","cn":"关于如何治疗这种疾病医学界有不同的看法。"},{"en":"Ideas on childcare may differ considerably between the parents.","cn":"在抚育儿童方面父母的观点可能迥然不同。"}]},"disobedience":{"media":{"uk":"media/uk/disobedience__gb_1.mp3","us":"media/us/disobedience__us_1.mp3"},"oxford":{"phon":"ˌdɪsəˈbiːdiəns","pos":"noun","senses":[{"en":"the act of failing or refusing to obey","cn":"不服从；不顺从；违抗","ex":{"en":"His behaviour was seen as another act of disobedience.","cn":"他的这一行为被视作又一次反叛。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"不服从;不顺从;抗命","en":"Disobedience is deliberately not doing what someone tells you to do, or what a rule or law says that you should do."}]}},"divergent":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有分歧的;不同的;相异的","en":"Divergent things are different from each other.","ex":{"en":"...two people who have divergent views on this question","cn":"在这个问题上意见相左的两个人"}}]},"media":{"uk":"media/uk/divergent__gb_1.mp3","us":"media/us/divergent__us_1.mp3"},"examples":[{"en":"divergent paths/opinions","cn":"岔路；歧见"},{"en":"The two species diverged millions of years ago.","cn":""}],"oxford":{"phon":"daɪˈvɜːdʒənt","pos":"adjective","senses":[{"en":"developing or moving in different directions; becoming less similar","cn":"分歧：发展或朝着不同的方向发展；越来越不相似","ex":{"en":"The two scientists have followed divergent paths since the 1990s.","cn":"自 20 世纪 90 年代以来，这两位科学家一直走着不同的道路。"}},{"en":"different; no longer similar","cn":"分歧；相异","ex":{"en":"There are divergent opinions on this issue.","cn":"对于这个问题，存在着不同的看法。"}}]}},"diagrams":{"lemma":"diagram"},"direct":{"media":{"uk":"media/uk/direct__gb_1.mp3","us":"media/us/direct__us_1.mp3"},"oxford":{"phon":"dəˈrekt","pos":"adjective","senses":[{"en":"going in the straightest line between two places without stopping or changing direction","cn":"笔直的；径直的；最近的","sc":"journey/route","ex":{"en":"the most direct route","cn":"最直接的路线"}},{"en":"happening or done without involving other people, actions, etc. in between","cn":"直接的；亲自的；亲身的","g":"[usually before noun]","sc":"nobody/nothing in between","ex":{"en":"She has been in direct contact with the prime minister.","cn":"她一直与首相有直接联系。"}},{"en":"with nothing between something and the source of the heat or light","cn":"直射的","g":"[only before noun]","sc":"heat/light","ex":{"en":"The plant should not be placed in direct sunlight.","cn":"这种植物不应置于阳光直射之下。"}},{"en":"saying exactly what you mean in a way that nobody can pretend not to understand","cn":"直爽的；直率的；坦率的","sc":"saying what you mean","ex":{"en":"I asked him a direct question: ‘Did you do it?’","cn":"我直接问了他一个问题：“你做到了吗？”"}},{"en":"clearly showing something","cn":"直接的；确切的","g":"[only before noun]","sc":"evidence","ex":{"en":"There is no direct evidence for the beneficial effects of these herbs.","cn":"没有直接证据表明这些草药有益处。"}},{"en":"exact","cn":"恰好","g":"[only before noun]","sc":"exact","ex":{"en":"That's the direct opposite of what you told me yesterday.","cn":"那与你昨天告诉我的截然相反。"}},{"en":"related through parents and children rather than brothers, sisters, aunts, etc.","cn":"直系的；嫡系的","g":"[only before noun]","sc":"relationship","ex":{"en":"a direct descendant of the country’s first president","cn":"该国第一任总统的嫡系后裔"}},{"en":"to control or be in charge of somebody/something","cn":"管理；监督；指导","g":"[transitive]","sc":"control","ex":{"en":"He was asked to take command and direct operations.","cn":"他奉命统率并指挥作战行动。"},"pos":"verb"},{"en":"to be in charge of actors in a play or film, or musicians in a band, orchestra, etc.","cn":"导演（戏剧或电影）；指挥（管弦乐队）","g":"[intransitive, transitive]","lab":"British English","sc":"film/play/music","ex":{"en":"She prefers to act rather than direct.","cn":"她宁愿当演员，不愿当导演。"},"pos":"verb"},{"en":"to aim something at a particular goal or person, or in a particular direction","cn":"把…对准（某目标、某人或某方向）","g":"[transitive]","sc":"aim","ex":{"en":"He directed his attention to the next task.","cn":"他把注意力集中在下一项任务上。"},"pos":"verb"},{"en":"to tell or show somebody how to get to somewhere or where to go","cn":"给（某人）指路；为（某人）领路","g":"[transitive]","sc":"show the way","ex":{"en":"It's not far—I'll direct you.","cn":"路不远，我指给你。"},"pos":"verb"},{"en":"to give an official order","cn":"指示；命令","g":"[transitive]","lab":"formal","sc":"give order","ex":{"en":"The police officers had been directed to search the building.","cn":"警察奉命搜查这栋大楼。"},"pos":"verb"},{"en":"to send a letter, etc. to a particular place or to a particular person","cn":"把（信件等）寄至；交予","g":"[transitive]","lab":"formal","sc":"letter/comment","ex":{"en":"Direct any complaints to the Customer Services department.","cn":"将投诉寄至用户服务部。"},"pos":"verb"},{"en":"without stopping or changing direction or vehicle","cn":"直接；径直","sc":"journey/route","ex":{"en":"We flew direct to Hong Kong.","cn":"我们直飞香港。"},"pos":"adverb"},{"en":"without involving other people, or without anyone or anything in between","cn":"亲自；直接","sc":"nobody in between","ex":{"en":"I prefer to deal with him direct.","cn":"我更愿意直接跟他打交道。"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"径直的;笔直的;直达的","en":"Direct means moving towards a place or object, without changing direction and without stopping, for example in a journey.","ex":{"en":"They'd come on a direct flight from Athens.","cn":"他们是搭乘从雅典直飞这里的航班过来的。"}},{"pos":"ADJ 形容词","cn":"(光或热)直接照射的，直接接触的","en":"If something is in direct heat or light, it is strongly affected by the heat or light, because there is nothing between it and the source of heat or light to protect it.","ex":{"en":"Medicines should be stored away from direct sunlight","cn":"药品的储放应避免阳光直射。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(经验、活动或系统)直接的，亲身的","en":"You use direct to describe an experience, activity, or system which only involves the people, actions, or things that are necessary to make it happen.","ex":{"en":"He has direct experience of the process of privatisation","cn":"他对私有化过程有着切身体会。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(联系等)直接的","en":"You use direct to emphasize the closeness of a connection between two things.","ex":{"en":"They were unable to prove that she died as a direct result of his injection","cn":"他们无法证明她的死是由于他的注射直接引起的。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"坦率的;率直的;直截了当的","en":"If you describe a person or their behaviour as direct, you mean that they are honest and open, and say exactly what they mean.","ex":{"en":"He avoided giving a direct answer","cn":"他避免作出正面回答。"}},{"pos":"VERB 动词","cn":"把…指向;把…对准","en":"If you direct something at a particular thing, you aim or point it at that thing.","ex":{"en":"I directed the extinguisher at the fire without effect","cn":"我把灭火器对准了火焰，但没起作用。"}},{"pos":"VERB 动词","cn":"使(注意力、情感、行为等)转向;使…指向;把…引向","en":"If your attention, emotions, or actions are directed at a particular person or thing, you are focusing them on that person or thing.","ex":{"en":"The learner's attention needs to be directed to the significant features","cn":"需要将学习者的注意力引向那些着重点上。"}},{"pos":"VERB 动词","cn":"使(话语或眼神)针对，指向，冲…而来","en":"If a remark or look is directed at you, someone says something to you or looks at you.","ex":{"en":"She could hardly believe the question was directed towards her","cn":"她很难相信这个问题是冲她来的。"}},{"pos":"VERB 动词","cn":"指引;为…指路","en":"If you direct someone somewhere, you tell them how to get there.","ex":{"en":"Could you direct them to Dr Lamont's office, please?","cn":"你能告诉他们去拉蒙特医生的办公室怎么走吗？"}},{"pos":"VERB 动词","cn":"领导;指导;组织;管理","en":"When someone directs a project or a group of people, they are responsible for organizing the people and activities that are involved.","ex":{"en":"Christopher will direct day-to-day operations.","cn":"克里斯托弗将管理日常的运营。"}},{"pos":"VERB 动词","cn":"导演，执导(电影、戏剧或电视节目)","en":"When someone directs a film, play, or television programme, they are responsible for the way in which it is performed and for telling the actors and assistants what to do.","ex":{"en":"He directed various TV shows","cn":"他执导过多种题材的电视节目。"}},{"pos":"VERB 动词","cn":"指示;命令","en":"If you are directed to do something, someone in authority tells you to do it.","ex":{"en":"They have been directed to give special attention to the problem of poverty","cn":"他们得到指示要特别关注贫困问题。"}},{"pos":"ADJ 形容词","cn":"直系的;嫡系的","en":"If you are a direct descendant of someone, you are related to them through your parents and your grandparents and so on.","ex":{"en":"She is a direct descendant of Queen Victoria.","cn":"她是维多利亚女王的嫡系后代。"}}]},"examples":[{"en":"The movie was directed by Steven Spielberg.","cn":"这部电影是由史蒂文 · 斯皮尔伯格导演的。"},{"en":"We are looking for somebody with direct experience of this type of work.","cn":"我们在寻找对这种工作有过亲身体验的人。"}]},"divides":{"lemma":"divide"},"distinguish":{"oxford":{"phon":"dɪˈstɪŋɡwɪʃ","pos":"verb","senses":[{"en":"to recognize the difference between two people or things","cn":"区分；辨别；分清","g":"[intransitive, transitive]","ex":{"en":"At what age are children able to distinguish between right and wrong?","cn":"儿童到什么年龄才能明辨是非？"}},{"en":"to be a characteristic that makes two people, animals or things different","cn":"成为…的特征；使具有…的特色；使有别于","g":"[transitive]","ex":{"en":"What was it that distinguished her from her classmates?","cn":"是什么使得她有别于班上其他同学呢？"}},{"en":"to be able to see or hear something","cn":"看清；认出；听出","g":"[transitive]","ex":{"en":"I could not distinguish her words, but she sounded agitated.","cn":"我听不清她说的话，但听得出她很激动。"}},{"en":"to do something so well that people notice and admire you","cn":"使出众；使著名；使受人青睐","g":"[transitive]","ex":{"en":"She has already distinguished herself as an athlete.","cn":"作为运动员她已享有盛名。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"区分;辨别;分清","en":"If you can distinguish one thing from another or distinguish between two things, you can see or understand how they are different.","ex":{"en":"Could he distinguish right from wrong?","cn":"他能分辨是非吗？"}},{"pos":"VERB 动词","cn":"(特质或特征)使有别于","en":"A feature or quality that distinguishes one thing from another causes the two things to be regarded as different, because only the first thing has the feature or quality.","ex":{"en":"There is something about music that distinguishes it from all other art forms","cn":"音乐的某种特质使其有别于所有其他艺术形式。"}},{"pos":"VERB 动词","cn":"看出;听出;辨别出","en":"If you can distinguish something, you can see, hear, or taste it although it is very difficult to detect.","ex":{"en":"There were cries, calls. He could distinguish voices.","cn":"有哭声、喊声——他能听出不同的声音。"}},{"pos":"VERB 动词","cn":"使出名;使受青睐","en":"If you distinguish yourself, you do something that makes you famous or important.","ex":{"en":"Over the next few years he distinguished himself as a leading constitutional scholar","cn":"在接下来的几年里，他作为一名宪法研究领域最杰出的学者而声名远扬。"}}]},"media":{"uk":"media/uk/distinguish__gb_1.mp3","us":"media/us/distinguish__us_1.mp3"},"examples":[{"en":"I could not distinguish her words, but she sounded agitated.","cn":"我听不清她说的话，但听得出她很激动。"},{"en":"What was it that distinguished her from her classmates?","cn":"是什么使得她有别于班上其他同学呢？"}]},"dioxide":{"oxford":{"phon":"daɪˈɒksaɪd","pos":"noun","senses":[{"en":"a substance formed by combining two atoms of oxygen and one atom of another chemical element","cn":"二氧化物"}]},"media":{"uk":"media/uk/dioxide__gb_1.mp3","us":"media/us/dioxide__us_1.mp3"},"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"}]}},"disguise":{"media":{"uk":"media/uk/disguise__gb_1.mp3","us":"media/us/disguise__us_1.mp3"},"oxford":{"phon":"dɪsˈɡaɪz","pos":"verb","senses":[{"en":"to change your appearance so that people cannot recognize you","cn":"假扮；装扮；伪装","ex":{"en":"The hijackers were heavily disguised.","cn":"劫持者伪装得严严实实。"}},{"en":"to hide something or change it, so that it cannot be recognized","cn":"掩蔽；掩饰","ex":{"en":"She made no attempt to disguise her surprise.","cn":"她根本不曾掩饰自己惊奇的心情。"}},{"en":"something that you wear or use to change your appearance so that people do not recognize you","cn":"伪装物；化装用具","g":"[countable, uncountable]","ex":{"en":"She wore glasses and a wig as a disguise.","cn":"她用眼镜和假发伪装起来。"},"pos":"noun"},{"en":"the art of changing your appearance so that people do not recognize you","cn":"假扮；装扮；伪装","g":"[uncountable]","ex":{"en":"He is a master of disguise.","cn":"他是伪装能手。"},"pos":"noun"},{"en":"a way of hiding the true nature of something","cn":"隐瞒；掩饰","g":"[countable, uncountable]","ex":{"en":"His angelic look is just a disguise.","cn":"他天使般的外表只是一种伪装。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"假装;装扮;伪装","en":"If you are in disguise, you are not wearing your usual clothes or you have altered your appearance in other ways, so that people will not recognize you.","ex":{"en":"You'll have to travel in disguise","cn":"你只能乔装出行。"}},{"pos":"VERB 动词","cn":"假扮;化妆;乔装","en":"If you disguise yourself, you put on clothes which make you look like someone else or alter your appearance in other ways, so that people will not recognize you.","ex":{"en":"She disguised herself as a man so she could fight on the battlefield.","cn":"她女扮男装，这样就可以上战场了。"}},{"pos":"VERB 动词","cn":"掩盖;掩饰","en":"To disguise something means to hide it or make it appear different so that people will not know about it or will not recognize it.","ex":{"en":"He made no attempt to disguise his agitation","cn":"他毫不掩饰自己的焦虑不安。"}},{"pos":"","cn":"","en":"a blessing in disguise→see: ;"}]},"examples":[{"en":"( figurative ) A vote for the Liberal Democrats is just a Labour vote in disguise.","cn":"投自由民主党的票不过是改头换面投工党的票。"},{"en":"It was a thinly disguised attack on the President.","cn":"明眼人一下就能看出这是在攻击总统。"}]},"dip":{"oxford":{"phon":"dɪp","pos":"verb","senses":[{"en":"to put something quickly into a liquid and take it out again","cn":"蘸；浸","g":"[transitive]","ex":{"en":"He dipped the brush into the paint.","cn":"他拿画笔蘸了蘸颜料。"}},{"en":"to go downwards or to a lower level; to make something do this","cn":"（使）下降，下沉","g":"[intransitive, transitive]","ex":{"en":"The sun dipped below the horizon.","cn":"太阳落到地平线下了。"}},{"en":"if you dip your headlights when driving a car at night, you make the light from them point down so that other drivers do not have the light in their eyes","cn":"把（汽车前灯的）远光调为近光","g":"[transitive]","lab":"British English"},{"en":"when farmers dip animals, especially sheep, they put them in a bath of a liquid containing chemicals in order to kill insects, etc.","cn":"给（牲畜，尤指绵羊）洗药浴","g":"[transitive]"},{"en":"a quick swim","cn":"游一游；泡一泡","g":"[countable, usually singular]","lab":"informal","ex":{"en":"Let's go for a dip before breakfast.","cn":"我们早饭前去游一会儿泳吧。"},"pos":"noun"},{"en":"a decrease in the amount or success of something, usually for only a short period","cn":"（通常指暂时的）减少，下降，衰退","g":"[countable]","ex":{"en":"Share prices have taken a slight dip.","cn":"股价略有下跌。"},"pos":"noun"},{"en":"a place where a surface suddenly drops to a lower level and then rises again","cn":"凹陷处；低洼处","g":"[countable]","ex":{"en":"a dip in the road","cn":"路上的凹陷处"},"pos":"noun"},{"en":"a thick mixture into which pieces of food are dipped before being eaten","cn":"调味酱（用食物来蘸着吃）","g":"[countable, uncountable]","pos":"noun"},{"en":"a liquid containing a chemical into which sheep and other animals can be dipped in order to kill insects on them","cn":"药浴液，清洗液（用于绵羊或其他牲畜洗浴以杀死身上的虫子）","g":"[uncountable, countable]","pos":"noun"},{"en":"a quick look at something","cn":"浏览；草草翻阅","g":"[singular]","ex":{"en":"A brief dip into history serves to confirm this view.","cn":"随便翻阅一下历史就足以证实这种观点。"},"pos":"noun"},{"en":"a quick movement of something down and up","cn":"（降而复升的）一动","g":"[countable, usually singular]","ex":{"en":"He gave a dip of his head.","cn":"他点了点头。"},"pos":"noun"},{"en":"a system in which documents are treated as images (the abbreviation for ‘document image processing’)","cn":"文件图像处理（全写为 document image processing）","pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"浸;蘸","en":"If you dip something in a liquid, you put it into the liquid for a short time, so that only part of it is covered, and take it out again.","ex":{"en":"They dip the food into the sauce","cn":"他们把食物放到调味汁里蘸了蘸。"}},{"pos":"VERB 动词","cn":"把(手)伸入","en":"If you dip your hand into a container or dip into the container, you put your hand into it in order to take something out of it.","ex":{"en":"She dipped a hand into the jar of sweets and pulled one out","cn":"她把手伸进糖果罐，摸出了一颗糖。"}},{"pos":"VERB 动词","cn":"(通常指迅速地)下降，下落，下沉","en":"If something dips, it makes a downward movement, usually quite quickly.","ex":{"en":"Blake jumped in expertly; the boat dipped slightly under his weight","cn":"布莱克很熟练地跳上了船，他的重量使小船微微向下沉了沉。"}},{"pos":"VERB 动词","cn":"陡然下降;凹下去;突然下倾","en":"If an area of land, a road, or a path dips, it goes down quite suddenly to a lower level.","ex":{"en":"The road dipped and rose again.","cn":"道路陡然沉下去又升上来。"}},{"pos":"VERB 动词","cn":"给(羊等家畜)洗药浴","en":"When farmers dip sheep or other farm animals, they put them into a container of liquid with chemicals in it, in order to kill harmful insects which live on the animals' bodies.","ex":{"en":"Their father was helping to dip the sheep.","cn":"他们的父亲在帮忙给羊群洗药浴。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"药浴液;浸液","en":"Dip is a liquid with chemicals in it which animals or objects can be dipped in to disinfect or clean them.","ex":{"en":"...sheep dip.","cn":"羊群用的药浴液"}},{"pos":"VERB 动词","cn":"(数量或水平，通常短暂地)下降，下跌，减少","en":"If the amount or level of something dips, it becomes smaller or lower, usually only for a short period of time.","ex":{"en":"Unemployment dipped to 6.9 per cent last month","cn":"上个月失业率降到了 6.9%。"}},{"pos":"N-VAR 可变名词","cn":"蘸酱;(蘸蔬菜或饼干吃的)调味酱，果酱","en":"A dip is a thick creamy sauce. You dip pieces of raw vegetable or biscuits into the sauce and then eat them.","ex":{"en":"Maybe we could just buy some dips.","cn":"或许我们可以只买一点儿蘸酱。"}},{"pos":"N-COUNT 可数名词","cn":"(短时的)游泳，泡水","en":"If you have or take a dip, you go for a quick swim in the sea, a river, or a swimming pool.","ex":{"en":"She flicked through a romantic paperback between occasional dips in the pool.","cn":"用在泳池里游一阵后歇一阵的几个空当，她翻完了一本平装本言情小说。"}},{"pos":"VERB 动词","cn":"将(汽车前灯)调为近光","en":"If you are driving a car and dip the headlights, you operate a switch that makes them shine downwards, so that they do not shine directly into the eyes of other drivers.","ex":{"en":"He dipped his headlights as they came up behind a slow-moving van","cn":"当他们靠近一辆缓慢行驶的货车时，他把汽车前灯调成了近光。"}},{"pos":"VERB 动词","cn":"浏览;翻看","en":"If you dip into a book, you have a brief look at it without reading or studying it seriously.","ex":{"en":"...a chance to dip into a wide selection of books on Buddhism.","cn":"博览佛教群书的机会"}},{"pos":"VERB 动词","cn":"动用(款项等)","en":"If you dip into a sum of money that you had intended to save, you use some of it to buy something or pay for something.","ex":{"en":"Just when she was ready to dip into her savings, Greg hastened to her rescue.","cn":"正当她准备动用自己的存款时，格雷格赶来给她救了急。"}},{"pos":"See also:","cn":"","en":"to dip your toes→see: ;"}]},"media":{"uk":"media/uk/dip__gb_2.mp3","us":"media/us/dip__us_2.mp3"},"examples":[{"en":"Sales for this quarter have dipped from 38.7 million to 33 million.","cn":"本季度销售额从 3 870 万下降到 3 300 万。"},{"en":"We took out a loan for the car because we didn't want to dip into our savings.","cn":"因为不想动用存款，我们申请了一笔贷款买汽车。"}]},"dive":{"media":{"uk":"media/uk/dive__gb_1.mp3","us":"media/us/dive__us_1.mp3"},"oxford":{"phon":"daɪv","pos":"verb","senses":[{"en":"to jump into water with your head and arms going in first","cn":"跳水（头和双臂先入水）","g":"[intransitive]","sc":"jump into water","ex":{"en":"We dived into the river to cool off.","cn":"我们一头跳进河里，凉快一下。"}},{"en":"to swim underwater wearing breathing equipment, collecting or looking at things","cn":"（戴呼吸装备）潜水","g":"[intransitive]","sc":"underwater","ex":{"en":"to dive for pearls","cn":"潜水采珠"}},{"en":"to go to a deeper level underwater","cn":"下潜；潜到更深的水下","g":"[intransitive]","sc":"underwater","ex":{"en":"The submarine dived to avoid being seen.","cn":"潜艇潜入水中以避免被发现。"}},{"en":"to go steeply down through the air","cn":"俯冲","g":"[intransitive]","sc":"of birds/aircraft","ex":{"en":"The seagulls soared then dived.","cn":"海鸥翱翔着，然后俯冲下来。"}},{"en":"to move or jump quickly in a particular direction, especially to avoid something, to try to catch a ball, etc.","cn":"扑，冲，奔（以避开某物、接球等）","g":"[intransitive]","lab":"informal","sc":"move/jump/fall","ex":{"en":"We heard an explosion and dived for cover (= got into a place where we would be protected).","cn":"我们听到一声爆炸便伏身找掩护。"}},{"en":"to fall deliberately when somebody tackles you","cn":"（对方阻截时）假摔","g":"[intransitive]","sc":"move/jump/fall"},{"en":"to fall suddenly","cn":"骤降；急剧下跌；暴跌","g":"[intransitive]","sc":"of prices","ex":{"en":"The share price dived from 75p to an all-time low of 50p.","cn":"股价从 75 便士暴跌到 50 便士的历史新低。"}},{"en":"a jump into deep water with your head first and your arms in front of you","cn":"（头和双臂先入水的）跳水","sc":"jump into water","ex":{"en":"a spectacular high dive (= from high above the water)","cn":"精彩的高台跳水"},"pos":"noun"},{"en":"an act of going underwater and swimming there with special equipment","cn":"（戴呼吸装备的）潜水","sc":"underwater","ex":{"en":"a dive to a depth of 18 metres","cn":"潜到 18 米水深处"},"pos":"noun"},{"en":"an act of suddenly flying downwards","cn":"扑；冲；俯冲","sc":"of birds/aircraft","ex":{"en":"The pilot seemed to be having difficulty in pulling out of the dive.","cn":"飞行员似乎难以使飞机停止俯冲。"},"pos":"noun"},{"en":"a bar, music club, etc. that is cheap, and perhaps dark or dirty","cn":"下等酒吧；低级夜总会","lab":"informal","sc":"bar/club","ex":{"en":"The band played in every smoky dive in town.","cn":"乐队在镇上每一次烟雾缭绕的潜水中演奏。"},"pos":"noun"},{"en":"a deliberate fall that a player makes when somebody tackles them","cn":"（遇到阻截时的）假摔，故意跌倒","sc":"fall","ex":{"en":"Kane's dive won England a penalty.","cn":"凯恩的假摔为英格兰赢得了一个点球。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"跳水","en":"If you dive into some water, you jump in head-first with your arms held straight above your head.","ex":{"en":"He tried to escape by diving into a river","cn":"他企图跳入河中逃跑。"}},{"pos":"VERB 动词","cn":"潜水","en":"If you dive, you go under the surface of the sea or a lake, using special breathing equipment.","ex":{"en":"Bezanik is diving to collect marine organisms.","cn":"贝扎尼奇正在潜水采集海洋生物。"}},{"pos":"VERB 动词","cn":"(鸟或动物)俯冲，急速下扑(或下潜)","en":"When birds and animals dive, they go quickly downwards, head-first, through the air or through water.","ex":{"en":"...a pelican which had just dived for a fish","cn":"刚刚潜入水中捕鱼的鹈鹕"}},{"pos":"VERB 动词","cn":"(飞机)俯冲","en":"If an aeroplane dives, it flies or drops down quickly and suddenly.","ex":{"en":"He was killed when his monoplane stalled and dived into the ground.","cn":"他因驾驶的单翼飞机失速坠地而丧生。"}},{"pos":"VERB 动词","cn":"冲向;跃向;扑向","en":"If you dive in a particular direction or into a particular place, you jump or move there quickly.","ex":{"en":"They dived into a taxi","cn":"他们迅速钻进一辆出租车。"}},{"pos":"VERB 动词","cn":"迅速将手伸入(包或容器中)","en":"If you dive into a bag or container, you put your hands into it quickly in order to get something out.","ex":{"en":"She dived into her bag and brought out a folded piece of paper.","cn":"她立即将手伸入包中拿出一张折好的纸。"}},{"pos":"VERB 动词","cn":"(股价、利润或数字)暴跌，骤降","en":"If shares, profits, or figures dive, their value falls suddenly and by a large amount.","ex":{"en":"If we cut interest rates, the pound would dive","cn":"如果我们降低利率，英镑就会大幅贬值。"}},{"pos":"N-COUNT 可数名词","cn":"下等酒吧;低级夜总会","en":"If you describe a bar or club as a dive, you mean it is dirty and dark, and not very respectable.","ex":{"en":"We've played in all the little pubs and dives around Liverpool.","cn":"我们在利物浦所有的小酒吧和低级夜总会演出过。"}}]},"examples":[{"en":"The share price dived from 49p to an all-time low of 40p.","cn":"股价从 49 便士暴跌到 40 便士的历史最低位。"},{"en":"It started to rain so we dived into the nearest cafe.","cn":"天下起雨来，我们立即钻进一家最近的咖啡馆。"}]},"diabetes":{"media":{"uk":"media/uk/diabetes__gb_1.mp3","us":"media/us/diabetes__us_1.mp3"},"oxford":{"phon":"ˌdaɪəˈbiːtiːz","pos":"noun","senses":[{"en":"a medical condition in which the body cannot produce enough insulin to control the amount of sugar in the blood","cn":"糖尿病"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"糖尿病","en":"Diabetes is a medical condition in which someone has too much sugar in their blood."}]},"examples":[{"en":"Diabetes is linked to obesity.","cn":"糖尿病与肥胖有关。"}]},"dish":{"media":{"uk":"media/uk/dish__gb_1.mp3","us":"media/us/dish__us_1.mp3","img":["media/ldoce/img/dish.jpg"]},"oxford":{"phon":"dɪʃ","pos":"noun","senses":[{"en":"a flat shallow container for cooking food in or serving it from","cn":"碟；盘","g":"[countable]","ex":{"en":"a baking/serving dish","cn":"烤盘；上食物的盘子"}},{"en":"the plates, bowls, cups, etc. that have been used for a meal and need to be washed","cn":"（待清洗的）餐具","g":"[plural]","ex":{"en":"I'll do the dishes (= wash them).","cn":"我来洗碗。"}},{"en":"food prepared in a particular way as part of a meal","cn":"一道菜；菜肴","g":"[countable]","ex":{"en":"a vegetarian/fish/meat/pasta dish","cn":"一盘素菜／鱼／肉／意面"}},{"en":"any object that is like a dish or bowl in shape","cn":"盘状物；碟状物","g":"[countable]","ex":{"en":"a soap dish","cn":"肥皂盘"}},{"en":"a sexually attractive person","cn":"性感的人","g":"[countable]","lab":"old-fashioned, informal，，","ex":{"en":"What a dish!","cn":"真性感！"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"盘;碟;碗","en":"A dish is a shallow container with a wide uncovered top. You eat and serve food from dishes and cook food in them.","ex":{"en":"...plastic bowls and dishes","cn":"塑料碗碟"}},{"pos":"N-COUNT 可数名词","cn":"一盘（或一碟）的量","en":"The contents of a dish can be referred to as a dish of something.","ex":{"en":"Nicholas ate a dish of spaghetti.","cn":"尼古拉斯吃了一盘意大利面条。"}},{"pos":"N-COUNT 可数名词","cn":"一盘菜;菜肴;食品","en":"Food that is prepared in a particular style or combination can be referred to as a dish .","ex":{"en":"This dish is best served cold","cn":"这菜最好凉着吃。"}},{"pos":"N-PLURAL 复数名词","cn":"(就餐时用过的)所有餐具","en":"All the objects that have been used to cook, serve, and eat a meal can be referred to as the dishes .","ex":{"en":"There were dirty dishes in the sink","cn":"水槽里放着脏碗。"}},{"pos":"N-COUNT 可数名词","cn":"盘状物;碟状物","en":"You can use dish to refer to anything that is round and hollow in shape with a wide uncovered top.","ex":{"en":"...a dish used to receive satellite broadcasts.","cn":"用来接收卫星广播的碟形卫星天线"}},{"pos":"PHRASE 短语","cn":"洗餐具","en":"If you do the dishes, you wash the dishes.","ex":{"en":"I hate doing the dishes.","cn":"我讨厌洗碗。"}},{"pos":"","cn":"","en":"to dish the dirt→see: ;"},{"pos":"","cn":"","en":"相关词组：dish out dish up"}]},"examples":[{"en":"He enjoys dishing it out, but he really can't take it (= cannot accept criticism from other people).","cn":"他喜欢指责别人，而自己却一点批评都接受不了。"},{"en":"She's always dishing out advice, even when you don't want it.","cn":"即使你不想听，她仍然没完没了地建议这建议那。"}]},"dickensian":{"media":{"uk":"media/uk/dickensian__gb_1.mp3","us":"media/us/dickensian__us_1.mp3"},"oxford":{"phon":"dɪˈkenziən","pos":"adjective","senses":[{"en":"connected with or typical of the novels of Charles Dickens, which often describe bad social conditions","cn":"狄更斯文体的；具有狄更斯小说特点的；类似狄更斯笔下描述的","ex":{"en":"a Dickensian slum","cn":"类似狄更斯笔下的贫民窟"}}]},"examples":[{"en":"a Dickensian slum","cn":"类似狄更斯笔下的贫民窟"},{"en":"a single mother living in a Dickensian block of flats","cn":"住在狄更斯小说中那种肮脏公寓楼里的单身母亲"}]},"discrimination":{"media":{"uk":"media/uk/discrimination__gb_1.mp3","us":"media/us/discrimination__us_1.mp3"},"oxford":{"phon":"dɪˌskrɪmɪˈneɪʃn","pos":"noun","senses":[{"en":"the practice of treating somebody or a particular group in society less fairly than others","cn":"区别对待；歧视；偏袒","g":"[uncountable]","lab":"British English","ex":{"en":"age/racial/gender/sex discrimination (= because of somebody’s age, race or sex)","cn":"年龄／种族／性别歧视"}},{"en":"the ability to judge what is good, true, etc.","cn":"识别力；辨别力；鉴赏力","g":"[uncountable]","lab":"approving","ex":{"en":"He showed great discrimination in his choice of friends.","cn":"他在择友方面颇具慧眼。"}},{"en":"the ability to recognize a difference between one thing and another; a difference that is recognized","cn":"区别；识别；辨别","g":"[uncountable, countable]","lab":"formal","ex":{"en":"to learn discrimination between right and wrong","cn":"学会分辨是非"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"区别对待;歧视","en":"Discrimination is the practice of treating one person or group of people less fairly or less well than other people or groups.","ex":{"en":"She is exempt from sex discrimination laws.","cn":"她免受性别歧视法的追究。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"鉴别力;辨别力","en":"Discrimination is knowing what is good or of high quality.","ex":{"en":"They cooked without skill and ate without discrimination.","cn":"他们烹调手艺不高，也不挑食。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"区别;区分;辨别","en":"Discrimination is the ability to recognize and understand the differences between two things.","ex":{"en":"...colour discrimination.","cn":"辨色能力"}}]},"examples":[{"en":"discrimination on the grounds of race, gender, or sexual orientation","cn":"按照种族、性别或性取向给予区别对待"},{"en":"He showed great discrimination in his choice of friends.","cn":"他在择友方面颇具慧眼。"}]},"discovery":{"media":{"uk":"media/uk/discovery__gb_1.mp3","us":"media/us/discovery__us_1.mp3"},"oxford":{"phon":"dɪˈskʌvəri","pos":"noun","senses":[{"en":"an act or the process of finding somebody/something, or learning about something that was not known about before","cn":"发现；发觉","g":"[countable, uncountable]","ex":{"en":"Researchers in this field have made some important new discoveries.","cn":"这个领域的研究人员有了一些重大的新发现。"}},{"en":"a thing, fact or person that is found or learned about for the first time","cn":"被发现的事物（或真相、人）","g":"[countable]","ex":{"en":"The drug is not a new discovery—it's been known about for years.","cn":"这种药并不是什么新发现，多年前便为人所知。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"发现;发觉;察觉","en":"If someone makes a discovery, they become aware of something that they did not know about before.","ex":{"en":"I felt I'd made an incredible discovery.","cn":"我觉得我有一个天大的发现。"}},{"pos":"N-VAR 可变名词","cn":"(第一个)发现","en":"If someone makes a discovery, they are the first person to find or become aware of a place, substance, or scientific fact that no one knew about before.","ex":{"en":"In that year, two momentous discoveries were made.","cn":"那一年，有两个重大发现。"}},{"pos":"N-VAR 可变名词","cn":"(对不为人知的演员、音乐人等的)发现","en":"If someone makes a discovery, they recognize that an actor, musician, or other performer who is not well-known has talent.","ex":{"en":"His job is the discovery and promotion of new artists.","cn":"他的任务就是发现并推出艺术新人。"}},{"pos":"N-VAR 可变名词","cn":"找到;（偶然的）发现","en":"When the discovery of people or objects happens, someone finds them, either by accident or as a result of looking for them.","ex":{"en":"...the discovery and destruction by soldiers of millions of marijuana plants.","cn":"士兵发现并销毁了大量大麻作物"}}]},"examples":[{"en":"The drug is not a new discovery — it's been known about for years.","cn":"这种药并不是什么新发现，多年前便为人所知。"},{"en":"The discovery of a child's body in the river has shocked the community.","cn":"在河里发现一个孩子的尸体使社区大为震惊。"}]},"dizzily":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"feeling as if everything is spinning around you and unable to balance","cn":""},{"en":"feeling unsteady and unable to balance, sometimes with the result that you want to be sick","cn":""}]},"examples":[{"en":"The heat and the champagne made him feel dizzy .","cn":"","src":"ld"},{"en":"She started to suffer from dizzy spells (= a short period when you feel dizzy ) .","cn":"","src":"ld"}],"media":{"uk":"media/uk/dizzily__gb_1.mp3","us":"media/us/dizzily__us_1.mp3"},"oxford":{"phon":"ˈdɪzɪli","pos":"adverb","senses":[{"en":"in a way that makes you feel as if everything is turning around you and that you are not able to balance","cn":"头晕目眩的；眩晕的","ex":{"en":"I looked dizzily over the edge.","cn":"我头晕地看着边缘。"}}]}},"discount":{"media":{"uk":"media/uk/discount__gb_1.mp3","us":"media/us/discount__us_1.mp3"},"oxford":{"phon":"ˈdɪskaʊnt","pos":"noun","senses":[{"en":"an amount of money that is taken off the usual cost of something","cn":"折扣","lab":"especially British English","ex":{"en":"to get/offer a discount","cn":"得到／提供折扣"}},{"en":"to take an amount of money off the usual cost of something; to sell something at a discount","cn":"打折扣；打折出售","g":"[usually passive]","ex":{"en":"Most of our stock has been discounted by up to 40 per cent.","cn":"我们的大部分存货价格低至 6 折。"},"pos":"verb"},{"en":"to think or say that something is not important or not true","cn":"认为…不重要；对…不全信；低估","lab":"formal","ex":{"en":"We cannot discount the possibility of further strikes.","cn":"我们不能低估再次发生罢工的可能性。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"减价;折扣","en":"A discount is a reduction in the usual price of something.","ex":{"en":"They are often available at a discount","cn":"它们经常进行打折销售。"}},{"pos":"VERB 动词","cn":"给…打折;打折出售","en":"If a shop or company discounts an amount or percentage from something that they are selling, they take the amount or percentage off the usual price.","ex":{"en":"This has forced airlines to discount fares heavily in order to spur demand","cn":"这迫使航空公司对机票大幅打折来刺激需求。"}},{"pos":"VERB 动词","cn":"认为(某种思想、事实、理论)不重要;不全信;认为…不相关","en":"If you discount an idea, fact, or theory, you consider that it is not true, not important, or not relevant.","ex":{"en":"However, traders tended to discount the rumor","cn":"然而，商人往往不相信这一谣传。"}}]},"examples":[{"en":"The news reports were being discounted as propaganda.","cn":"人们认为这些新闻报道不过是为了宣传，不可全信。"},{"en":"We cannot discount the possibility of further strikes.","cn":"我们不能低估再次发生罢工的可能性。"}]},"disappearance":{"media":{"uk":"media/uk/disappearance__gb_1.mp3","us":"media/us/disappearance__us_1.mp3"},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"消失;失踪","en":"If you refer to someone's disappearance, you are referring to the fact that nobody knows where they have gone.","ex":{"en":"Her disappearance has baffled police","cn":"她的失踪让警方很困惑。"}},{"pos":"N-COUNT 可数名词","cn":"丢失;被盗","en":"If you refer to the disappearance of an object, you are referring to the fact that it has been lost or stolen.","ex":{"en":"Police are investigating the disappearance from council offices of confidential files.","cn":"警察正在调查市政办公室机密档案被盗一案。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(指人、事物或动物)渐渐消失，灭绝","en":"The disappearance of a type of thing, person, or animal is a process in which it becomes less common and finally no longer exists.","ex":{"en":"...the virtual disappearance of the red telephone box.","cn":"红色公用电话亭几乎消失殆尽"}}]},"examples":[{"en":"the disappearance of many species of plants and animals from our planet","cn":"许多动植物物种从我们这颗行星上的消失"},{"en":"Police are investigating the disappearance of a young woman.","cn":"警方正在调查一位年轻女子的失踪案。"}],"oxford":{"phon":"ˌdɪsəˈpɪərəns","pos":"noun","senses":[{"en":"the fact of being lost or impossible to find","cn":"失踪；丢失","g":"[uncountable, countable]","ex":{"en":"Police are investigating the disappearance of a young woman.","cn":"警方正在调查一名年轻女子失踪的案件。"}},{"en":"the fact of no longer existing; the fact of becoming impossible to see","cn":"失踪：不再存在的事实；变得看不见","g":"[uncountable]","ex":{"en":"the disappearance of many species of plants and animals from our planet","cn":"我们这颗行星上许多动植物物种的消失"}}]}},"disapproving":{"oxford":{"phon":"ˌdɪsəˈpruːvɪŋ","pos":"adjective","senses":[{"en":"showing that you do not approve of somebody/something","cn":"不赞成的；表示反对的；不以为然的","ex":{"en":"a disapproving glance/tone/look","cn":"不以为然的一瞥／语气／样子"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不赞成的;表示反对的;不以为然的","en":"A disapproving action or expression shows that you do not approve of something or someone.","ex":{"en":"Janet gave him a disapproving look.","cn":"珍妮特不满地看了他一眼。"}}]},"media":{"uk":"media/uk/disapproving__gb_1.mp3","us":"media/us/disapproving__us_1.mp3"},"examples":[{"en":"He looked disapprovingly at the row of empty wine bottles.","cn":"他不以为然地看了看那排空酒瓶。"},{"en":"a disapproving glance/tone/look","cn":"不以为然的一瞥/语气/样子"}],"base":"disapprove"},"disruption":{"media":{"uk":"media/uk/disruption__gb_1.mp3","us":"media/us/disruption__us_1.mp3"},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"中断;扰乱;混乱","en":"When there is disruption of an event, system, or process, it is prevented from continuing or operating in a normal way.","ex":{"en":"The strike is expected to cause delays and disruption to flights from Britain","cn":"预计罢工将导致英国航班的延误和中断。"}}]},"examples":[{"en":"We aim to help you move house with minimum disruption to yourself.","cn":"我们的宗旨是帮您搬家的时候，尽量减少给您带来的不便。"},{"en":"The strike caused serious disruptions.","cn":"罢工造成了严重的混乱。"}],"oxford":{"phon":"dɪsˈrʌpʃn","pos":"noun","senses":[{"en":"a situation in which it is difficult for something to continue in the normal way; the act of stopping something from continuing in the normal way","cn":"扰乱；中断；妨碍","ex":{"en":"We aim to help you move house with minimum disruption to yourself.","cn":"我们力求助您轻松搬家，将搬家一事带给您的不便降到最低。"}},{"en":"significant change to an industry or market due to innovation (= new ideas or methods) in technology","cn":"（使用新方法或技术对传统行业或市场的）颠覆","lab":"business","ex":{"en":"The banking industry is primed for major disruption.","cn":"银行业已准备好迎接巨变。"}}]}},"digging":{"lemma":"dig"},"discourage":{"oxford":{"phon":"dɪsˈkʌrɪdʒ","pos":"verb","senses":[{"en":"to try to prevent something or to prevent somebody from doing something, especially by making it difficult to do or by showing that you do not approve of it","cn":"阻拦；阻止；劝阻","ex":{"en":"a campaign to discourage smoking among teenagers","cn":"劝阻青少年吸烟的运动"}},{"en":"to make somebody feel less confident or enthusiastic about doing something","cn":"使灰心；使泄气；使丧失信心","ex":{"en":"Don't be discouraged by the first failure—try again!","cn":"这才是第一次失败，别灰心丧气，再试一次吧！"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"使泄气;使灰心","en":"If someone or something discourages you, they cause you to lose your enthusiasm about your actions.","ex":{"en":"It may be difficult to do at first. Don't let this discourage you.","cn":"万事开头难，别因此而灰心。"}},{"pos":"VERB 动词","cn":"打消…的念头;阻止;劝阻","en":"To discourage an action or to discourage someone from doing it means to make them not want to do it.","ex":{"en":"...typhoons that discouraged shopping and leisure activities.","cn":"使购物和休闲活动化为泡影的台风"}}]},"media":{"uk":"media/uk/discourage__gb_1.mp3","us":"media/us/discourage__us_1.mp3"},"examples":[{"en":"Don't be discouraged by the first failure — try again!","cn":"这才是第一次失败，别灰心丧气，再试一次吧！"},{"en":"Learners can feel very discouraged if an exercise is too difficult.","cn":"如果练习太难，学习者就可能感到没信心。"}]},"dig":{"oxford":{"phon":"dɪɡ","pos":"verb","senses":[{"en":"to make a hole in the ground or to move soil from one place to another using your hands, a tool or a machine","cn":"掘（地）；凿（洞）；挖（土）","g":"[intransitive, transitive]","lab":"British English","ex":{"en":"I think I'll do some digging in the garden.","cn":"我想我该给花园松松土了。"}},{"en":"to remove something from the ground with a tool","cn":"掘得；（采）掘出","g":"[transitive]","ex":{"en":"I'll dig some potatoes for lunch.","cn":"我要挖点土豆做午餐。"}},{"en":"to search in something in order to find an object in something","cn":"寻找，搜寻（物品）","g":"[intransitive]","ex":{"en":"I dug around in my bag for a pen.","cn":"我在包里到处翻找笔。"}},{"en":"to approve of or like something very much","cn":"赞成；看中；喜欢","g":"[transitive]","lab":"old-fashioned, slang，，"},{"en":"a small push with your finger or elbow","cn":"（用手指或肘部）轻碰，轻戳，轻推","ex":{"en":"She gave him a dig in the ribs.","cn":"她轻轻地戳了一下他的肋部。"},"pos":"noun"},{"en":"a remark that is intended to annoy or upset somebody","cn":"挖苦；嘲讽","ex":{"en":"He kept making sly little digs at me.","cn":"他总是拐弯抹角地挖苦我。"},"pos":"noun"},{"en":"an occasion when an organized group of people dig in the ground to discover old buildings or objects, in order to find out more about their history","cn":"考古发掘","ex":{"en":"to go on a dig","cn":"进行考古发掘"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"挖;掘","en":"If people or animals dig, they make a hole in the ground or in a pile of earth, stones, or rubbish.","ex":{"en":"They tried digging in a patch just below the cave","cn":"他们试着在洞穴正下方的一块地上挖掘。"}},{"pos":"VERB 动词","cn":"伸手（至…深处）掏","en":"If you dig into something such as a deep container, you put your hand in it to search for something.","ex":{"en":"He dug into his coat pocket for his keys.","cn":"他把手伸进上衣口袋里摸钥匙。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（把…）戳（进）；（将…）刺（入）","en":"If you dig one thing into another or if one thing digs into another, the first thing is pushed hard into the second, or presses hard into it.","ex":{"en":"She digs the serving spoon into the moussaka","cn":"她把分菜匙伸进那盘碎肉茄子蛋中。"}},{"pos":"VERB 动词","cn":"研究;探究;细查","en":"If you dig into a subject or a store of information, you study it very carefully in order to discover or check facts.","ex":{"en":"The enquiry dug deeper into the alleged financial misdeeds of his government","cn":"这一调查对其政府涉嫌的财政违规行为展开了进一步深究。"}},{"pos":"VERB 动词","cn":"(尤指从自己造成的困境或令人不快的情形中)脱（身）","en":"If you dig yourself out of a difficult or unpleasant situation, especially one which you caused yourself, you manage to get out of it.","ex":{"en":"Occupants of the White House have exploited their office at key moments in an election campaign to dig themselves out of trouble","cn":"在竞选活动的关键时刻，白宫的主人利用职权帮助自己摆脱了麻烦。"}},{"pos":"VERB 动词","cn":"喜欢;欣赏;理解","en":"If you say that you dig something, you mean that you like it and understand it.","ex":{"en":"'They play classic rock'n'roll,' states her boyfriend, 'My dad digs them too.'","cn":"“他们演奏经典摇滚乐，”她的男朋友说道，“我爸爸也喜欢他们。”"}},{"pos":"N-COUNT 可数名词","cn":"考古发掘","en":"A dig is an organized activity in which people dig into the ground in order to discover ancient historical objects.","ex":{"en":"He's an archaeologist and has been on a dig in Crete for the past year.","cn":"他是位考古学家，过去的一年都在参与克里特岛上的一项考古发掘工作。"}},{"pos":"N-COUNT 可数名词","cn":"挖苦;嘲讽","en":"If you have a dig at someone, you say something which is intended to make fun of them or upset them.","ex":{"en":"Americans are always quick to have a dig at the British","cn":"美国人总是动不动就嘲讽英国人。"}},{"pos":"N-COUNT 可数名词","cn":"（用手指或臂肘的）戳，碰，触","en":"If you give someone a dig in a part of their body, you push them with your finger or your elbow, usually as a warning or as a joke.","ex":{"en":"Cassandra silenced him with a sharp dig in the small of the back.","cn":"卡桑德拉使劲戳了一下他的后腰，让他住嘴。"}},{"pos":"N-PLURAL 复数名词","cn":"租住的房间","en":"If you live in digs, you live in a room in someone else's house and pay them rent.","ex":{"en":"He went to London and lived in digs in Gloucester Road","cn":"他去了伦敦，在格洛斯特路的一所房子里租了房间住。"}},{"pos":"PHRASE 短语","cn":"彻底调查;全面调查","en":"If you dig deep, you do a very thorough investigation into something.","ex":{"en":"I want you to dig deep. Find out who she is, and where she came from.","cn":"我想让你彻底调查一下，弄清她是谁，从哪里来的。"}},{"pos":"PHRASE 短语","cn":"设法拿出钱","en":"If someone digs into their pocket or digs into their purse, they manage after some difficulty to find the money to pay for something.","ex":{"en":"Holidaymakers are digging deep into their pockets to book late summer breaks.","cn":"度假者想方设法拿出钱来预订夏末的短暂假期。"}},{"pos":"","cn":"","en":"to dig one's heels in→see: ;"},{"pos":"","cn":"","en":"相关词组：dig around dig in dig out dig over dig up"}]},"media":{"uk":"media/uk/dig__gb_1.mp3","us":"media/us/dig__us_1.mp3","img":["media/ldoce/img/dig.jpg"]},"examples":[{"en":"Will you dig a little into his past and see what you find?","cn":"你稍微探究一下他的过去看看能发现什么，好吗？"},{"en":"More than a dozen people were dug out of the avalanche alive.","cn":"十多个埋在雪崩下的人被挖了出来，仍然活着。"}]},"dictionary":{"oxford":{"phon":"ˈdɪkʃənri","pos":"noun","senses":[{"en":"a book or electronic resource that gives a list of the words of a language in alphabetical order and explains what they mean, or gives a word for them in a foreign language","cn":"词典；字典；辞书","ex":{"en":"a Spanish-English dictionary","cn":"西班牙语–英语词典"}},{"en":"a book that explains the words that are used in a particular subject","cn":"专业术语大全；专业词典","ex":{"en":"a dictionary of mathematics","cn":"数学词典"}},{"en":"a list of words in electronic form, for example stored in a computer’s spellchecker","cn":"电子词典"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"词典;字典;辞书","en":"A dictionary is a book in which the words and phrases of a language are listed alphabetically, together with their meanings or their translations in another language.","ex":{"en":"...a Welsh-English dictionary.","cn":"一本威尔士语-英语词典"}},{"pos":"N-COUNT 可数名词","cn":"专业词典;术语大全","en":"A dictionary is an alphabetically ordered reference book on one particular subject or limited group of subjects.","ex":{"en":"...the Dictionary of National Biography.","cn":"《英国传记大词典》"}}]},"media":{"uk":"media/uk/dictionary__gb_1.mp3","us":"media/us/dictionary__us_1.mp3"},"examples":[{"en":"a Spanish-English dictionary","cn":"西班牙语 – 英语词典"},{"en":"a dictionary of mathematics","cn":"数学词典"}]},"discriminate":{"oxford":{"phon":"dɪˈskrɪmɪneɪt","pos":"verb","senses":[{"en":"to recognize that there is a difference between people or things; to show a difference between people or things","cn":"区别；辨别；区分","g":"[intransitive, transitive]","ex":{"en":"The computer program was unable to discriminate between letters and numbers.","cn":"这计算机程序不能辨别字母与数字。"}},{"en":"to treat one person or group worse/better than another in an unfair way","cn":"区别对待；歧视；偏袒","g":"[intransitive]","ex":{"en":"practices that discriminate against women and in favour of men","cn":"重男轻女的做法"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"区分;辨别","en":"If you can discriminate between two things, you can recognize that they are different.","ex":{"en":"He is incapable of discriminating between a good idea and a terrible one","cn":"他分不清主意的好坏。"}},{"pos":"VERB 动词","cn":"区别对待;歧视;偏袒","en":"To discriminate against a group of people or in favour of a group of people means to unfairly treat them worse or better than other groups.","ex":{"en":"They believe the law discriminates against women.","cn":"他们认为该项法律歧视女性。"}}]},"media":{"uk":"media/uk/discriminate__gb_1.mp3","us":"media/us/discriminate__us_1.mp3"},"examples":[{"en":"It is illegal to discriminate on grounds of race, sex or religion.","cn":"因种族、性别或宗教信仰而有所歧视是非法的。"},{"en":"A number of features discriminate this species from others.","cn":"有些特征使这一物种与其他物种区别开来。"}]},"dissolve":{"media":{"uk":"media/uk/dissolve__gb_1.mp3","us":"media/us/dissolve__us_1.mp3"},"oxford":{"phon":"dɪˈzɒlv","pos":"verb","senses":[{"en":"to mix with a liquid and become part of it","cn":"溶解","g":"[intransitive]","ex":{"en":"Salt dissolves in water.","cn":"盐溶解于水。"}},{"en":"to make a solid become part of a liquid","cn":"使（固体）溶解","g":"[transitive]","ex":{"en":"Dissolve the tablet in water.","cn":"把药片溶于水中。"}},{"en":"to officially end a marriage, business agreement or parliament","cn":"解除（婚姻关系）；终止（商业协议）；解散（议会）","g":"[transitive]","ex":{"en":"Their marriage was dissolved in 1999.","cn":"他们于 1999 年解除了婚姻关系。"}},{"en":"to disappear; to make something disappear","cn":"消除；（使）消失，消散","g":"[intransitive, transitive]","ex":{"en":"When the ambulance had gone, the crowd dissolved.","cn":"救护车离开后人群便散开了。"}},{"en":"to suddenly start laughing, crying, etc.","cn":"禁不住（笑起来或哭起来等）","g":"[intransitive]","ex":{"en":"When the teacher looked up, the children dissolved into giggles.","cn":"教师抬头看时，孩子们不禁咯咯地笑起来。"}},{"en":"to remove or destroy something, especially by a chemical process; to be destroyed in this way","cn":"（尤以化学手段）除去，毁掉；（被）破坏","g":"[transitive, intransitive]","ex":{"en":"a new detergent that dissolves stains","cn":"新型去污洗涤剂"}}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"（使）溶解","en":"If a substance dissolves in liquid or if you dissolve it, it becomes mixed with the liquid and disappears.","ex":{"en":"Heat gently until the sugar dissolves","cn":"慢慢加热直到糖溶解为止。"}},{"pos":"VERB 动词","cn":"解散(团体或机构)","en":"When an organization or institution is dissolved, it is officially ended or broken up.","ex":{"en":"The committee has been dissolved","cn":"委员会已经解散了。"}},{"pos":"VERB 动词","cn":"解散(议会)","en":"When a parliament is dissolved, it is formally ended, so that elections for a new parliament can be held.","ex":{"en":"The present assembly will be dissolved on April 30th","cn":"现在的议会将于 4 月 30 日解散。"}},{"pos":"VERB 动词","cn":"解除(婚姻关系）；终止（商业协议)","en":"When a marriage or business arrangement is dissolved, it is officially ended.","ex":{"en":"The marriage was dissolved in 1976.","cn":"这段婚姻于1976年结束。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）消失;消除;消散","en":"If something such as a problem or feeling dissolves or is dissolved, it becomes weaker and disappears.","ex":{"en":"His new-found optimism dissolved","cn":"他刚刚萌生的乐观情绪消失了。"}},{"pos":"","cn":"","en":"相关词组：dissolve into"}]},"examples":[{"en":"Every time she heard his name, she dissolved into tears.","cn":"每当听到他的名字时，她都禁不住泪流满面。"},{"en":"Their marriage was dissolved in 1999.","cn":"他们于 1999 年解除了婚姻关系。"}]},"directed":{"lemma":"direct"},"dining":{"oxford":{"phon":"ˈdaɪnɪŋ","pos":"noun","senses":[{"en":"the activity of eating a meal","cn":"进餐；用餐；吃饭","ex":{"en":"A patio area just outside the house is ideal for outdoor dining.","cn":"房子外面的露台区是户外用餐的理想场所。"}}]}},"directions":{"lemma":"direction"},"disowned":{"oxford":{"phon":"dɪsˈəʊn","pos":"verb","senses":[{"en":"to decide that you no longer want to be connected with or responsible for sb/sth","cn":"与 … 断绝关系；否认对 … 的责任"}]}},"dilemmas":{"lemma":"dilemma"},"displays":{"lemma":"display"},"distortions":{"lemma":"distortion"},"dismissed":{"lemma":"dismiss"},"discarded":{"lemma":"discard"},"discoveries":{"lemma":"discovery"},"differences":{"lemma":"difference"},"distorted":{"oxford":{"phon":"dɪˈstɔːtɪd","pos":"adjective","senses":[{"en":"pulled out of shape so that it looks strange; made to sound strange","cn":"扭曲的；歪曲的","ex":{"en":"a distorted image","cn":"扭曲的图像"}},{"en":"presented in a way that changes them so that they are no longer correct or true","cn":"失真的；歪曲的","ex":{"en":"The article gave a distorted picture of his childhood.","cn":"这篇文章对他的童年作了歪曲的描述。"}}]},"media":{"uk":"media/ldoce/hwd/bre/3/distort0205.mp3","us":"media/ldoce/hwd/ame/8/distort.mp3"},"examples":[{"en":"Tall buildings can distort radio signals.","cn":""},{"en":"His account was badly distorted by the press.","cn":""}],"base":"distort"},"directing":{"lemma":"direct"},"discussed":{"lemma":"discuss"},"disasters":{"lemma":"disaster"},"dinnertime":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"正餐时间","en":"Dinnertime is the period of the day when most people have their dinner.","ex":{"en":"The telephone call came shortly before dinnertime.","cn":"电话是在正餐快要开始时打来的。"}}]},"media":{"uk":"media/ldoce/hwd/bre/d/dinnertime0205.mp3","us":"media/ldoce/hwd/ame/f/laaddinnertime.mp3"},"examples":[{"en":"Do you want to go for a drink at dinnertime?","cn":"午餐时你想不想去喝一杯？"}]},"dispersed":{"lemma":"disperse"},"displayed":{"lemma":"display"},"disappearing":{"lemma":"disappear"},"disillusioning":{"oxford":{"phon":"ˌdɪsɪˈluːʒn","pos":"verb","senses":[{"en":"to destroy sb's belief in or good opinion of sb/sth","cn":"使醒悟；使不再抱幻想；使幻想破灭"}]}},"dives":{"lemma":"dive"},"died":{"lemma":"die"},"diversions":{"lemma":"diversion"},"distinctions":{"lemma":"distinction"},"dishes":{"lemma":"dish"},"distances":{"lemma":"distance"},"diners":{"oxford":{"phon":"ˈdaɪnə(r)","pos":"noun","senses":[{"en":"a person eating a meal, especially in a restaurant （","cn":"尤指餐馆的）就餐者"},{"en":"( especially NAmE ) a small, usually cheap, restaurant （","cn":"常指较便宜的）小餐馆，小饭店"}]}},"directories":{"lemma":"directory"},"distributed":{"lemma":"distribute"},"directs":{"lemma":"direct"},"difficulties":{"lemma":"difficulty"},"distributes":{"lemma":"distribute"},"discovered":{"lemma":"discover"},"disappeared":{"lemma":"disappear"},"discussing":{"lemma":"discuss"},"dispatched":{"oxford":{"phon":"dɪˈspætʃ","pos":"verb","senses":[{"en":"( formal ) to send sb/sth somewhere, especially for a special purpose","cn":"派遣；调遣；派出"},{"en":"( formal ) to send a letter, package or message somewhere","cn":"发出，发送（邮件、包裹、信息）"}]}},"disorders":{"lemma":"disorder"},"discounts":{"lemma":"discount"},"directors":{"lemma":"director"},"discovering":{"lemma":"discover"},"diseases":{"lemma":"disease"},"discusses":{"lemma":"discuss"},"disdaining":{"lemma":"disdain"},"dictates":{"oxford":{"phon":"dɪkˈteɪt","pos":"verb","senses":[{"en":"to say words for sb else to write down","cn":"口述"},{"en":"to tell sb what to do, especially in an annoying way （","cn":"尤指以令人厌烦的方式）指使，强行规定"}]}},"diversified":{"lemma":"diversify"},"dies":{"lemma":"die"},"disliked":{"lemma":"dislike"},"displeasure":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"不悦;不满;生气","en":"Someone's displeasure is a feeling of annoyance that they have about something that has happened.","ex":{"en":"The population has already begun to show its displeasure at the slow pace of change.","cn":"人们已经开始表露出对改革步伐缓慢的不满。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the feeling of being annoyed or not satisfied with someone or something","cn":"不悦﹐恼火﹐生气"},{"en":"SYN annoyance displeasure at/with Their displeasure at being kept waiting was clear.","cn":"他们明显很恼火﹐因为让他们久等了。 incur somebody’s displeasure (= make someone displeased )"}]},"collocations":{"phrases":["ADJ. deep | divine, official, royal He saw the English victory as a sign of divine displeasure.","VERB + DISPLEASURE cause, incur His tactless words had incurred his father's deep displeasure. | express, show, voice | conceal, hide He mad","PREP. ~ at his displeasure at being ignored | ~ with her displeasure with her colleagues"]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41displeasure.mp3","us":"media/ldoce/hwd/ame/a/displeasure.mp3"},"examples":[{"en":"She made no attempt to hide her displeasure at the prospect.","cn":"她没有掩饰自己对前景并不乐观。"}],"oxford":{"phon":"dɪsˈpleʒə(r)","pos":"noun","senses":[{"en":"the feeling of being upset and annoyed","cn":"烦恼；生气；不悦","ex":{"en":"She made no attempt to hide her displeasure at the prospect.","cn":"她没有掩饰自己对前景并不乐观。"}}]}},"diploma":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(大学)毕业文凭，学位证书;(美国中学的)毕业文凭","en":"A diploma is a qualification which may be awarded to a student by a university or college, or by a high school in the United States.","ex":{"en":"...a new two-year course leading to a diploma in social work.","cn":"一门为期两年、毕业后可以获得社会福利工作方面文凭的新课程"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"in Britain, a document that shows that someone has successfully completed a course of study or passed an examination; in the US, a document showing that a student has successfully completed their high school, college, or university education","cn":""},{"en":"you get a qualification when you finish a course and pass examinations at the end of it","cn":""},{"en":"the qualification that you get when you successfully finish a course at university","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A diploma is a document people receive when they graduate from a school or program. It is a symbol of academic success. You often see framed diplomas displayed in a doctor's office."}]},"collocations":{"phrases":["ADJ. college, university | graduate, postgraduate, professional | higher | national The college offers the Higher National Diploma in comput","VERB + DIPLOMA study for, take | have, hold | be awarded, gain, get, obtain, receive | award (sb), confer (on sb) The university awards dipl","DIPLOMA + NOUN course, programme, studies | holder Diploma holders have a far better chance of employment than those with no qualification.","PREP. ~ in a diploma in hotel management | ~ of diploma of higher education","PHRASES at diploma level Most students here are studying for a qualification at diploma level."]},"media":{"uk":"media/ldoce/hwd/bre/8/diploma0205.mp3","us":"media/ldoce/hwd/ame/8/diploma.mp3"},"examples":[{"en":"She is taking a diploma in management studies.","cn":"她在攻读管理学文凭课程。"},{"en":"a two-year diploma course","cn":"二年制的文凭课程"}],"oxford":{"phon":"dɪˈpləʊmə","pos":"noun","senses":[{"en":"a course of study at a college or university","cn":"文凭课程","lab":"British English","ex":{"en":"a two-year diploma course","cn":"二年制的文凭课程"}},{"en":"a document showing that you have completed a course of study or part of your education","cn":"毕业文凭","ex":{"en":"a High School diploma","cn":"高中毕业文凭"}}]}},"distinguishable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"可以区别开的;可以辨明的","en":"If something is distinguishable from other things, it has a quality or feature which makes it possible for you to recognize it and see that it is different.","ex":{"en":"...features that make their products distinguishable from those of their rivals","cn":"使他们的产品区别于竞争对手产品的特色"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"可辨认的;可辨识的","en":"If something is distinguishable, you can see or hear it in conditions when it is difficult to see or hear anything.","ex":{"en":"He put his ear to the floor and heard angry shouts, but no words were distinguishable","cn":"他把耳朵贴在地板上，听到了怒吼，但是听不清所说的内容。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"easy to recognize as being different from something else","cn":"容易分辨的﹐区别得开的"},{"en":"OPP indistinguishable distinguishable from The fake was barely distinguishable from the original painting.","cn":"这幅赝品与原画几乎无法区别。 barely/hardly/scarcely distinguishable clearly/easily/readily distinguishable The cheese is easily distin"}]},"vocab":{"pos":"adj","senses":[{"en":"Something that's distinguishable can be detected or observed, especially as being separate or different from something else. The one chocolate sea salt doughnut in the box will be easily distinguishable from the plain doughnuts."}]},"collocations":{"phrases":["VERBS be | become","ADV. clearly, easily, readily | barely, hardly, scarcely","PREP. by The animal is easily distinguishable by the black stripes above its eye. | from The male bird is barely distinguishable from the fe"]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41distinguishabl.mp3","us":"media/ldoce/hwd/ame/9/distinguishable.mp3"},"examples":[{"en":"The male bird is easily distinguishable from the female.","cn":"这种鸟很容易辨认雌雄。"},{"en":"The coast was barely distinguishable in the mist.","cn":"在雾中很难看清海岸。"}],"oxford":{"phon":"dɪˈstɪŋɡwɪʃəbl","pos":"adjective","senses":[{"en":"that can be recognized as different from somebody/something else","cn":"有区别的;可区分的;易辨别的","ex":{"en":"The male bird is easily distinguishable from the female.","cn":"这种鸟很容易辨认雌雄。"}},{"en":"that can be seen or heard","cn":"看清；认出；听出","ex":{"en":"The coast was barely distinguishable in the mist.","cn":"在雾中很难看清海岸。"}}]}},"disastrous":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"极糟糕的;灾难性的","en":"A disastrous event has extremely bad consequences and effects.","ex":{"en":"...the recent, disastrous earthquake","cn":"最近的灾难性地震"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"完全失败的;极糟的","en":"If you describe something as disastrous, you mean that it was very unsuccessful.","ex":{"en":"England's cricketers have had another disastrous day.","cn":"英格兰板球队又经历了灰色的一天。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"causing terrible destruction and suffering and many deaths, over a wide area","cn":""},{"en":"causing great suffering and sadness","cn":""},{"en":"very bad, or ending in failure","cn":"灾难性的﹐以失败告终的"}]},"vocab":{"pos":"adj","senses":[{"en":"Setting things on fire to see how fast they burn might seem like fun, but it can be disastrous . Something that's disastrous has terrible consequences."}]},"collocations":{"phrases":["VERBS be, prove | become","ADV. absolutely, quite, utterly The policy was absolutely disastrous for the economy. | fairly, pretty | potentially | ecologically, elector"]},"media":{"uk":"media/ldoce/hwd/bre/3/disastrous0205.mp3","us":"media/ldoce/hwd/ame/2/disastrous.mp3"},"examples":[{"en":"Lowering interest rates could have disastrous consequences for the economy.","cn":"降低利率可能给经济带来灾难性后果。"},{"en":"How could everything go so disastrously wrong?","cn":"怎么会事事都出这么大的错呢？"}],"oxford":{"phon":"dɪˈzɑːstrəs","pos":"adjective","senses":[{"en":"very bad, harmful or unsuccessful","cn":"极糟糕的；灾难性的；完全失败的","ex":{"en":"a disastrous harvest/fire/result","cn":"严重歉收／火灾；灾难性的结果"}}]}},"diplomat":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"外交官;外交家","en":"A diplomat is a senior official who discusses affairs with another country on behalf of his or her own country, usually working as a member of an embassy."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"relating to the people who officially represent their government in a foreign country","cn":""},{"en":"a diplomat of the highest rank who is the official representative of their government in a foreign country","cn":""},{"en":"the group of people who are sent to live in a foreign country in order to officially represent their government in that country","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A diplomat is a person who helps people who have differing points of view find common ground. In government, a diplomat is an official who represents his or her country in other nations."}]},"collocations":{"phrases":["ADJ. senior | experienced, good, skilful, veteran | former, retired | foreign | career, professional | American, British, etc.","VERB + DIPLOMAT be, serve as, work as He served as a diplomat in Russia before the war."]},"media":{"uk":"media/ldoce/hwd/bre/1/diplomat0205.mp3","us":"media/ldoce/hwd/ame/b/diplomat.mp3"},"examples":[{"en":"French diplomats","cn":"法国外交官"}],"oxford":{"phon":"ˈdɪpləmæt","pos":"noun","senses":[{"en":"a person whose job is to represent his or her country in a foreign country, for example, in an embassy","cn":"外交官","lab":"old-fashioned","ex":{"en":"Washington's top diplomat in Havana","cn":"华盛顿驻哈瓦那最高外交官"}},{"en":"a person who shows skill at dealing with other people","cn":"善于交际的人；通权达变的人；圆通的人；有手腕的人","ex":{"en":"You’ll need to be a real diplomat to persuade them to come to some agreement.","cn":"你需要成为一名真正的外交官才能说服他们达成某种协议。"}}]}},"disk":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"磁盘;磁碟","en":"In a computer, the disk is the part where information is stored.","ex":{"en":"The program takes up 2.5 megabytes of disk space.","cn":"这个程序占用 2.5 兆的磁盘空间。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an object that is in the shape of a circle with a large round space in the middle","cn":""},{"en":"an object that is in the shape of a flat circle","cn":""},{"en":"something such as a piece of string or wire that is curved round to make a shape almost like a circle","cn":""}]},"collocations":{"phrases":["ADJ. computer | hard | floppy | master The master disk can b e duplicated as many times a s required. | back-up | program | server, system |","VERB + DISK insert, put in Insert the disk into the drive slot. | remove, take out | format | read The computer reads the disk. | copy, dupl","DISK + VERB contain sth The dis k contains the program you'll need . | hold sth Each disk holds 700 MB .","DISK + NOUN capacity, space I' m running out of disk space on m y computer. | drive | storage","PREP. from ~ The informatio n required can then be retrieve d from disk. | on (a/the) ~ Hav e you got the file on disk? the dat a on the dis"]},"media":{"uk":"media/ldoce/hwd/bre/f/disk0205.mp3","us":"media/ldoce/hwd/ame/4/disk.mp3"},"examples":[{"en":"Red blood cells are roughly the shape of a disk.","cn":"红细胞大致呈圆盘状。"}],"oxford":{"phon":"dɪsk","pos":"noun","senses":[{"en":"a thin flat round object","cn":"圆盘；圆片","lab":"especially North American English","ex":{"en":"Red blood cells are roughly the shape of a disk.","cn":"红细胞大致呈圆盘状。"}},{"en":"a device for storing information on a computer, in the shape of a round flat plate that spins (= turns) to give access to all parts of its magnetic surface, which records information received in electronic form","cn":"磁盘；盘","lab":"computing","ex":{"en":"I'll copy the disk into a file.","cn":"我要把磁盘内容复制到文档中。"}}]}},"disrepair":{"collins":{"senses":[{"pos":"PHRASE 短语","cn":"失修;破败","en":"If something is in disrepair or is in a state of disrepair, it is broken or in bad condition.","ex":{"en":"The house was unoccupied and in a bad state of disrepair","cn":"房子里空无一人，破败不堪。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"if a building, structure, or machine falls into disrepair , its condition gradually becomes worse because no one looks after it","cn":""},{"en":"if something goes to rack and ruin , its condition gets worse and worse and no one tries to repair it until it becomes impossible to save or repair","cn":""},{"en":"buildings, roads etc that are in disrepair are in bad condition because they have not been cared for 〔","cn":"建筑物﹑道路等的〕破败﹐失修"}]},"collocations":{"phrases":["VERB + DISREPAIR fall into The building had fallen into disrepair.","PREP. in ~ Much of the old building was still in disrepair.","PHRASES a state of disrepair"]},"media":{"uk":"media/ldoce/hwd/bre/5/disrepair0205.mp3","us":"media/ldoce/hwd/ame/6/disrepair.mp3"},"examples":[{"en":"The station quickly fell into disrepair after it was closed.","cn":"车站关闭后很快便破败不堪。"},{"en":"buildings allowed to fall into disrepair","cn":"任由其破败的建筑物"}],"oxford":{"phon":"ˌdɪsrɪˈpeə(r)","pos":"noun","senses":[{"en":"a building, road, etc. that is in a state of disrepair has not been taken care of and is broken or in bad condition","cn":"失修；破败；破损","ex":{"en":"The station quickly fell into disrepair after it was closed.","cn":"车站关闭后很快便破败不堪。"}}]}},"disclose":{"collins":{"senses":[{"pos":"VERB 动词","cn":"揭露;泄露;使公开","en":"If you disclose new or secret information, you tell people about it.","ex":{"en":"Neither side would disclose details of the transaction","cn":"双方均不肯披露交易细节。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to let someone know about something that is secret or has not been known until now","cn":""},{"en":"to talk about something to someone, so that they know about it","cn":""},{"en":"to publicly reveal something such as a fact or a name that has been kept secret","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"Disclose means to reveal or expose information that has previously been kept a secret — like a politician might be forced to disclose his finances or former scandals while running for office."}]},"collocations":{"phrases":["ADV. fully He had not fully disclosed all his business dealings. | publicly","VERB + DISCLOSE be obliged to, be required to, must Members of Parliament are required to disclose all their financial interests. | be reluc","PREP. to She was accused of disclosing confidential material to a competitor."]},"media":{"uk":"media/ldoce/hwd/bre/0/disclose0205.mp3","us":"media/ldoce/hwd/ame/d/disclose.mp3"},"examples":[{"en":"The spokesman refused to disclose details of the takeover to the press.","cn":"发言人拒绝向新闻界透露公司收购的详细情况。"},{"en":"The report discloses that human error was to blame for the accident.","cn":"报告披露这次事故是人为失误造成的。"}],"oxford":{"phon":"dɪsˈkləʊz","pos":"verb","senses":[{"en":"to give somebody information about something, especially something that was previously secret","cn":"揭露；透露；泄露","ex":{"en":"The spokesman refused to disclose details of the takeover to the press.","cn":"发言人拒绝向新闻界透露收购的详细情况。"}},{"en":"to allow something that was hidden to be seen","cn":"使显露；使暴露","ex":{"en":"The door swung open, disclosing a long dark passage.","cn":"门开了，露出一条昏暗的长通道。"}}]}},"disuse":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"废弃;不用","en":"If something falls into disuse, people stop using it. If something becomes worse as a result of disuse, it becomes worse because no one uses it.","ex":{"en":"...a church which has fallen into disuse","cn":"废弃的教堂"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a disused factory, mine, railway etc is old and not used any more","cn":""},{"en":"something that is unused has not yet been used or has not been used for a long time","cn":""},{"en":"if machines or factories are idle , they are not being used","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Use the noun disuse to describe a condition of not being used. After years of disuse , you won't be surprised when your dad's motorcycle doesn't start."}]},"collocations":{"phrases":["VERB + DISUSE be in The workforce has shrunk to less than a thousand and much of the plant is in disuse. | fall into A new bridge was built ","PREP. from/through/with ~ Her muscles had become weak through disuse.","PHRASES a period of disuse"]},"media":{"uk":"media/ldoce/hwd/bre/6/disuse0205.mp3","us":"media/ldoce/hwd/ame/e/disuse.mp3"},"examples":[{"en":"The factory fell into disuse twenty years ago.","cn":"这家工厂二十年前就废弃了。"},{"en":"The building eventually fell into disuse .","cn":"该建筑物最终被废弃不用了。"}],"oxford":{"phon":"dɪsˈjuːs","pos":"noun","senses":[{"en":"a situation in which something is no longer being used","cn":"不用；废弃","ex":{"en":"The factory fell into disuse twenty years ago.","cn":"这家工厂二十年前就废弃了。"}}]}},"directory":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(通常按字母顺序排列的)通讯录，姓名住址录，工商行名录","en":"A directory is a book which gives lists of facts, for example people's names, addresses, and telephone numbers, or the names and addresses of business companies, usually arranged in alphabetical order.","ex":{"en":"...a telephone directory.","cn":"电话号码簿"}},{"pos":"N-COUNT 可数名词","cn":"(计算机磁盘中文件等的)目录","en":"A directory is an area of a computer disk which contains one or more files or other directories.","ex":{"en":"This option lets you create new files or directories.","cn":"用这个选项你可以创建新的文件或目录。"}},{"pos":"N-COUNT 可数名词","cn":"(国际互联网网站上的)专题目录","en":"On the World Wide Web, a directory is a list of the subjects that you can find information on.","ex":{"en":"Yahoo is the oldest and best-known Web directory service.","cn":"雅虎是最早且最知名的因特网目录服务网站。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a book or list of names, facts etc, usually arranged in alphabetical order 〔","cn":"通常按字母顺序排列的〕姓名地址录﹐名录﹐电话簿"},{"en":"a place in a computer where file s or programs are organized 〔","cn":"计算机文件或程序的〕目录"}]},"collocations":{"phrases":["ADJ. business, shopping, telephone, trade I found the company's name in a trade directory.","VERB + DIRECTORY consult, look sb/sth up in | compile, create | edit | produce, publish","PREP. in a/the ~ Names are listed alphabetically in the directory. | ~ of a directory of names and numbers"]},"media":{"uk":"media/ldoce/hwd/bre/e/directory0205.mp3","us":"media/ldoce/hwd/ame/2/directory.mp3"},"examples":[{"en":"a directory of European Trade Associations","cn":"欧洲同业公会名录"},{"en":"a telephone/trade directory","cn":"电话号码簿；商行名录"}],"oxford":{"phon":"dəˈrektəri","pos":"noun","senses":[{"en":"a book or electronic resource containing lists of information, usually in alphabetical order, for example people’s phone numbers or the names and addresses of businesses in a particular area","cn":"名录；电话号码簿；公司名录","ex":{"en":"a telephone/trade directory","cn":"电话号码簿；商行名录"}},{"en":"a file containing a group of other files or programs in a computer","cn":"（计算机文件或程序的）目录"},{"en":"a board in an organization or large store listing the names of departments and where to find them","cn":"（组织机构或大型商场的）指示牌，指引牌","ex":{"en":"There's a store directory over there.","cn":"那边有一个商店指示牌。"}}]}},"digestion":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"消化","en":"Digestion is the process of digesting food.","ex":{"en":"No liquids are served with meals because they interfere with digestion.","cn":"上饭菜时不要同时上汤水或饮品，因为这会影响消化。"}},{"pos":"N-COUNT 可数名词","cn":"消化系统","en":"Your digestion is the system in your body which digests your food.","ex":{"en":"My digestion ain't so hot these days, either.","cn":"我的消化系统这几天也不怎么对劲儿。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the process of digesting food","cn":"消化（过程）"},{"en":"your ability to digest food easily","cn":"消化能力"}]},"collocations":{"phrases":["ADJ. good | poor","VERB + DIGESTION have She's got very poor digestion. | aid, help Peppermint aids digestion."]},"media":{"uk":"media/ldoce/hwd/bre/9/digestion0205.mp3","us":"media/ldoce/hwd/ame/4/digestion.mp3"},"examples":[{"en":"to have a good/poor digestion","cn":"消化能力强/弱"},{"en":"Too much tea is bad for your digestion.","cn":"喝太多茶对消化不好。"}],"oxford":{"phon":"daɪˈdʒestʃən","pos":"noun","senses":[{"en":"the process of digesting food","cn":"消化","g":"[uncountable]","ex":{"en":"Vegetables are usually cooked to aid digestion.","cn":"蔬菜通常煮熟以帮助消化。"}},{"en":"the ability to digest food","cn":"消化能力","g":"[countable, usually singular]","ex":{"en":"to have a good/poor digestion","cn":"消化能力强／弱"}},{"en":"the process by which a substance breaks down when treated with heat, enzymes or a solvent (1)","cn":"消化","g":"[uncountable]","lab":"chemistry","ex":{"en":"Food and animal waste will be processed via anaerobic digestion to produce biogas for energy or fertilizer.","cn":"食物和动物废物将通过厌氧消化进行处理，产生用于能源或肥料的沼气。"}}]}},"distort":{"collins":{"senses":[{"pos":"VERB 动词","cn":"歪曲;扭曲;曲解","en":"If you distort a statement, fact, or idea, you report or represent it in an untrue way.","ex":{"en":"The media distorts reality; categorises people as all good or all bad","cn":"媒体会歪曲事实，将人说得不是完美无缺就是一无是处。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使）变形;(使)失真","en":"If something you can see or hear is distorted or distorts, its appearance or sound is changed so that it seems unclear.","ex":{"en":"A painter may exaggerate or distort shapes and forms","cn":"画家可能会对线条和形状进行夸大或扭曲。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to explain facts, statements etc in a way that makes them seem different from what they really are","cn":""},{"en":"to dishonestly change the meaning of a piece of information or of something that someone has said, in order to get an advantage for yourself or to support your own opinion","cn":""},{"en":"to give people a wrong idea about someone or their opinions, by what you write or say","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"Distort means to twist out of shape. When you look at a tree through a twisting kaleidoscope, you distort its image, making its branches and leaves look wavy and misshapen."}]},"collocations":{"phrases":["ADV. grossly, seriously, severely He was accused of grossly distorting the facts. | completely | slightly | deliberately"]},"media":{"uk":"media/ldoce/hwd/bre/3/distort0205.mp3","us":"media/ldoce/hwd/ame/8/distort.mp3"},"examples":[{"en":"The loudspeaker seemed to distort his voice.","cn":"他的声音从喇叭里传出来好像失真了。"},{"en":"The article gave a distorted picture of his childhood.","cn":"这篇文章对他的童年作了歪曲的描述。"}],"oxford":{"phon":"dɪˈstɔːt","pos":"verb","senses":[{"en":"to change the shape, appearance or sound of something so that it is strange or not clear","cn":"使变形；扭曲；使失真","ex":{"en":"a fairground mirror that distorts your shape","cn":"露天游乐场的哈哈镜"}},{"en":"to change facts, ideas, etc. so that they are no longer correct or true","cn":"歪曲；曲解","ex":{"en":"Newspapers are often guilty of distorting the truth.","cn":"报章常犯歪曲事实的错误。"}}]}},"distortion":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"歪曲;曲解","en":"Distortion is the changing of something into something that is not true or not acceptable.","ex":{"en":"I think it would be a gross distortion of reality to say that they were motivated by self-interest","cn":"我认为说他们是受自身利益的驱使是对事实的严重歪曲。"}},{"pos":"N-VAR 可变名词","cn":"失真;变形","en":"Distortion is the changing of the appearance or sound of something in a way that makes it seem strange or unclear.","ex":{"en":"Audio signals can be transmitted along cables without distortion.","cn":"声音信号可以通过电缆传送而不失真。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to explain facts, statements etc in a way that makes them seem different from what they really are","cn":""},{"en":"to dishonestly change the meaning of a piece of information or of something that someone has said, in order to get an advantage for yourself or to support your own opinion","cn":""},{"en":"to give people a wrong idea about someone or their opinions, by what you write or say","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A distortion is a change, twist, or exaggeration that makes something appear different from the way it really is. You can distort an image, a thought, or even an idea. To say that I never take out the garbage is a distortion of the facts."}]},"collocations":{"phrases":["ADJ. severe | slight | inevitable","VERB + DISTORTION cause, create, lead to The wrong chemical balance can cause severe distortion of the photographic image. | avoid 2 changin","ADJ. gross, serious His report was attacked as a gross distortion of the truth. | deliberate"]},"media":{"uk":"media/ldoce/hwd/bre/3/distort0205.mp3","us":"media/ldoce/hwd/ame/8/distort.mp3"},"examples":[{"en":"modern alloys that are resistant to wear and distortion","cn":"耐磨、防变形的新型合金"},{"en":"a distortion of the facts","cn":"对事实的歪曲"}],"oxford":{"phon":"dɪˈstɔːʃn","pos":"noun","senses":[{"en":"a change in the shape, appearance or sound of something so that it is strange or not clear","cn":"使变形；扭曲；使失真","ex":{"en":"modern alloys that are resistant to wear and distortion","cn":"耐磨、防变形的新型合金"}},{"en":"a change in facts, ideas, etc. that makes them no longer correct or true","cn":"歪曲；曲解","ex":{"en":"a distortion of the facts","cn":"对事实的歪曲"}}]}},"dilemma":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（进退两难的）窘境，困境","en":"A dilemma is a difficult situation in which you have to choose between two or more alternatives. on the horns of a dilemma→see: ;","ex":{"en":"He was faced with the dilemma of whether or not to return to his country","cn":"要不要回国，他进退两难。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a situation in which it is very difficult to decide what to do, because all the choices seem equally good or equally bad","cn":"进退两难的境地﹐困境"},{"en":"a situation in which you cannot do one thing until you do another thing, but you cannot do that thing until you do the first thing, with the result that you can do neither","cn":""},{"en":"a situation in which something bad will happen whatever you decide to do","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A dilemma is a tough choice. When you're in a difficult situation and each option looks equally bad, you're in a dilemma ."}]},"collocations":{"phrases":["ADJ. acute, appalling, big, difficult, genuine, great, impossible, real, serious, terrible, thorny | central, essential, fundamental The fun","VERB + DILEMMA create, pose This poses a difficult dilemma for teachers. | be caught in, be faced with, confront, face, have They were caugh","DILEMMA + VERB arise, occur, present itself the dilemma that arises when a doctor has to decide whether or not to prescribe an expensive tre","PREP. in a/the ~ The minister is now in an impossible dilemma. | ~ about/over She faced a dilemma about whether to accept the offer or not. ","PHRASES a solution to a dilemma, a way out of a dilemma I couldn't see any way out of the dilemma."]},"media":{"uk":"media/ldoce/hwd/bre/d/dilemma0205.mp3","us":"media/ldoce/hwd/ame/2/dilemma.mp3"},"examples":[{"en":"to face a dilemma","cn":"面临左右为难的困境"},{"en":"to be in a dilemma","cn":"处于进退两难的境地"}],"oxford":{"phon":"dɪˈlemə","pos":"noun","senses":[{"en":"a situation that makes problems, often one in which you have to make a very difficult choice between things of equal importance","cn":"（进退两难的）窘境，困境","ex":{"en":"I could see no way of resolving this moral dilemma.","cn":"我想不出解决这种道德困境的办法。"}}]}},"directive":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"指示;命令","en":"A directive is an official instruction that is given by someone in authority.","ex":{"en":"Thanks to a new EU directive, insecticide labelling will be more specific.","cn":"根据欧盟的一项新指令，杀虫剂的标签标注将更加明确。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an official statement ordering you to do something, given by someone with the power to do this, especially a military officer","cn":""},{"en":"a statement telling someone what they must do, usually giving them details of how they should do it","cn":""},{"en":"an official order by someone such as a king or a military officer which must be obeyed","cn":""}]},"collocations":{"phrases":["ADJ. clear Don't start anything without a clear directive from management. | general | important | draft, proposed | EU, European (Commissio","VERB + DIRECTIVE issue The EU issued a new drinking water directive. | adopt, agree (on/upon), approve, sign | comply with, implement All co","DIRECTIVE + VERB come into force A new EU directive on maternity leave will come into force next month. | require sth The directive requires","PREP. in accordance with a/the ~ They acted in accordance with the latest directive from Brussels. | in a/the ~ The proposals are contained ","PHRASES the provisions/terms of a directive"]},"media":{"uk":"media/ldoce/hwd/bre/b/directive_n0205.mp3","us":"media/ldoce/hwd/ame/d/directive.mp3"},"examples":[{"en":"They are seeking a central, directive role in national energy policy.","cn":"他们正寻求在国家能源政策方面起中心指导作用。"},{"en":"The EU has issued a new set of directives on pollution.","cn":"欧盟发布了一系列关于污染的新指令。"}],"oxford":{"phon":"dəˈrektɪv","pos":"noun","senses":[{"en":"an official instruction","cn":"指示；命令","ex":{"en":"The EU has issued a new set of directives on pollution.","cn":"欧盟发布了一系列关于污染的新指令。"}},{"en":"giving instructions","cn":"指示的；指导的","ex":{"en":"They are seeking a central, directive role in national energy policy.","cn":"他们正寻求在国家能源政策方面起中心指导作用。"},"pos":"adjective"}]}},"disregard":{"collins":{"senses":[{"pos":"VERB 动词","cn":"不理会;不顾;漠视","en":"If you disregard something, you ignore it or do not take account of it.","ex":{"en":"He disregarded the advice of his executives","cn":"他对主管层的建议置若罔闻。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to not obey a law or rule","cn":""},{"en":"to not do what a rule or law says you must do","cn":""},{"en":"to disobey or do something that is against a rule, agreement, principle etc","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"If everyone at the city council meeting tends to disregard anything that's said by the eccentric gentleman with the parrot on his shoulder, it means that no one pays any attention to him."}]},"collocations":{"phrases":["ADJ. complete, total, utter | blatant, flagrant | callous, cavalier, cynical | reckless, wanton their reckless disregard for human life | bl","VERB + DISREGARD demonstrate, show","PREP. ~ for He showed complete disregard for the feelings of his family. | ~ of their flagrant disregard of the rules"]},"media":{"uk":"media/ldoce/hwd/bre/5/disregard_v0205.mp3","us":"media/ldoce/hwd/ame/e/disregard1.mp3"},"examples":[{"en":"The board completely disregarded my recommendations.","cn":"董事会完全无视我的建议。"},{"en":"She shows a total disregard for other people's feelings.","cn":"她丝毫不顾及别人的感受。"}],"oxford":{"phon":"ˌdɪsrɪˈɡɑːd","pos":"verb","senses":[{"en":"to not consider something; to treat something as unimportant","cn":"不理会；不顾；漠视","ex":{"en":"The board completely disregarded my recommendations.","cn":"董事会完全无视我的建议。"}},{"en":"the act of treating somebody/something as not important and not caring about them/it","cn":"漠视；忽视","ex":{"en":"their reckless disregard for human life","cn":"他们对生命的无视"},"pos":"noun"}]}},"disloyalty":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"不忠","en":"Disloyalty is disloyal behaviour.","ex":{"en":"Charges had already been made against certain officials suspected of disloyalty.","cn":"对某些有不忠嫌疑的官员已经提起了诉讼。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not loyal to your friends, your country, or the group you belong to","cn":""},{"en":"someone who is treacherous is extremely disloyal and cannot be trusted because they secretly intend to harm other people in order to get advantages for themselves","cn":""},{"en":"when someone behaves in a way that is not loyal to their friends, country, or the group they belong to","cn":""}]},"collocations":{"phrases":["VERB + DISLOYALTY show | accuse sb of Her friends accused her of disloyalty.","PREP. ~ to He has shown disloyalty to the party and is not to be trusted."]},"media":{"uk":"media/ldoce/hwd/bre/3/disloyal0205.mp3","us":"media/ldoce/hwd/ame/c/disloyal.mp3"},"examples":[{"en":"He felt he had been disloyal to his friends.","cn":""}],"oxford":{"phon":"dɪsˈlɔɪəlti","pos":"noun","senses":[{"en":"the fact of not showing support for your friends, family, country, etc.","cn":"（对国家、家庭等）不忠实的，不忠诚的；（对朋友等）不守信义的","ex":{"en":"She felt guilty of disloyalty to her dead husband.","cn":"她因对死去的丈夫不忠而感到内疚。"}}]}},"disconcerting":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"令人不安的;令人困惑的;令人尴尬的","en":"If you say that something is disconcerting, you mean that it makes you feel anxious, confused, or embarrassed.","ex":{"en":"The reception desk is not at street level, which is a little disconcerting.","cn":"接待处不在临街的这层，这多少让人有点想不通。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"making you feel slightly confused, embarrassed, or worried","cn":"令人困惑的﹔令人尴尬的﹔令人不安的"}]},"vocab":{"pos":"adj","senses":[{"en":"Something is disconcerting if it makes you uneasy or unsettles you. Even if you don't give your little brother's dreams of conquering the world and enslaving humanity much chance of success, you may find them disconcerting ."}]},"collocations":{"phrases":["VERBS be | become | find sth","ADV. highly, very | a bit, a little, rather, slightly, somewhat I found all that noise rather disconcerting."]},"media":{"uk":"media/ldoce/hwd/bre/3/brelasdedisconcerting.mp3","us":"media/ldoce/hwd/ame/7/laaddisconcerting.mp3"},"examples":[{"en":"She had the disconcerting habit of saying exactly what she thought.","cn":"她怎么想的就怎么说，这种习惯令人非常难堪。"},{"en":"a disconcerting question","cn":"令人困惑的问题"}],"oxford":{"phon":"ˌdɪskənˈsɜːtɪŋ","pos":"adjective","senses":[{"en":"making you feel worried, confused or embarrassed","cn":"让你感到担心、困惑或尴尬","ex":{"en":"She had the disconcerting habit of saying exactly what she thought.","cn":"她有一个令人难堪的习惯：说话直率。"}}]}},"discredit":{"collins":{"senses":[{"pos":"VERB 动词","cn":"败坏…的名声;使丧失信誉;使丢脸","en":"To discredit someone or something means to cause them to lose people's respect or trust.","ex":{"en":"...a secret unit within the company that had been set up to discredit its major rival","cn":"公司里设立的败坏其主要竞争对手名声的秘密部门"}},{"pos":"VERB 动词","cn":"使不可信;证实…是假的","en":"To discredit an idea or evidence means to make it appear false or not certain.","ex":{"en":"They realized there would be difficulties in discrediting the evidence.","cn":"他们意识到要揭穿这个证据困难重重。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to spoil the idea that people have about someone, especially a famous person who is often on television, in newspapers and magazines etc","cn":""},{"en":"to make people no longer have a good opinion about someone, especially a politician or someone with an important job","cn":""},{"en":"containing information about someone's dishonest or immoral behaviour, which damages the good opinion that people have of them","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"Discredit means to cause mistrust or cast the accuracy of something into doubt. If you say that schooling is important to you, but you never study, your actions discredit you and your words."}]},"collocations":{"phrases":["ADJ. great","VERB + DISCREDIT bring, reflect By telling lies he brought discredit upon Parliament. Your failure reflects no discredit upon you?you did yo","PREP. to sb's ~ His selfish decision is greatly to his discredit. | ~ to They were a discredit to their country."]},"media":{"uk":"media/ldoce/hwd/bre/3/discredit_v0205.mp3","us":"media/ldoce/hwd/ame/d/discredit1.mp3"},"examples":[{"en":"Britain, to its discredit, did not speak out against these atrocities.","cn":"英国没有公开反对这些残暴行为，使其名誉扫地。"},{"en":"Violent football fans bring discredit on the teams they support.","cn":"狂暴的足球迷败坏了他们所支持球队的声誉。"}],"oxford":{"phon":"dɪsˈkredɪt","pos":"verb","senses":[{"en":"to make people stop respecting somebody/something","cn":"败坏…的名声；使丧失信誉；使丢脸","ex":{"en":"The photos were deliberately taken to discredit the president.","cn":"这些蓄意拍摄的照片旨在败坏总统的名声。"}},{"en":"to make people stop believing that something is true; to make something appear unlikely to be true","cn":"使不相信；使（受到）怀疑","ex":{"en":"These theories are now largely discredited among linguists.","cn":"这些理论现已大多受到语言学家的质疑。"}},{"en":"damage to somebody’s/something's reputation; loss of respect","cn":"名誉丧失；信誉丧失；丢脸","g":"[uncountable]","ex":{"en":"Violent football fans bring discredit on the teams they support.","cn":"狂暴的足球迷败坏了他们所支持球队的声誉。"},"pos":"noun"},{"en":"a person or thing that causes damage to somebody's/something's reputation or loss of respect","cn":"丢脸的人（或事）；耻辱","g":"[countable]","ex":{"en":"They were a discredit to their country.","cn":"他们是国家的耻辱。"},"pos":"noun"}]}},"disdain":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"轻视;鄙视;蔑视","en":"If you feel disdain for someone or something, you dislike them because you think that they are inferior or unimportant.","ex":{"en":"Janet looked at him with disdain","cn":"珍妮特轻蔑地看着他。"}},{"pos":"VERB 动词","cn":"轻视;鄙视;蔑视","en":"If you disdain someone or something, you regard them with disdain.","ex":{"en":"Jackie disdained the servants that her millions could buy.","cn":"杰姬鄙视那些她用钱就可以收买的奴仆。"}},{"pos":"VERB 动词","cn":"不屑于（做）","en":"If you disdain to do something, you do not do it, because you feel that you are too important to do it.","ex":{"en":"Franklin told Sara that he had himself disdained to take the job.","cn":"富兰克林告诉萨拉他不屑于去做那份工作。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a complete lack of respect that you show for someone or something because you think they are not important or good enough","cn":"鄙视﹐轻视﹐藐视"},{"en":"to have no respect for someone or something, because you think they are not important or good enough","cn":"鄙视﹐轻视﹐藐视"},{"en":"to refuse to do something because you are too proud to do it","cn":"不屑于做某事"}]},"vocab":{"pos":"n v","senses":[{"en":"If you feel that something isn't worthy of your consideration, you may disdain it (or treat it with disdain )."}]},"collocations":{"phrases":["ADJ. great | utter | obvious | amused | cool, glacial | aristocratic, haughty","VERB + DISDAIN feel, have She did not hesitate to express the disdain that she felt. | express, show Judges sometimes show great disdain for","PREP. in ~ She turned her head away in disdain. | with ~ Why does he treat his father with such disdain? | ~ for He has an aristocratic disd","PHRASES an expression/a look of disdain"]},"media":{"uk":"media/ldoce/hwd/bre/3/disdain_n0205.mp3","us":"media/ldoce/hwd/ame/c/disdain1.mp3"},"examples":[{"en":"She disdained his offer of help.","cn":"他提出要帮助，遭到她的鄙弃。"},{"en":"He disdained to turn to his son for advice.","cn":"他不屑向自己的儿子请教。"}],"oxford":{"phon":"dɪsˈdeɪn","pos":"noun","senses":[{"en":"the feeling that somebody/something is not good enough to deserve your respect or attention","cn":"鄙视；蔑视；鄙弃","ex":{"en":"She treated him with disdain.","cn":"她对他很鄙视。"}},{"en":"to think that somebody/something does not deserve your respect or interest","cn":"鄙视；蔑视；鄙弃","ex":{"en":"She disdained his offer of help.","cn":"他提出要帮忙，遭到她的鄙弃。"},"pos":"verb"},{"en":"to refuse to do something because you think that you are too important to do it","cn":"不屑（做某事）","ex":{"en":"He disdained to turn to his son for advice.","cn":"他不屑向自己的儿子请教。"},"pos":"verb"}]}},"disarmament":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"裁军;裁减军备(尤指核武器)","en":"Disarmament is the act of reducing the number of weapons, especially nuclear weapons, that a country has.","ex":{"en":"...the pace of nuclear disarmament.","cn":"裁减核武器的步伐"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when a country reduces the number of weapons it has, or the size of its army, navy etc","cn":"裁军﹐裁减军备"}]},"collocations":{"phrases":["ADJ. nuclear They campaigned for nuclear disarmament. | international, multilateral The party supports multilateral disarmament. | unilatera","VERB + DISARMAMENT campaign for | support","DISARMAMENT + NOUN negotiations, talks, treaty"]},"media":{"uk":"media/ldoce/hwd/bre/a/disarmament0205.mp3","us":"media/ldoce/hwd/ame/8/disarmament.mp3"},"examples":[{"en":"disarmament talks","cn":"裁军谈判"},{"en":"nuclear disarmament","cn":"核裁军"}],"oxford":{"phon":"dɪsˈɑːməmənt","pos":"noun","senses":[{"en":"the fact of a country reducing the size of its armed forces or the number of weapons, especially nuclear weapons, that it has","cn":"裁军；裁减军备（尤指核武器）","ex":{"en":"They campaigned for nuclear disarmament.","cn":"他们发起了要求核裁军的运动。"}}]}},"diversion":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"转移注意力的行为;令人分心的事情","en":"A diversion is an action or event that attracts your attention away from what you are doing or concentrating on.","ex":{"en":"The robbers threw smoke bombs to create a diversion","cn":"劫匪扔烟幕弹来转移人们的视线。"}},{"pos":"N-COUNT 可数名词","cn":"消遣;娱乐","en":"A diversion is an activity that you do for pleasure.","ex":{"en":"Finger painting is very messy but an excellent diversion.","cn":"用手指画画是很脏，但却是一项极好的消遣。"}},{"pos":"N-COUNT 可数名词","cn":"临时绕行路;临时支路","en":"A diversion is a special route arranged for traffic to follow when the normal route cannot be used.","ex":{"en":"They turned back because of traffic diversions.","cn":"因为交通要临时绕行，他们掉头了。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"转向;转移;偏离","en":"The diversion of something involves changing its course or destination.","ex":{"en":"...the illegal diversion of profits from secret arms sales.","cn":"秘密军火交易所获利润的非法转移"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a clever plan designed to make someone believe something that you want them to believe, or do something that you want them to do","cn":""},{"en":"a clever plan designed to harm someone, for example by making them go somewhere where they will be caught or attacked, or making them say something they will be punished for","cn":""},{"en":"something that is said or done with the deliberate intention of deceiving people","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A diversion can be something that takes you off the course you are on, like a detour while you are traveling, or a game of tennis that takes you away from the stress of work."}]},"collocations":{"phrases":["ADJ. brief, short | major","VERB + DIVERSION make, take From Poiso we make a short diversion to drive to the top of the mountain.","PREP. ~ from the diversion of water from the river into the reservoir | ~ to The pilot set the aircraft up for a diversion to the nearest su","ADJ. temporary A temporary diversion has been set up to take traffic away from the accident site. | traffic","VERB + DIVERSION set up | signpost The road will be closed for two days; diversions have been signposted.","DIVERSION + VERB be in operation The main road is now closed and diversions are in operation. 3 distraction","ADJ. welcome","VERB + DIVERSION create, provide The fire was started to create a diversion, allowing some prisoners to escape."]},"media":{"uk":"media/ldoce/hwd/bre/6/diversion0205.mp3","us":"media/ldoce/hwd/ame/e/diversion.mp3"},"examples":[{"en":"For the government, the war was a welcome diversion from the country's economic problems.","cn":"政府欢迎这场战争，因为它转移了人们对国家经济问题的注意力。"},{"en":"A smoke bomb created a diversion while the robbery took place.","cn":"劫案发生时，一枚烟雾弹转移了人们的视线。"}],"oxford":{"phon":"daɪˈvɜːʃn","pos":"noun","senses":[{"en":"the act of changing the direction that somebody/something is following, or what something is used for","cn":"转向；转移；偏离","g":"[countable, uncountable]","ex":{"en":"a river diversion project","cn":"河流改道工程"}},{"en":"something that takes your attention away from somebody/something while something else is happening","cn":"转移视线（或注意力）的事物","g":"[countable]","ex":{"en":"For the government, the war was a welcome diversion from the country's economic problems.","cn":"政府欢迎这场战争，因为它转移了人们对国家经济问题的注意力。"}},{"en":"a road or route that is used when the usual one is closed","cn":"临时绕行路；分流路","g":"[countable]","lab":"British English","ex":{"en":"Diversions will be signposted.","cn":"临时绕行路都将设置路标。"}},{"en":"an activity that is done for pleasure, especially because it takes your attention away from something else","cn":"消遣；娱乐","g":"[countable]","lab":"rather formal","ex":{"en":"The party will make a pleasant diversion.","cn":"这个聚会将是一个很不错的消遣活动。"}}]}},"distasteful":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"使人不愉快的;令人反感的;讨厌的","en":"If something is distasteful to you, you think it is unpleasant, disgusting, or immoral.","ex":{"en":"He found it distasteful to be offered drinks before witnessing the execution.","cn":"他觉得在目睹行刑前还要上酒让人很不舒服。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"unpleasant or morally offensive","cn":"令人生厌的﹐令人反感的"}]},"collocations":{"phrases":["VERBS be, seem | find sth","ADV. extremely, highly I find his attitude highly distasteful. | thoroughly | fairly, rather","PREP. to The work was thoroughly distasteful to her."]},"media":{"uk":"media/ldoce/hwd/bre/f/distasteful0205.mp3","us":"media/ldoce/hwd/ame/7/distasteful.mp3"},"examples":[{"en":"What follows is John’s story. Parts of it may seem distasteful, even shocking.","cn":"接下来是约翰的叙述﹐其中有些部分也许令人不快﹐甚至令人震惊。"}],"oxford":{"phon":"dɪsˈteɪstfl","pos":"adjective","senses":[{"en":"unpleasant or offensive","cn":"令人不快的；令人反感的；讨厌的","ex":{"en":"The bad language in the film was distasteful and unnecessary.","cn":"电影中的脏话令人反感且没有必要。"}}]}},"disgraceful":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（行为、情形等）丢脸的，可耻的，不名誉的","en":"If you say that something such as behaviour or a situation is disgraceful, you disapprove of it strongly, and feel that the person or people responsible should be ashamed of it.","ex":{"en":"It's disgraceful that they have detained him for so long","cn":"他们把他扣押了这么长时间，真不光彩。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"bad, embarrassing, or unacceptable","cn":"可耻的﹐丢脸的，不光彩的"}]},"collocations":{"phrases":["VERBS be","ADV. absolutely, quite, utterly There's litter everywhere. It's absolutely disgraceful."]},"media":{"uk":"media/ldoce/hwd/bre/5/disgraceful0205.mp3","us":"media/ldoce/hwd/ame/4/disgraceful.mp3"},"examples":[{"en":"It's disgraceful that none of the family tried to help her.","cn":"家里竟无人肯帮助她，太不像话了。"},{"en":"His behaviour was absolutely disgraceful!","cn":"他的行为真可耻！"}],"oxford":{"phon":"dɪsˈɡreɪsfl","pos":"adjective","senses":[{"en":"very bad or unacceptable; that people should feel ashamed about","cn":"不光彩的；可耻的；丢脸的","ex":{"en":"His behaviour was absolutely disgraceful!","cn":"他的行为真可耻！"}}]}},"dignified":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有尊严的;庄严的;高贵的","en":"If you say that someone or something is dignified, you mean they are calm, impressive and deserve respect.","ex":{"en":"He seemed a very dignified and charming man","cn":"他看上去很高贵，富有魅力。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a feeling of respect and confidence in yourself and in your abilities","cn":""},{"en":"the feeling that you are someone who deserves to be liked, respected, and admired","cn":""},{"en":"the ability to behave in a calm way that shows that you respect yourself, even in difficult situations","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Dignified means self-respecting and worthy. If you want to have a dignified memorial service, skip the karaoke machine and instead softly play the favorite music of the person you're remembering."}]},"collocations":{"phrases":["VERBS be, look, seem | remain","ADV. very | quite | quietly He remained quietly dignified in defeat."]},"media":{"uk":"media/ldoce/hwd/bre/5/brelasdedignified.mp3","us":"media/ldoce/hwd/ame/6/dignified.mp3"},"examples":[{"en":"Throughout his trial he maintained a dignified silence.","cn":"在整个审讯过程中，他始终沉默以保持尊严。"},{"en":"a dignified person/manner/voice","cn":"有尊严的人；庄重的举止；庄严的声音"}],"oxford":{"phon":"ˈdɪɡnɪfaɪd","pos":"adjective","senses":[{"en":"calm and serious and deserving respect","cn":"庄重的；庄严的；有尊严的","ex":{"en":"a dignified person/manner/voice","cn":"有尊严的人；庄重的举止；庄严的声音"}}]}},"discrepancy":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"差异;不符;不一致;出入","en":"If there is a discrepancy between two things that ought to be the same, there is a noticeable difference between them.","ex":{"en":"...the discrepancy between press and radio reports.","cn":"新闻和广播报道之间的出入"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"if one statement or fact contradicts another one, it is so different that it makes the other one seem untrue or impossible","cn":""},{"en":"very different from each other - use this especially when two things should be the same","cn":""},{"en":"if a statement, story, fact etc is inconsistent with what you expect or already know of the situation, it is completely different from it","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A discrepancy is a lack of agreement or balance. If there is a discrepancy between the money you earned and the number on your paycheck, you should complain to your boss."}]},"collocations":{"phrases":["ADJ. glaring, great, huge, large, major, marked, material, serious, substantial, wide | minor, slight, small | apparent","VERB + DISCREPANCY account for, explain How do you explain the apparent discrepancies between the money and the receipts? | find, note, noti","DISCREPANCY + VERB exist | arise, occur","PREP. ~ between Discrepancies occurred between the written and electronic records. | ~ in There were wide discrepancies in the evidence."]},"media":{"uk":"media/ldoce/hwd/bre/8/discrepancy0205.mp3","us":"media/ldoce/hwd/ame/8/discrepancy.mp3"},"examples":[{"en":"What are the reasons for the discrepancy between girls' and boys' performance in school?","cn":"女生和男生在学校表现不同的原因何在呢？"},{"en":"wide discrepancies in prices quoted for the work","cn":"这项工作的报价出入很大"}],"oxford":{"phon":"dɪˈskrepənsi","pos":"noun","senses":[{"en":"a difference between two or more things that should be the same","cn":"差异；不符合；不一致","ex":{"en":"wide discrepancies in prices quoted for the work","cn":"这项工作的报价出入很大"}}]}},"diplomacy":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"外交","en":"Diplomacy is the activity or profession of managing relations between the governments of different countries.","ex":{"en":"Today's Security Council resolution will be a significant success for American diplomacy","cn":"今天的安理会决议将是美国外交取得的一个重大成功。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(处理人际关系等的)手腕，策略，手段","en":"Diplomacy is the skill of being careful to say or do things which will not offend people.","ex":{"en":"He stormed off in a fury, and it took all Minnelli's powers of diplomacy to get him to return.","cn":"他愤然离去，米内利使出了浑身解数才把他劝了回来。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the job or activity of managing the relationships between countries","cn":"外交﹔外交活动"},{"en":"skill in dealing with people without upsetting them","cn":"处世之道﹐交际手段"}]},"vocab":{"pos":"n","senses":[{"en":"Diplomacy is the art of helping groups to get along and even work together. If you have a gift for diplomacy , you can get bickering siblings to cooperate."}]},"collocations":{"phrases":["ADJ. careful, shrewd | &lsquo;gunboat &hellip; &rsquo; What they could not take by political intrigue they took by &lsquo;gunboat diplomacy&","VERB + DIPLOMACY use prefering to use diplomacy rather than force","DIPLOMACY + VERB go on Behind the scenes a lot of secret diplomacy was going on.","PREP. by/through ~ We must try and resolve this situation through diplomacy rather than conflict. 2 skill in dealing with people","ADJ. great | quiet","VERB + DIPLOMACY have We need someone who has tact and diplomacy. | exercise, show, use I thought you showed great diplomacy in dealing with","PREP. by/through ~ The way forward in this situation is by diplomacy and negotiation. | with ~ She handled the awkward situation with her us"]},"media":{"uk":"media/ldoce/hwd/bre/2/diplomacy0205.mp3","us":"media/ldoce/hwd/ame/3/diplomacy.mp3"},"examples":[{"en":"Diplomacy is better than war.","cn":"采取外交手段胜于诉诸战争。"},{"en":"international diplomacy","cn":"国际外交"}],"oxford":{"phon":"dɪˈpləʊməsi","pos":"noun","senses":[{"en":"the activity of managing relations between different countries; the skill in doing this","cn":"外交；外交技巧；外交手腕","lab":"US English","ex":{"en":"international diplomacy","cn":"国际外交"}},{"en":"skill in dealing with people in difficult situations without upsetting or offending them","cn":"（处理人际关系的）手腕，手段，策略","ex":{"en":"She was praised for her tact and diplomacy.","cn":"她因机智和外交而受到赞扬。"}}]}},"dismiss":{"collins":{"senses":[{"pos":"VERB 动词","cn":"不考虑;不理会","en":"If you dismiss something, you decide or say that it is not important enough for you to think about or consider.","ex":{"en":"Mr Wakeham dismissed the reports as speculation","cn":"韦克厄姆先生把这些报道当作臆测而不予考虑。"}},{"pos":"VERB 动词","cn":"(从头脑中)去除;不再考虑;抛弃","en":"If you dismiss something from your mind, you stop thinking about it.","ex":{"en":"I dismissed him from my mind","cn":"我不再想他了。"}},{"pos":"VERB 动词","cn":"解雇;免…的职;开除","en":"When an employer dismisses an employee, the employer tells the employee that they are no longer needed to do the job that they have been doing.","ex":{"en":"...the power to dismiss civil servants who refuse to work","cn":"开除拒不上班的公务员的权力"}},{"pos":"VERB 动词","cn":"让…离去;把…打发走;解散;遣散","en":"If you are dismissed by someone in authority, they tell you that you can go away from them.","ex":{"en":"Two more witnesses were called, heard and dismissed","cn":"又有两个目击者被传唤，提供证言后获准退席。"}},{"pos":"VERB 动词","cn":"(法官)驳回，不予受理","en":"When a judge dismisses a case against someone, he or she formally states that there is no need for a trial, usually because there is not enough evidence for the case to continue.","ex":{"en":"An American judge yesterday dismissed murder charges against Dr Jack Kevorkian.","cn":"昨天一个美国法官驳回了对杰克·凯沃尔基安医生的谋杀指控。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to not accept a statement, explanation, or decision because you think it is wrong or untrue","cn":""},{"en":"to refuse to accept someone's opinions, suggestions, proof etc without even considering it","cn":""},{"en":"to refuse to consider someone’s idea, opinion etc, because you think it is not serious, true, or important","cn":"拒绝考虑﹐不理会"}]},"vocab":{"pos":"v","senses":[{"en":"At the end of a lesson period, your teacher says, \"class dismissed.\" This means that you and the rest of the students are free to go."}]},"collocations":{"phrases":["ADV. quickly | out of hand, summarily He dismissed her suggestion out of hand. | easily, lightly, readily Children's fears should never be d","VERB + DISMISS cannot/could not, unable to | be difficult to, be easy to, be possible to It was not easy to dismiss the matter from his thou","PREP. as, from She dismissed their arguments as irrelevant. She tried to dismiss the idea from her mind. 2 remove sb from a job","ADV. fairly | unfairly, wrongfully The court ruled that Ms Hill had been unfairly dismissed. | constructively | summarily","PREP. from He was summarily dismissed from his job."]},"media":{"uk":"media/ldoce/hwd/bre/6/dismiss0205.mp3","us":"media/ldoce/hwd/ame/2/dismiss.mp3"},"examples":[{"en":"I think we can safely dismiss their objections.","cn":"我认为我们对他们的异议完全可以不予理会。"},{"en":"He dismissed the opinion polls as worthless.","cn":"他认为民意测验毫无用处而不予考虑。"}],"oxford":{"phon":"dɪsˈmɪs","pos":"verb","senses":[{"en":"to decide that somebody/something is not important and not worth thinking or talking about","cn":"不予考虑；摒弃；对…不屑一提","ex":{"en":"to dismiss a suggestion/a claim/an idea","cn":"驳回建议／要求／想法"}},{"en":"to put thoughts or feelings out of your mind","cn":"去除，消除，摒除（思想、感情等）","ex":{"en":"Dismissing her fears, she climbed higher.","cn":"她排除了恐惧，爬得更高了。"}},{"en":"to officially remove somebody from their job","cn":"解雇；免职；开除","ex":{"en":"She claims she was unfairly dismissed from her post.","cn":"她声称自己被无理免职。"}},{"en":"to send somebody away or allow them to leave","cn":"让（某人）离开；把（某人）打发走；解散","ex":{"en":"At 12 o'clock the class was dismissed.","cn":"12 点下课了。"}},{"en":"to say that a trial or legal case should not continue, usually because there is not enough evidence","cn":"驳回；不受理","lab":"law","ex":{"en":"The judge dismissed the case for lack of evidence.","cn":"法官以证据不足驳回了此案。"}},{"en":"to end the innings of a player or team","cn":"使（球员或球队）退场；使出局"}]}},"disrepute":{"collins":{"senses":[{"pos":"PHRASE 短语","cn":"丧失名誉;落得坏名声","en":"If something is brought into disrepute or falls into disrepute, it loses its good reputation, because it is connected with activities that people do not approve of.","ex":{"en":"Such people bring our profession into disrepute.","cn":"这种人令我们这一行业蒙羞。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to give a group or place a bad reputation by behaving in an unacceptable way","cn":""},{"en":"to damage the reputation of the organization that you work for or the job that you do by doing something bad or illegal - use this especially in legal or official contexts","cn":""},{"en":"to make people stop trusting or believing in someone or something","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Disrepute is when a person or a group has a really bad reputation. A mean prank played by just a few football players, for example, might bring the entire team into disrepute ."}]},"collocations":{"phrases":["VERB + DISREPUTE fall into The old system had fallen into disrepute. | bring sth into The players' behaviour on the field is likely to bring","PREP. in ~ This theory is now in disrepute."]},"media":{"uk":"media/ldoce/hwd/bre/c/disrepute0205.mp3","us":"media/ldoce/hwd/ame/9/disrepute.mp3"},"examples":[{"en":"The players' behaviour on the field is likely to bring the game into disrepute.","cn":"球员在赛场上的表现很可能使这场比赛臭名远扬。"},{"en":"He faces six charges of bringing the game into disrepute .","cn":"他面临六项败坏这项运动声誉的指控。"}],"oxford":{"phon":"ˌdɪsrɪˈpjuːt","pos":"noun","senses":[{"en":"the fact that somebody/something loses the respect of other people","cn":"丧失名誉；坏名声","ex":{"en":"The players' behaviour on the field is likely to bring the game into disrepute.","cn":"球员在赛场上的表现很可能使这场比赛臭名远扬。"}}]}},"discomfort":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"不舒服;不适","en":"Discomfort is a painful feeling in part of your body when you have been hurt slightly or when you have been uncomfortable for a long time.","ex":{"en":"She carried her left arm at an awkward angle, as if it were causing her discomfort","cn":"她的左胳膊很不自然地抬着，好像它让她不舒服似的。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"尴尬;惭愧;窘迫","en":"Discomfort is a feeling of worry caused by shame or embarrassment.","ex":{"en":"He sniffed, fidgeting in discomfort, uneasy at the suggestion","cn":"他吸了吸鼻子，对这项提议感到窘迫不安，心烦意乱。"}},{"pos":"N-COUNT 可数名词","cn":"使人感到不舒服的事情","en":"Discomforts are conditions which cause you to feel physically uncomfortable.","ex":{"en":"...the discomforts of camping.","cn":"露营的不适"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the feeling when part of your body hurts","cn":""},{"en":"a continuous pain, especially one that is not very bad. Most commonly used in compounds such as headache , toothache , and backache","cn":""},{"en":"a sudden slight pain that comes and then disappears quickly","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Discomfort is the feeling of irritation, soreness, or pain that, though not severe, is annoying. Every year, people who get a cold or the flu experience a few days of discomfort ."}]},"collocations":{"phrases":["ADJ. acute, considerable, great, severe, growing He became conscious of a growing discomfort. | mild, minor, slight You may experience some ","QUANT. amount, degree","VERB + DISCOMFORT complain of, experience, feel, get, have, suffer Some of the patients complained of discomfort. I didn't have much discomf","PREP. in ~ He appeared to be in great discomfort. | with/without ~ You should be able to drive without discomfort after about two weeks. 2 e","VERB + DISCOMFORT cause The revelations caused some discomfort to the president. | enjoy Paula smiled, enjoying her sister's discomfort.","DISCOMFORT + VERB grow, increase"]},"media":{"uk":"media/ldoce/hwd/bre/a/discomfort0205.mp3","us":"media/ldoce/hwd/ame/5/discomfort.mp3"},"examples":[{"en":"John's presence caused her considerable discomfort.","cn":"约翰在场使她颇感尴尬。"},{"en":"You will experience some minor discomfort during the treatment.","cn":"治疗中你会稍感不适。"}],"oxford":{"phon":"dɪsˈkʌmfət","pos":"noun","senses":[{"en":"a feeling of slight pain or of being physically uncomfortable","cn":"轻微的病痛；不舒服；不适","g":"[uncountable]","ex":{"en":"You will experience some minor discomfort during the treatment.","cn":"治疗中你会稍感不适。"}},{"en":"a feeling of worry or being embarrassed","cn":"不安；不自在；尴尬","g":"[uncountable]","ex":{"en":"John's presence caused her considerable discomfort.","cn":"约翰在场使她颇感尴尬。"}},{"en":"something that makes you feel uncomfortable or causes you a slight feeling of pain","cn":"使人不舒服的事物；苦事；痛苦","g":"[countable]","ex":{"en":"the dangers and discomforts of a life at sea","cn":"海上生活的危险和不适"}},{"en":"to make somebody feel anxious or embarrassed","cn":"使不舒服；使不安；使尴尬","ex":{"en":"Many patients complained of being discomforted by the doctor’s manner.","cn":"许多患者抱怨医生的态度让他们感到不舒服。"},"pos":"verb"}]}},"ditch":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(道路、田地边上的)沟，渠","en":"A ditch is a long narrow channel cut into the ground at the side of a road or field."},{"pos":"VERB 动词","cn":"摆脱;抛弃;丢弃","en":"If you ditch something that you have or are responsible for, you abandon it or get rid of it, because you no longer want it.","ex":{"en":"I decided to ditch the sofa bed.","cn":"我决定把沙发床扔了。"}},{"pos":"VERB 动词","cn":"抛弃;甩掉;与…断交","en":"If someone ditches someone, they end a relationship with that person.","ex":{"en":"I can't bring myself to ditch him and start again.","cn":"我不忍心蹬掉他再觅新欢。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使）(飞机)紧急迫降","en":"If a pilot ditches an aircraft or if it ditches, the pilot makes an emergency landing.","ex":{"en":"One American pilot was forced to ditch his jet in the Gulf","cn":"一位美国飞行员被迫将喷气式飞机紧急迫降在波斯湾上。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a long narrow hole dug at the side of a field, road etc to hold or remove unwanted water 〔","cn":"在田边﹑路边等处挖的〕沟﹐渠"},{"en":"to remove or deal with something that is causing you trouble, such as an illness or a problem","cn":""},{"en":"to officially end a law, legal right, or system, especially one that has existed for a long time","cn":""}]},"vocab":{"pos":"1 n v 2 v 3 v","senses":[{"en":"A ditch is a long trench or pit dug into the ground. If your lawns are always soggy, build a drainage ditch for the excess water to flow into."}]},"collocations":{"phrases":["ADJ. deep, wide | shallow, small | open The drainage system consisted of a few open ditches to facilitate run-off. | muddy | drainage, irrig","VERB + DITCH dig","DITCH + VERB run The ditch ran parallel to the road. | surround sth His lettuce garden was surrounded by a deep ditch.","PREP. in/into a ~ I tripped and fell into a muddy ditch."]},"media":{"uk":"media/ldoce/hwd/bre/2/brelasdeditch.mp3","us":"media/ldoce/hwd/ame/6/ditch1.mp3"},"examples":[{"en":"The new road building programme has been ditched.","cn":"新的道路建设计划已废弃。"},{"en":"He ditched his girlfriend.","cn":"他把女朋友给甩了。"}],"oxford":{"phon":"dɪtʃ","pos":"noun","senses":[{"en":"a long channel dug at the side of a field or road, to hold or take away water","cn":"沟；渠","ex":{"en":"The car left the road and ended up in a ditch.","cn":"汽车驶离公路，最后掉进了沟里。"}},{"en":"to get rid of something/somebody because you no longer want or need it/them","cn":"摆脱；抛弃；丢弃","g":"[transitive]","lab":"informal","ex":{"en":"The new road building programme has been ditched.","cn":"新的道路建设计划已废弃。"},"pos":"verb"},{"en":"if a pilot ditches an aircraft, or if it ditches, it lands in the sea in an emergency","cn":"使（飞机）在海上紧急降落；（在海上）迫降","g":"[transitive, intransitive]","pos":"verb"},{"en":"to stay away from school without permission","cn":"旷课；逃学","g":"[transitive]","lab":"North American English, informal，，","pos":"verb"}]}},"disservice":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"损害;伤害;危害","en":"If you do someone or something a disservice, you harm them in some way.","ex":{"en":"He said the protesters were doing a disservice to the nation","cn":"他说抗议者正对国家造成危害。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to do something that gives other people a bad opinion of someone or something","cn":"损害[破坏]〔某人或某物〕的声誉[形象]"},{"en":"to do something that gives other people a bad opinion of someone or something","cn":"损害[破坏]某人/某物的声誉[形象]"}]},"collocations":{"phrases":["ADJ. grave, great","VERB + DISSERVICE do sb","PREP. ~ to This violence will do a grave disservice to their cause."]},"media":{"uk":"media/ldoce/hwd/bre/f/disservice_n0205.mp3","us":"media/ldoce/hwd/ame/5/disservice.mp3"},"examples":[{"en":"The fans have done the game a great disservice.","cn":"球迷们的行为大大损害了这项运动的名声。"},{"en":"Hart’s poems are disserviced by the decision to squeeze three or even four short pieces onto one page.","cn":"把三首甚至四首短诗挤在同一页上的决定损害了哈特的诗作。"}]},"disparity":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"不同;不等;差异;悬殊","en":"If there is a disparity between two or more things, there is a noticeable difference between them.","ex":{"en":"...the economic disparities between East and West Berlin.","cn":"东西柏林之间经济上的悬殊"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a detail, fact, or quality that makes one person or thing different from another","cn":""},{"en":"a very clear difference that you can easily see when you compare two things or people","cn":""},{"en":"a big difference between two amounts, two ages, or two groups of people","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"If there is a disparity between how great you think you are at tennis, and how you actually play, you are probably surprised by how often you lose. Disparity is the condition of being unequal, and a disparity is a noticeable difference."}]},"collocations":{"phrases":["ADJ. considerable, enormous, great, gross, wide | growing | clear, glaring, obvious","PREP. ~ between The great disparity between the teams did not make for an entertaining game. | ~ in the disparity in their salaries | ~ of a"]},"media":{"uk":"media/ldoce/hwd/bre/0/disparity0205.mp3","us":"media/ldoce/hwd/ame/2/disparity.mp3"},"examples":[{"en":"the wide disparity between rich and poor","cn":"贫富悬殊"},{"en":"a disparity between the rates of pay for men and women","cn":"男性与女性在工资水平上的差异"}],"oxford":{"phon":"dɪˈspærəti","pos":"noun","senses":[{"en":"a difference, especially one connected with unfair treatment","cn":"（尤指因不公正对待引起的）不同，不等，差异，悬殊","ex":{"en":"The wide disparity between rich and poor was highlighted.","cn":"特别强调了贫富差距悬殊的问题。"}}]}},"distinctive":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"独特的;特别的;有特色的","en":"Something that is distinctive has a special quality or feature which makes it easily recognizable and different from other things of the same type.","ex":{"en":"...the distinctive odour of chlorine.","cn":"氯气特有的气味"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if something or someone is different, they are not like something or someone else, or they are not like they were before","cn":""},{"en":"very different, special, or unusual and the only one of its kind. Don’t use words such as very before unique","cn":""},{"en":"having a special feature or appearance that makes something different from other things, and makes it easy to recognize","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Her big eyes and plump lips are distinctive features that make her a great model. These are just some of the special features that distinguish her."}]},"collocations":{"phrases":["VERBS be","ADV. extremely, highly, very The shell has a highly distinctive pattern. | quite | fairly"]},"media":{"uk":"media/ldoce/hwd/bre/5/distinctive0205.mp3","us":"media/ldoce/hwd/ame/6/distinctive.mp3"},"examples":[{"en":"The male bird has distinctive white markings on its head.","cn":"雄鸟的头上有明显的白色斑纹。"},{"en":"clothes with a distinctive style","cn":"式样独特的衣服"}],"oxford":{"phon":"dɪˈstɪŋktɪv","pos":"adjective","senses":[{"en":"having a quality or characteristic that makes something different and easily noticed","cn":"独特的；特别的；有特色的","ex":{"en":"clothes with a distinctive style","cn":"式样独特的衣服"}}]}},"disrespect":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"不尊敬;无礼;轻蔑","en":"If someone shows disrespect, they speak or behave in a way that shows lack of respect for a person, law, or custom.","ex":{"en":"...young people with complete disrespect for authority.","cn":"根本不把权威放在眼里的年轻人"}},{"pos":"PHRASE 短语","cn":"(在表示批评某人或某物时)绝无不尊敬之意","en":"You can say 'no disrespect to someone or something' when you are just about to criticize them, in order to indicate that you are not hostile towards them or admire them for other things.","ex":{"en":"No disrespect to John Beck, but the club has been happier since he left.","cn":"我对约翰·贝克绝无不敬之意，但自他离开后俱乐部气氛的确更活跃了。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"rude, especially towards someone you should respect, for example your parents or someone in authority","cn":""},{"en":"making rude remarks to or asking personal questions of someone you should respect - use this especially about children","cn":""},{"en":"rude and showing no respect for someone in authority, especially by saying things or asking questions about something that it is not your right to know or discuss","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"To disrespect someone is to act in an insulting way toward them. When you disrespect people, you think very little of them."}]},"collocations":{"phrases":["ADJ. total | healthy","VERB + DISRESPECT have, show, treat sb/sth with She felt he had total disrespect for women. | mean no I mean no disrespect to the team, but ","PREP. ~ for The new manager showed a healthy disrespect for formality.","PHRASES no disrespect intended/to &hellip; No disrespect intended sir; it was just a joke."]},"media":{"uk":"media/ldoce/hwd/bre/a/disrespect_n0205.mp3","us":"media/ldoce/hwd/ame/7/disrespect.mp3"},"examples":[{"en":"No disrespect intended sir. It was just a joke.","cn":"先生，绝无不敬之意。这不过是个玩笑而已。"},{"en":"They were accused of disrespecting the country's flag.","cn":"他们被控亵渎国旗。"}],"oxford":{"phon":"ˌdɪsrɪˈspekt","pos":"noun","senses":[{"en":"a lack of respect for somebody/something","cn":"不尊敬；无礼；轻蔑","ex":{"en":"disrespect for the law/the dead","cn":"藐视法律；对死者的不敬"}},{"en":"to speak about or treat somebody/something without respect","cn":"不尊敬；对…无礼","ex":{"en":"They were accused of disrespecting the country's flag.","cn":"他们被控亵渎国旗。"},"pos":"verb"}]}},"distribute":{"collins":{"senses":[{"pos":"VERB 动词","cn":"分发;分配;分送","en":"If you distribute things, you hand them or deliver them to a number of people.","ex":{"en":"Students shouted slogans and distributed leaflets","cn":"学生们喊着口号，分发着传单。"}},{"pos":"VERB 动词","cn":"配销;运销;分销","en":"When a company distributes goods, it supplies them to the shops or businesses that sell them.","ex":{"en":"We didn't understand how difficult it was to distribute a national paper.","cn":"我们不了解分销一份全国发行的报纸有多难。"}},{"pos":"VERB 动词","cn":"（在成员中）分配，分派","en":"If you distribute things among the members of a group, you share them among those members.","ex":{"en":"Immediately after his election he began to distribute major offices among his friends and supporters.","cn":"他当选后立即着手将要职分派给他的朋友和支持者们。"}},{"pos":"VERB 动词","cn":"撒;播","en":"To distribute a substance over something means to scatter it over it.","ex":{"en":"Distribute the topping evenly over the fruit.","cn":"将配料均匀地撒在水果上。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to give something to each of the people in a group","cn":""},{"en":"to give things to a large number of people, especially in the streets","cn":""},{"en":"to divide something into equal parts and give a part to each person","cn":""}]},"vocab":{"pos":"1 v 2 v","senses":[{"en":"To distribute is to disperse widely, hand out or spread around. While you're still snoozing, the paper boy is busy distributing the newspaper all over the neighborhood."}]},"collocations":{"phrases":["ADV. equally, fairly | unequally | widely The leaflets have been widely distributed. | free Copies of the book were distributed free to each","PREP. among We distributed the money equally among the team members. | between, to distributing aid to people in need 2 spread sth","ADV. evenly, uniformly Wealth is not evenly distributed between age groups. | unevenly | randomly Smokers were randomly distributed in the s","PREP. among, between, throughout There are over 35,000 species of orchid distributed throughout the world."]},"media":{"uk":"media/ldoce/hwd/bre/f/distribute0205.mp3","us":"media/ldoce/hwd/ame/b/distribute.mp3"},"examples":[{"en":"The money was distributed among schools in the area.","cn":"这笔款项是在本地区的学校中分配的。"},{"en":"The organization distributed food to the earthquake victims.","cn":"这个机构向地震灾民分发了食品。"}],"oxford":{"phon":"dɪˈstrɪbjuːt","pos":"verb","senses":[{"en":"to give things to a large number of people; to share something between a number of people","cn":"分发；分配","ex":{"en":"The leaflets have been widely distributed.","cn":"传单已广泛散发。"}},{"en":"to send goods to shops and businesses so that they can be sold","cn":"分销","ex":{"en":"Who distributes our products in the UK?","cn":"谁在英国经销我们的产品？"}},{"en":"to spread something, or different parts of something, over an area","cn":"使散开；使分布；分散","g":"[often passive]","ex":{"en":"Make sure your weight is evenly distributed.","cn":"要确保你的重量分布均匀。"}}]}},"dissent":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(尤指与多数人或权威人士的)意见不一致,意见分歧","en":"Dissent is strong disagreement or dissatisfaction with a decision or opinion, especially one that is supported by most people or by people in authority.","ex":{"en":"He is the toughest military ruler yet and has responded harshly to any dissent","cn":"他是迄今最强硬的军事统治者，对任何异议都一律进行打压。"}},{"pos":"VERB 动词","cn":"不同意，持异议(尤指与多数人或权威人士支持的观点、决定相左)","en":"If you dissent, you express disagreement with a decision or opinion, especially one that is supported by most people or by people in authority.","ex":{"en":"Just one of the 10 members dissented","cn":"只有1/10的成员不同意。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when people disagree with each other","cn":""},{"en":"when people are unable to agree, especially about something important - use this as a way of avoiding more direct words like 'argument' and 'disagreement'","cn":""},{"en":"a serious disagreement about a decision, plan, or action, that causes arguments for a long time in newspapers, on television etc","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"To dissent is to publicly disagree with an official opinion or decision. Dissent is also a noun referring to public disagreement."}]},"collocations":{"phrases":["ADJ. serious, strong He would brook no serious dissent. | growing | internal internal party dissent | political, religious Political dissent","VERB + DISSENT arouse, cause, provoke | express, show There are many ways of expressing dissent. | brook, tolerate | stifle, suppress The re","PREP. ~ against popular dissent against the Church | ~ from His dissent from his family's religious beliefs caused a lot of ill-feeling.","PHRASES a voice of dissent In the early 1960s, the voices of dissent began to rise."]},"media":{"uk":"media/ldoce/hwd/bre/1/dissent_v0205.mp3","us":"media/ldoce/hwd/ame/c/l2dissent.mp3"},"examples":[{"en":"Only two ministers dissented from the official view.","cn":"只有两位部长与官方持不同的观点。"},{"en":"dissenting groups/voices/views/opinion","cn":"持不同意见的团体；反对的呼声；不同的观点；异议"}],"oxford":{"phon":"dɪˈsent","pos":"noun","senses":[{"en":"the fact of having or expressing opinions that are different from those that are officially accepted","cn":"（与官方的）不同意见，异议","g":"[uncountable]","ex":{"en":"political/religious dissent","cn":"政治观点／宗教信仰上的分歧"}},{"en":"the offence of openly disagreeing with the referee's decision","cn":"不服裁判","g":"[uncountable]","ex":{"en":"He was sent off for dissent.","cn":"他因不服裁判被罚下场。"}},{"en":"a judge’s statement giving reasons why they disagree with a decision made by the other judges in a court case","cn":"（诉讼案中某法官对其他法官判决的）异议，不同意见","g":"[countable]","lab":"North American English"},{"en":"to have or express opinions that are different from those that are officially accepted","cn":"（对官方意见）不同意，持异议","ex":{"en":"Only two ministers dissented from the official view.","cn":"只有两位部长与官方持不同的观点。"},"pos":"verb"}]}},"disillusionment":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"醒悟;不再抱幻想;理想破灭","en":"Disillusionment is the disappointment that you feel when you discover that something is not as good as you had expected or thought.","ex":{"en":"...his growing disillusionment with his work.","cn":"他对他的工作越来越不抱幻想"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"unhappy because something you hoped for did not happen, or because something was not as good as you expected","cn":""},{"en":"to feel disappointed because something was not as good as you expected, or someone did not do what you expected them to do for you – a rather informal use","cn":""},{"en":"disappointed because you have lost your belief that an idea is right, or that something or someone is good","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Feeling disillusionment means you're bummed out because you no longer believe in something — usually because you find out it isn't as amazing as you thought."}]},"collocations":{"phrases":["ADJ. general, public, widespread | growing","VERB + DISILLUSIONMENT cause","PREP. ~ among causing widespread disillusionment among young people | ~ with There is growing public disillusionment with the present system"]},"media":{"uk":"media/ldoce/hwd/bre/1/brelasdedisillusioned.mp3","us":"media/ldoce/hwd/ame/e/disillusioned.mp3"},"examples":[{"en":"There is widespread disillusionment with the present government.","cn":"人们对现政府普遍感到失望。"},{"en":"As she grew older, Laura became increasingly disillusioned with politics.","cn":""}],"oxford":{"phon":"ˌdɪsɪˈluːʒnmənt","pos":"noun","senses":[{"en":"the state of being disillusioned","cn":"醒悟；不再抱幻想；幻想破灭","ex":{"en":"There is widespread disillusionment with the present government.","cn":"人们对现政府普遍感到失望。"}}]}},"distaste":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"不喜欢;反感;厌恶","en":"If you feel distaste for someone or something, you dislike them and consider them to be unpleasant, disgusting, or immoral.","ex":{"en":"Roger looked at her with distaste","cn":"罗杰厌恶地看着她。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a feeling of not liking someone or something","cn":""},{"en":"a feeling of dislike that you have for someone or something because you think they are very unpleasant or offensive","cn":""},{"en":"a strong, sometimes unreasonable, dislike of something","cn":""}]},"collocations":{"phrases":["ADJ. deep, extreme, great, intense, profound, strong | growing | evident, obvious She regarded the child with evident distaste. | irrational","VERB + DISTASTE feel, have | express, show trying not to show her distaste | conceal, hide He couldn't conceal the deep distaste that he fel","PREP. in ~ She wrinkled her nose in mock distaste. | with ~ Jim looked with distaste at the cockroach in his soup. | ~ at He couldn't hide h","PHRASES an expression/a look of distaste, a feeling of distaste"]},"media":{"uk":"media/ldoce/hwd/bre/f/distaste0205.mp3","us":"media/ldoce/hwd/ame/f/distaste.mp3"},"examples":[{"en":"He looked around the filthy room in distaste.","cn":"他厌恶地环顾着这肮脏的房间。"},{"en":"a distaste for politics of any sort","cn":"对任何形式的政治的反感"}],"oxford":{"phon":"dɪsˈteɪst","pos":"noun","senses":[{"en":"a feeling that somebody/something is unpleasant or offensive","cn":"不喜欢；反感；厌恶","ex":{"en":"He looked around the filthy room in distaste.","cn":"他厌恶地环视着这肮脏的房间。"}}]}},"dismal":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"忧郁的;凄凉的;令人沮丧的","en":"Something that is dismal is bad in a sad or depressing way.","ex":{"en":"...Israel's dismal record in the Olympics","cn":"以色列在奥运会上让人沮丧的记录"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(尤指外表)阴暗的，阴沉的，沉闷的","en":"Something that is dismal is sad and depressing, especially in appearance.","ex":{"en":"The main part of the hospital is pretty dismal but the children's ward is really lively.","cn":"医院的主体部分死气沉沉，但是儿科病房却充满生气。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"use this about a story, piece of music, period of time etc that makes you feel sad","cn":""},{"en":"a time when you are unhappy because you are in a difficult or unpleasant situation","cn":""},{"en":"a depressing experience, story, piece of news etc makes you feel that there is nothing to be happy about and not much hope for the future","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Dismal is a dreary, depressing sort of bad. \"With the cold rain and their team behind by six field goals, the mood in the stands was so dismal even the cheerleaders had lost their 'Rah.'\""}]},"collocations":{"phrases":["VERBS be, look | become","ADV. really It was a really dismal day. | a bit, fairly, pretty, rather Last year's results were fairly dismal."]},"media":{"uk":"media/ldoce/hwd/bre/0/dismal0205.mp3","us":"media/ldoce/hwd/ame/3/dismal.mp3"},"examples":[{"en":"The singer gave a dismal performance of some old songs.","cn":"那歌手唱了几首老歌，唱得也不怎么样。"},{"en":"Their recent attempt to increase sales has been a dismal failure.","cn":"他们最近努力提高销售量，全是白费劲。"}],"oxford":{"phon":"ˈdɪzməl","pos":"adjective","senses":[{"en":"causing or showing the feeling of being sad","cn":"忧郁的；凄凉的；惨淡的；阴沉的","ex":{"en":"dismal conditions/surroundings/weather","cn":"悲惨的状况；凄凉的环境；阴沉的天气"}},{"en":"not successful; of very low quality","cn":"不成功的；差劲的；不怎么样的","lab":"informal","ex":{"en":"The singer gave a dismal performance of some old songs.","cn":"那歌手唱了几首老歌，唱得不怎么样。"}}]}},"divisible":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"可除尽的","en":"If one number is divisible by another number, the second number can be divided into the first exactly, with nothing left over.","ex":{"en":"Twenty-eight is divisible by seven.","cn":"28 可以被 7 除尽。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"able to be divided, for example by a number","cn":"可分的﹔可整除的"}]},"collocations":{"phrases":["VERBS be","ADV. infinitely He argued that all matter was infinitely divisible.","PREP. by Twelve is divisible by four. | into Plants are divisible into three main groups."]},"media":{"uk":"media/ldoce/hwd/bre/1/divisible0205.mp3","us":"media/ldoce/hwd/ame/a/divisible.mp3"},"examples":[{"en":"8 is divisible by 2 and 4, but not by 3. * 8","cn":"可被 2 和 4 除尽，但不能被 3 除尽。"},{"en":"8 is divisible by 2 and 4, but not by 3.","cn":""}],"oxford":{"phon":"dɪˈvɪzəbl","pos":"adjective","senses":[{"en":"that can be divided","cn":"可分开的","ex":{"en":"Plants are divisible into three main groups.","cn":"植物可分为三大类。"}},{"en":"that can be divided, usually with nothing left over","cn":"可除；可除尽","lab":"mathematics","ex":{"en":"8 is divisible by 2 and 4, but not by 3.","cn":"8 可被 2 和 4 整除，但不能被 3 整除。"}}]}},"diagnose":{"collins":{"senses":[{"pos":"VERB 动词","cn":"诊断;确诊;判断;断定","en":"If someone or something is diagnosed as having a particular illness or problem, their illness or problem is identified. If an illness or problem is diagnosed, it is identified.","ex":{"en":"The soldiers were diagnosed as having flu","cn":"这些士兵经诊断患了流感。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to find out the exact details or facts about something, especially by using technical methods and equipment","cn":""},{"en":"to find out facts that will prove how something happened or what caused it","cn":""},{"en":"to find out exactly what the cause or origin of something is","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"If you diagnose a disease, you recognize it by the signs and symptoms your patient shows. Your high temperature and the green crud you keep coughing up will allow your doctor to diagnose your bronchitis."}]},"collocations":{"phrases":["ADV. correctly | incorrectly, wrongly Her condition was wrongly diagnosed by the doctor.","PREP. with He was diagnosed with leukaemia."]},"media":{"uk":"media/ldoce/hwd/bre/6/diagnose0205.mp3","us":"media/ldoce/hwd/ame/3/diagnose.mp3"},"examples":[{"en":"He was diagnosed (as) a diabetic when he was 64.","cn":"他 64 岁时被诊断患有糖尿病。"},{"en":"The test is used to diagnose a variety of diseases.","cn":"此项化验可用于诊断多种疾病。"}],"oxford":{"phon":"ˈdaɪəɡnəʊz","pos":"verb","senses":[{"en":"to say exactly what an illness or the cause of a problem is","cn":"诊断（疾病）；判断（问题的原因）","lab":"British English","ex":{"en":"The test is used to diagnose a variety of diseases.","cn":"此项化验可用于诊断多种疾病。"}}]}},"dissertation":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"专题论文;（尤指）学位论文","en":"A dissertation is a long formal piece of writing on a particular subject, especially for a university degree.","ex":{"en":"He is currently writing a dissertation on the Somali civil war.","cn":"他目前正在写一篇关于索马里内战的论文。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a piece of writing written by a student as part of a course of study","cn":""},{"en":"an essay written by a someone who has studied a subject as part of their research. Paper is also used about an essay that you have to write for a class at school, especially in American English","cn":""},{"en":"a long essay written as part of a university degree","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A dissertation is a long piece of writing that uses research to bring to light an original idea. Don't go to grad school unless you're prepared to write, say, a 300-page dissertation on some topic."}]},"collocations":{"phrases":["ADJ. research | doctoral, Master's, undergraduate | MSc, PhD, etc. | 15,000-word, etc.","VERB + DISSERTATION do, prepare, write Students can either do a dissertation or take part in a practical project. | complete, finish | hand ","PREP. ~ on He wrote his Master's dissertation on rats."]},"media":{"uk":"media/ldoce/hwd/bre/6/dissertation0205.mp3","us":"media/ldoce/hwd/ame/d/dissertation.mp3"},"oxford":{"phon":"ˌdɪsəˈteɪʃn","pos":"noun","senses":[{"en":"a long piece of writing on a particular subject, especially one written for a university degree","cn":"专题论文；（尤指）学位论文","ex":{"en":"He wrote his Master's dissertation on rats.","cn":"他的硕士论文写的是关于老鼠的问题。"}}]}},"discharge":{"collins":{"senses":[{"pos":"VERB 动词","cn":"允许…离开(医院、军队);(从监狱)释放","en":"When someone is discharged from hospital, prison, or one of the armed services, they are officially allowed to leave, or told that they must leave.","ex":{"en":"He has a broken nose but may be discharged today","cn":"他鼻梁断了，但或许今天就能出院。"}},{"pos":"VERB 动词","cn":"履行（职责）；完成（任务）","en":"If someone discharges their duties or responsibilities, they do everything that needs to be done in order to complete them.","ex":{"en":"...the quiet competence with which he discharged his many college duties.","cn":"他得以胜任众多大学职务的那种内秀"}},{"pos":"VERB 动词","cn":"清偿(债务)","en":"If someone discharges a debt, they pay it.","ex":{"en":"The goods will be sold for a fraction of their value in order to discharge the debt.","cn":"货物将被贱价卖出以清偿债务。"}},{"pos":"VERB 动词","cn":"排出;使流出;放出","en":"If something is discharged from inside a place, it comes out.","ex":{"en":"The resulting salty water will be discharged at sea","cn":"所产生的盐水将被排入大海。"}},{"pos":"N-VAR 可变名词","cn":"（物质的）放出，排出","en":"When there is a discharge of a substance, the substance comes out from inside somewhere.","ex":{"en":"They develop a fever and a watery discharge from their eyes","cn":"他们开始发烧，眼睛里分泌出一种水状物。"}},{"pos":"VERB 动词","cn":"击发(枪、炮)","en":"If someone discharges a gun, they fire it.","ex":{"en":"Lewis was tried for unlawfully and dangerously discharging a weapon.","cn":"刘易斯因非法和不安全的开枪而受到了审判。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make someone leave their job, especially because they have done something wrong","cn":""},{"en":"to make someone leave their job, especially because they are not good at it, or because they have done something wrong","cn":""},{"en":"to make a lot of workers, especially workers in a large factory or organization, leave their jobs, because there is not enough work for them to do, or not enough money to pay their wages","cn":""}]},"vocab":{"pos":"1 v n 2 v n 3 v n 4 ","senses":[{"en":"To discharge is to fire a gun or an employee, or to set someone free from a hospital or jail. You'd probably like being discharged from jail, but not from your job, unless you really hate it."}]},"collocations":{"phrases":["ADV. dishonourably, honourably","PREP. from He was found guilty and dishonourably discharged from the army. 2 from prison/court","ADV. conditionally He was conditionally discharged after admitting the theft. 3 gas/liquid","ADV. directly","PREP. from, into Raw sewage was discharged from the treatment plant directly into the river."]},"media":{"uk":"media/ldoce/hwd/bre/9/discharge_v0205.mp3","us":"media/ldoce/hwd/ame/6/l3discharge.mp3"},"examples":[{"en":"The factory was fined for discharging chemicals into the river.","cn":"这家工厂因往河里排放化学物质而被罚款。"},{"en":"He was conditionally discharged after admitting the theft.","cn":"他承认偷盗行为后被有条件地释放了。"}],"oxford":{"phon":"dɪsˈtʃɑːdʒ","pos":"verb","senses":[{"en":"to give somebody official permission to leave the police or the armed forces; to make somebody leave the police or the armed forces","cn":"（警察机关或军队）批准（某人）退役，使（某人）退出","g":"[transitive, usually passive]","sc":"from the police/army","ex":{"en":"He was discharged from the army following his injury.","cn":"他受伤后就退伍了。"}},{"en":"to allow somebody to leave hospital because they are well enough to leave","cn":"准许（某人）出院","g":"[transitive, often passive]","sc":"from hospital","ex":{"en":"Patients were being discharged from the hospital too early.","cn":"病人都过早获准出院。"}},{"en":"to allow somebody to leave prison or court","cn":"释放","g":"[transitive, often passive]","sc":"from prison/court","ex":{"en":"He was conditionally discharged after admitting the theft.","cn":"他承认偷盗行为后被有条件地释放了。"}},{"en":"to allow a member of a jury to stop serving in a court case","cn":"使（陪审团成员）退出；解散（陪审团）","g":"[transitive, often passive]","sc":"from prison/court","ex":{"en":"If the jury cannot agree, it should be discharged.","cn":"如果陪审团不能达成一致意见，就应该解散。"}},{"en":"when a gas or a liquid discharges or is discharged, or somebody discharges it, it flows somewhere","cn":"排出；放出；流出","g":"[intransitive, transitive]","sc":"gas/liquid","ex":{"en":"The river is diverted through the power station before discharging into the sea.","cn":"这条河改道经水电站后流入大海。"}},{"en":"if part of the body discharges something, a liquid such as pus comes out of it","cn":"（人体部位）排出（脓等）","g":"[transitive]","sc":"gas/liquid","ex":{"en":"The wound started discharging pus.","cn":"伤口开始流脓。"}},{"en":"to release force or power","cn":"发（力）；放（电）","g":"[transitive, intransitive]","lab":"specialist","sc":"force/power","ex":{"en":"Lightning is caused by clouds discharging electricity.","cn":"闪电是由云层放电产生的。"}},{"en":"to do everything that is necessary to perform and complete a particular duty","cn":"尽（职）；完成；履行","g":"[transitive]","sc":"duty","ex":{"en":"to discharge your duties/responsibilities/obligations","cn":"履行职责／责任／义务"}},{"en":"to fire a gun, etc.; (of a gun, etc.) to be fired","cn":"开枪；（枪炮等）发射","g":"[transitive, intransitive]","sc":"gun","ex":{"en":"The police officer accidentally discharged a firearm while unloading it.","cn":"警察在卸弹时不慎走火。"}},{"en":"the action of releasing a substance such as a liquid or gas; a substance that comes out from inside somewhere","cn":"排出（物）；放出（物）；流出（物）","g":"[uncountable, countable]","sc":"of liquid/gas","ex":{"en":"a ban on the discharge of toxic waste","cn":"禁止有毒废物的排放"},"pos":"noun"},{"en":"the release of electricity from a charged object; a flow of electricity through air or other gas","cn":"放电；闪电","g":"[uncountable, countable]","sc":"of electricity","ex":{"en":"thunder and lightning caused by electrical discharges","cn":"由放电产生的雷电"},"pos":"noun"},{"en":"the act of officially allowing somebody, or of telling somebody, to leave the police or the army","cn":"退伍；退役","g":"[uncountable, countable]","sc":"from the police/army","ex":{"en":"The illness resulted in his discharge from the army.","cn":"这场病导致他从部队退伍。"},"pos":"noun"},{"en":"the act of allowing somebody to leave hospital because they are well enough to leave","cn":"出院","g":"[uncountable, countable]","sc":"from hospital","ex":{"en":"Referrals can be discussed before discharge from hospital.","cn":"出院前可对病人转诊进行讨论"},"pos":"noun"},{"en":"the act of allowing somebody to leave prison or court","cn":"释放；准许出狱","g":"[countable]","sc":"from prison/court","ex":{"en":"He was given an absolute discharge but banned from driving for twelve months.","cn":"他获得无条件释放，但 12 个月内禁止开车。"},"pos":"noun"},{"en":"the act of performing a task or a duty or of paying money that is owed","cn":"（任务或职责的）履行，执行；（债务的）清偿","g":"[uncountable]","sc":"of duty","ex":{"en":"the discharge of debts/obligations","cn":"债务的清偿；义务的履行"},"pos":"noun"},{"en":"the action of firing a gun, etc.","cn":"发射；开枪","g":"[countable, uncountable]","sc":"of gun","ex":{"en":"an accidental discharge from a dropped gun","cn":"枪掉在地上走火"},"pos":"noun"}]}},"dinghy":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"小舢板;小划艇","en":"A dinghy is a small open boat that you sail or row."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a large boat with a sail, used for pleasure or sport","cn":""},{"en":"a boat that uses one or more sails","cn":""},{"en":"a small boat that you move through the water with oars","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A long journey by sea requires a large ship, but if you’re out for an afternoon on the pond, you may want to take the dinghy , a small boat."}]},"collocations":{"phrases":["ADJ. inflatable, rubber | sailing","VERB + DINGHY row, sail She sailed the dinghy across the bay.","DINGHY + NOUN sailing, sailor","PREP. in/into a/the ~ She rowed ashore in the dinghy."]},"media":{"img":["media/ldoce/img/dinghy.jpg","media/thumb/dinghy.jpg"],"uk":"media/ldoce/hwd/bre/2/dinghy_las2_br.mp3","us":"media/ldoce/hwd/ame/3/dinghy.mp3"},"examples":[{"en":"a sailing dinghy","cn":"小帆船"}],"oxford":{"phon":"ˈdɪŋi","pos":"noun","senses":[{"en":"a small open boat that you sail or row","cn":"小艇；敞篷小船；舢板","ex":{"en":"a sailing dinghy","cn":"小帆船"}},{"en":"a small open boat made of plastic or rubber that is filled with air","cn":"橡皮艇；橡皮筏","ex":{"en":"The crew were taken to shore in an inflatable dinghy.","cn":"全体船员坐充气橡皮筏上了岸。"}}]}},"disc":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"圆盘状物;圆盘形状","en":"A disc is a flat, circular shape or object.","ex":{"en":"Most shredding machines are based on a revolving disc fitted with replaceable blades.","cn":"大多数粉碎机都是基于一个装有可替换刀片的旋转圆盘来实现作业的。"}},{"pos":"N-COUNT 可数名词","cn":"椎间盘","en":"A disc is one of the thin, circular pieces of cartilage which separates the bones in your back.","ex":{"en":"I had slipped a disc and was frozen in a spasm of pain.","cn":"我有一个椎间盘错位了，疼得我动弹不得。"}},{"pos":"N-COUNT 可数名词","cn":"唱片","en":"A disc is a record that you play on a record player.","ex":{"en":"This disc includes the piano sonata in C minor.","cn":"这张唱片包括了 C小调的钢琴奏鸣曲。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a round flat shape or object","cn":"圆盘形状﹐圆盘状物"},{"en":"a compact disc","cn":"激光唱片﹔光碟﹐光盘"},{"en":"a record that you play on a record player 〔","cn":"唱机上播放的〕唱片"}]},"collocations":{"phrases":["ADJ. vinyl I've got an old vinyl disc of her singing.","VERB + DISC play | hear, listen to | produce, record","PREP. on (a/the) ~ He is one of the greatest opera singers on disc. The Prokofiev sonata comes first on the disc. | ~ of a disc of the two M","ADJ. prolapsed, slipped He's in bed with a slipped disc.","VERB + DISC slip She's slipped a disc."]},"media":{"uk":"media/ldoce/hwd/bre/3/disc0205.mp3","us":"media/ldoce/hwd/ame/9/laaddisc.mp3"},"examples":[{"en":"This recording is available online or on disc.","cn":"这录音可在线获取，也可购买激光唱片。"},{"en":"He's been off work with a slipped disc (= one that has moved from its correct position, causing pain).","cn":"他因椎间盘突出一直未上班。"}],"oxford":{"phon":"dɪsk","pos":"noun","senses":[{"en":"a thin flat round object","cn":"圆盘；圆片","ex":{"en":"He wears an identity disc around his neck.","cn":"他脖子上挂着圆形身份牌。"}},{"en":"a CD or DVD","cn":"光盘；激光唱片；数字光盘；数字影碟","ex":{"en":"This disc contains lots of extra features, including an interview with the director.","cn":"这张光盘包含许多额外的功能，包括对导演的采访。"}},{"en":"a disk for a computer","cn":"（计算机）光碟，光盘","lab":"British English","ex":{"en":"He inserted the disc into the machine.","cn":"他把唱片插入机器。"}},{"en":"a record (= a thin round piece of plastic on which music, etc. is recorded)","cn":"纪录","lab":"old-fashioned","ex":{"en":"I have an old vinyl disc of her singing.","cn":"我有一张她的黑胶老唱片。"}},{"en":"a structure made of cartilage between the bones of the back","cn":"椎间盘"}]}},"distribution":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"分发;分派;分送","en":"The distribution of things involves giving or delivering them to a number of people or places.","ex":{"en":"...the council which controls the distribution of foreign aid","cn":"掌管外援物资派发的委员会"}},{"pos":"N-VAR 可变名词","cn":"分配;分布","en":"The distribution of something is how much of it there is in each place or at each time, or how much of it each person has.","ex":{"en":"...a more equitable distribution of wealth.","cn":"更公平合理的财富分配"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(电影在各院线的)发行，上映","en":"Film distribution involves deciding which cinemas a particular film is shown in.","ex":{"en":"...a film-distribution company.","cn":"电影发行公司"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the act of sharing things among a large group of people in a planned way","cn":"分发﹐分配，发放"},{"en":"when goods are supplied to shops and companies for them to sell 〔","cn":"商品的〕配送，分销﹐经销"},{"en":"the way in which something exists in different amounts in different parts of an area or group","cn":"分布"}]},"vocab":{"pos":"n","senses":[{"en":"Distribution means the passing out of something. A teacher is in charge of distribution of corrected essays. A lunch lady manages the distribution of food."}]},"collocations":{"phrases":["ADJ. egalitarian, equitable, fair to ensure a fair distribution of wealth | inequitable, unfair | equal an equal distribution of wealth betw","VERB + DISTRIBUTION achieve, ensure The engine is mounted in the middle to achieve a more even weight distribution. | determine Radiology wa","DISTRIBUTION + NOUN pattern Animal herds may form in response to the distribution patterns of food. | map an atlas containing distribution m","PREP. ~ across the distribution of resources across society | ~ among data on wealth distribution among age groups | ~ between a disparity i","PHRASES a change in distribution changes in the distribution of wealth and income 2 giving/delivering sth to people","ADJ. free The document contains sensitive information and is not suitable for free (= unrestricted) distribution. The previously free (= not","VERB + DISTRIBUTION control, handle, organize The company is to handle the distribution of the product in Europe. | available for 2,000 copi","DISTRIBUTION + NOUN agreement, arrangement, deal Her company has signed a non-exclusive distribution agreement. | list I attach a copy of th"]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41distribution.mp3","us":"media/ldoce/hwd/ame/0/distribution.mp3"},"examples":[{"en":"The map shows the distribution of this species across the world.","cn":"地图上标明了这一物种在全世界的分布情况。"},{"en":"They studied the geographical distribution of the disease.","cn":"他们研究了这种疾病的地域分布情况。"}],"oxford":{"phon":"ˌdɪstrɪˈbjuːʃn","pos":"noun","senses":[{"en":"the way that something is spread or exists over a particular area or among a particular group of people","cn":"分配；分布","g":"[uncountable, countable]","ex":{"en":"They studied the geographical distribution of the disease.","cn":"他们研究了这种疾病的地域分布情况。"}},{"en":"the act of giving or sharing something out among a number of people","cn":"分发；分送","g":"[uncountable, countable]","ex":{"en":"the distribution of food and medicines","cn":"分发食品和药物"}},{"en":"the system of transporting and delivering a product","cn":"（商品）运销，经销，分销","g":"[uncountable]","lab":"business","ex":{"en":"They have systems in place for marketing, sales and distribution.","cn":"他们拥有适当的营销、销售和分销系统。"}}]}},"din":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"喧闹声;喧嚣声;嘈杂声","en":"A din is a very loud and unpleasant noise that lasts for some time.","ex":{"en":"They tried to make themselves heard over the din of the crowd.","cn":"他们力图让自己的声音盖过人群的喧闹声。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a loud sound, especially an unpleasant one","cn":""},{"en":"a loud unpleasant noise, especially one that annoys you. Racket is more informal than din","cn":""},{"en":"a very loud unpleasant noise, especially one that continues for a long time","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"Walk into the average school cafeteria at lunchtime, and you'll get a good sense of what a din is — loud, confused, continuous, generally unpleasant, and often potentially headache-inducing noise."}]},"collocations":{"phrases":["ADJ. awful, raucous, terrible | constant","VERB + DIN make Who's making that awful din? | hear | hear sb above/over She could not be heard above the din of the crowd.","PREP. above/over the ~ Charles shouted above the din.","PHRASES the din of battle"]},"media":{"uk":"media/ldoce/hwd/bre/6/din_n0205.mp3","us":"media/ldoce/hwd/ame/1/din1.mp3"},"examples":[{"en":"The children were making an awful din.","cn":"孩子们吵得厉害。"},{"en":"The din of the engines was deafening.","cn":"引擎的噪声震耳欲聋。"}],"oxford":{"phon":"dɪn","pos":"noun","senses":[{"en":"a loud, unpleasant noise that lasts for a long time","cn":"喧嚣声；嘈杂声；吵闹声","ex":{"en":"The children were making an awful din.","cn":"孩子们吵得厉害。"}}]}},"dictatorship":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"独裁政府;独裁统治;专政","en":"Dictatorship is government by a dictator.","ex":{"en":"...a new era of democracy after a long period of military dictatorship in the country.","cn":"该国长期军事独裁后迎来的一个新的民主时代"}},{"pos":"N-COUNT 可数名词","cn":"独裁国家","en":"A dictatorship is a country which is ruled by a dictator or by a very strict and harsh government.","ex":{"en":"Every country in the region was a military dictatorship.","cn":"该地区的所有国家都是军事独裁国家。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a political system or country that has a dictator (= a leader who has complete power and who has not been elected )","cn":""},{"en":"used for describing countries in which ordinary people have no power and the government has complete control over everything","cn":""},{"en":"a country where the government strictly controls people’s freedom, for example to travel or to talk about politics","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A dictatorship is a government or a social situation where one person makes all the rules and decisions without input from anyone else."}]},"collocations":{"phrases":["ADJ. communist, fascist | left-wing, right-wing | military | totalitarian | benevolent","VERB + DICTATORSHIP establish, set up The generals established a military dictatorship. | overthrow They succeeded in overthrowing the fasci","PREP. during a/the ~ the atrocities that took place during his dictatorship | under (a/the) ~ These men had all lived under dictatorship."]},"media":{"uk":"media/ldoce/hwd/bre/c/dictatorship0205.mp3","us":"media/ldoce/hwd/ame/a/dictatorship.mp3"},"oxford":{"phon":"ˌdɪkˈteɪtəʃɪp","pos":"noun","senses":[{"en":"government by a dictator","cn":"独裁；专政","g":"[countable, uncountable]","lab":"especially North American English","ex":{"en":"The generals established a military dictatorship.","cn":"将军们建立了军事独裁统治。"}},{"en":"a country that is ruled by a dictator","cn":"独裁国家","g":"[countable]","ex":{"en":"Some of these countries are democracies and some are dictatorships.","cn":"这些国家有些是民主国家，有些是独裁国家。"}}]}},"disgusting":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"令人厌恶的;令人作呕的","en":"If you say that something is disgusting, you are criticizing it because it is extremely unpleasant.","ex":{"en":"It tasted disgusting","cn":"这味道令人作呕。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"完全不能接受的;可怕的","en":"If you say that something is disgusting, you mean that you find it completely unacceptable.","ex":{"en":"It's disgusting that the taxpayer is subsidising this project.","cn":"由纳税人来资助这一项目实在是说不过去。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"very bad","cn":""},{"en":"very bad, especially in a way that shocks or upsets you","cn":""},{"en":"smelling or tasting very bad","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Something disgusting is awful in a way that makes you want to throw up — it's really, really yucky. Nobody likes disgusting things."}]},"collocations":{"phrases":["VERBS be, look, smell, sound, taste That soup tastes disgusting! | find sth I find his behaviour disgusting.","ADV. really | absolutely, quite I think the way she's treated him is absolutely disgusting. | pretty, rather He's got some rather disgusting"]},"media":{"uk":"media/ldoce/hwd/bre/7/brelasdedisgusting.mp3","us":"media/ldoce/hwd/ame/a/disgusting.mp3"},"examples":[{"en":"I think it's disgusting that they're closing the local hospital.","cn":"他们要关闭这家地方医院，我认为这太让人气愤了。"},{"en":"The kitchen was in a disgusting state when she left.","cn":"她离开时厨房里一片狼藉。"}],"oxford":{"phon":"dɪsˈɡʌstɪŋ","pos":"adjective","senses":[{"en":"extremely unpleasant","cn":"令人作呕的；极其讨厌的","ex":{"en":"The kitchen was in a disgusting state when she left.","cn":"她离开时厨房里一片狼藉。"}},{"en":"making you feel shocked, upset or angry","cn":"令人恶心的；令人气愤的","ex":{"en":"I think it's disgusting that they're closing the local hospital.","cn":"他们要关闭这家地方医院，我认为这太让人气愤了。"}}]},"base":"disgust"},"differentiate":{"collins":{"senses":[{"pos":"VERB 动词","cn":"区分;区别;辨别","en":"If you differentiate between things or if you differentiate one thing from another, you recognize or show the difference between them.","ex":{"en":"A child may not differentiate between his imagination and the real world","cn":"儿童可能无法将自己的幻想与真实世界区分开来。"}},{"pos":"VERB 动词","cn":"使有差别;使不同","en":"A quality or feature that differentiates one thing from another makes the two things different.","ex":{"en":"...distinctive policies that differentiate them from the other parties.","cn":"使他们有别于其他政党的特殊政策"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to be able to notice that two things or people are different, even though they seem to be similar","cn":""},{"en":"to be able to see that two very similar people or things are different - use this especially in questions and negative statements","cn":""},{"en":"to be able to recognize and understand the difference between two or more similar people or things","cn":""}]},"vocab":{"pos":"1 v 2 v","senses":[{"en":"To differentiate is to identify the differences between things, to discriminate among them. For example, if the light is dim at the party, you might find it hard to differentiate between the spicy bean dip and the chocolate sauce."}]},"collocations":{"phrases":["ADV. clearly","VERB + DIFFERENTIATE be important to | be easy to, be possible to | be difficult to","PREP. between It is not always possible to differentiate between the two diseases. | from features which clearly differentiate this product "]},"media":{"uk":"media/ldoce/hwd/bre/c/differentiate0205.mp3","us":"media/ldoce/hwd/ame/7/differentiate.mp3"},"examples":[{"en":"The male's yellow beak differentiates it from the female.","cn":"雄鸟黄色的喙是与雌鸟相区别的主要特征。"},{"en":"I can't differentiate one variety from another.","cn":"我无法将这几个品种区别开来。"}],"oxford":{"phon":"ˌdɪfəˈrenʃieɪt","pos":"verb","senses":[{"en":"to recognize or show that two things are not the same","cn":"区分；区别；辨别","g":"[intransitive, transitive]","ex":{"en":"It's difficult to differentiate between the two varieties.","cn":"这两个品种很难辨别。"}},{"en":"to be the particular thing that shows that things or people are not the same","cn":"表明…间的差别；构成…间差别的特征","g":"[transitive]","ex":{"en":"The male's yellow beak differentiates it from the female.","cn":"雄鸟黄色的喙是与雌鸟相区别的主要特征。"}},{"en":"to treat people or things in a different way, especially in an unfair way","cn":"（尤指不公正地）差别对待，区别对待","g":"[intransitive]","ex":{"en":"Rules that differentiate between employees on the basis of gender need to be revised.","cn":"需要修改根据性别区分员工的规则。"}},{"en":"to become more specialized during growth and development; to make a cell or tissue more specialized during growth and development","cn":"分化","g":"[intransitive, transitive]","lab":"biology","ex":{"en":"The fertilized egg differentiates into several different cell types.","cn":"受精卵分化成几种不同的细胞。"}}]}},"dice":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"骰子;色子","en":"A dice is a small cube which has between one and six spots or numbers on its sides, and which is used in games to provide random numbers. In old-fashioned English, 'dice' was used only as a plural form, and the singular was die, but now 'dice' is used as both the singular and the plural form."},{"pos":"N-UNCOUNT 不可数名词","cn":"掷骰子游戏","en":"Dice is a game which is played using dice."},{"pos":"VERB 动词","cn":"把(食物)切成小块;将…切丁","en":"If you dice food, you cut it into small cubes.","ex":{"en":"Dice the onion","cn":"把洋葱切成丁。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to cut cheese, carrot etc into small pieces by rubbing it against a special tool","cn":""},{"en":"to make butter, chocolate etc become liquid","cn":""},{"en":"to put flour or other powders through a sieve (= tool like a net made of wire, which you use for removing larger grains or pieces )","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"Dice are what you roll when you're playing Yahtzee or Monopoly; they are two cubes marked with dots on each side that represent the numbers one through six."}]},"collocations":{"phrases":["ADJ. loaded","VERB + DICE roll, throw You decide who's going to start by throwing the dice.","PREP. on a/the ~ You move forward according to the number on the dice.","PHRASES a roll/throw of the dice The roll of the dice went against them."]},"media":{"img":["media/ldoce/img/dice.jpg","media/thumb/dice.jpg"],"uk":"media/ldoce/hwd/bre/d/dice_v0205.mp3","us":"media/ldoce/hwd/ame/c/dice1.mp3"},"examples":[{"en":"‘Did you get that job?’ ‘No dice.’ “","cn":"你得到那份工作了吗？” “没门儿啊。”"},{"en":"We played dice all night.","cn":"我们掷了一夜的骰子。"}],"oxford":{"phon":"daɪs","pos":"noun","senses":[{"en":"a small cube of wood, plastic, etc., with a different number of spots on each of its sides, used in games of chance","cn":"骰子；色子","g":"[countable]","lab":"especially in North American English","ex":{"en":"a pair of dice","cn":"一对骰子"}},{"en":"a game played with dice","cn":"掷骰游戏；掷骰赌博","g":"[uncountable]","ex":{"en":"We played dice all night.","cn":"我们掷了一夜的骰子。"}},{"en":"to cut meat, vegetables, etc. into small square pieces","cn":"将（肉、菜等）切成小方块；将…切成丁","ex":{"en":"diced carrots","cn":"胡萝卜丁"},"pos":"verb"}]}},"discernible":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"看得清的;辨别得出的","en":"If something is discernible, you can see it or recognize that it exists.","ex":{"en":"Far away the outline of the island is just discernible","cn":"远处，岛屿轮廓仅依稀可辨。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to know who someone is or what something is, especially because you have seen or heard them before","cn":""},{"en":"to recognize someone or something and say who or what they are","cn":""},{"en":"to recognize and understand the difference between two or more things or people","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Discernible means noticeable. If your extra hours training are having no discernible influence on your basketball game, it means your game has not changed."}]},"collocations":{"phrases":["VERBS be | become","ADV. clearly, easily, readily The difference between the two is readily discernible. | just | barely, scarcely Her face was barely discernib"]},"media":{"uk":"media/ldoce/hwd/bre/9/discern0205.mp3","us":"media/ldoce/hwd/ame/5/discern.mp3"},"examples":[{"en":"There is often no discernible difference between rival brands.","cn":"相互竞争的品牌之间往往看不出明显的区别。"},{"en":"His face was barely discernible in the gloom.","cn":"在黑暗中很难看得清他的脸。"}],"oxford":{"phon":"dɪˈsɜːnəbl","pos":"adjective","senses":[{"en":"that can be recognized or understood","cn":"可辨别的","ex":{"en":"There is often no discernible difference between rival brands.","cn":"竞争品牌之间通常没有明显的差别。"}},{"en":"that can be seen or heard, but not very clearly","cn":"看得清的；听得清的","ex":{"en":"His face was barely discernible in the gloom.","cn":"在黑暗中很难看得清他的脸。"}}]}},"disposal":{"collins":{"senses":[{"pos":"PHRASE 短语","cn":"任…处理;供…任意使用;由…自由支配","en":"If you have something at your disposal, you are able to use it whenever you want, and for whatever purpose you want. If you say that you are at someone's disposal, you mean that you are willing to help them in any way you can.","ex":{"en":"Do you have this information at your disposal?","cn":"你对这个情况有所了解吗？"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(废物等的)丢掉，清理，销毁，处理","en":"Disposal is the act of getting rid of something that is no longer wanted or needed.","ex":{"en":"...methods for the permanent disposal of radioactive wastes.","cn":"处理放射性废料的一劳永逸的办法"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"if something is available , you can get it, buy it, or use it","cn":""},{"en":"a room or seat that is free is not being used by anyone now, and no one has asked for it to be kept for them to use later","cn":""},{"en":"something that is spare is not being used now, but it can be used if someone needs it","cn":""}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"Disposal means getting rid of something, or throwing it away. When you go on a picnic, be sure to have a bag for the disposal of your trash afterward, or you will be a terrible litterbug."}]},"collocations":{"phrases":["ADJ. safe | routine | illegal | ultimate the problems of the ultimate disposal of nuclear waste | bomb, refuse, rubbish, sewage, waste | lan","DISPOSAL + NOUN site | method | system, unit a kitchen waste disposal unit | company, expert, squad The device was defused by army bomb disp","PREP. at your ~ (= available for your use) He will have a car at his disposal for the whole month. Well, I'm at your disposal (= I am ready "]},"media":{"uk":"media/ldoce/hwd/bre/a/disposal0205.mp3","us":"media/ldoce/hwd/ame/7/disposal.mp3"},"examples":[{"en":"He will have a car at his disposal for the whole month.","cn":"他将有一辆汽车归他使用一个月。"},{"en":"Well, I'm at your disposal (= I am ready to help you in any way I can).","cn":"好吧，我听候你的吩咐。"}],"oxford":{"phon":"dɪˈspəʊzl","pos":"noun","senses":[{"en":"the act of getting rid of something","cn":"去掉；清除；处理","g":"[uncountable]","ex":{"en":"The council is responsible for waste disposal and street cleaning.","cn":"市政局负责垃圾处理和街道清洁。"}},{"en":"the sale of part of a business, property, etc.","cn":"（企业、财产等的）变卖，让与","g":"[countable]","lab":"business","ex":{"en":"The next step is to think about disposal of your assets.","cn":"下一步是考虑处置您的资产。"}},{"en":"a machine connected to the waste pipe of a kitchen sink, for cutting food waste into small pieces","cn":"食物垃圾处理器（安装于厨房水槽下方，可粉碎厨余垃圾）","g":"[countable]","lab":"both North American English"}]}},"disposed":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"乐意的;愿意的","en":"If you are disposed to do something, you are willing or eager to do it.","ex":{"en":"We passed one or two dwellings, but were not disposed to stop","cn":"我们路过了一两个歇脚处，但却无意驻足。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（态度、看法）有…倾向的","en":"You can use disposed when you are talking about someone's general attitude or opinion. For example, if you are well or favourably disposed to someone or something, you like them or approve of them.","ex":{"en":"I saw that the publishers were well disposed towards my book","cn":"我看出出版商对我的书颇有好感。"}},{"pos":"ADJ 形容词","cn":"以…形式排列的","en":"If things are disposed in a particular way, they are arranged in that way.","ex":{"en":"Anyone seeking to paint 18th-century rooms needs to be familiar with the way colour was disposed within a room.","cn":"任何人想要对 18 世纪的房间进行粉刷，都需要熟悉房间内色彩的布局。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"to like or approve of someone or something （","cn":"对某人）有好感﹐很赞成（某人/某物）"},{"en":"to want or be willing to do something","cn":"想要[愿意]做某事"},{"en":"to have a tendency towards something","cn":"倾向于某事物"}]},"collocations":{"phrases":["VERBS be, feel, seem","ADV. agreeably, favourably, kindly, well | naturally","PREP. to She seems favourably disposed to the move. | towards being naturally disposed towards speculation"]},"media":{"uk":"media/ldoce/hwd/bre/d/brelasdedisposed.mp3","us":"media/ldoce/hwd/ame/3/disposed.mp3"},"examples":[{"en":"You're most welcome to join us if you feel so disposed.","cn":"你若有意参加，我们非常欢迎。"},{"en":"She seems favourably disposed to the move.","cn":"她似乎对这一行动持赞同态度。"}],"oxford":{"phon":"dɪˈspəʊzd","pos":"adjective","senses":[{"en":"willing or prepared to do something","cn":"倾向于；有意于；乐意","ex":{"en":"I'm not disposed to argue.","cn":"我无意争论。"}},{"en":"having a good/bad opinion of a person or thing","cn":"对…有好感（或恶感）","ex":{"en":"She seems favourably disposed to the move.","cn":"她似乎对这一行动持赞同态度。"}}]}},"discord":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"不一致;不和;纷争","en":"Discord is disagreement and argument between people."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when people disagree with each other","cn":""},{"en":"when people are unable to agree, especially about something important - use this as a way of avoiding more direct words like 'argument' and 'disagreement'","cn":""},{"en":"a serious disagreement about a decision, plan, or action, that causes arguments for a long time in newspapers, on television etc","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"Discord is the strife and tension that arises when two sides disagree on something, like the high pitched screaming of two kids fighting over the front seat of the car."}]},"collocations":{"phrases":["ADJ. internal | family, marital","QUANT. hint, note A note of discord surfaced during the leaders' meeting.","VERB + DISCORD avoid","PHRASES a source of discord The contrasts between rich and poor nations are a source of discord."]},"media":{"uk":"media/ldoce/hwd/bre/2/discord0205.mp3","us":"media/ldoce/hwd/ame/7/discord.mp3"},"examples":[{"en":"A note of discord surfaced during the proceedings.","cn":"事件进程中出现了意见分歧。"},{"en":"marital/family discord","cn":"夫妻/家庭不和"}],"oxford":{"phon":"ˈdɪskɔːd","pos":"noun","senses":[{"en":"disagreement; arguing","cn":"不一致；不和；纷争","g":"[uncountable]","lab":"formal","ex":{"en":"marital/family discord","cn":"夫妻／家庭不和"}},{"en":"a combination of musical notes that do not sound pleasant together","cn":"不协和和弦","g":"[countable, uncountable]","lab":"music"}]}},"distract":{"collins":{"senses":[{"pos":"VERB 动词","cn":"分散(注意力);使分心","en":"If something distracts you or your attention from something, it takes your attention away from it.","ex":{"en":"Tom admits that playing video games sometimes distracts him from his homework","cn":"汤姆承认玩电子游戏有时会使他无心做作业。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to stop someone when they are working, talking, or having a meeting, especially because you want to ask a question or tell them something","cn":""},{"en":"to stop someone when they are working, talking, or having a meeting, especially because you want to ask them a question or tell them something","cn":""},{"en":"to disturb someone who is doing something, especially in a way that is annoying","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"Distract is what you do when you draw someone’s attention — Hey! Look! Over there! Oh. Never mind. What was I saying? That’s right: distract is to draw attention away from what someone is doing."}]},"collocations":{"phrases":["ADV. easily He's easily distracted from his work | momentarily A noise outside momentarily distracted her.","PREP. (away) from an attempt to distract attention away from the real problems in the country"]},"media":{"uk":"media/ldoce/hwd/bre/4/distract0205.mp3","us":"media/ldoce/hwd/ame/1/distract.mp3"},"examples":[{"en":"Don't talk to her — she's very easily distracted.","cn":"不要同她讲话 — 她的注意力很容易分散。"},{"en":"It was another attempt to distract attention from the truth.","cn":"这又是企图分散人们对事实真相的注意力。"}],"oxford":{"phon":"dɪˈstrækt","pos":"verb","senses":[{"en":"to take somebody’s attention away from what they are trying to do","cn":"转移（注意力）；分散（思想）；使分心","ex":{"en":"You're distracting me from my work.","cn":"你使我不能专心工作。"}}]}},"distraught":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"心烦意乱的;心急如焚的;发狂的","en":"If someone is distraught, they are so upset and worried that they cannot think clearly.","ex":{"en":"His distraught parents were being comforted by relatives.","cn":"亲戚们正在安慰他那心急如焚的父母。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"very sad, especially because you are lonely, cold, ill, or upset – used about people and periods of time","cn":""},{"en":"very sad and without hope for a long time, because things are wrong in your life or because of a medical condition","cn":""},{"en":"extremely sad because of something that has happened to someone or something that you care about very much","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"If you are upset, you are distraught . If you want to explain why you are pulling your hair out, just utter \"Leave me alone; I'm distraught \" It'll work."}]},"collocations":{"phrases":["VERBS appear, be, look, seem, sound She sounded absolutely distraught. | become | remain Weeks after the accident she remained distraught. |","ADV. extremely, really, terribly, very | absolutely, completely, quite, utterly","PREP. at They were terribly distraught at the news of his accident."]},"media":{"uk":"media/ldoce/hwd/bre/e/distraught0205.mp3","us":"media/ldoce/hwd/ame/e/distraught.mp3"},"examples":[{"en":"Relatives are tonight comforting the distraught parents.","cn":"亲戚们今晚都在安慰这对忧心如焚的父母。"}],"oxford":{"phon":"dɪˈstrɔːt","pos":"adjective","senses":[{"en":"extremely upset and anxious so that you cannot think clearly","cn":"心烦意乱的；心急如焚的；发狂的","ex":{"en":"She’s still too distraught to speak about the tragedy.","cn":"她仍然心烦意乱，无法谈论这场悲剧。"}}]}},"disperse":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"（使）分散;（使）散布","en":"When something disperses or when you disperse it, it spreads over a wide area.","ex":{"en":"The oil appeared to be dispersing","cn":"油好像在扩散。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）散开;分散;驱散","en":"When a group of people disperses or when someone disperses them, the group splits up and the people leave in different directions.","ex":{"en":"Police fired shots and used teargas to disperse the demonstrators","cn":"警方鸣枪并使用催泪弹来驱散示威者。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if the police or the army disperses a crowd, they make it separate, and people leave in different directions","cn":""},{"en":"if someone, especially the police, breaks up a crowd, they make it separate, and people go away in small groups","cn":""},{"en":"if a crowd disperses , people begin to move away from it","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"To make a crowd at a party disperse , you could take away the food, turn off the music and ask for volunteers to clean up. Disperse is to spread out people or things, making them move in different directions."}]},"collocations":{"phrases":["ADV. quickly, rapidly | quietly | widely The population in this area is quite widely dispersed. | geographically to decentralize and geograp","VERB + DISPERSE begin to The crowd slowly began to disperse."]},"media":{"uk":"media/ldoce/hwd/bre/3/disperse0205.mp3","us":"media/ldoce/hwd/ame/2/disperse.mp3"},"examples":[{"en":"Police dispersed the protesters with tear gas.","cn":"警察用催泪弹驱散了抗议者。"},{"en":"The crowd dispersed quickly.","cn":"人群很快便散开了。"}],"oxford":{"phon":"dɪˈspɜːs","pos":"verb","senses":[{"en":"to move apart and go away in different directions; to make somebody/something do this","cn":"（使）分散，散开；疏散；驱散","g":"[intransitive, transitive]","ex":{"en":"The fog began to disperse.","cn":"雾开始散了。"}},{"en":"to spread or to make something spread over a wide area","cn":"散布；散发；传播","g":"[transitive, intransitive]","ex":{"en":"The seeds are dispersed by the wind.","cn":"这些种子由风传播。"}}]}},"distressing":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"使人痛苦的;令人苦恼的;使人忧虑的","en":"If something is distressing, it upsets you or worries you.","ex":{"en":"It is very distressing to see your baby attached to tubes and monitors","cn":"看见自己宝宝身上连着各种管子和监视器，心里会非常痛苦。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"making you feel extremely upset or worried","cn":""},{"en":"a painful experience or memory makes you feel extremely upset and sad","cn":""},{"en":"an experience or event that is harrowing makes you feel extremely upset because it is very frightening or shocking","cn":""}]},"collocations":{"phrases":["VERBS be | become | find sth I found the story deeply distressing.","ADV. deeply, extremely, highly, very | quite, rather | emotionally","PREP. for The divorce was extremely distressing for the children."]},"media":{"uk":"media/ldoce/hwd/bre/1/brelasdedistressing.mp3","us":"media/ldoce/hwd/ame/b/distressing.mp3"},"examples":[{"en":"a distressing experience","cn":"一次痛苦的经历"}],"oxford":{"phon":"dɪˈstresɪŋ","pos":"adjective","senses":[{"en":"making you feel extremely upset, especially because somebody is suffering","cn":"使人痛苦的；令人苦恼的","ex":{"en":"It was a very distressing documentary.","cn":"这是一部非常令人心痛的纪录片。"}}]},"base":"distress"},"divisive":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"造成不和的;引起分歧的;制造争端的","en":"Something that is divisive causes unfriendliness and argument between people.","ex":{"en":"Abortion has always been a divisive issue","cn":"人工流产一直是个引发争议的问题。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"causing a lot of disagreement between people","cn":"造成不和的﹐导致分裂的"}]},"vocab":{"pos":"adj","senses":[{"en":"If you say something that is intended to make people angry with each other, your words are divisive . For example, saying \"only stupid people like dogs\" are words divisive enough to get people fighting mad — at you!"}]},"collocations":{"phrases":["VERBS be | become | remain","ADV. deeply | potentially | economically, politically, socially He believes that unemployment is socially divisive and is leading to the cre"]},"media":{"uk":"media/ldoce/hwd/bre/e/divisive0205.mp3","us":"media/ldoce/hwd/ame/d/divisive.mp3"},"examples":[{"en":"He believes that unemployment is socially divisive.","cn":"他认为失业会引起社会分化。"},{"en":"The strike was a divisive issue in the community.","cn":"这场罢工导致社区内部分裂。"}],"oxford":{"phon":"dɪˈvaɪsɪv","pos":"adjective","senses":[{"en":"causing people to be split into groups that disagree with or oppose each other","cn":"造成不和的；引起分歧的；制造分裂的","ex":{"en":"He believes that unemployment is socially divisive.","cn":"他认为失业会引起社会分化。"}}]}},"disintegrate":{"collins":{"senses":[{"pos":"VERB 动词","cn":"崩溃;瓦解","en":"If something disintegrates, it becomes seriously weakened, and is divided or destroyed.","ex":{"en":"During October 1918 the Austro-Hungarian Empire began to disintegrate.","cn":"在 1918 年 10 月间，奥匈帝国开始瓦解。"}},{"pos":"VERB 动词","cn":"碎裂;分裂;粉碎","en":"If an object or substance disintegrates, it breaks into many small pieces or parts and is destroyed.","ex":{"en":"At 420mph the windscreen disintegrated.","cn":"挡风玻璃在时速420英里时破碎。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if a large object breaks up , it breaks into a lot of pieces especially as a result of natural forces, or serious damage","cn":""},{"en":"to break into a lot of small pieces, especially because of being weak, old, or badly made","cn":""},{"en":"to break easily into pieces, especially because of being badly made or very old","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"Soak your tooth in a cup of soda for long enough and it will disintegrate , or break apart from decay."}]},"collocations":{"phrases":["ADV. completely The plane completely disintegrated on impact. | slowly The social fabric of this country is slowly disintegrating.","VERB + DISINTEGRATE begin to The bag had already begun to disintegrate.","PREP. into The country has disintegrated into separate states. | under He was a lawyer who had disintegrated under the strain."]},"media":{"uk":"media/ldoce/hwd/bre/2/disintegrate0205.mp3","us":"media/ldoce/hwd/ame/6/disintegrate.mp3"},"examples":[{"en":"The authority of the central government was rapidly disintegrating.","cn":"中央政府的权力在迅速瓦解。"},{"en":"The plane disintegrated as it fell into the sea.","cn":"飞机坠入大海时解体了。"}],"oxford":{"phon":"dɪsˈɪntɪɡreɪt","pos":"verb","senses":[{"en":"to break into small parts or pieces and be destroyed","cn":"碎裂；解体；分裂","g":"[intransitive]","ex":{"en":"The plane disintegrated as it fell into the sea.","cn":"飞机坠入大海时解体了。"}},{"en":"to become much less strong or united and be gradually destroyed","cn":"衰微；瓦解；崩溃","g":"[intransitive]","ex":{"en":"The authority of the central government was rapidly disintegrating.","cn":"中央政府的权威在迅速丧失。"}}]}},"disgrace":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"丢脸;耻辱;不光彩","en":"If you say that someone is in disgrace, you are emphasizing that other people disapprove of them and do not respect them because of something that they have done.","ex":{"en":"His vice president also had to resign in disgrace","cn":"他的副总统也被迫不光彩地辞去职务。"}},{"pos":"N-SING 单数名词","cn":"丢脸的事;不名誉的事","en":"If you say that something is a disgrace, you are emphasizing that it is very bad or wrong, and that you find it completely unacceptable.","ex":{"en":"The way the sales were handled was a complete disgrace","cn":"这种销售手段为人所不齿。"}},{"pos":"N-SING 单数名词","cn":"让人蒙羞的人","en":"You say that someone is a disgrace to someone else when you want to emphasize that their behaviour causes the other person to feel ashamed.","ex":{"en":"Republican leaders called him a disgrace to the party","cn":"共和党领导人称他是全党的耻辱。"}},{"pos":"VERB 动词","cn":"使丢脸;使受辱","en":"If you say that someone disgraces someone else, you are emphasizing that their behaviour causes the other person to feel ashamed.","ex":{"en":"I have disgraced my family's name","cn":"我让家人蒙羞。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a complete loss of people’s respect because you have done something very bad and shocking","cn":""},{"en":"a feeling of great shame and embarrassment because you have been made to look weak or stupid – a very formal use","cn":""},{"en":"the feeling that you have when you know that you have behaved badly or that you have lost other people's respect","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"Use the verb disgrace to say that someone has brought shame upon himself. Your brother might disgrace himself at the family reunion by being rude to your Uncle Bob."}]},"collocations":{"phrases":["VERB + DISGRACE fall into Their father fell into disgrace and lost his business. | bring His crime had brought disgrace upon his whole famil","PREP. in ~ He's in disgrace for having left his room in a mess.","PHRASES there's no disgrace in sth There's no disgrace in being poor. 2 disgraceful person/thing","ADJ. absolute, utter This room is an absolute disgrace (= because it is very dirty/untidy) ! | national, public The state of our hospitals i","PREP. ~ to The filthy streets are a disgrace to the town."]},"media":{"uk":"media/ldoce/hwd/bre/6/disgrace_n0205.mp3","us":"media/ldoce/hwd/ame/d/disgrace1.mp3"},"examples":[{"en":"The swimmer was sent home from the Olympics in disgrace.","cn":"这位游泳运动员很不光彩地从奥运会上被遣送回国。"},{"en":"It's a disgrace that (= it is very wrong that) they are paid so little.","cn":"他们的报酬如此微薄，太不像话了。"}],"oxford":{"phon":"dɪsˈɡreɪs","pos":"noun","senses":[{"en":"the loss of other people’s respect and approval because of the bad way somebody has behaved","cn":"丢脸；耻辱；不光彩","g":"[uncountable]","ex":{"en":"Her behaviour has brought disgrace on her family.","cn":"她的行为使家人蒙羞。"}},{"en":"a person or thing that is so bad that people connected with them or it feel or should feel ashamed","cn":"令人感到羞耻的人（或事）","g":"[singular]","ex":{"en":"Your homework is an absolute disgrace.","cn":"你的作业太丢人了。"}},{"en":"to behave badly in a way that makes you or other people feel ashamed","cn":"使丢脸；使蒙受耻辱","ex":{"en":"I disgraced myself by drinking far too much.","cn":"我喝酒过多出了洋相。"},"pos":"verb"},{"en":"to lose the respect of people, usually so that you lose a position of power","cn":"使名誉扫地；使失势；使失去地位","ex":{"en":"He was publicly disgraced and sent into exile.","cn":"他被当众贬谪，放逐异乡。"},"pos":"verb"}]}},"dissident":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"持不同政见者;异议者","en":"Dissidents are people who disagree with and criticize their government, especially because it is undemocratic.","ex":{"en":"...political dissidents.","cn":"持不同政见者"}},{"pos":"ADJ 形容词","cn":"有不同意见的;持不同政见的","en":"Dissident people disagree with or criticize their government or a powerful organization they belong to.","ex":{"en":"...a dissident Russian novelist","cn":"持不同政见的俄罗斯小说家"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who publicly criticizes the government in a country where this is punished","cn":"持不同政见者"}]},"vocab":{"pos":"n adj","senses":[{"en":"If you are a dissident , you are a person who is rebelling against a government. Dissidents can do their work peacefully or with violence."}]},"collocations":{"phrases":["ADJ. leading, prominent | political, religious | exiled, imprisoned"]},"media":{"uk":"media/ldoce/hwd/bre/4/dissident0205.mp3","us":"media/ldoce/hwd/ame/1/dissident.mp3"},"examples":[{"en":"a political dissident","cn":"持不同政见者"}],"oxford":{"phon":"ˈdɪsɪdənt","pos":"noun","senses":[{"en":"a person who strongly disagrees with and criticizes their government, especially in a country where this kind of action is dangerous","cn":"持不同政见者","ex":{"en":"political dissidents","cn":"政治异见人士"}},{"en":"strongly disagreeing with and criticizing your government, especially in a country where this kind of action is dangerous","cn":"持不同政见者","ex":{"en":"the suppression of dissident views","cn":"压制不同意见"},"pos":"adjective"}]}},"disfigure":{"collins":{"senses":[{"pos":"VERB 动词","cn":"使变丑;毁损…的容貌","en":"If someone is disfigured, their appearance is spoiled.","ex":{"en":"Many of the wounded had been badly disfigured.","cn":"很多伤者面容严重受损。"}},{"pos":"VERB 动词","cn":"破坏…的外形;毁损…的外观","en":"To disfigure an object or a place means to spoil its appearance.","ex":{"en":"Wind turbines are large and noisy and they disfigure the landscape.","cn":"风力涡轮机个头大、噪音响，还会破坏周边风景。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to spoil the appearance that something naturally has","cn":"毁坏…的外观﹐使变丑"}]},"vocab":{"pos":"v","senses":[{"en":"To disfigure something is to ruin its appearance, which is what would happen if you drew a big bushy mustache and a pair of antennae on the Mona Lisa."}]},"collocations":{"phrases":["ADV. badly, grossly He was badly disfigured by the accident. | permanently"]},"media":{"uk":"media/ldoce/hwd/bre/2/disfigure0205.mp3","us":"media/ldoce/hwd/ame/d/disfigure.mp3"},"examples":[{"en":"Her face was disfigured by a long red scar.","cn":"她脸上一条红色的长疤使她破相了。"},{"en":"He suffered permanent disfigurement in the fire.","cn":"那场火灾永久毁了他的面容。"}],"oxford":{"phon":"dɪsˈfɪɡə(r)","pos":"verb","senses":[{"en":"to damage the appearance of a person, thing or place","cn":"损毁…的外形；使变丑；毁容","ex":{"en":"Her face was disfigured by a long red scar.","cn":"她脸上一条红色的长疤使她破相了。"}}]}},"dismissive":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"拒绝考虑…的;对…轻视的;对…鄙视的","en":"If you are dismissive of someone or something, you say or show that you think they are not important or have no value.","ex":{"en":"Mr Jones was dismissive of the report, saying it was riddled with inaccuracies.","cn":"琼斯先生对报告不屑一顾，称其中充斥着谬误。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"replying in very few words in a way that seems rude","cn":""},{"en":"a terse message, reply, statement etc uses very few words and is deliberately intended to make people stop speaking to you or asking you questions","cn":""},{"en":"using few words and saying directly what you think, because that is the way you usually speak, even though it often seems rude to other people","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"To be dismissive is to be indifferent and a little rude. Being dismissive is a sign of disrespect."}]},"collocations":{"phrases":["VERBS be, seem, sound","ADV. very | completely, entirely | mildly, rather, slightly, somewhat | coldly Her manner was coldly dismissive.","PREP. of She was very dismissive of his achievements."]},"media":{"uk":"media/ldoce/hwd/bre/f/dismissive0205.mp3","us":"media/ldoce/hwd/ame/3/dismissive.mp3"},"examples":[{"en":"to shrug/wave dismissively","cn":"轻蔑地耸耸肩/挥挥手"},{"en":"a dismissive gesture/tone","cn":"轻蔑的手势/语调"}],"oxford":{"phon":"dɪsˈmɪsɪv","pos":"adjective","senses":[{"en":"showing that you do not believe a person or thing to be important or worth considering","cn":"轻蔑的；鄙视的","ex":{"en":"a dismissive gesture/tone","cn":"轻蔑的手势／语调"}}]}},"disciple":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"信徒;门徒;追随者;崇奉者","en":"If you are someone's disciple, you are influenced by their teachings and try to follow their example.","ex":{"en":"...a disciple of Freud.","cn":"弗洛伊德的门徒"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who believes in the ideas of a great teacher or leader, especially a religious one 〔","cn":"尤指宗教导师的〕追随者﹐门徒﹐信徒"},{"en":"one of the first 12 men to follow Christ","cn":"耶稣的十二门徒之一"}]},"vocab":{"pos":"n","senses":[{"en":"A disciple is a follower or a fan of someone. You might consider yourself to be a disciple of your favorite yoga teacher."}]},"collocations":{"phrases":["ADJ. ardent She was an ardent disciple of Freud.","VERB + DISCIPLE become | make He commanded them to go out and make disciples of all nations."]},"media":{"uk":"media/ldoce/hwd/bre/a/disciple0205.mp3","us":"media/ldoce/hwd/ame/e/disciple.mp3"},"examples":[{"en":"a disciple of the economist John Maynard Keynes","cn":"经济学家约翰 · 梅纳德 · 凯恩斯的信徒"},{"en":"He was also an avid reader and a disciple of Tolstoy.","cn":"他也是托尔斯泰的热心读者和信徒。"}],"oxford":{"phon":"dɪˈsaɪpl","pos":"noun","senses":[{"en":"a person who believes in and follows the teachings of a religious or political leader","cn":"信徒；门徒；追随者","ex":{"en":"a disciple of the economist John Maynard Keynes","cn":"经济学家约翰·梅纳德·凯恩斯的信徒"}},{"en":"(according to the Bible) one of the people who followed Jesus Christ and his teachings when he was living on earth, especially one of the twelve apostles","cn":"（耶稣的）门徒，十二门徒之一","ex":{"en":"John, the beloved disciple of Jesus","cn":"耶稣的爱徒约翰"}}]}},"dine":{"collins":{"senses":[{"pos":"VERB 动词","cn":"进餐;用餐;吃饭","en":"When you dine, you have dinner. to wine and dine→see: ;","ex":{"en":"He dines alone most nights","cn":"大多数晚上他都是一个人用餐。"}},{"pos":"","cn":"","en":"相关词组：dine on dine out"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to eat a meal","cn":""},{"en":"to eat a meal","cn":""},{"en":"to eat something such as a small meal or a sandwich","cn":""}]},"collocations":{"phrases":["ADV. al fresco the joys of dining al fresco | in style We dined in style in the hotel restaurant. | out Dining out in attractive surrounding","PREP. on We dined on fresh local fish."]},"media":{"uk":"media/ldoce/hwd/bre/6/brelasdedine.mp3","us":"media/ldoce/hwd/ame/b/dine.mp3"},"examples":[{"en":"We dined with my parents at a restaurant in town.","cn":"我们同我父母在镇里一家餐馆吃饭。"},{"en":"He was dining with friends at the Ritz.","cn":"他和朋友在里茨饭店一起进餐。"}],"oxford":{"phon":"daɪn","pos":"verb","senses":[{"en":"to eat dinner","cn":"进餐；用饭","lab":"especially British English","ex":{"en":"We dined with my parents at a restaurant in town.","cn":"我们同我父母在镇里一家餐馆吃饭。"}}]}},"diphtheria":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"白喉","en":"Diphtheria is a dangerous infectious disease which causes fever and difficulty in breathing and swallowing."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a serious infectious throat disease that makes breathing difficult","cn":"白喉"}]},"collocations":{"phrases":["VERB + DIPHTHERIA have, suffer from | catch, contract, get | immunize sb against Parents are advised to have their children immunized agains","DIPHTHERIA + NOUN epidemic | vaccine •"]},"media":{"uk":"media/ldoce/hwd/bre/2/diphtheria0205.mp3","us":"media/ldoce/hwd/ame/e/diphtheria.mp3"},"oxford":{"phon":"dɪfˈθɪəriə","pos":"noun","senses":[{"en":"a serious disease of the throat that causes difficulty in breathing","cn":"白喉","ex":{"en":"Parents are advised to have their children immunized against diphtheria.","cn":"建议家长让孩子接种抗白喉疫苗。"}}]}},"dissimilar":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不一样的;不相同的;不相似的","en":"If one thing is dissimilar to another, or if two things are dissimilar, they are very different from each other.","ex":{"en":"His methods were not dissimilar to those used by Freud","cn":"他的方法和弗洛伊德的并无二致。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if something or someone is different, they are not like something or someone else, or they are not like they were before","cn":""},{"en":"very different, special, or unusual and the only one of its kind. Don’t use words such as very before unique","cn":""},{"en":"having a special feature or appearance that makes something different from other things, and makes it easy to recognize","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"If your sister has dark skin and dark hair, and you have fair skin and fair hair, people might say that your looks are dissimilar or not alike."}]},"collocations":{"phrases":["VERBS appear, be, look","ADV. very | quite, totally | not altogether, not entirely, not wholly","PREP. from His views are not dissimilar from those of the Health Minister. | to The way of life here is not altogether dissimilar to that in"]},"media":{"uk":"media/ldoce/hwd/bre/9/dissimilar0205.mp3","us":"media/ldoce/hwd/ame/9/dissimilar.mp3"},"examples":[{"en":"These wines are not dissimilar (= are similar).","cn":"这些葡萄酒都差不多。"},{"en":"Madonna’s career is not dissimilar to (= is quite similar to ) Cher’s.","cn":"麦当娜的艺术生涯与雪儿不无类似。"}],"oxford":{"phon":"dɪˈsɪmɪlə(r)","pos":"adjective","senses":[{"en":"not the same","cn":"不一样的；不同的；不相似的","ex":{"en":"These wines are not dissimilar (= are similar).","cn":"这些葡萄酒都差不多。"}}]}},"dishwasher":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"洗碗机","en":"A dishwasher is an electrically operated machine that washes and dries plates, saucepans, and cutlery."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a machine that washes dishes","cn":"洗碗机"},{"en":"someone whose job is to wash dirty dishes, plates etc, especially in a restaurant 〔","cn":"尤指餐厅的〕洗碗工﹐洗碟工"}]},"collocations":{"phrases":["VERB + DISHWASHER load, stack | empty | run It wastes energy to run the dishwasher half empty.","DISHWASHER + NOUN detergent, powder, salt","PHRASES dishwasher proof/safe Are these glasses dishwasher safe?"]},"media":{"img":["media/ldoce/img/dishwasher.jpg"],"uk":"media/ldoce/hwd/bre/9/dishwasher0205.mp3","us":"media/ldoce/hwd/ame/0/dishwasher.mp3"},"examples":[{"en":"to load/stack the dishwasher","cn":"将碗碟放在/码在洗碟机里"}],"oxford":{"phon":"ˈdɪʃwɒʃə(r)","pos":"noun","senses":[{"en":"a machine for washing plates, cups, etc.","cn":"洗碗机","ex":{"en":"to load/stack the dishwasher","cn":"将碗碟放在／码在洗碗机里"}},{"en":"a person whose job is to wash plates, etc., for example in a restaurant","cn":"洗碗工"}]}},"diagnosis":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"诊断（结论）;判断（结论）","en":"Diagnosis is the discovery and naming of what is wrong with someone who is ill or with something that is not working properly.","ex":{"en":"I need to have a second test to confirm the diagnosis","cn":"我需要再进行一次检查以确诊。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the process of discovering exactly what is wrong with someone or something, by examining them closely","cn":"诊断﹔判断"}]},"vocab":{"pos":"n","senses":[{"en":"When a doctor tells you why you're feeling ill, he gives you a diagnosis. He asks questions, checks your symptoms, and then identifies what's making you sick."}]},"collocations":{"phrases":["ADJ. accurate, correct, right | incorrect, wrong | definite, definitive, firm, positive | provisional, tentative Without the results of the ","VERB + DIAGNOSIS establish, give, make, reach The doctor cannot give a diagnosis without knowing the full medical history. | confirm Further","PREP. after ~, before ~ Patients may suffer from some of the symptoms years before diagnosis. | ~ of the diagnosis of the disease a diagnosi","PHRASES a method of diagnosis They are using new methods of diagnosis."]},"media":{"uk":"media/ldoce/hwd/bre/0/diagnosis0205.mp3","us":"media/ldoce/hwd/ame/a/diagnosis.mp3"},"examples":[{"en":"An accurate diagnosis was made after a series of tests.","cn":"准确的诊断是在一系列的化验后作出的。"},{"en":"They are waiting for the doctor's diagnosis.","cn":"他们正在等待医生的诊断结果。"}],"oxford":{"phon":"ˌdaɪəɡˈnəʊsɪs","pos":"noun","senses":[{"en":"the act of discovering or identifying the exact cause of an illness or a problem","cn":"诊断；（问题原因的）判断","ex":{"en":"a diagnosis of lung cancer","cn":"肺癌的诊断"}}]}},"diverge":{"collins":{"senses":[{"pos":"V-RECIP 相互动词","cn":"分化;偏离;背离","en":"If one thing diverges from another similar thing, the first thing becomes different from the second or develops differently from it. You can also say that two things diverge .","ex":{"en":"His interests increasingly diverged from those of his colleagues","cn":"他的兴趣和同事们越来越不一样了。"}},{"pos":"V-RECIP 相互动词","cn":"(意见、观点等)存在分歧，相悖，相异","en":"If one opinion or idea diverges from another, they contradict each other or are different. You can also say that two opinions or ideas diverge .","ex":{"en":"The view of the Estonian government does not diverge that far from Lipmaa's thinking","cn":"爱沙尼亚政府的观点和李普马的想法相去不远。"}},{"pos":"V-RECIP 相互动词","cn":"(道路)分开，分叉，叉开","en":"If one road, path, or route diverges from another, they lead in different directions after starting from the same place. You can also say that roads, paths, or routes diverge .","ex":{"en":"...a course that diverged from the Calvert Island coastline","cn":"从卡尔弗特岛海岸线叉开的一条路"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if similar things diverge, they develop in different ways and so are no longer similar 〔","cn":"相似物〕朝不同方向演变，分化"},{"en":"if opinions, interests etc diverge, they are different from each other 〔","cn":"意见﹑兴趣等〕相异"},{"en":"if two lines or paths diverge, they separate and go in different directions 〔","cn":"两条线或路〕岔开﹐分开"}]},"vocab":{"pos":"v","senses":[{"en":"When two roads diverge , they split and go in different directions. If your opinion diverges from mine, we do not agree. To diverge means to move apart or be separate."}]},"collocations":{"phrases":["ADV. considerably, markedly, widely","PREP. from This country's interests diverge considerably from those of other European countries."]},"media":{"uk":"media/ldoce/hwd/bre/3/diverge0205.mp3","us":"media/ldoce/hwd/ame/4/diverge.mp3"},"examples":[{"en":"We went through school and college together, but then our paths diverged.","cn":"我们从小学到大学一直在一起，但后来就分道扬镳了。"},{"en":"The coastal road diverges from the freeway just north of Santa Monica.","cn":"沿海公路与这条高速公路就在圣莫尼卡以北处岔开。"}],"oxford":{"phon":"daɪˈvɜːdʒ","pos":"verb","senses":[{"en":"to separate and go in different directions","cn":"分叉；岔开","g":"[intransitive]","ex":{"en":"The parallel lines appear to diverge.","cn":"这些平行线像是岔开了。"}},{"en":"to be different","cn":"分歧；相异","g":"[intransitive]","lab":"formal","ex":{"en":"Opinions diverge greatly on this issue.","cn":"在这个问题上意见分歧很大。"}},{"en":"to be or become different from what is expected, planned, etc.","cn":"偏离；背离；违背","g":"[intransitive]","ex":{"en":"to diverge from the norm","cn":"与常态不符"}}]}},"disability":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(身体上的)残疾，伤残，缺陷","en":"A disability is a permanent injury, illness, or physical or mental condition that tends to restrict the way that someone can live their life.","ex":{"en":"Facilities for people with disabilities are still insufficient.","cn":"供伤残人士使用的设施仍然匮乏。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"无能力;缺陷;障碍","en":"Disability is the state of being disabled.","ex":{"en":"Disability can make extra demands on financial resources.","cn":"残障人士会需要更多的财政资源。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a problem with part of your body which makes it difficult for you to walk, talk, see etc","cn":""},{"en":"a mental or physical problem that makes someone disabled","cn":""},{"en":"a physical or mental condition that makes it difficult for someone to use a part of their body properly, or to learn normally","cn":"伤残﹐残障﹐障碍"}]},"vocab":{"pos":"n","senses":[{"en":"A disability is a physical or mental condition that makes you unable to function in some way. Deafness is a disability ."}]},"collocations":{"phrases":["ADJ. severe | permanent | learning, mental, physical children who have severe learning disabilities","VERB + DISABILITY have | cope with, live with learning to live with disability","DISABILITY + NOUN movement, organization | discrimination | allowance, pension"]},"media":{"uk":"media/ldoce/hwd/bre/b/disability0205.mp3","us":"media/ldoce/hwd/ame/8/disability.mp3"},"examples":[{"en":"He qualifies for help on the grounds of disability.","cn":"他因身有残疾有资格得到帮助。"},{"en":"people with severe learning disabilities","cn":"具有严重学习障碍的人"}],"oxford":{"phon":"ˌdɪsəˈbɪləti","pos":"noun","senses":[{"en":"a physical or mental condition that makes it difficult for somebody to do some things that most other people can do","cn":"残疾，缺陷，残障","g":"[countable]","ex":{"en":"a physical/developmental/intellectual disability","cn":"身体/发育/智力障碍"}},{"en":"the state of having a physical or mental condition that makes it difficult to do some things that most other people can do","cn":"身体或精神状况使人们难以做一些大多数人都能做的事情","g":"[uncountable]","ex":{"en":"learning to live with disability","cn":"学习在残疾状态下生活"}}]}},"disreputable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"名声不好的;不名誉的;不光彩的","en":"If you say that someone or something is disreputable, you are critical of them because they are not respectable or cannot be trusted.","ex":{"en":"He was found to have been enjoying the company of disreputable women.","cn":"他被人发现喜欢与那些不三不四的女人混在一起。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"considered to be dishonest, bad, illegal etc","cn":"名声不好的﹐不名誉的﹐不光彩的"}]},"vocab":{"pos":"adj","senses":[{"en":"If a person or organization is disreputable , they have an image problem. They are — or at least appear to be — crooked, shady, or just plain bad news."}]},"collocations":{"phrases":["VERBS be, look, seem","ADV. highly, very | rather, slightly, vaguely He had a vaguely disreputable appearance."]},"media":{"uk":"media/ldoce/hwd/bre/9/disreputable0205.mp3","us":"media/ldoce/hwd/ame/f/disreputable.mp3"},"examples":[{"en":"She spent the evening with her disreputable brother Stefan.","cn":"她同声名狼藉的弟弟斯蒂芬一起度过了这个傍晚。"},{"en":"a disreputable area of the city","cn":"城里破旧肮脏的地方"}],"oxford":{"phon":"dɪsˈrepjətəbl","pos":"adjective","senses":[{"en":"that people do not respect or trust; considered to be bad, dangerous or dishonest","cn":"名声不好的；不名誉的；不光彩的","ex":{"en":"She spent the evening with her disreputable brother Stefan.","cn":"她同声名狼藉的弟弟斯蒂芬一起度过了这个晚上。"}}]}},"dividend":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"红利;股息;股利","en":"A dividend is the part of a company's profits which is paid to people who have shares in the company.","ex":{"en":"The first quarter dividend has been increased by nearly 4 per cent.","cn":"第一季度的股息增长了近 4%。"}},{"pos":"PHRASE 短语","cn":"有回报;产生效益","en":"If something pays dividends, it brings advantages at a later date.","ex":{"en":"Steps taken now to maximise your health will pay dividends later on.","cn":"现在采取措施增强体质会使你日后受益。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a part of a company’s profit that is divided among the people with share s in the company","cn":"股利，股息﹐红利"},{"en":"prize money offered in a national competition called the football pools which people can win by correctly guessing the results of football games","cn":"足彩彩金"},{"en":"a number that is to be divided by another number","cn":"被除数"}]},"vocab":{"pos":"n","senses":[{"en":"A dividend is a bonus. If you buy a cup of coffee and the shop owner throws in a free muffin, that's a dividend . Your charm and loyal patronage are paying dividends !"}]},"collocations":{"phrases":["ADJ. high | 10%, etc. | fixed | increased | gross, total | net | expected a method of valuing shares based on expected dividends | annual, q","VERB + DIVIDEND pay | receive | announce, declare The company has not yet declared its dividends for this year. | recommend The board has re","DIVIDEND + VERB be up The dividend is up 10.6% to 11.3p. | go up, grow, jump, rise The dividend should jump to 5p. | stay The dividend stays","DIVIDEND + NOUN payment, payout | growth, increase | cut | income, total, yield | policy","PREP. ~ on They have announced the quarterly dividend on the shares.","PHRASES an increase in a dividend 2 benefit/reward","ADJ. considerable, enormous, great, handsome, rich | economic","VERB + DIVIDEND bring, pay, produce, reap, yield Her hard work paid dividends when she won the school dancing competition. The company reape"]},"media":{"uk":"media/ldoce/hwd/bre/2/dividend0205.mp3","us":"media/ldoce/hwd/ame/1/dividend.mp3"},"examples":[{"en":"dividend payments of 50 cents a share","cn":"每股 50 分的股息支付"},{"en":"Good eating habits will pay dividends later on in life.","cn":"保持良好的饮食习惯﹐将来会受益的。"}],"oxford":{"phon":"ˈdɪvɪdend","pos":"noun","senses":[{"en":"an amount of the profits that a company pays to people who own shares in the company","cn":"股息；股利","ex":{"en":"Shareholders will receive an interim dividend payment of 50 cents a share.","cn":"股东将获得每股50分的中期股息。"}},{"en":"great advantages or profits","cn":"优势；效益","ex":{"en":"Exercising regularly will pay dividends in the end.","cn":"经常锻炼身体终将得到回报。"}},{"en":"a payment that is divided among a number of people, for example winners in the football pools or members of a cooperative","cn":"（足球彩票的）彩金；（合作社的）红利","lab":"British English"},{"en":"a number that is to be divided by another number","cn":"被除数","lab":"mathematics"}]}},"discard":{"collins":{"senses":[{"pos":"VERB 动词","cn":"丢弃;抛弃","en":"If you discard something, you get rid of it because you no longer want it or need it.","ex":{"en":"Read the manufacturer's guidelines before discarding the box.","cn":"在丢掉盒子前先看一下制造商的使用说明。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to get rid of something, especially when you are trying to make a place more tidy or to make space for new things","cn":""},{"en":"to throw something away, especially something old or dirty","cn":""},{"en":"to get rid of something, especially when you are trying to make a place more tidy or to make room for new things","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"When you discard something, you get rid of it. If your closet is overflowing with clothes you haven't worn since 1992, why not discard some of them?"}]},"collocations":{"phrases":["ADV. completely, entirely These ideas have now been completely discarded.","PREP. in favour of Older managers have been discarded in favour of younger people."]},"media":{"uk":"media/ldoce/hwd/bre/5/discard_v0205.mp3","us":"media/ldoce/hwd/ame/4/l3discard.mp3"},"examples":[{"en":"( figurative ) She could now discard all thought of promotion.","cn":"她现在可以打消晋升的念头了。"},{"en":"The room was littered with discarded newspapers.","cn":"房间里到处是乱扔的报纸。"}],"oxford":{"phon":"dɪˈskɑːd","pos":"verb","senses":[{"en":"to get rid of something that you no longer want or need","cn":"丢弃；抛弃","g":"[transitive]","lab":"formal","ex":{"en":"The room was littered with discarded newspapers.","cn":"房间里到处是乱扔的报纸。"}},{"en":"to get rid of a card that you do not want","cn":"垫（牌）；打出（无用的牌）","g":"[transitive, intransitive]"},{"en":"a person or thing that is not wanted or that is thrown away, especially a card in a card game","cn":"被抛弃的人（或物）；（尤指纸牌游戏中的）弃牌","pos":"noun"}]}},"disturbance":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"骚乱;动乱","en":"A disturbance is an incident in which people behave violently in public.","ex":{"en":"During the disturbance which followed, three Englishmen were hurt.","cn":"在接下来的骚乱中，3名英国人受伤。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"干扰;扰乱","en":"Disturbance means upsetting or disorganizing something which was previously in a calm and well-ordered state.","ex":{"en":"The home would cause less disturbance to local residents than a school","cn":"养老院对当地居民造成的干扰会比学校小。"}},{"pos":"N-VAR 可变名词","cn":"（身体或心理上的）失调，紊乱","en":"You can use disturbance to refer to a medical or psychological problem, when someone's body or mind is not working in the normal way.","ex":{"en":"Poor educational performance is related to emotional disturbance.","cn":"糟糕的学习成绩与情绪失常有关。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a situation in which a large crowd of people is behaving in a violent and uncontrolled way, especially when they are protesting about something","cn":""},{"en":"a social or political situation in which people protest and often behave violently","cn":""},{"en":"a situation in which people fight or behave violently in public","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A disturbance is a noisy commotion that causes a hubbub or interruption. It can also be a worried mental state."}]},"collocations":{"phrases":["ADJ. considerable, major, serious | minimal, minimum, minor, slight","QUANT. level an unacceptable level of disturbance to occupiers of adjacent properties","VERB + DISTURBANCE cause, create, make The traffic causes serious disturbance to residents. | suffer | prevent She moved the nest very caref","PREP. without ~ a place where you can work without disturbance | ~ from disturbance from noisy lorries | ~ of the major disturbance of marin","ADJ. serious The decision led to serious disturbances in all the country's main cities. | violent | public | crowd, mass | serious | civil, ","VERB + DISTURBANCE cause, give rise to, lead to, provoke, trigger (off) He was arrested and charged with causing a disturbance in a public p","DISTURBANCE + VERB occur | involve sb disturbances involving members of a crowd of 550 demonstrators","PREP. during/in a/the ~ Several people were injured during a disturbance in the capital city. | ~ among There had been violent disturbances "]},"media":{"uk":"media/ldoce/hwd/bre/7/disturbance0205.mp3","us":"media/ldoce/hwd/ame/f/disturbance.mp3"},"examples":[{"en":"The building work is creating constant noise, dust and disturbance.","cn":"建筑施工不断制造噪音、灰尘和干扰。"},{"en":"He was charged with causing a disturbance after the game.","cn":"他被指控在比赛结束后制造骚乱。"}],"oxford":{"phon":"dɪˈstɜːbəns","pos":"noun","senses":[{"en":"actions that make you stop what you are doing, or that upset the normal state that something is in; the act of disturbing somebody/something or the fact of being disturbed","cn":"（受）打扰，干扰，妨碍","g":"[uncountable, countable, usually singular]","ex":{"en":"The building work is creating constant noise, dust and disturbance.","cn":"建筑施工不断制造噪声、灰尘和干扰。"}},{"en":"a situation in which people behave violently in a public place","cn":"骚乱；骚动；动乱","g":"[countable, uncountable]","ex":{"en":"News of the arrests provoked serious disturbances in the streets.","cn":"逮捕的消息引起了严重的街头骚乱。"}},{"en":"a state in which a function of somebody's body or mind is not working as it normally would","cn":"障碍；失调；紊乱","g":"[countable, uncountable]","ex":{"en":"sleep disturbances","cn":"睡眠障碍"}}]}},"digit":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(从 0 到 9 的任何一个)数字","en":"A digit is a written symbol for any of the ten numbers from 0 to 9.","ex":{"en":"Her telephone number differs from mine by one digit.","cn":"她的电话号码和我的只差一个数字。"}},{"pos":"N-COUNT 可数名词","cn":"手指;拇指;脚趾","en":"A digit is a finger, thumb, or toe.","ex":{"en":"Many animals have five digits.","cn":"许多动物有 5 趾。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a word or sign that is used to talk about an exact quantity or to show the position of something in a series","cn":""},{"en":"a number written as a sign, not as a word","cn":""},{"en":"a single number between 0 and 9, for example 1, 5, or 8 - used especially in formal or technical contexts","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"If you want to sound smart, you can refer to your finger, thumb, or toe as a digit . Each of the numbers from 0 to 9 is another kind of digit ."}]},"collocations":{"phrases":["ADJ. binary, decimal the decimal digits 0 to 9","QUANT. sequence, series, set, string a sequence of binary digits","PHRASES three, four, etc. digits long The number can be up to eight digits long."]},"media":{"uk":"media/ldoce/hwd/bre/8/digit0205.mp3","us":"media/ldoce/hwd/ame/9/digit.mp3"},"examples":[{"en":"The number 57306 contains five digits.","cn":"数字 57 306 是个五位数。"},{"en":"a four-digit number","cn":"四位数"}],"oxford":{"phon":"ˈdɪdʒɪt","pos":"noun","senses":[{"en":"any of the numbers from 0 to 9","cn":"（从 0 到 9 的任何一个）数字","ex":{"en":"The number 57 306 contains five digits.","cn":"数字 57 306 是个五位数。"}},{"en":"a finger, thumb or toe","cn":"手指；拇指；脚趾","lab":"anatomy"}]}},"dissatisfaction":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"不满;不悦","en":"If you feel dissatisfaction with something, you are not contented or pleased with it.","ex":{"en":"She has already expressed her dissatisfaction with this aspect of the policy","cn":"她对政策的这一方面已经表达了不满。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a feeling of not being satisfied","cn":"不满意﹐不满足"}]},"collocations":{"phrases":["ADJ. considerable, deep | growing, increasing | general, widespread | popular, public | customer | political, sexual | job","VERB + DISSATISFACTION cause, give rise to, lead to Pay cuts have led to widespread dissatisfaction. | express","PREP. ~ about/over dissatisfaction over the slow progress of the peace process | ~ among There was widespread dissatisfaction among the publ","PHRASES a feeling/sense of dissatisfaction, a cause/source of dissatisfaction"]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41dissatisfactio.mp3","us":"media/ldoce/hwd/ame/3/dissatisfaction.mp3"},"examples":[{"en":"Many people have expressed their dissatisfaction with the arrangement.","cn":"许多人表示对这一安排不满。"},{"en":"30% of customers expressed dissatisfaction with the service. 30%","cn":"的顾客对服务表示不满意。"}],"oxford":{"phon":"ˌdɪsˌsætɪsˈfækʃn","pos":"noun","senses":[{"en":"a feeling that you are not pleased or satisfied","cn":"不快；不悦；不满意","g":"[uncountable]","ex":{"en":"Many people have expressed their dissatisfaction with the arrangement.","cn":"许多人表示对这一安排不满。"}},{"en":"something that causes you to feel dissatisfied","cn":"令人不满之事","g":"[countable, usually plural]","ex":{"en":"The characters struggle with their own personal dissatisfactions and frustrations.","cn":"角色们与自己的个人不满和挫折作斗争。"}}]}},"dimension":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"方面;部分","en":"A particular dimension of something is a particular aspect of it.","ex":{"en":"There is a political dimension to the accusations","cn":"这些指控含有政治方面的因素。"}},{"pos":"N-PLURAL 复数名词","cn":"(情况或问题的)范围，规模，程度","en":"If you talk about the dimensions of a situation or problem, you are talking about its extent and size.","ex":{"en":"He considers the dimensions of the problem","cn":"他考虑了问题的严重程度。"}},{"pos":"N-COUNT 可数名词","cn":"（长、宽、高等的）量度;尺寸;大小;面积","en":"A dimension is a measurement such as length, width, or height. If you talk about the dimensions of an object or place, you are referring to its size and proportions.","ex":{"en":"Drilling will continue on the site to assess the dimensions of the new oilfield","cn":"该处的钻探工作将继续下去，以便估测新油田的面积。"}},{"pos":"N-COUNT 可数名词","cn":"(数学和科学中的)维（度）","en":"In mathematics and science, dimension is used in describing spatial concepts such as points, lines, and solids."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"one of the many parts of a situation or subject, which can each be considered separately","cn":""},{"en":"one part of a situation or someone's character - use this especially when you are comparing one part with another","cn":""},{"en":"a part of a situation that makes you look at the situation in a particular way","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"A dimension is the measurement of something in physical space. You might give the painters every dimension of the rooms you want painted, including depth, height, and width."}]},"collocations":{"phrases":["ADJ. approximate | exact, precise It is important to measure the exact dimensions of the room. | overall | compact Despite the unit's compac","VERB + DIMENSION check, measure Can we just check the dimensions of the bedroom again?","PHRASES in two/three dimensions a model in three dimensions 2 aspect","ADJ. added, additional, different, extra, further, new | distinct In looking at population ageing we will consider two distinct dimensions. ","VERB + DIMENSION add, give (sth) Her illness adds an extra dimension to the problem. | have The affair had a different dimension now. | acqu","PREP. ~ to the spiritual dimension to our lives"]},"media":{"img":["media/ldoce/img/ldoce_069.png"],"uk":"media/ldoce/hwd/bre/f/dimension0205.mp3","us":"media/ldoce/hwd/ame/e/dimension.mp3"},"examples":[{"en":"Her job added a new dimension to her life.","cn":"她的工作为她的生活增添了新的内容。"},{"en":"We measured the dimensions of the kitchen.","cn":"我们测量了厨房的面积。"}],"oxford":{"phon":"daɪˈmenʃn","pos":"noun","senses":[{"en":"a measurement in space, for example how high, wide or long something is","cn":"维，维度（构成空间的因素）","ex":{"en":"We measured the dimensions of the kitchen.","cn":"我们测量了厨房的尺寸。"}},{"en":"the size and extent of a situation","cn":"规模；程度；范围","g":"[usually plural]","ex":{"en":"a problem of considerable dimensions","cn":"一个涉及面相当广的问题"}},{"en":"an aspect, or way of looking at or thinking about something","cn":"方面；侧面","ex":{"en":"Her job added a new dimension to her life.","cn":"她的工作为她的生活增添了新的内容。"}}]}},"disarray":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"混乱;紊乱","en":"If people or things are in disarray, they are disorganized and confused.","ex":{"en":"The nation is in disarray following rioting led by the military","cn":"军队发动暴乱之后国家陷入混乱中。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"凌乱;不整齐","en":"If things or places are in disarray, they are in a very untidy state.","ex":{"en":"She was left lying on her side and her clothes were in disarray","cn":"发现她时她侧躺着，且衣衫不整。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"not arranged according to any kind of order or plan","cn":""},{"en":"not well organized - use this about events or activities that are not successful, because they have not been planned well","cn":""},{"en":"a business or organization that is badly run produces bad results because it is badly managed or organized","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"If something is confused or disorganized, use the noun disarray , like the disarray that follows your little brother everywhere he goes because he spills everything and never puts away his toys."}]},"collocations":{"phrases":["ADJ. complete, total | some | financial","VERB + DISARRAY fall into His personal life fell into disarray when his wife left him. | throw sth into Our plans were thrown into disarray ","PREP. in ~ The meeting broke up in disarray. | ~ within a period of disarray within the National Party","PHRASES a state of disarray"]},"media":{"uk":"media/ldoce/hwd/bre/f/disarray0205.mp3","us":"media/ldoce/hwd/ame/8/disarray.mp3"},"examples":[{"en":"Our plans were thrown into disarray by her arrival.","cn":"我们的计划因她的到来而陷入一片混乱。"},{"en":"The peace talks broke up in disarray.","cn":"和谈在混乱中破裂了。"}],"oxford":{"phon":"ˌdɪsəˈreɪ","pos":"noun","senses":[{"en":"a lack of order or organization in a situation or a place","cn":"混乱；紊乱","ex":{"en":"The peace talks broke up in disarray.","cn":"和谈在混乱中破裂了。"}}]}},"distributor":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"经销商;配销商;分销商","en":"A distributor is a company that supplies goods to shops or other businesses.","ex":{"en":"...Spain's largest distributor of petroleum products","cn":"西班牙最大的石油产品分销商"}},{"pos":"N-COUNT 可数名词","cn":"(发动机的)配电器，配电盘","en":"The distributor in a car or other motor vehicle is a device that sends electric current to the spark plugs in the engine."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a company or person that supplies shops and companies with goods","cn":"分销商﹐经销商﹐配送商"},{"en":"the part of an engine that sends an electric current to the spark plug s 〔","cn":"发动机的〕分电器"}]},"vocab":{"pos":"n","senses":[{"en":"It's great that you've got something amazing to sell, but without a distributor you're not going to be able to get it to the people who want to buy it. To distribute it, you need a distributor ."}]},"collocations":{"phrases":["ADJ. global, international, overseas, worldwide | local, national | exclusive, sole | authorized, licensed | independent, third party Third ","VERB + DISTRIBUTOR appoint (sb) as We have been appointed sole UK distributor of a number of Hungarian wines. | act as We will act as the ex","PREP. through a/the ~ You can get the book through your local distributor. | ~ for the exclusive distributor for these goods a distributor f"]},"media":{"uk":"media/ldoce/hwd/bre/0/distributor0205.mp3","us":"media/ldoce/hwd/ame/2/distributor.mp3"},"examples":[{"en":"Japan's largest software distributor","cn":"日本最大的软件分销公司"}],"oxford":{"phon":"dɪˈstrɪbjətə(r)","pos":"noun","senses":[{"en":"a person or company that supplies goods to shops, etc.","cn":"经销商；分销商","ex":{"en":"They are Japan's largest software distributor.","cn":"他们是日本最大的软件分销公司。"}},{"en":"a device in an engine that sends electric current to the spark plugs","cn":"（发动机的）分电器"}]}},"digest":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"消化","en":"When food digests or when you digest it, it passes through your body to your stomach. Your stomach removes the substances that your body needs and gets rid of the rest.","ex":{"en":"Do not undertake strenuous exercise for a few hours after a meal to allow food to digest","cn":"饭后几个小时不要从事剧烈运动，以便食物能够消化。"}},{"pos":"VERB 动词","cn":"理解;领会;领悟","en":"If you digest information, you think about it carefully so that you understand it.","ex":{"en":"They learn well but seem to need time to digest information","cn":"他们学得不错，但似乎还需要一些时间来消化信息。"}},{"pos":"VERB 动词","cn":"慢慢接受(令人不快的消息)","en":"If you digest some unpleasant news, you think about it until you are able to accept it and know how to deal with it.","ex":{"en":"All this has upset me. I need time to digest it all.","cn":"所以这些都让我心烦。我需要时间来慢慢接受这一切。"}},{"pos":"N-COUNT 可数名词","cn":"文摘;汇编;摘要","en":"A digest is a collection of pieces of writing. They are published together in a shorter form than they were originally published.","ex":{"en":"The organization publishes a regular digest of environmental statistics.","cn":"该组织定期出版一份环境统计数据摘要。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to understand new information, especially when there is a large amount of it or when it is difficult to understand, by thinking about it carefully for a fairly long time","cn":""},{"en":"to understand and remember new facts or information","cn":""},{"en":"to understand a large amount of new information","cn":""}]},"vocab":{"pos":"1 v 2 v n 3 v","senses":[{"en":"When your stomach breaks down food, it digests it. To digest is to process food so it can be absorbed into the body or information so the mind can absorb it."}]},"collocations":{"phrases":["ADV. easily Some foods are digested more easily than others. | fully | partially The parent bird partially digests food in its crop.","VERB + DIGEST can/can't He has to avoid fat because his body can't digest it. | be difficult to, be easy to Cheese is very difficult to dige"]},"media":{"uk":"media/ldoce/hwd/bre/1/ld44digest.mp3","us":"media/ldoce/hwd/ame/7/l3digest.mp3"},"examples":[{"en":"He paused, waiting for her to digest the information.","cn":"他停了一会儿，等她慢慢领会这一信息。"},{"en":"You should allow a little time after a meal for the food to digest.","cn":"饭后你应该留点时间让食物消化。"}],"oxford":{"phon":"daɪˈdʒest","pos":"verb","senses":[{"en":"when you digest food, or it digests, it is changed into substances that your body can use","cn":"消化","g":"[transitive, intransitive]","ex":{"en":"Humans cannot digest plants such as grass.","cn":"人不能消化草类植物。"}},{"en":"to treat a substance with heat, enzymes or a solvent (1) in order to break it down or obtain other substances that can be used","cn":"蒸煮；（用酶、溶剂）分解，提炼","g":"[transitive]","lab":"chemistry","ex":{"en":"The plant uses anaerobic bacteria to digest organic material and release methane gas.","cn":"该工厂利用厌氧细菌消化有机物质并释放甲烷气体。"}},{"en":"to think about something so that you fully understand it","cn":"领会；领悟；理解","g":"[transitive]","ex":{"en":"He paused, waiting for her to digest the information.","cn":"他停了一会儿，等她慢慢领会这一信息。"}},{"en":"a short report containing the most important facts of a longer report or piece of writing; a collection of short reports","cn":"摘要；概要；文摘；汇编","ex":{"en":"a monthly news digest","cn":"每月新闻摘要"},"pos":"noun"}]}},"dismay":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"惊恐;焦虑;哀伤","en":"Dismay is a strong feeling of fear, worry, or sadness that is caused by something unpleasant and unexpected.","ex":{"en":"Local councillors have reacted with dismay and indignation","cn":"地方政务委员的反应是惊恐和愤怒。"}},{"pos":"VERB 动词","cn":"使惊恐;使焦急;使哀伤","en":"If you are dismayed by something, it makes you feel afraid, worried, or sad.","ex":{"en":"The committee was dismayed by what it had been told","cn":"委员会对所告知的一切很是惊愕。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the worry, disappointment, or unhappiness you feel when something unpleasant happens","cn":"忧郁﹐失望﹐沮丧"},{"en":"to make someone feel worried, disappointed, and upset","cn":"使担心﹐使失望﹐使忧虑"}]},"vocab":{"pos":"n v","senses":[{"en":"If you discover late Sunday night that the dog really did eat your homework, you might cry out in dismay . Dismay describes an emotional state of alarm, fear, or serious disappointment."}]},"collocations":{"phrases":["ADJ. deep, great The government has expressed &lsquo;deep dismay&rsquo; at police violence against protesters. | growing, mounting | widespr","VERB + DISMAY feel I felt a mounting dismay at the prospect. | express | hide It was impossible to hide my dismay at what I had seen. | caus","PREP. in ~ Louise stared at the torn letter in dismay. | with ~ I read of her resignation with some dismay. | ~ at his dismay at her reactio","PHRASES (much) to your dismay Much to my dismay, she was out when I called."]},"media":{"uk":"media/ldoce/hwd/bre/e/dismay_v0205.mp3","us":"media/ldoce/hwd/ame/5/dismay1.mp3"},"examples":[{"en":"She could not hide her dismay at the result.","cn":"她无法掩饰自己对这一结果的惶恐不安。"},{"en":"The news has been greeted with dismay by local business leaders.","cn":"当地商界领袖听到这消息都感到很丧气。"}],"oxford":{"phon":"dɪsˈmeɪ","pos":"noun","senses":[{"en":"a worried, sad feeling after you have received an unpleasant surprise","cn":"诧异；惊愕；灰心；丧气","ex":{"en":"She could not hide her dismay at the result.","cn":"她无法掩饰自己对这一结果的惶恐不安。"}},{"en":"to make somebody feel shocked and disappointed","cn":"使诧异；使惊愕；使失望","ex":{"en":"Their reaction dismayed him.","cn":"他们的反应使他感到惊愕。"},"pos":"verb"}]}},"disposition":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"性情;性格","en":"Someone's disposition is the way that they tend to behave or feel.","ex":{"en":"The rides are unsuitable for people of a nervous disposition","cn":"骑马这一活动不适合天性易紧张的人。"}},{"pos":"N-SING 单数名词","cn":"倾向;意向","en":"A disposition to do something is a willingness to do it.","ex":{"en":"This has given him a disposition to consider our traditions critically","cn":"这使他倾向以批判眼光看待我们的传统。"}},{"pos":"N-SING 单数名词","cn":"排列;布置","en":"If you refer to the disposition of a number of objects, you mean the pattern in which they are arranged or their positions in relation to each other.","ex":{"en":"...to understand the buildings from the disposition of walls and entrances.","cn":"从墙体门窗布局来识别建筑物"}},{"pos":"N-COUNT 可数名词","cn":"(财产的)赠予，转让，分配","en":"The disposition of money or property is the act of giving or distributing it to a number of people.","ex":{"en":"Judge Stacks was appointed to oversee the disposition of funds.","cn":"斯塔克斯法官被指定监督资金的分配。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the combination of qualities that makes someone a particular kind of person, for example a good or bad, honest or dishonest person","cn":""},{"en":"someone's character - use this especially about how someone behaves towards other people, for example whether they are friendly or unfriendly, confident or easily frightened etc","cn":""},{"en":"someone's character - use this especially to say whether someone is naturally good or bad, gentle or severe etc","cn":""}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"Someone's disposition is their mood or general attitude about life. If your friend woke up on the wrong side of the bed, tell her that she might need a disposition makeover."}]},"collocations":{"phrases":["ADJ. cheerful, happy, pleasant, sunny | friendly, sociable | placid | nervous | jealous | aggressive, touchy | criminal","VERB + DISPOSITION have, show These dogs show a very sociable disposition.","PREP. of a &hellip; ~ This film is not recommended for those of a nervous disposition."]},"media":{"uk":"media/ldoce/hwd/bre/7/disposition0205.mp3","us":"media/ldoce/hwd/ame/5/disposition.mp3"},"examples":[{"en":"to have/show a disposition towards violence","cn":"有/表现出暴力倾向"},{"en":"people of a nervous disposition","cn":"神经质的人"}],"oxford":{"phon":"ˌdɪspəˈzɪʃn","pos":"noun","senses":[{"en":"the natural qualities of a person’s character","cn":"性格；性情","g":"[countable, usually singular]","lab":"formal","ex":{"en":"to have a cheerful disposition","cn":"性情开朗"}},{"en":"a quality of tending to behave in a particular way","cn":"倾向；意向","g":"[countable, usually singular]","lab":"formal","ex":{"en":"to have/show a disposition towards violence","cn":"有／表现出暴力倾向"}},{"en":"the way something is placed or arranged","cn":"排列；布置；安排","g":"[countable, usually singular]","lab":"formal"},{"en":"a formal act of giving property or money to somebody","cn":"（财产或金钱的）处置，让与","g":"[countable, uncountable]","lab":"law"}]}},"discern":{"collins":{"senses":[{"pos":"VERB 动词","cn":"觉察出;知道;了解;辨明","en":"If you can discern something, you are aware of it and know what it is.","ex":{"en":"You need a long series of data to be able to discern such a trend","cn":"你需要一长串的数据才能看出这一趋势。"}},{"pos":"VERB 动词","cn":"依稀看出;分辨出","en":"If you can discern something, you can just see it, but not clearly.","ex":{"en":"Below the bridge we could just discern a narrow, weedy ditch.","cn":"我们仅能依稀辨出桥下一条杂草丛生的窄沟。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to know who someone is or what something is, especially because you have seen or heard them before","cn":""},{"en":"to recognize someone or something and say who or what they are","cn":""},{"en":"to recognize and understand the difference between two or more things or people","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"If you can make out, pick out, or distinguish something, you can discern it. This is a word for recognizing and perceiving things."}]},"collocations":{"phrases":["ADV. clearly, easily She could clearly discern a figure walking up towards the house. | dimly, just","VERB + DISCERN be able to, can/could | be difficult to, be hard to | be possible to"]},"media":{"uk":"media/ldoce/hwd/bre/9/discern0205.mp3","us":"media/ldoce/hwd/ame/5/discern.mp3"},"examples":[{"en":"It is possible to discern a number of different techniques in her work.","cn":"从她的作品中可以了解到许多不同的创作手法。"},{"en":"There is often no discernible difference between rival brands.","cn":"相互竞争的品牌之间往往看不出明显的区别。"}],"oxford":{"phon":"dɪˈsɜːn","pos":"verb","senses":[{"en":"to know, recognize or understand something, especially something that is not obvious","cn":"觉察出；识别；了解","ex":{"en":"It is possible to discern a number of different techniques in her work.","cn":"从她的作品中可以辨别出许多不同的创作手法。"}},{"en":"to see or hear something, usually with difficulty","cn":"（依稀）看出，分辨出，听出","ex":{"en":"We could just discern the house in the distance.","cn":"我们只能勉强分辨出远处的房子。"}}]}},"discretion":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"谨慎;慎重","en":"Discretion is the quality of behaving in a quiet and controlled way without drawing attention to yourself or giving away personal or private information.","ex":{"en":"Larsson sometimes joined in the fun, but with more discretion","cn":"拉森有时会和大家一起玩乐，但是显得更加矜持。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"自行决定的自由;酌情决定权","en":"If someone in a position of authority uses their discretion or has the discretion to do something in a particular situation, they have the freedom and authority to decide what to do.","ex":{"en":"This committee may want to exercise its discretion to look into those charges","cn":"这个委员会可能想行使其自行决定权来调查那些指控。"}},{"pos":"PHRASE 短语","cn":"由…斟酌决定;随…的意愿","en":"If something happens at someone's discretion, it can happen only if they decide to do it or give their permission.","ex":{"en":"We may vary the limit at our discretion and will notify you of any change","cn":"我们可能会斟酌改变限额，有任何变动将通知您。"}},{"pos":"PHRASE 短语","cn":"谨慎即大勇;勇敢贵在审慎","en":"If you say discretion is the better part of valour, you mean that avoiding a dangerous or unpleasant situation is sometimes the most sensible thing to do."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"if you do something with care, you are careful to avoid damage, mistakes etc","cn":""},{"en":"care to avoid danger or risks, or care about trusting information that might not be true","cn":""},{"en":"a sensible and careful attitude that makes you avoid unnecessary risks – a rather formal use","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"If you have the freedom to decide something on your own, the decision is left to your discretion. You're in charge."}]},"collocations":{"phrases":["ADJ. considerable, full, greater, more, wide | absolute, complete, unfettered The school governors have absolute discretion over which pupil","VERB + DISCRETION exercise, have, use The police exercise discretion in the area of minor traffic offences. | give sb They would like local ","PREP. at sb's ~ Bail is granted at the discretion of the court. There is no service charge and tipping is at your discretion. | ~ about We h","PHRASES the exercise/operation of discretion 2 being discreet","ADJ. great, the utmost","VERB + DISCRETION call for, need, require This case calls for the utmost discretion. | rely on This is confidential, but I know that I can r","PREP. with ~ to conduct enquiries with discretion.","PHRASES a lack of discretion, a need for discretion"]},"media":{"uk":"media/ldoce/hwd/bre/c/discretion0205.mp3","us":"media/ldoce/hwd/ame/3/discretion.mp3"},"examples":[{"en":"How much to tell terminally ill patients is left to the discretion of the doctor.","cn":"让晚期病人知道多少病情由医生自行决定。"},{"en":"There is no service charge and tipping is at your discretion.","cn":"不收服务费，给不给小费由你自行决定。"}],"oxford":{"phon":"dɪˈskreʃn","pos":"noun","senses":[{"en":"the freedom or power to decide what should be done in a particular situation","cn":"自行决定的自由；自行决定权","ex":{"en":"I'll leave it up to you to use your discretion.","cn":"我把这件事留给你自己斟酌决定。"}},{"en":"care in what you say or do, in order to keep something secret or to avoid causing difficulty for somebody or making them feel embarrassed; the quality of being discreet","cn":"谨慎；慎重；审慎","ex":{"en":"This is confidential, but I know that I can rely on your discretion.","cn":"这是机密，不过我知道你靠得住。"}}]}},"disorganized":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"缺乏组织的;无系统的;杂乱无章的","en":"Something that is disorganized is in a confused state or is badly planned or managed.","ex":{"en":"A report by the state prosecutor described the police action as confused and disorganised","cn":"州检察官的报告称警方的这次行动混乱无序、毫无章法。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(指人做事)无条理的，计划不周的","en":"Someone who is disorganized is very bad at organizing things in their life.","ex":{"en":"My boss is completely disorganised.","cn":"我的老板做事毫无条理可言。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"use this to say that someone does not organize their work, life etc very well. Not very organized is not as strong as disorganized .","cn":""},{"en":"use this about someone who has not organized their work, life etc in a sensible way and therefore has been unable to be successful","cn":""},{"en":"not arranged according to any kind of order or plan","cn":""}]},"collocations":{"phrases":["VERBS be, seem | become","ADV. highly, hopelessly, very She never gets anywhere on time. She's hopelessly disorganized. | completely, totally | rather, somewhat"]},"media":{"uk":"media/ldoce/hwd/bre/9/brelasdedisorganized.mp3","us":"media/ldoce/hwd/ame/a/disorganized.mp3"},"examples":[{"en":"It was a hectic disorganized weekend.","cn":"这个周末忙乱得一塌糊涂。"},{"en":"She's so disorganized.","cn":"她太缺乏条理了。"}],"oxford":{"phon":"dɪsˈɔːɡənaɪzd","pos":"adjective","senses":[{"en":"badly planned; not able to plan or organize well","cn":"计划不周的；缺乏组织的；杂乱无章的","ex":{"en":"It was a hectic disorganized weekend.","cn":"这个周末忙乱得一塌糊涂。"}}]}},"dialog":{"lemma":"dialogue"},"digger":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"挖掘机;挖掘器","en":"A digger is a machine that is used for digging.","ex":{"en":"...a mechanical digger.","cn":"挖掘机"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a large machine that digs and moves earth","cn":"挖掘机"}]},"media":{"img":["media/ldoce/img/construction_digger.jpg"],"uk":"media/ldoce/hwd/bre/8/ld41digger.mp3","us":"media/ldoce/hwd/ame/0/digger.mp3"},"oxford":{"phon":"ˈdɪɡə(r)","pos":"noun","senses":[{"en":"a large machine that is used for digging up the ground","cn":"挖掘机"},{"en":"a person or an animal that digs","cn":"挖掘者；有挖掘习性的动物"},{"en":"a man","cn":"男人；家伙；老兄","lab":"Australian English, New Zealand English, old-fashioned, informal，，，，，，"}]}},"diy":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（尤指在家里）自己动手，自行维修","en":"DIY is the activity of making or repairing things yourself, especially in your home. DIY is an abbreviation for (缩略=) 'do-it-yourself'.","ex":{"en":"He's useless at DIY. He won't even put up a shelf.","cn":"他自己动手能力太差，甚至连搭个架子都不会。"}},{"pos":"ADJ 形容词","cn":"（商店）出售自己动手做所需物品的","en":"A DIY shop is one that sells tools, paint, and other equipment needed for DIY.","ex":{"en":"You can get kits to do this from DIY stores.","cn":"你可以在自己动手商店里买一套工具自己来做这个。"}},{"pos":"ADJ 形容词","cn":"自己动手做的","en":"DIY things are things that you make or do yourself, rather than buying them ready-made or paying someone else to do them.","ex":{"en":"They sell materials for DIY mosaics and ready-made panels.","cn":"他们出售自己动手做镶嵌画所需材料和现成的镶板。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a very large shop that is divided into several big parts, each of which sells one type of thing, such as clothes, furniture, or kitchen equipment","cn":""},{"en":"a very large modern shop, especially one that is built outside the centre of a city","cn":""},{"en":"a very large shop that sells equipment and tools for repairing and decorating your home","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/1/brelasdediy.mp3","us":"media/ldoce/hwd/ame/0/ld41diy.mp3"},"examples":[{"en":"a DIY store * DIY","cn":"商店"}],"oxford":{"phon":"ˌdiː aɪ ˈwaɪ","pos":"noun","senses":[{"en":"the activity of making, repairing or decorating things in the home yourself, instead of paying somebody to do it (the abbreviation for ‘do-it-yourself’)","cn":"自己动手（与雇人做相对，全写为 do-it-yourself）","lab":"British English","ex":{"en":"a DIY store","cn":"DIY 商店"}}]}}});
